window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[14]=[{"i":33941,"n":"סאבאלניק, שמעון מוילנא","b":"ערך את הספר \"באר אברהם\" מתורתו של ר אברהם אבלי פוסוואלר מוילנא יחד עם ר אהרן דוד שקלובר.","s":"פין-קריה נאמנה"},{"i":33942,"n":"סאבח, יצחק","b":"מגדולי רבני מרוקו,עלה לירושלים-ש\"מ","s":"אוצר הרבנים 10855"},{"i":33943,"n":"סאבטיש, מאיר משאכטיץ","f":"משה","bp":"סאבטישט","dt":"תקצח - ח חשון","dp":"שאכטיץ","b":"רב בשאחטיץ. הסכים על \"בית יעקב\", נספד ב\"מלל לאברהם\".","s":"החת\"ס ותלמידיו; אוצר הרבנים 12749"},{"i":33944,"n":"סאבי, שאלתיאל משלוניקי","b":"ראש הקהלה היהודית בשלוניקי בזמן השואה.","s":"זכרון שלוניקי-239"},{"i":33945,"n":"סאברייגו, אברהם משה מאדרינופול","b":"רב באדרינופול-שנות ה-ש'. בנו - ר משה מאדרינופול.","s":"רוזניס-תורכיה-ב"},{"i":33946,"n":"סאברייגו, משה מאדרינופול","f":"אברהם מאדרינופול","b":"רב באדרינופול-שלא.","s":"רוזניס-תורכיה-ב"},{"i":33947,"n":"סאגיס, אברהם","b":"מחכמי קהיר-שנ\"ה","s":"ארזי הלבנון"},{"i":33948,"n":"סאגיס, אברהם פניירו","b":"מחכמי תורכיה-רן, ונזכר בספרי חכמי דורו.","s":"אלופי יעקב א-שפב"},{"i":33949,"n":"סאגיס, אסתרוק","b":"אחיו של ר רפאל שמואל סאגיס מברושא, בשליחות-תמב אחיו לרבני קושטא בענין עגונות.","s":"רוזניס-תורכיה-ד"},{"i":33950,"n":"סאגיס, יונתן מצפת","b":"מחכמי צפת ומתלמידי הארי, חתום בשטר התקשרות תלמידי הארי משנת שלה, ונמנה על הכת הראשונה מיד אחרי ר חיים ויטאל. בספר הגלגולים נאמר על נשמתו שהוא משורש אהרן וחור, ונמצא דרוש ממנו על \"ג כדים יש לשכינה\".","s":"גליס; כתבי יד בקבלה לג. שלום, שלום \"ציון\" שנה ה ספר ב."},{"i":33951,"n":"סאגיס, יוסף ממצרים - א","b":"רב באלכסנדריה-שנות ה-ר'.","s":"רוזניס-תורכיה-א"},{"i":33952,"n":"סאגיס, יוסף ממצרים - ב","b":"דיין במצרים, חתם-שסד באלכסנדריה עם ר יעקב קשטרו. (לדעת רוזניס היה במקורו מצפת - ואולי הוא מחליף בינו לבין ר יוסף המוסמך).","s":"רוזניס-תורכיה-ג"},{"i":33953,"n":"סאגיס, יוסף מצפת","b":"מחכמי ברוסה, עלה לצפת, מקובל. בשנת ש\"א נזכר כחברו של ר יוסף קארו בשו\"ת אבן העזר. היה אחד מ-4 הסמוכים שנסמכו על ידי ר יעקב בירב. ב\"דברי יוסף\" נזכר כרבו של ר אלעזר אזכרי. תשובות ממנו גם בשות המבי\"ט. נדפס ממנו \"מאמר לתשובה\" שנדפס בסוף ספר פירוש רות לר עובדיה מברטנורה.","s":"גליס; אוצר הרבנים 8466; רוזניס-תורכיה-ב; גאון-יהודי המזרח; פין-כנסת ישראל; ירושלים ו."},{"i":33954,"n":"סאגיס, משה מצפת","f":"שלמה","bt":"שלט","bp":"צפת","dp":"צפת","b":"תלמיד ר יוסף טרני (שהיה תלמידו של אביו). מחכמי צפת, רב באמסייא(=אמאציא)-שמז, היה גם באנגורה-תורכיה, שאלות ממנו למהרי\"ט בצפת, חזר לצפת מראשי בית מדרש ר אברהם אבוהב-תח. תשובה ממנו אצל ר משה גלנטי. חיבר מפתחות ל\"אהלי תם\" לר תם ן יחייא.","s":"אוצר הרבנים 14955; ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":33955,"n":"סאגיס, נסים יוסף מברושה","bt":"תרנד","bp":"ברושה(=ברוסה)","b":"מחכמי ברוסה, עלה לארץ-תרפה בראש קבוצה והתישבו בבאר יעקב, וכיהן כרב הקבוצה.","s":"גאון-יהודי המזרח"},{"i":33956,"n":"סאגיס, רפאל שלמה מקושטא","bt":"קושטא","b":"דיין בקושטא, רב בברושא-תם ודיינים אצלו - ר יהודה סורביאל, ר יעקב לודריג(=רודריג). נזכר ב\"בני משה\".","s":"ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":33957,"n":"סאגיס, שלמה מספרד ושלוניקי","b":"חזן בספרד, לאחר הגירוש חזן בשלוניקי.","s":"רוזניס-תורכיה-א"},{"i":33958,"n":"סאגיס, שלמה מצפת - א","b":"מגדולי חכמי דורו,מרביץ תורה בצפת-ר\"ך","s":"אוצר הרבנים 18540"},{"i":33959,"n":"סאגיס, שלמה מצפת ומצרים","f":"יוסף","k":"חתן האר\"י?","bp":"צפת","dt":"שמז (באוצר שס)","dp":"צפת","b":"מחכמי צפת מגדולי המקובלים ועמד בראש ישיבה. מעט מחדושיו בספרי של תלמידיו ר טוביה הלוי \"חן טוב\", ור חייא רופא בעל \"מעשה חייא\", עוד מתלמידיו ר גדליה בן משה קורדובירו, המהרי\"ט. רב במצרים. בשנת שכט חתם בדבר מנהגי ארץ ישראל בענין ירושות. חתנו היה ר אברהם שלום. (לדעת ארזי הלבנון יתכן כי מדובר בשני חכמים אחד בצפת ואחד במצרים). ב\"איתן האזרחי\" לר אברהם רפפורט כותב כי היה חתנו של האר\"י.","s":"גליס; אוצר הרבנים 18541; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ג; פרומקין-תח\"י"},{"i":33960,"n":"סאגיס, שמואל מברוסה","b":"רב בברוסה-תכב עם ר יצחק רפאל אלפנדרי.","s":"רוזניס-תורכיה-ד"},{"i":33961,"n":"סאהס, וולף מצאברן","b":"רב בצאברן,","s":"מתוך קטלוג"},{"i":33962,"n":"סאויצקי, מרדכי מבוסטון","f":"יוסף","k":"בעל בית מרדכי","bt":"תרעא","bp":"לידא","dt":"כז סיון תשנ\"א","b":"תלמיד ישיבת ראדין ונודע כ\"עילוי מלידא\". חתן ר אליעזר פופקא מפילדלפיה(-נכדת ר יעקב משה ספיר מסארטוב ופתח תקוה). נסמך מאת: ר מאיר מאירוביץ מנוברדוק, ר חנוך הניך אייגעש מוילנא, ר חיים עוזר גרודזינסקי. היגר לארה\"ב וכיהן כרב בבוסטון-תשה. חיבר \"בית מרדכי\" נ\"י תשד. פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג.","s":"אמריקה; אוצר כתבי עת-לוין; אנשי שם-אמריקה","bk":[["ביכורי מרדכי",""]]},{"i":33963,"n":"סאיאס, אדגר משלוניקי","f":"אליהו","b":"למד רפואה בפאריס. רופא בשלוניקי-תרס.","s":"זכרון שלוניקי-187"},{"i":33964,"n":"סאיאס, ז'ול חיים משלוניקי","b":"רופא בשלוניקי-תרס. אחיו של הרופא לאזאר.","s":"זכרון שלוניקי-187"},{"i":33965,"n":"סאיאס, יוסף משלוניקי","f":"משה","dt":"תרמו","dp":"שלוניקי","b":"גביר בשלוניקי. אחיו של הגביר שלום.","s":"זכרון שלוניקי-151"},{"i":33966,"n":"סאיאס, יוסף משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי.","s":"זכרון שלוניקי-212"},{"i":33967,"n":"סאיאס, לאזאר משלוניקי","b":"רופא בשלוניקי-תרס. אחיו של הרופא ז'ול חיים.","s":"זכרון שלוניקי-187"},{"i":33968,"n":"סאיאס, מרדכי משלוניקי","f":"דוד","bt":"תרמה","dt":"תרצט","b":"תלמיד ישיבת ר יעקב קובו. רב בשלוניקי. רב באניברס, רב הקהלה הספרדית באנטורפן.","s":"ארזי הלבנון; זכרון שלוניקי-213"},{"i":33969,"n":"סאיאס, שלום משלוניקי","f":"משה","b":"גביר מראשי קהלת שלוניקי-תרלח, והקים ישיבה בשם \"לשכת הגזית\" וממנה יצאו רבנים ומורי הוראות.","s":"זכרון שלוניקי-123,140"},{"i":33970,"n":"סאיאס, שלמה יצחק משלוניקי","b":"דיין בשלוניקי-תרם.","s":"זכרון שלוניקי-152"},{"i":33971,"n":"סאיקי, יעקב","dt":"תשג","b":"רב באראן","s":"אוצר הרבנים 9788"},{"i":33972,"n":"סאלאדין, זרחיה","f":"יצחק הלוי","b":"מרבני ספרד, רב בסאראגוסה, וואגורא-ק\"ל, ברח לאלג'יר בגירוש-קנ\"א, חזר לספרד, היה בויכוח לפני האפיפיור-קע\"ג","s":"ארזי הלבנון"},{"i":33973,"n":"סאלד, בנימין מניו יורק","b":"תלמיד הכת\"ס בפרשבורג. רב בניו יורק.","s":"פרשבורג-וינגרטן"},{"i":33974,"n":"סאלודיס, שם טוב משלוניקי","b":"רב בשלוניקי-ש\"פ","s":"אוצר הרבנים 18917; ארזי הלבנון"},{"i":33975,"n":"סאליואש, אהרן מאזמיר","dt":"תקכט - כב סיון","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":33976,"n":"סאלינאס, אהרן","dt":"תקכט - כה סיון","dp":"אזמיר","b":"רופא באזמיר","s":"ארזי הלבנון"},{"i":33977,"n":"סאליני, דנמו מאיטליה","b":"מחכמי איטליה, סגינהור, מנגן וסופר. יסד בית מחסה ות\"ת לעוורים. אחיו - ר אברהם.","s":"פין-כנסת ישראל"},{"i":33978,"n":"סאלם - משפחה","b":"מכונה גם סולאם, סלם, שלם. מוצא המשפחה בעיר סאלם בגבול קשטיליה. על כך ב\"אהל דוד\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":33979,"n":"סאלם, נתן מחלב וירושלים","f":"אברהם","b":"מחכמי חלב. עלה לירושלים, והיה מנהל ת\"ת \"מגן דוד\".","s":"ארזי הלבנון"},{"i":33980,"n":"סאלמון - משפחה","dp":"צפת","b":"משפחה ספרדית (לא משפחת סלומון האשכנזית)","s":"פרומקין-תח\"י"},{"i":33981,"n":"סאלמון, יוסף הכהן מאלגיר וירוש","dt":"תקנז - כט תשרי","dp":"ירושלים","b":"רב באלגיר, עלה לירושלים-תקלג, ועבר בדרכו בליוורנו והו\"ל \"קרבן אהרן\" לר אהרן מועטי.","s":"גליס; אוצר הרבנים 8477; מלכי ישורון-חכמי אלגיר; פרומקין-תח\"י"},{"i":33982,"n":"סאלמון, משה הכהן מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',","s":"פרומקין-תח\"י"},{"i":33983,"n":"סאמאנון, אליהו משלוניקי","b":"מתורגמן בשלוניקי-תקה - והיה דין ודברים בינו לראשי הקהלה בענין תשלום המס. בנו - הגביר יוסף משלוניקי.","s":"זכרון שלוניקי-76"},{"i":33984,"n":"סאמאנון, יוסף משלוניקי וירושלי","f":"אליהו משלוניקי","dp":"טבריה","b":"גביר בשלוניקי-בשנות ה-תק'. מחכמי ירושלים וטבריה, פקיד ישיבת בית אל בירושלים-תקיח. חתום על שטר התקשרות עם ר שלום שרעבי, בשנת תקכא בשליחות טבריה לאיטליה ולאחר מכן לשליחויות נוספות. בשנת תקעו חתם על כתב שליחות ר חיים שלמה אבולעפיה. אולי הוא שהיה רב הכולל בטבריה ופסק-תקנז בענין הקידושין של בתו של השליח שמואל עניו.","s":"גליס; זכרון שלוניקי-93; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":33985,"n":"סאמון ן, אברהם מאלגיר","f":"דוד","k":"בעל אור החמה","dt":"תרעז","b":"מחכמי תלמסאן ובקי בתולדות הקהלה. חיבר עם ר אהרן אלקובי \"אור החמה\" על חכמת העיבור בערבית יהודית - תונס תרנז, \"שירות ותשבחות\". ?? לא באוצר ??","s":"מלכי ישורון-חכמי אלגיר"},{"i":33986,"n":"סאמון ן, אלעזר מפאס","b":"מחכמי פאס הקדמונים, דור עשירי ממנו - ר שלמה סאמון.","s":"מלכי רבנן"},{"i":33987,"n":"סאמון ן, דוד מטבריה","b":"מחכמי טבריה בשנות ה-תר, חתם על מסמך בערבית.","s":"מתוך קטלוג"},{"i":33988,"n":"סאמון ן, יוסף מטיטואן-מרוקו","k":"בעל עדות ביהוסף","bp":"פאס","dt":"תקנח - לפני","b":"רב בטיטואן-מרוקו, תלמיד ר שמואל אלבז. התישב בליוורנו-תקל. אביו של ר שם טוב. חברו של ר אליהו צרפתי מפאס.","s":"אוצר הרבנים 8479; מלכי רבנן; ארזי הלבנון; טולדנו-נר המערב"},{"i":33989,"n":"סאמון ן, יוסף ממרוקו ובוכרה","b":"מחכמי מרוקו-שנות ה-תק', עלה לצפת. בשליחות-תקכג בבוכרה ופרס, והתישב בבוכרה ללמד תורה ותיקן שם תקנות. מצאצאיו משפחה בבוכרה. נזכר ב\"זכר צדיק\"-ירושלים תרן ובו דרשות ממנו בספרדית שמצא נכדו המו\"ל בבוכרה. עליו ב\"יסוד מערבי\".","s":"טולדנו-נר המערב"},{"i":33990,"n":"סאמון ן, יוסף מפאס","b":"מחכמי פאס-שנות ה-ת'.","s":"מלכי רבנן"},{"i":33991,"n":"סאמון ן, יוסף מפאס","f":"כליפא","b":"מחכמי פאס-תקל.","s":"מלכי רבנן"},{"i":33992,"n":"סאמון ן, יעקב מטבריה","f":"אפרים","k":"בעל מאיר בת עין","dt":"תרעב","dp":"טבריה","b":"מחכמי טבריה, בשנת תרלב בשליחות בארצות ערב ובשנת תרן שוב בשליחות. חיבר \"מאיר בת עין\" בגדד תרכח. ?? לא באוצר ?? חתם על כתב שליחות ר דוד יבגי.","s":"גליס; מלכי ישורון-חכמי אלגיר"},{"i":33993,"n":"סאמון ן, שלמה מטבריה","dt":"תרפו - ו שבט","dp":"טבריה","b":"מחכמי טבריה, חתם על תעודות הקהלה. בשליחות-תרעג במצרים.","s":"ארזי הלבנון"},{"i":33994,"n":"סאמון ן, שם טוב ממרוקו וליוורנ","f":"יוסף חיים","k":"בעל לקח טוב","b":"מחכמי פאס, הו\"ל ספר אביו \"עדות ביהוסף\" בליוורנו - ונשאר שם כרב ודיין. חיבר \"לקח טוב\" ונדפס בתוך ספר אביו. חתם-תקעא עם ר יעקב נוניס ואיס, ור יעקב מדינה.","s":"ארזי הלבנון"},{"i":33995,"n":"סאמון, שלמה מפאס","f":"אלעזר","b":"מחכמי פאס הקדומים.","s":"מלכי רבנן"},{"i":33996,"n":"סאמועל, שמואל זנויל מביליץ ביא","b":"מחכמי ביליץ-ביאלא. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט.","s":"אוצר כתבי עת-לוין"},{"i":33997,"n":"סאמיאייה, אברהם הרופא מקושטא","b":"רופא בקושטא-שנות הר'-ש', בזמן ר יוסף המון ובנו ר משה.","s":"רוזניס-תורכיה-א"},{"i":33998,"n":"סאמיגה, יוסף משלוניקי ונציה","f":"בנימין","k":"בעל בנין עולם","bp":"שלוניקי","dt":"שפט - טו סיון","dp":"ונציה","b":"רב בשלוניקי, ונציה (וכנראה גם בפדובה). כנראה היה רבו של בעל \"כנסת הגדולה\" ושל היש\"ר. בכת\"י חדושים שהחליף עם ר שמחה לוצאטו. חיבר גם \"מקרא קדש\", \"טעמי מצוות\", \"בנין עולם\", ועוד.","s":"אוצר הרבנים 8480; איטליה גירונדי-י כח; זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":33999,"n":"סאמעק, משה צבי מפרשבורג","b":"מראשי ה\"מנזה\" בישיבת פרשבורג-תרץ.","s":"פרשבורג-וינגרטן"},{"i":34000,"n":"סאנאטץ, יוסף ממראקש","b":"חתם-תקנט עם ר אברהם בן יעקב פינטו על קיום שטר.","s":"מתוך קטלוג"},{"i":34001,"n":"סאנט, חיים דוד","b":"תלמיד ר חיים טויבש בעל \"חיים של שלום\". פרסם מאמר ב\"אהל יצחק\" סטמר תרסט.","s":"מתוך קטלוג"},{"i":34002,"n":"סאנט, חיים דוד מ","f":"משה מסיגט","k":"בעל פרדס מרדכי-תרפח","bt":"תרנו","bp":"בישטינא-מארמארוש","b":"חיבר גם \"אוצר נחמד\", \"קובץ התוספות\" - ובו רבבות שיטות וכללים מהתוספות לפי א-ב, \"אוצר הש\"ס\" ובו סדר הענינים בש\"ס לפי א-ב.","s":"טרנסילבניה; אמריקה"},{"i":34003,"n":"סאנטוף, בער מגלוגלא","b":"אב\"ד גלוגא, קרעמזיר. נכדו ר משה ליב קרעמזיר מפרשבורג-שנפטר תקנד.","s":"אבני בית היוצר-וייס"},{"i":34004,"n":"סאניקר, יהודה מברוזויל","b":"רב בברונזויל-ניו יורק.","s":"מתוך קטלוג"},{"i":34005,"n":"סאסי די, משה יצחק מאמשטרדם","b":"גביר באמשטרדם-תקלז בזמן ביקור החיד\"א.","s":"רוזניס-תורכיה-ה"},{"i":34006,"n":"סאסי הכהן מג'רבה","k":"בעל פרוכת המסך","dt":"תשלא - יז אלול","dp":"צפת","b":"תלמיד ר מכלוף עידאן. מחכמי הדיג'ת. עלה לארץ-תשטו והתגורר בצפת. חיבר גם \"מדרשות של שם ועבר\". פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"קרן דוד\" - גרבה תרעו.","s":"ארזי הלבנון; אוצר כתבי עת-לוין","bk":[["פרוכת המסך",""]]},{"i":34007,"n":"סאסי מתוק יהונתן הכהן מג'רבה","k":"בעל ברכת ה'","bt":"תקצא","dt":"תרסה - יט חשון","dp":"ג'רבה","b":"רב בג'רבא. תלמיד ר כליפא עידאן, תלמיד וחתן ר יצחק חורי. תיקן תקנות רבות והתנגד לפתיחת בי\"ס כי\"ח בג'רבה. חיבר גם \"זרע דוד\", \"זכות יצחק\" ועוד.","s":"אוצר הרבנים 16497; ארזי הלבנון","bk":[["ברכת ה'",""],["זרע דוד",""],["זכות יצחק",""]]},{"i":34008,"n":"סאפורטה, אברהם משלוניקי","b":"דיין בשלוניקי-שכה.","s":"זכרון שלוניקי"},{"i":34009,"n":"סאפורטה, אברהם משלוניקי","dt":"תקא","dp":"שלוניקי","b":"גביר בשלוניקי. אחיו של אליהו. נספו במגיפה-תקא.","s":"זכרון שלוניקי-93"},{"i":34010,"n":"סאפורטה, אליהו משלוניקי","dt":"תקא","dp":"שלוניקי","b":"גביר בשלוניקי. אחיו של אברהם. נספו במגיפה-תקא.","s":"זכרון שלוניקי-93"},{"i":34011,"n":"סאפורטה, בנימין מירושלים","b":"מחכמי ישיבת אברהם מיוחס בירושלים-תקיח.","s":"רוזניס-תורכיה-ה"},{"i":34012,"n":"סאפורטה, ברוך מירושלים","b":"מחכמי ישיבת ר אברהם מיוחס בירושלים-תקיח, מקובל, מתלמידי הרש\"ש.","s":"ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":34013,"n":"סאפורטה, חיים ברוך מירושלים","b":"מחכמי ירושלים, תלמיד ר שלום שרעבי (\"בית אל\"), בשנת תקנא בשליחות באירופה.","s":"גליס; סימנסון ספר צפת, שא\"י"},{"i":34014,"n":"סאפורטה, חיים ברוך משלוניקי","b":"דיין בשלוניקי-תקן.","s":"זכרון שלוניקי-116"},{"i":34015,"n":"סאפורטה, חנוך מספרד - א","b":"מחכמי ספרד בזמן הרשב\"ץ. עבר ליוון, לימד את בני הקראים תלמוד. מתלמידיו - ר\"מ כוסטינה.","s":"ארזי הלבנון; פין-כנסת ישראל"},{"i":34016,"n":"סאפורטה, חנוך מספרד וקושטא","b":"מרביץ תורה,גדול בתורה ומדע,רב גולי קטלוניא באדרינופולי-שנת ש'","s":"אוצר הרבנים 6656; פין-כנסת ישראל"},{"i":34017,"n":"סאפורטה, חנניה משלוניקי","dt":"תרטז - יב חשון","dp":"שלוניקי","b":"רמ בשלוניקי, ורב הכולל לצדו של ר אשר קובו.","s":"ארזי הלבנון; זכרון שלוניקי-139"},{"i":34018,"n":"סאפורטה, יוסף יעקב משלוניקי","dt":"תקיז","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":34019,"n":"סאפורטה, יוסף יצחק משלוניקי","dt":"תקא","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"תורת חיים\" לר חיים שבתי-תעג.","s":"זכרון שלוניקי-92"},{"i":34020,"n":"סאפורטה, יוסף מלאריסה","bp":"שלוניקי","dt":"תפא","b":"גביר נדיב בלאריסה, נספד בשלוניקי בק\"ק ליסבון חדש.","s":"רוזניס-תורכיה-ה"},{"i":34021,"n":"סאפורטה, יוסף משלוניקי וירושלי","f":"ראה גם צאלמונא, יוסף","dt":"תקיא","dp":"ירושלים","b":"מחכמי שלוניקי, ירושלים, היה זקנו ורבו של ר שלמה שלם מאמשטרדם.","s":"גליס; זכרון שלוניקי-93"},{"i":34022,"n":"סאפורטה, יעקב אברהם משלוניקי","dt":"תקכא","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":34023,"n":"סאפורטה, משה משלוניקי","b":"דיין בשלוניקי-תקס בערך.","s":"רוזניס-תורכיה-ו"},{"i":34024,"n":"סאפורטה, רפאל יוסף מירושלים","b":"מחכמי ירושלים, חתם על תקנת הקהל-תקעא יחד עם ר אליהו פרנס.","s":"פרומקין-תח\"י"},{"i":34025,"n":"סאפורטה, שלמה מקושטא","b":"ממונה על איסור והיתר בקושטא, ראב\"ד בקושטא-תקף.","s":"ארזי הלבנון"},{"i":34026,"n":"סאפורטה, שמואל משלוניקי","dt":"תקי","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":34027,"n":"סאפורטה, שמואל משלוניקי","dt":"תר","dp":"שלוניקי","b":"מחכמי שלוניקי, סירב לרבנות ועסק במסחר. סייע בהדפסת \"אורות אילים\" לר אליעזר פאפו-תקפג. נספד ע\"י חתנו - ר אברהם גטניו.","s":"זכרון שלוניקי-112"},{"i":34028,"n":"סאפורטה, שמואל משלוניקי","b":"מחכמי שלוניקי-רפ. חתנו - ר יעקב אלמיעזר משלוניקי.","s":"עמנואל-שלוניקי"},{"i":34029,"n":"סאפורטה, שניאור משלוניקי","dt":"תקלא","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":34030,"n":"סאפיאן, אליעזר מלויצק","bt":"תרלו","b":"חתן ר מרדכי גינצבורג מקאשיווקא. בנו ר יצחק לייב.","s":"אלפסי"},{"i":34031,"n":"סאפין, יצחק משלוניקי","dt":"תצא - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי, הבנקאי של הפאשה-תץ.","s":"זכרון שלוניקי-70"},{"i":34032,"n":"סאקאמיש, יעקב מאובן","b":"גביר, ראש החוכרים באובן-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":34033,"n":"סאקער, חיים יצחק","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - יאסי תרסט.","s":"אוצר כתבי עת-לוין"},{"i":34034,"n":"סאקער, רפאל","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - יאסי תרסט.","s":"אוצר כתבי עת-לוין"},{"i":34035,"n":"סאקראמיש, שלמה מפליבנה","b":"רב בפליבנה בזמן מהרשד\"ם, ונזכר בתשובותיו.","s":"ארזי הלבנון; רוזניס-תורכיה-ב"},{"i":34036,"n":"סאקרדוטי, תאודור טודרוס מרומא","b":"רופא האפיפיור יוליוס השלישי-שיא. תרגם ספרי רפואה מערבית לרומית.","s":"פין-כנסת ישראל"},{"i":34037,"n":"סאקריאריאו, דוד מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":34038,"n":"סאראגו, שמריה מירושלים","b":"מחכמי ישיבת \"דמשק אליעזר\" בירושלים-תקיח.","s":"פרומקין-תח\"י"},{"i":34039,"n":"סארדי, אברהם חיים דוד מקוש-אדא","b":"דיין בקוש-אדאסי-תקנט, ישב בדין פטירת יצחק אלמדיאל עם ר חיים שמעון גדיליא ור אברהם איסטאמאטי.","s":"רוזניס-תורכיה-ה"},{"i":34040,"n":"סארדי, אפרים מקוש-אדאסי","f":"שלמה","b":"דיין בקוש-אדאסי-תקנט, ישב בדין פטירת יצחק אלמדיאל עם ר אברהם חיים סיגורה. (ראה גם: ר אברהם חיים סיגורה).","s":"רוזניס-תורכיה-ה"},{"i":34041,"n":"סארטוב, צבי מנחם","dt":"תשג","b":"מרבני פולין","s":"אוצר הרבנים 17548"},{"i":34042,"n":"סבא, אפרים מפולין","dt":"שלה - יח סיון","dp":"קראקא","b":"אחיו של ר מרדכי מקראקא. בנו - הרופא ר דוד מקראקא.","s":"אלופי יעקב א-תתקז"},{"i":34043,"n":"סבא, דוד מקראקא","f":"אפרים מפולין","dt":"שלה - יח סיון","dp":"קראקא","b":"רופא מחכמי קראקא.","s":"אוצר הרבנים 4931,4669; אלופי יעקב א-תתקז; צונץ-קראקא"},{"i":34044,"n":"סבא, יעקב יאקיל מטוטשין","k":"בעל קרנות המזבח","bt":"תרכד","dt":"תרפח - יח אדר","b":"רב בטוטשין-ווהלין-תרמט, קאלקא.","s":"אוצר הרבנים 9783; אהלי שם"},{"i":34045,"n":"סבא, מיכל יצחק","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":34046,"n":"סבא, מרדכי מקראקא","dt":"שלו - יט טבת","dp":"קראקא","b":"מגדולי חכמי קראקא.","s":"אוצר הרבנים 13954; צונץ-קראקא"},{"i":34047,"n":"סבאג, אברהם","dt":"תרסח","dp":"מוגדיר-מרוקו","b":"עלה מצפון אפריקה לטבריה, ולמד בישבית ר חיים שמואל הכהן קונוורתי, בשנת תריז חתום על הקמת ישיבת \"בית יעקב\". בשליחות בארצות ערב-תרכה, ואחר כך בצפון אפריקה-תרלג, חדושים ממנו בתוך ספר \"ישא ברכה\" לר יעקב שאול אלישר, בשנת תרמד היה ראב\"ד בעיר מוגדיר.","s":"גליס; ארזי הלבנון"},{"i":34048,"n":"סבאג, יצחק ממכנאס","dt":"תשלא - ח טבת","b":"תלמיד ר חיים ברדוגו, ור שלמה בן רפאל טולדנו. למד בחברותא עם ר מרדכי עמאר בעל דברי שלום ואמת. עלה לארץ והתישב בטירת הכרמל, והקים שם ישיבה. תלמידו - ר שלום משאש רבה של ירושלים. מתורתו ב\"אהל יצחק\".","s":"ארזי הלבנון"},{"i":34049,"n":"סבאג, מגוס מג'רבה","bt":"תרסב","bp":"ג'רבה","b":"רב בג'רבה, עלה לארץ-תשיח והתישב בבאר שבע, צדיק שעסק בעזרה לפונים אליו, בנו ר שלום על מקומו אחריו.","s":"ארזי הלבנון"},{"i":34050,"n":"סבאן, דוד מאזמיר","dt":"תקמו - כט שבט","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":34051,"n":"סבאן, חיים מקושטא","b":"מחכמי ורבני קושטא","s":"ארזי הלבנון"},{"i":34052,"n":"סבאן, יום טוב מצפת","b":"מחכמי צפת, חתם על כתב שליחות בשנת תצו, בשנת תקב בשליחות יחד עם ר יוסף בן ג'ויה.","s":"גליס; רוזניס-תורכיה-ה; שא\"י, בן צבי \"ספר צפת\"."},{"i":34053,"n":"סבאן, יצחק ממרוקו","dt":"תקסג - א אלול","b":"מחכמי מרוקו.","s":"ארזי הלבנון"},{"i":34054,"n":"סבאן, רפאל דוד מקושטא","f":"נסים","k":"בעל מדר\"ס לפירושים","bt":"תרלז","bp":"קושטא - קוזגונז'וק","dt":"תשכא - ז כסלו","dp":"קושטא","b":"תלמיד ר יוסף הכהן מקושטא, ר יום טוב הכהן מקושטא, ור קונרטה דילסון. מזכירו של החכם באשי ר משה הלוי. חתן ר חיים נשיא מחאסקי. רב בחאסקוי על מקום חותנו, והיה אחראי גם על הקהלות גאלטא, ביאוגלו, קאסימפאשה, שישלי והקהלות האיטלקית והאשכנזית. שליח מיוחד של הרבנים הראשיים ר משה לוי ור חיים נחום ור חיים משה ביג'יראנו ברחבי האימפריה העותומנית, ונתמנה לממלא מקום הרב הראשי וכינויו \"קאימקאם\". חכם באשי-תשיב.","s":"ארזי הלבנון"},{"i":34055,"n":"סבח, יצחק","f":"ראה צבאח, יצחק"},{"i":34056,"n":"סבטקה, צבי","k":"חתן המהר\"ל מפרג","b":"דיין,רב ונאמן הקהילה בפרג-ש\"צ","s":"אוצר הרבנים 17383"},{"i":34057,"n":"סביבי, דוד מונציה","k":"בעל מגן דוד","b":"רב בונציה בזמן ר רפאל די סילוה. נפטר בן למעלה מתשעים שנה - כמובא ב\"לקט הקמח\". חיבר \"מגן דוד\" והוא קצור \"מעבר יבוק\" - ונציה.","s":"איטליה גירונדי-ד טו,כח"},{"i":34058,"n":"סבירסקי, דב ברל מארה\"ב","f":"דוד בן זונדל סוויר","bp":"סוויר-פלך וילנא","b":"נכד(-אבי אמו) ר שמריה גבאי (אביו של ר יעקב לוין מאלקניק וארץ ישראל). תלמיד ישיבת ראדין, נוברדוק, נסמך מאת: ר רפאל שפירא, ר יחיאל מיכל אפשטין. חתן ר אברהם כהנא מסאד. רב ברודישוק-פלך קובנא-תרסד, היגר לארה\"ב-תרפב, וכיהן כרב קהלת קובנא בשיקאגו. ממיסדי ישיבת פאראקיל סקוהל. חבר אגודת הרבנים באמריקה.","s":"אוצר הרבנים 4572; אנשי שם-אמריקה"},{"i":34059,"n":"סבע, אברהם מספרד ואלגיר","f":"יעקב החסיד","k":"בעל צרור המור","bt":"רי - בערך","bp":"קסטיליה","dt":"רסב - ט תשרי","dp":"וירונא או תלמסאן","b":"תלמיד ר יצחק די ליאון. מקובל דרשן ומוכיח ורופא בספרד, לאחר הגירוש עבר לפורטוגל-רנב, משם לארזיליי(=אלגיר)-רנז, רב ודרשן בפאס, נפטר בספינה, חיבר \"צרור המור\". בנו ר יצחק - חותנו של ר יוסף קארו, שניים מבניו נלקחו ממנו בפורטוגל להמרה כפויה. תאריך פטירתו לפי מלכי ישורון - אלגיר רפ - בערך.","s":"אוצר הרבנים 640; ארזי הלבנון; אלופי יעקב א-רסד; מלכי ישורון-חכמי אלגיר; פין-כנסת ישראל"},{"i":34060,"n":"סבע, אברהם מספרד ותורכיה","k":"בעל צרור המור","b":"רופא ורב באדרינופולי-ש\"כ. יש הסבורים כי הוא ר אברהם מספרד ואלגיר שהגיע לתורכיה. אחיו - ר יצחק-חותנו של ר יוסף קארו.","s":"אוצר הרבנים 640 א'; מלכי ישורון-חכמי אלגיר; פין-כנסת ישראל"},{"i":34061,"n":"סבע, יהודה מרבאט-מרוקו","b":"מחכמי רבאט-שנות התר'.","s":"מלכי רבנן"},{"i":34062,"n":"סבע, יהודה משלוניקי","f":"יצחק משלוניקי או מרו","b":"רב בשלוניקי-שנות ה-תק'.","s":"רוזניס-תורכיה-ה"},{"i":34063,"n":"סבע, יוסף מסאלי-מרוקו","b":"מו\"ץ בסאלי-מרוקו, חתם על פס\"ד-תע, עם ר מרדכי הכהן ור יעקב בן יוסף ביבאס ונזכר ב\"משפט וצבי\".","s":"מלכי רבנן"},{"i":34064,"n":"סבע, יחיא מצפרו-מרוקו","f":"מאיר","b":"מחכמי צפרו-מרוקו-שנות ה-תק'.","s":"מלכי רבנן"},{"i":34065,"n":"סבע, יעקב משלוניקי","b":"מחכמי שלוניקי ומחותמי ההסכמות-שנות הר'.","s":"זכרון שלוניקי; רוזניס-תורכיה-ב"},{"i":34066,"n":"סבע, יצחק מאספי-מרוקו","b":"סופר שטרות מחכמי אספי יחד עם ר יוסף קורקוס, חתם על שטר-תקי. נזכר ב\"שו\"ת רב אדא\".","s":"מלכי רבנן"},{"i":34067,"n":"סבע, יצחק ממכנאס","b":"מחכמי מכנאס-תסה. דרשה ממנו בכת\"י.","s":"ארזי הלבנון"},{"i":34068,"n":"סבע, יצחק מסאלי - הזקן","k":"בעל שופרא דסופרי","b":"רב בסאלי, רבאט בשנות הת-תק. חברם של ר אברהם רודריגז, ר שם טוב ן עטר ור יהודה אנהורי. חיבר \"שופרא דסופרי\" ונדפס בתוך \"חסד ואמת\" שלוניקי תקעג, חיבר גם חדושים בתנ\"ך. חברם של ר אברהם רודריגז, ר שם טוב ן עטר, ר יהודה אנהורי. לפי רוזניס היה מחכמי שלוניקי ונכדו ר יצחק סבע הדפיס את ספרו בסוף החיבור \"חסד ואמת\". בנו - ר יהודה.","s":"ארזי הלבנון; מלכי רבנן; רוזניס-תורכיה-ה"},{"i":34069,"n":"סבע, יצחק מסאלי - הנכד","k":"בעל קרני ראמים","b":"מצאצאי ר אברהם סבע. תלמיד ר משה די אבילא מסאלי, ור אברהם ן צור. רב בסאלי. חיבר \"בית יצחק\", \"חסד ואמת\", \"מקום בינה\" ועוד.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34070,"n":"סבע, יצחק מספרד ואדרינופול","f":"אברהם","b":"רב באדרינופול-רצ. חותנו של ר יוסף קארו בזיוו\"ש ומזכירו ב\"בית יוסף\". לדעת רוזניס - הוא אחיו של ר אברהם בעל \"צרור המור\".","s":"אוצר הרבנים 10856; ארזי הלבנון; פין-כנסת ישראל"},{"i":34071,"n":"סבע, מאיר ממרוקו","b":"רב בצפרו, חתם-תקפג עם ר יהושע ישראל יעקב עולייל ור יהודה אלבז. בנו - ר אליהו.","s":"מתוך קטלוג"},{"i":34072,"n":"סבע, מאיר מפאס","dt":"שעא - ח חשון","dp":"פאס","b":"רב במרוקו. נהרג עק\"ה עם חברו ר יוסף הכהן מפאס, נספד ע\"י ר וידאל הצרפתי. מצאצאי ר אברהם סבע מספרד.","s":"ארזי הלבנון; מלכי רבנן; טולדנו-נר המערב"},{"i":34073,"n":"סבע, מרדכי מפאס","b":"מחכמי פאס-תצז, וחתם על פסקי דין עם חכמי דורו. חתם-תץ עם נסים ן דנאן (לא ידוע מיהו).","s":"ארזי הלבנון; מלכי רבנן"},{"i":34074,"n":"סבע, משה מצפרו-מרוקו","f":"מסעוד","b":"מחכמי צפרו-מרוקו - שנות ה-ת', חתם עם ר יצחק חותא.","s":"מלכי רבנן"},{"i":34075,"n":"סבע, שלמה מצפת","b":"מחכמי צפת, חתם-תקכא על כתב שליחות ר חיים מודעי, ועל כתב שליחות ר אשר קוריאט-תקכג, ועל כתב שליחות ר מרדכי בונאן-תקכד.","s":"גליס; רוזניס-תורכיה-ה"},{"i":34076,"n":"סבע, שמואל מגזילי","b":"רב בגזילי-ליד תירייא - בדור שלאחר הגירוש.","s":"רוזניס-תורכיה-ב"},{"i":34077,"n":"סבע, שמואל ממצרים","b":"רב במצרים-של.","s":"אוצר הרבנים 19289; ארזי הלבנון; רוזניס-תורכיה-ב"},{"i":34078,"n":"סבע, שמואל מקושטא ואדרינופול","f":"יצחק-חותן ר יוסף קאר","dt":"שנג - בערך","b":"רב באדרינופול - ובביתו היתה אסיפת חכמים ובהם ר יוסף קארו - עד שנת רפג, עבר לקושטא. חתם על החרם של ר יוסף ן לב כנגד העיר אנקונא, חתם שני למהריב\"ל, תשובה ממנו ב\"אהלי תם\" לר תם ן יחיא, ובשו\"ת \"נחלה ליהושע\". גיסו של ר יוסף קארו.","s":"ארזי הלבנון; פין-כנסת ישראל; רוזניס-תורכיה-ב,ג"},{"i":34079,"n":"סבעון, אברהם מאלגיר","f":"[משה]","bt":"תר","dt":"תרע - בערך","b":"רב ודיין בווהראן-תרמה אצל ר יעקב דרמון. חתם עם רבני ווהראן על שאלה לשד\"ר ר רחמים פרנקו ב\"שערי רחמים\", ועל מעשה בי\"ד אודות מקום קבורת יעקב עקריש.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34080,"n":"סבעון, חיים מאלגיר","bt":"ש","dt":"שע - בערך","b":"רב במסתגאנם. נזכר אצל הרשב\"ץ האחרון.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34081,"n":"סבעון, משה מאלגיר","f":"מרדכי","bt":"תקסו","bp":"תלמסאן","dt":"תרמח","b":"תלמיד ר משה כנאפו, מחכמי ווהראן-אלגיר. מקובל. אספן ספרים והיו ברשותו למעלה מ-5,000 ספרים. היה במחלוקת כנגד \"זבח שלמים\" לר אברהם אנקאווא - שהשיג על דברי הראשונים, ור אברהם חיבר קונטרס בתגובה ונדפס בתוך \"טהרת כסף\" ליוורנו תרך.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34082,"n":"סבעון, סעדיה מאלגיר","bt":"תקצא","bp":"מסתגאנם","dt":"תרנו","dp":"בלעבאס","b":"רב בבלעבאס-אלגיר.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34083,"n":"סבעון, פתחיה מרדכי מאלגיר","b":"מחכמי והראן-אלגיר-שנות ה-תר.","s":"מתוך קטלוג"},{"i":34084,"n":"סבעוני, אברהם בן משה מאלגיר","f":"ראה: סבעון, אברהם"},{"i":34085,"n":"סבעוני, אברהם ממרוקו","bt":"תריא","b":"רב הכולל בקזבלנקה-תר\"ע","s":"אוצר הרבנים 639"},{"i":34086,"n":"סבעוני, אברהם מפאס-מרוקו","b":"מחכמי פאס-שנות ה-ת'.","s":"מלכי רבנן"},{"i":34087,"n":"סבעוני, אהרן מסאלי-מרוקו","f":"ישועה","k":"בעל ספר דרשות","dt":"תסז","b":"תלמיד ר יצחק אתורקי. מקובל, מחכמי סאלי, ממתנגדי השבתאות במרוקו. בניו: ר ישועה, ר יהודה.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34088,"n":"סבעוני, דוד ממרוקו","f":"אהרן","k":"בעל נאום דוד","b":"דרשן ורב בסאלי-שנו, עבר לפאס. חיבר \"טוב רואי\" בכת\"י והיה בידי אי\"ש הצרפתי. אחיו - ר ישועה.","s":"ארזי הלבנון; מלכי רבנן; טולדנו-נר המערב"},{"i":34089,"n":"סבעוני, יעקב ממראקש","b":"מו\"ץ במראקש, חתם על פס\"ד-תרכג עם ר שמואל יעקב בטאן, ר דוד לוסקי ור אלעזר חזאן. בנו - ר מרדכי בעל \"ישועות יעקב\".","s":"מלכי רבנן"},{"i":34090,"n":"סבעוני, ישועה מסאלי","f":"אהרן","b":"רב בסאלי-שנות ה-ש'. אחיו של ר דוד בעל \"טובי רואי\".","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":34091,"n":"סבעוני, ישעיה ממרוקו","f":"יצחק","b":"שו\"ב במרוקו. נסמך מאת ר יוסף הכהן אלחדד ור שלמה יעקב ן חמו.","s":"מתוך קטלוג"},{"i":34092,"n":"סבעוני, מסעוד ממראקש","k":"בעל ישועות יעקב","b":"רב במראקש- בשנות ה-תר. חיבר גם \"מר דרור\" בכת\"י.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34093,"n":"סבעוני, מרדכי ממרוקו","k":"בעל פרשת מרדכי","b":"רב במרוקו. חיבר גם \"ישועות יעקב\".","s":"ארזי הלבנון"},{"i":34094,"n":"סבעוני, ראובן מאלגיר","bt":"שפ - בערך","dt":"תן - בערך","b":"רב בתלמסאן-תל. יתכן שמקור השם מהעיר שבחא בבל והוא שיבוש של \"אשבחוני\". בנו - ר שלם.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר; מלכי רבנן"},{"i":34095,"n":"סבעוני, שלום (שלם) ממרוקו","f":"ראובן","dt":"תצג - אחרי","dp":"מכנאס","b":"מחכמי סאלי - בשנות ה-ת'. חתם-תץ עם המשבי\"ר, ר יהודה בירדוגו, ר אהרן הצרפתי, ועוד. נזכר ב\"משפט וצדקה ביעקב\". חיבר שיר לחג הפסח.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34096,"n":"סגה, חליל ממשהד-פרס","f":"אליהו","dt":"תשלד","dp":"ישראל","b":"הרביץ תורה במשהד,עלה לא\"י","s":"ארזי הלבנון"},{"i":34097,"n":"סגיל ,יהודה יצחק מוילקוביסק","b":"דיין בוילקוביסק.","s":"ליטא"},{"i":34098,"n":"סגינר, זאב וולף יהודה מדוקלא","dt":"תרמב","b":"מחכמי דוקלא. בנו ר יחזקאל חתנו של ר שלמה ברוך טיטלבוים מסטרופקוב.","s":"וונדר-גליציה ח\"ג"},{"i":34099,"n":"סגל (חזן), חיים מראצק","f":"אברהם","k":"בעל אורח חיים","bt":"תרה","bp":"סלובודקה","dt":"תרעד","dp":"יאנובה","b":"תלמיד ישיבת סלובודקה. רב בסודארג, ראצק-פלך סובאלק, יאנובה-תרנג - כ-30 שנה. פרסם מאמרים ב\"בית ועד לחכמים\", ועוד. רבים מכתביו אבדו בשריפה ביאנובה. נכדו ר אברהם מרדכי פוגרמנסקי שנפטר צעיר.","s":"ליטא"},{"i":34100,"n":"סגל, אברהם מהוצפלוץ","b":"רב בהוצפלוץ-תק\"צ","s":"אוצר הרבנים 649"},{"i":34101,"n":"סגל, אברהם מניישטט","b":"רב בנישטאט,הרב הראשון בווילנא","s":"אוצר הרבנים 644"},{"i":34102,"n":"סגל, אברהם מנמשסלוק","b":"רב בנמשסלוק-תרכ\"ד","s":"אוצר הרבנים 650"},{"i":34103,"n":"סגל, אברהם מקראקא","b":"נכד ר אברהם מוכר ירקות. חתן ר יהושע בעל מגיני שלמה (ולפי המצבה של נכדו ר הלל - נכדו ולא חתנו). רב בלובלין, ראש ופרנס בקראקא-ת'. בניו - ר שמואל (19225), ר מרדכי מלבוב-אביו של הקדוש ר הלל מלבוב. חתניו - ר בנימין זאב וולף מזמיגרד, ר צבי הירש ונכדו ר יהושע פאלק בעל \"פני יהושע\".","s":"אוצר הרבנים 645; בובר-לבוב"},{"i":34104,"n":"סגל, אברהם מקראקא ולבוב","f":"אליעזר","b":"נכד ר אברהם אשכנזי. רב בקראקא, לבוב וראש ישיבה. חתם-תמז על שטר ביריד ירוסלב עם ר פנחס משה ועוד.","s":"אוצר הרבנים 647; מצבות קדש-לבוב; בובר-לבוב"},{"i":34105,"n":"סגל, אברהם מריגליץ","b":"רב בריגליץ","s":"אוצר הרבנים 646"},{"i":34106,"n":"סגל, אברהם מרסנוביץ","b":"רב ברסנוביץ-תק\"צ","s":"אוצר הרבנים 648"},{"i":34107,"n":"סגל, אברהם צבי הירש מקלישצל","b":"רב בקלעשצל(=קלעשצל)-תרע. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן.","s":"אוצר הרבנים 1367; אוצר כתבי עת-לוין"},{"i":34108,"n":"סגל, אהרן זליג מברודי","dt":"תצא - כט טבת","b":"מקובל,מגדולי חכמי ברודי","s":"אוצר הרבנים 1786"},{"i":34109,"n":"סגל, אהרן ישכר בער מלבוב","b":"דיין בלבוב-תקכ\"ב-תקל\"ג","s":"אוצר הרבנים 1821"},{"i":34110,"n":"סגל, אהרן ממילינצא","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - יאסי תרסט.","s":"אוצר כתבי עת-לוין"},{"i":34111,"n":"סגל, אליהו מקובנא ותל אביב","f":"מרדכי יצחק","bt":"1891","bp":"מאריאמפול","dt":"1963","dp":"תל אביב","b":"רופא, פעיל בחוגי הציונים וב\"מכבי\". מנהל סמינר למורים \"תרבות\" בקובנא-1924, הגימנסיה העברית בקובנא-1925. בזמן השואה ניהל את המרפאות בגיטו סלובודקה, היה בדכאו. ניצל מהשואה ואחריה עלה לארץ-1946 והיה רופא בתל אביב. פרסם מאמרים ב\"אונזער עתיד\" של ש.ל. ציטרון, \"הד ליטא\", ועוד. תרגם לעברית \"מחקר בתולדות העם העברי\" לד\"ר מ. דוחובני.","s":"ליטא"},{"i":34112,"n":"סגל, אליעזר","s":"אוצר הרבנים 2560"},{"i":34113,"n":"סגל, אליעזר ליפמן מברודי","k":"בעל בית שלמה","b":"מגדולי חכמי ברוד-תק\"מ","s":"אוצר הרבנים 2698"},{"i":34114,"n":"סגל, אליעזר ליפמן מפרשבורג","b":"מחכמי פרשבורג, חתם-תקטז על הסכמה בפרשבורג עם ר משה חריף, ר עקיבא איגר ועוד.","s":"אבני בית היוצר-וייס"},{"i":34115,"n":"סגל, אפרים הלוי מקויל.","b":"רב בקויל-תקע, חתנו - ר ישכר מצנסטחוב בעל \"פתחי שערים\".","s":"אוצר הרבנים 3055"},{"i":34116,"n":"סגל, בצלאל","b":"רב-שנת תק\"מ","s":"אוצר הרבנים 4021"},{"i":34117,"n":"סגל, ברוך מויליאמפול","b":"מו\"צ בויליאמפול-תקעד לצדו ואולי גם על מקום ר אברהם יעקב וילנר.","s":"אוצר הרבנים 4125; ליפמן-קובנא"},{"i":34118,"n":"סגל, גבריאל משנדובה","f":"יהושע סגל","dt":"תרעב - כא אלול","b":"חתן ר אליהו חיים מייזל מלודז. רב בשנדובה(=שניאדובא), ראב\"ד בלודז. בנו - ר משה מנחם יוסף מלודז.","s":"אוצר הרבנים 4291; אנשי שם-אמריקה"},{"i":34119,"n":"סגל, גדליה מבסקביץ","b":"רב בבסקוביץ-ת\"ק","s":"אוצר הרבנים 4346"},{"i":34120,"n":"סגל, דב בר","f":"אריה הלוי","dt":"תרטו","dp":"ירושלים","b":"חתנו של ר מנחם מנדל משקלוב. ראש השוחטים בירושלים, בשנת תרו בשליחות בליטא. בשנת תריב חתם על תקנת התכשיטים, ובשנת תריג על כתב הסכמה לשוחט.","s":"גליס; ניר לבית הלוי, זכלה ה וט"},{"i":34121,"n":"סגל, דב בריש מצורטקוב","f":"אברהם סגל","b":"רב בצורטקוב-תקע. חתנו - ר יואל כץ מסטניסלב.","s":"אוצר הרבנים 4569; אוסטרהא מד"},{"i":34122,"n":"סגל, דוד הלוי - בעל הט\"ז","f":"שמואל מלודמיר","k":"בעל הט\"ז-טורי זהב","r":"אדמו\"ר מרעדים, ובסוף ימיו גם רב דעיר חדש","bt":"שמז - לפני","bp":"לודמיר","dt":"תכז - כו שבט","dp":"לבוב","b":"מגדולי הפוסקים. נכד-אבי אמו - ר יצחק בצלאלש מלודמיר. תלמיד אחיו ר יצחק הלוי מלודמיר בעל \"חדושי מהר\"י הלוי\" - ומביא ממנו בספרו הט\"ז. חתן ר יואל סירקש בעל הב\"ח. ראש ישיבה בקראקא, רב בפוטיליצא-שעח, פוזן-שעט, אוסטרהא-תא, בפרעות תח נדד בגלות והגיע לאליק וכיהן כרב, רב בלבוב-תיד. חיבר סליחות ליום כו בסיון - שבו ניצל עם קהילת אליק מחמלניצקי. בניו: ר מרדכי מלבוב עק\"ה, ר שלמה מלבוב עק\"ה - נהרגו בעלילה בחיי אביהם-תכד, ר ישעיה, בנו חורגו ר אריה ליב סירקיש - ושניהם נשלחו ע\"י הט\"ז לתהות על קנקנו של שבתאי צבי. חתנו - ר גד ונכדו ר יואל משברשין בעל \"מגיני זהב\", חתנו ר מאיר מאפטא ולובלין.","s":"אוצר הרבנים 4882; אוסטרהא טז; פין-כנסת ישראל; מצבות קדש-לבוב; בובר-זולקוא; בובר-לבוב; שלחן ערוך מהדורת מכון ירושלם בתחילתו, כוכבי אור גליון 860; יומא דהילולא","bk":[["דברי דוד","מפרשי רש\"י"],["ט\"ז",""],["ט\"ז [=טורי זהב]",""],["דברי דוד [על רש\"י עה\"ת]",""],["טורי זהב - ט\"ז -",""],["דברי דוד - טורי זהב",""],["ט\"ז","מפרשי שו\"ע"]],"e":"שמ\"ו-תכ\"ז"},{"i":34123,"n":"סגל, דוד מסערעד","b":"רב בסערעד","s":"אוצר הרבנים 4932"},{"i":34124,"n":"סגל, הלל מסלובודקא","f":"יעקב אליהו מסלובודקה","k":"הצדיק ר הלל","dp":"קעלב","b":"מצאצאי ר הלל מאה\"ו וזולקוא בעל בית הלל. חתן ר שמואל קלמר-אחיו של ר אליהו רגולר. גיסו של ר אריה ליב פרומקין מירושלים. נפטר צעיר.","s":"ליטא; פרומקין-תח\"י"},{"i":34125,"n":"סגל, וולף מטאוואריש ומאנשטאר","b":"שאלה ממנו אל ר ברוך אשר פרלס-תריא ובו כותב כי עבר מטאוואריש למנאשטאר.","s":"מתוך קטלוג"},{"i":34126,"n":"סגל, חיים אריה מדנציג","f":"מאיר","dp":"יארמוט","b":"מגיד בדנציג.","s":"גרינוולד-סלובקיה והונגריה"},{"i":34127,"n":"סגל, חיים יוסף מראטין","f":"יהודה ליב סגל","b":"רב בראטין-תק\"י","s":"אוצר הרבנים 6378"},{"i":34128,"n":"סגל, חיים מיאנוב","k":"בעל אורח לחיים","b":"רב ביאנוב-תרע. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב.","s":"אוצר הרבנים 6086; אוצר כתבי עת-לוין"},{"i":34129,"n":"סגל, חיים שלום מירושלים","b":"פרסם מאמרים ב\"שערי תורה\" - ירושלים תשה, \"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף.","s":"אוצר כתבי עת-לוין"},{"i":34130,"n":"סגל, טויבע מוילנא","k":"בעל גאלדיצקע די מלוה","bt":"1860 - בערך","bp":"וילנא","b":"סוציאליסטית. פרסמה מאמרים בעתונות האידית. חיברה רומן סוציאליסטי הראשון באידיש בהשפעת צרנישבסקי \"גאלדיצקע די מלוה'טע\" וארשא 1883. ?? לא באוצר ??","s":"ליטא"},{"i":34131,"n":"סגל, יהודה","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א.","s":"אוצר כתבי עת-לוין"},{"i":34132,"n":"סגל, יהודה אריה","s":"אוצר הרבנים 7141"},{"i":34133,"n":"סגל, יהודה הלוי מוארשא","f":"יהושע הלוי","dt":"תרפג - כ תשרי","b":"דיין בוארשא. מצאצאי הגר\"א.","s":"אוצר הרבנים 7037"},{"i":34134,"n":"סגל, יהודה זאב מאנגליה","k":"החפץ חיים מאנגליה","b":"רב בליטא, עבר למנצ'סטר-אנגליה. עורר על לימוד ספר חפץ חיים.","s":"מתוך קטלוג"},{"i":34135,"n":"סגל, יהודה זכריה מרדכי חיים","bt":"תרפד","dt":"תשסא","b":"פוסק ומקובל, מקורב לחזון איש ולרב שך.","s":"מתוך קטלוג"},{"i":34136,"n":"סגל, יהודה זרחיה מתל אביב","k":"בעל צמח יהודה","r":"רב בקרית שלום בתל אביב","bt":"תרפד","dt":"תשסא - ט אדר","b":"רב שכונת \"קרית שלום\" בתל אביב. חיבר גם \"ראשית העבודה\", \"משפטי החן\", ועוד.","s":"מוריה 24-א-ב; תוספת להמודיע כו אייר תשעה עמודים כח - כט - ויתילדו מאמר 191","bk":[["ברורים בגדרי מנהגי העדות השונות",""],["חידושי רבי יהודה זרחיה - חידושים וביאורים בסוגיות הש\"ס הערות והארות",""],["משפטי החן - נושאי הלכה לפי סדר התורה",""],["צמח יהודה - ש\"ס ושו\"ע",""],["ראשית העבודה - למשתוקקים בעבודת ה' בראשית דרכם מתוך ספרי המוסר והחסידות",""]]},{"i":34137,"n":"סגל, יהודה ליב מדרוהוביטש","f":"יקותיאל זלמן הלוי","b":"רב בדראביטש,עיר חדש-תק\"ו","s":"אוצר הרבנים 7353"},{"i":34138,"n":"סגל, יהודה ליב מקשונו ומאקובה","dt":"תקפד - יט אייר","b":"מלמד באויבן (אצל ר אברהם ר גימפל), רב במאקעווע(=מאקובה)-תקמא. היה מתומכי ר יצחק גריסהאבר במחלוקתו עם אהרן חורין. נזכר ב\"שריון קשקשים\" לחארין(=חורין), וב\"נודע ביהודה\".","s":"אוצר הרבנים 7355; גרינוולד-סלובקיה והונגריה"},{"i":34139,"n":"סגל, יהודה ליב משידלוב","b":"רב בשידלוב","s":"אוצר הרבנים 7352"},{"i":34140,"n":"סגל, יהושע השל הלוי מקידאן","f":"גטשליק מאונגריש ברוד","b":"חתן ר ישכר בר הכהן מהמבורג. רב בקידאן-תק.","s":"אוצר הרבנים 7723; דוקס-אוה למושב"},{"i":34141,"n":"סגל, יואל ממטרסדורף","b":"דומ\"צ במטרסדורף-תר\"י","s":"אוצר הרבנים 7850"},{"i":34142,"n":"סגל, יוחנן מלבוב","b":"ראב\"ד בלבוב-ש\"צ","s":"אוצר הרבנים 7908"},{"i":34143,"n":"סגל, יוסף מלבוב","f":"משה חריף סגל","b":"מרביץ תורה בלבוב-תפח. (ראה גם יוסף חריף סגל מלבוב ופרמישלא).","s":"אוצר הרבנים 8467"},{"i":34144,"n":"סגל, יוסף ממיטאוי","f":"אליה","b":"תלמיד ביהמ\"ד לרבנים בברלין. רב מטעם במיטאוי-תרנח, עזב תרסג ונסע להשתלם במדעים.","s":"אובצינסקי-קורלנד"},{"i":34145,"n":"סגל, יוסף משיקגו ונס ציונה","k":"בעל חזון יוסף","bt":"תרמה","dt":"תשלד - א אייר","b":"רב בבזין,שיקאגו-תרפ\"ב,נס ציונה-תרפ\"ז,ארה\"ב,עלה לירושלים-תשכ\"א","s":"אוצר הרבנים 8468"},{"i":34146,"n":"סגל, יחיאל מיכל מקאליש","k":"בעל שערי שמים","b":"רב בקאליש-תי. חיבר \"שערי שמים\" ובו חדושים מאביו, ומדודו זקנו - המהרש\"א.","s":"אוצר הרבנים 9300; פין-כנסת ישראל"},{"i":34147,"n":"סגל, יעקב אליהו מסלובודקא","f":"אורי הלוי","b":"תלמיד ר אליהו רגולר. רב בסלובודקא(=ויליאמפול)-תרי על מקום רבו שעבר לקאליש ומפני כבוד רבו סירב להיקרא רב העיר אלא מו\"צ לעדת סלובודקה. הסכים על \"דבר חיים\". מחותן עם ר שמואל קלמר-אחיו של רבו - בנו ר הלל היה חתנו של ר שמואל. בנו גם - ר משה דעס רבס. הסמיך את הרבנים - ר אריה דב וולפרט מוילקי, ר נח ויינר מנובוגרוד, ר שמואל רפפורט מרגולה וארה\"ב, ועוד.","s":"אוצר הרבנים 10005,9784; ליטא; ליפמן-קובנא"},{"i":34148,"n":"סגל, יעקב ברוך","f":"יהודה סגל","b":"רב בנעאפול-שנת ש'","s":"אוצר הרבנים 10031"},{"i":34149,"n":"סגל, יעקב מלובזניץ","k":"בעל שם יעקב","b":"מו\"צ בלובזניץ-ת\"נ","s":"אוצר הרבנים 9785"},{"i":34150,"n":"סגל, יעקב מפיטלנגן","f":"מיכאל","k":"בעל באר שבע","b":"ש\"ץ בפיטלנגן-אלזס-תקפז. חיבר \"באר שבע\" לזכר שבעת ילדיו - בכת\"י.","s":"מתוך קטלוג"},{"i":34151,"n":"סגל, יצחק איזיק מאשכנז","b":"מגדולי חכמי אשכנז,מרביץ תורה בנוישטט-ר\"כ","s":"אוצר הרבנים 10859"},{"i":34152,"n":"סגל, יצחק איזיק מלובלין","f":"יהודה אריה סגל","b":"רב בלובלין-תפ\"ד","s":"אוצר הרבנים 11199"},{"i":34153,"n":"סגל, יצחק מדוברומיל","f":"יהושע הלוי","b":"רב בדוברומיל-תק\"י","s":"אוצר הרבנים 10858"},{"i":34154,"n":"סגל, יצחק מוילנא","f":"ברוך","bt":"תרז","dt":"1891","dp":"ריגא","b":"גביר בוילנא. קונסול צרפת בוילנא.","s":"עיר וילנא ח\"ב"},{"i":34155,"n":"סגל, יצחק מלמברג","b":"רב בלבוב-תס\"ד","s":"אוצר הרבנים 10860"},{"i":34156,"n":"סגל, יצחק מניו יורק","f":"חיים הלוי","bt":"תרלח","bp":"האלוסק-פלך מינסק","b":"תלמיד ר זאב וולף מבוברויסק, ר ברוך דב ליבוביץ מקובנא, כולל קובנא. נסמך מאת: ר ח\"ל ליטווין בעל \"שערי דעה\", ר משה דנישבסקי, ר ברוך בר ליבוביץ, ר משה שמואל שפירא מבוברויסק, ר שלמה זלמן לנדא מהלוסק, ר ברוך דב ליבוביץ. דרשן, רב בקהלת \"זכרו תורת משה\" בניו יורק-תרסו, באיאן-ניו ג'רזי-תרסט. מנשיאי אגודת הרבנים בארה\"ב, ממיסדי חברת \"מחזיקי הדת\" בארה\"ב. לזכרו \"הלכות יצחק\" תשלט ובו תשובות ממנו וחלופי מכתבים.","s":"אוצר הרבנים 10863; אמריקה; אהלי שם; אנשי שם-אמריקה"},{"i":34157,"n":"סגל, יצחק מסקולקה","k":"יצחק סקולקר","b":"תלמיד חבר לר שמעון שקופ, ונחשב לאחד מגדולי עולם התורה הליטאי. חתן ר נחום גרינהוז. רב בסוקולקה(=סקולקה)-ליטא-תרס. בנו - ר שלמה שוסטר מארה\"ב.","s":"אוצר הרבנים 10862; מוריה 24-ז-ט"},{"i":34158,"n":"סגל, יצחק מפרג","b":"דיין מו\"ש בפרג-תס\"א","s":"אוצר הרבנים 10857"},{"i":34159,"n":"סגל, יצחק מצאבלן","dt":"תשג","b":"רב בצאבלן","s":"אוצר הרבנים 10861"},{"i":34160,"n":"סגל, יצחק מקאמעריד","dt":"תרסה","b":"רב בקאמערייד","s":"אוצר הרבנים 10864"},{"i":34161,"n":"סגל, יצחק שמעון","dt":"תקעג - כ טבת","b":"מו\"צ בווילנה","s":"אוצר הרבנים 11507"},{"i":34162,"n":"סגל, ישעיה הלוי מלבוב","f":"דוד - הט\"ז","b":"מגדולי חכמי לבוב-ת\"כ,רב בקומרנא-תכ\"ו. אביו שלחו יחד עם אחיו חורגו ר אריה ליב סירקיש בעל \"שאגת אריה\" לתהות על קנקנו של ש\"ץ.","s":"אוצר הרבנים 11737; אוסטרהא טז-ד; רוזניס-תורכיה-ד; בובר-לבוב"},{"i":34163,"n":"סגל, ישראל","f":"מרדכי סגל","b":"רב-שנת ת\"ק","s":"אוצר הרבנים 12006"},{"i":34164,"n":"סגל, ישראל מוינה","b":"מקובל,מרביץ תורה בווינה-עד הגירוש(ת\"ל),רב בברודא,מדינת וירצבורג-תנ\"ו","s":"אוצר הרבנים 12004"},{"i":34165,"n":"סגל, לזר מליטא וברזיל","bt":"1889","bp":"וילנא","dt":"1957","b":"צייר ואומן. למד בברלין ופאריס. היגר לברזיל. מיצירותיו: \"קדיש\", \"זכרונות מוילנא\", ועוד.","s":"ליטא"},{"i":34166,"n":"סגל, ליב מלודמיר","b":"מופת הדור,רב בלודמיר-שנת ת'","s":"אוצר הרבנים 12601"},{"i":34167,"n":"סגל, ליפמן מצילץ","b":"רב בצילץ-תק\"מ","s":"אוצר הרבנים 12695"},{"i":34168,"n":"סגל, מאיר","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":34169,"n":"סגל, מאיר מדוברומיל","b":"רב בדוברומיל","s":"אוצר הרבנים 12913"},{"i":34170,"n":"סגל, מאיר מחיפה","b":"פרסם מאמר ב\"אוהל יוסף\" נ\"י תשו, \"תבונה\" - ירושלים תשא-תשח.","s":"אוצר כתבי עת-לוין"},{"i":34171,"n":"סגל, מאיר מליסא","f":"אליעזר ליברמן","k":"בעל מאיר השחר","b":"רב בזבארטין, דיין בליסא-תק. בנו - ר חיים אריה מגיד מדנציג.","s":"אוצר הרבנים 12912; גרינוולד-סלובקיה והונגריה"},{"i":34172,"n":"סגל, מאיר מפרג","f":"יחזקאל סגל","k":"בעל דברי מאיר","b":"רב בפרג-תק\"ס","s":"אוצר הרבנים 12944"},{"i":34173,"n":"סגל, מנחם מנדל מהורדנא","b":"מגיד בהורדנא-תצ\"א","s":"אוצר הרבנים 13500"},{"i":34174,"n":"סגל, מרדכי אריה ליב מאדלסק","f":"אברהם צבי מקלשצל","bt":"תרמא-ג","b":"אב\"ד באדלסק-תרסח, וואלפא. חתם על הקמת ועד הישיבות מיסוד החפץ חיים ור חיים עוזר.","s":"אוצר הרבנים 14079; אהלי שם"},{"i":34175,"n":"סגל, מרדכי הלוי מלבוב","f":"דוד - הט\"ז","dt":"תכד - ח אייר","b":"מגדולי חכמי לבוב. נהרג עק\"ה בחיי אביו.","s":"אוצר הרבנים 13956 א'; אוסטרהא טז-ד; מצבות קדש-לבוב"},{"i":34176,"n":"סגל, מרדכי מוואלפא","dt":"תשג","b":"רב בוואלפא","s":"אוצר הרבנים 13957 א'"},{"i":34177,"n":"סגל, מרדכי מטיסמניץ - א","f":"משה הלוי","b":"מגדולי דורו,ראש מדינה בטיסמניץ-ת\"ע","s":"אוצר הרבנים 13956 ב'"},{"i":34178,"n":"סגל, מרדכי מסמניץ","b":"דומ\"צ בסמניץ-תר\"י","s":"אוצר הרבנים 13955"},{"i":34179,"n":"סגל, מרדכי מצפת","b":"גביר בצפת-תרלב, יסד את ביה\"ח הראשון בצפת.","s":"מתוך קטלוג"},{"i":34180,"n":"סגל, משה חיים מאנגליה","bt":"תרלו","bp":"קובנא","b":"תלמיד ישיבות ליטא, ד\"ר מאוני' אוקספורד. רב באוקספורד-תרסב, ניו קסל-תרע. חיבר באנגלית \"קרבת לשון המשנה...\".","s":"אוצר הרבנים 15403; אהלי שם"},{"i":34181,"n":"סגל, משה יונה מטשעבין","b":"רב בטשעבין-תר\"מ","s":"אוצר הרבנים 15458"},{"i":34182,"n":"סגל, משה יצחק מליבאוי וסאסמקן","f":"משלם זלמן הלוי","k":"בעל חדושים על הש\"ס","bt":"תקעב","bp":"ראסיין","dt":"תרל","dp":"יאנוסטוב","b":"תלמיד ר אליהו רגולר מקאליש. רב בססמקן(=סאסמקין)-קורלנד ור משה לרנבלאט על מקומו אחריו, וינדאו, גולדינגן, שוואקשנה-תרכד, קראטינגה, טאווריג, ליבאוי ור צבי הירש בורנשטין על מקומו אחריו (לבקשתו של ר משה יצחק), פלונגיאן, פוניבז, פולנגן, אוגוסטוב(=יאנוסטוב). היה במחלוקת עם הגבירים שפגעו בעניים, ולכן נרדף ע\"י ראשי הקהל ונאלץ להשלים הכנסתו במסחר, וכשטענו נגדו רבנים שהוא פוגע בכבוד התורה אמר \"מוטב שאקבור את הרבנות משאקבר על ידה\". בנו - ר שלמה הלוי, וחתניו: ר זאב דב ליפשיץ בעל \"רוח חיים\", ר תנחום שרגא רבל מלינקובה, ר כתריאל נתן אהרן מקורשאן בעל \"כתר המלך\".","s":"ליטא; אובצינסקי-קורלנד; מרקוביץ-ראסיין"},{"i":34183,"n":"סגל, משה מלבוב","dt":"תעט - כז אלול","b":"ראש ומנהיג בלבוב","s":"אוצר הרבנים 14960"},{"i":34184,"n":"סגל, משה ממינסק וזברז","f":"לעמל","dt":"תנו","b":"רב במינסק, זבאריז. אולי הוא חתן אלמנת ר משה כץ בנו של בעל הש\"ך. חתנו - ר יצחק הכהן (10726). (ראה גם: ז\"ק, משה בן מרדכי הקדוש ממינסק)","s":"אוצר הרבנים 14958; פין-קריה נאמנה"},{"i":34185,"n":"סגל, משה מנחם יוסף הלוי מלודז","f":"גבריאל מלודז","bt":"תרלה-ו","bp":"לודז","dt":"תשב","b":"דיין בלודז-תרס\"ה,ראב\"ד בועד הרבנים שם-תרעד. פרסם מאמרים ב\"חידושי תורה\" - לודז תרצו - קובץ חבורת בני ישיבת מיר בלודז.","s":"אוצר הרבנים 15558; אוצר כתבי עת-לוין"},{"i":34186,"n":"סגל, משה מקראקא","dt":"שכז - יט אדר","b":"מרביץ תורה בקרקא","s":"אוצר הרבנים 14959"},{"i":34187,"n":"סגל, משה צבי מליטא וירושלים","f":"אליעזר","k":"בעל \"מבוא המקרא\"","bt":"1876","bp":"מאיסיאד-ליד טלז","b":"תלמיד ישיבת סלנט, פלונגיאן. עבר ללונדון ולמד שם. חתן ר אריה ליב פרומקין. מורה באוכספורד לבלשנות שמית ומדעי המקרא. רב בניו קסל-תרסט, סואנזי, בריסטול. מראשי התנועה הציונית באנגליה. חבר \"ועד הצירים\" בירושלים-תרעח, ועמד בראשו-תרעט. מרצה באונ' העברית בירושלים-תרפו למשנה ומקרא. חבר ועד הלשון העברית. פרסם מחקרים וספרים בעברית ובאנגלית, ובהם פירוש לספר שמואל-תרעט, \"דקדוק לשון המשנה\", ועוד. סייע בעריכת מילון בן יהודה הגדול. וחיבר מילון עברי אנגלי.","s":"ליטא"},{"i":34188,"n":"סגל, נח גבריאל","b":"רב-שנת תקע\"ה","s":"אוצר הרבנים 15829"},{"i":34189,"n":"סגל, נפתלי יצחק מלבוב","f":"אריה יהודה ליב","k":"בעל נפתלי שבע רצון","dt":"שטז - יט חשון","dp":"לבוב","b":"רב בלבוב","s":"אוצר הרבנים 16250; בובר-לבוב; מבשר ואומר יט חשון תשעד","bk":[["נפתלי שבע רצון",""]]},{"i":34190,"n":"סגל, פייטל","b":"רב-שנת תק\"ס","s":"אוצר הרבנים 16842"},{"i":34191,"n":"סגל, צבי הירש מאטש","b":"רב באטש-תק\"פ","s":"אוצר הרבנים 17385"},{"i":34192,"n":"סגל, צבי הירש מזיטומיר","k":"בעל ילקוטי צבי","bp":"קובנא","dp":"זיטומיר","b":"מורה לתלמוד בביהמ\"ד לרבנים בזיטומיר-במאה ה-19. מיזג חסידות והשכלה והיה מחסידי ר יהושע השל מאפטא. בקי בספרות רבנית ודובר צרפתית וגרמנית. א.צ. צוויפל הו\"ל מתורתו בשם \"ילקוטי צבי\".","s":"ליטא"},{"i":34193,"n":"סגל, צבי הירש מנאמנסדורף","b":"רב בנאמנסדורף-תקצ\"ט","s":"אוצר הרבנים 17386"},{"i":34194,"n":"סגל, רפאל מזקרטשין","f":"אפרים סגל","b":"רב בזאקראטשין-ת\"ר","s":"אוצר הרבנים 17861"},{"i":34195,"n":"סגל, שלום יצחק הלוי מטרסטינא","bt":"תרלב","dt":"תרצו - ב סיון","b":"בקי,רב בסופראסל-תרנ\"ו,טרסטינא-תרע\"ו","s":"אוצר הרבנים 18256"},{"i":34196,"n":"סגל, שלמה הלוי מלבוב","f":"דוד - הט\"ז","dt":"תכד - ח אייר","b":"מגדולי חכמי לבוב. נהרג עק\"ה בחיי אביו.","s":"אוצר הרבנים 18486; אוסטרהא טז-ד; בובר-לבוב"},{"i":34197,"n":"סגל, שמואל מליסא","f":"בועז","k":"בעל רמת שמואל","b":"דיין בליסא-תמ.","s":"אוצר הרבנים 19290"},{"i":34198,"n":"סגל, שפטל מטיפליס ותל אביב","bt":"תרמז","dt":"תשטז - כג חשון","b":"ר\"מ בטיפליס,עלה לתל אביב","s":"אוצר הרבנים 18077"},{"i":34199,"n":"סגלוביץ, יחיאל משה ממלאווא","f":"חיים","bt":"תרכג","b":"ר\"מ בספטקין(=סאפאטקין)-פלך סובאלק-תרמז, מלאבה(=מלאווא)-פלך פלאצק-תרסג. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט. מעורכי \"קובץ דרושים\" - פיעטרקוב תרפג. מתורתו בספר אביו \"מקור חיים\", וב\"מאסף דרושים\" לאחיו ר יעקב מאיר, וב,נטעי איתן\" לר אברהם זקהיים מואליא.","s":"אוצר הרבנים 9332; אוצר כתבי עת-לוין; אהלי שם"},{"i":34200,"n":"סגלוביץ, יחיאל משה מרובזביץ","b":"תלמיד ר חיים מוולוזין. רב ברובזביץ(=רובזעוויץ)-תר\"י","s":"אוצר הרבנים 9331"},{"i":34201,"n":"סגלוביץ, יעקב מאיר מהרודישץ","f":"חיים","k":"בעל מאסף דרושים","bt":"תרלט","dt":"תשד - ד שבט","dp":"[ניו יורק]","b":"נכד ר בנימין יעקב מהרודישץ. רב בפודבריזה(=פאדבערעזיע)-פלך וילנא, הורודשיץ(=הראדישיץ)-פלך מינסק, טוואר, דנציג, בריסל, ניו יורק. הו\"ל \"מאסף דרושי\" - וילנא תרסט. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט.","s":"אוצר הרבנים 10216; אמריקה; אוצר כתבי עת-לוין; אהלי שם"},{"i":34202,"n":"סגלמסי, יהודה","f":"יוסף הנגיד","b":"פייטן מחכמי צפון אפריקה-שנות ה-ק', בנו של ר' יוסף הנגיד,ראש הסדר וראש כלה בקיירואן בזמן רב האי גאון. חיבר סליחה במחזור מנהג תלמסן \"אלה כוכבי מרום..\".","s":"ארזי הלבנון; פין-כנסת ישראל"},{"i":34203,"n":"סגן הכהן, יעקב מברוד","dt":"תרמא","b":"מחכמי ברודי, רב במיקוליניץ, בוצאץ על מקום ה\"חסד לאברהם\" והמהרש\"ם שבא להספידו על מקומו אחריו.","s":"וונדר-גליציה ח\"ג"},{"i":34204,"n":"סגרון, כמוס מג'רבה","k":"בעל וסמך ידו","bt":"תרעח","dt":"תשנה - טו כסלו","dp":"באר שבע","b":"מחכמי ג'רבא, עלה לארץ והתישב בבאר שבע.","s":"ארזי הלבנון"},{"i":34205,"n":"סגרון, מרדכי מג'רבה","k":"בעל דברי מרדכי","dt":"תשל","dp":"טבריה","b":"תלמיד ר דידו (דוד) הכהן מתונס. רב במדנין-תונס, תאטאוין. חיבר גם \"מאמר מרדכי\", \"גדולת מרדכי\" ועוד. פרסם מאמרים תורניים ב\"כתר תורה\" ו\"הירח\" שיצאו לאור בג'רבא. עלה לארץ וכיהן כרב במושב זמרת. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"הירח\" - ג'רבה תשח, \"מקבציאל\" - גרבה תרצה.","s":"ארזי הלבנון; אוצר כתבי עת-לוין","bk":[["וישב מרדכי",""]]},{"i":34206,"n":"סגרי - משפחה","b":"משפחת רבנים מאיטליה.","s":"גאון-יהודי המזרח"},{"i":34207,"n":"סגרי, אברהם מאלכסנדריה","dt":"תד","b":"דיין באלכסנדריה","s":"אוצר הרבנים 653"},{"i":34208,"n":"סגרי, אברהם מטורינו וירושלים","f":"יהודה","bt":"תמה","bp":"טורינו-איטליה","dt":"תקלב","dp":"ירושלים (ולא טורינו)","b":"מחכמי איטליה, בשנת תע עלה לטבריה, ואחר כך דיין בצפת, חתן ר ישראל אשכנזי מצפת, נולדו לו 9 בנים ו-2 בנות, אחד מבניו ר ישראל בעל \"תפארת ישראל\" \"עטרת ישראל\" ועוד. בשנת תקיח בזמן הרעש בצפת היה בשליחות, ואחר כך עבר לירושלים. חיבר פירוש על המשניות, הרמב\"ם ועוד. בנו ר ישראל סגרי בעל \"תפארת ישראל\" - נהרג ברעש בצפת - ואחריו נולד לר אברהם בן נוסף ונקרא ר ישראל רפאל שהיה בשליחות בפדובה-תקסט.","s":"גליס; איטליה גירונדי-א מט; אוצר הרבנים 655; פין-כנסת ישראל; שם הגדולים השלישי; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה; דעת קדושים לווינר ועוד"},{"i":34209,"n":"סגרי, אברהם מקסאלי","f":"יהודה","k":"רב אס\"י-בעל בקשה יפה","bp":"טורינו","dt":"תקב - אחרי","dp":"טורינו","b":"רב בקסאלי. תלמיד מהר\"י בריאל. חברם של מהרב\"ך-ר בנימין הכהן מריגיו, ר שבתי אלחנן מהזקנים, ר גור אריה פינצי ממנטובה ור יוסף אירגס מליוורנו. תשובה ממנו ב\"דברי שלום ואמת\" להרר\"ק. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה. חתם שמו על הספר \"דברי יוסף\" - ליוורנו תקב - ומכאן שנפטר אחרי הדפסת הספר. חיבר \"בקשה יפה לזמן המגפה\" בתוך מחזורי אשכנז. נכדו - ר יצחק רפאל פינצי מפדובה.","s":"אוצר הרבנים 654; איטליה גירונדי-א ט,יא; אוצר כתבי עת-לוין; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":34210,"n":"סגרי, זכריה","b":"מחכמי ורבני איטליה","s":"ארזי הלבנון"},{"i":34211,"n":"סגרי, חיים ישראל רפאל - רי\"ח","f":"אברהם מצפת","k":"בעל עטרת ישראל","bp":"ירושלים","dt":"תקצג - כג טבת","dp":"ירושלים","b":"נכד ר ישראל אשכנזי מפולין וצפת. דיין בירושלים, בבית דינו של הרב סוזין. חתם בשם \"רי\"ח סגרי\", בשליחות טבריה באשכנז ואיטליה, בשנים תקס-תקסט ובתקעו וביקר כמאתיים וחמשים קהלות, חתם עם רבני ירושלים בשנים תקפא-תקפט. פנקס שליחותו בביהמ\"ד לרבנים בניו יורק (12273). חיבר \"תפארת ישראל\" \"עטרת ישראל\" ועוד בכתב יד. בתרביץ ט מוכח כי הוא אינו ר ישראל חיים רפאל סגרי שנפטר בשנת תקעג, ושהיה כפי הנראה בן משפחתו. בשליחות טבריה במערב אירופה מטעם קהילת הספרדים והאשכנזים. נזכר ב\"אביר יעקב\" לר יעקב שבתי סיניגאליאה. בנו - ר יהודה מטבריה.","s":"גליס; ארזי הלבנון; אוצר הרבנים 12200; איטליה גירונדי-י נ; פרומקין-תח\"י; שא\"י"},{"i":34212,"n":"סגרי, חיים מאיטליה","k":"בעל בנין אב","b":"אבי משפחת רבנים ובנקאים באיטליה. רב בפאדובה-תמ, ורצ'ללי. בראש משלחת רבנים לטורקיה לבדוק אחר שבתי צבי-תכו. חיבר \"בנין אב\" בכת\"י. היה מחלוקת בינו לר יעקב חזק מפדובה על סדר התקיעות. בנו - ר אלישע מוירצילי, ונכדו ר יהושע בן ציון מוירצילי, ומבניהם - ר יהושע בן ציון סגרי - אחד הרבנים שעמדו באסיפת הרבנים בפאריז-תקסז.","s":"איטליה גירונדי-ח ו; אוצר הרבנים 6088; ארזי הלבנון; פין-כנסת ישראל"},{"i":34213,"n":"סגרי, טודרוס מאיטליה","b":"מרביץ תורה בפיימונטי-תכ\"ד","s":"אוצר הרבנים 6773; ארזי הלבנון"},{"i":34214,"n":"סגרי, יהודה מטבריה","f":"ישראל","bt":"תקטו","bp":"צפת","dt":"תקפד","dp":"טבריה","b":"מחכמי טבריה, בשנת תקמה חתם על כתב שליחות ר חיים ישראל סגרי. בשנת תקן שליח בצפון אפריקה, ומשם מכתבים ממנו.מכתב בשבחו של ר יהודה ב\"אוצר גנזים\" לי. טולידנו (לדעתו של טולידנו נכתב על ידי ר רפאל ברדוגו). נספד בספר \"תהלה לדוד\".","s":"גליס; אוצר 7039; ירושלים ו, ריבקינד \"ציון\" ה-ו."},{"i":34215,"n":"סגרי, יהודה מירושלים","f":"אברהם","b":"מגדולי חכמי ירושלים-תק\"מ","s":"אוצר הרבנים 7038; ארזי הלבנון"},{"i":34216,"n":"סגרי, יהושע מסקנדיאנו וקסאלי","k":"בעל בקרת איסור","bt":"תסט","dt":"תקנז-ע -כו ניסן","dp":"סקאנדייאנו","b":"תלמיד ר יהודה בריאל, ר גור אריה פינצי במנטובה, דודו ר אברהם בקסאלי. דיין בוורסליה(=וירצעלי), חזן ומלמד בסקנדיאנו-נסיכות פדובה. חיבר \"בקרת איסור\", \"שר הטבחים\", ועוד. ראש בית הדין בפריז-תקסו, מחברי הסנהדרין של נפוליאון (ויש אומרים שזו טעות כי נפטר קודם לכן). נספד בפדובה ע\"י ר יצחק רפאל פינצי. (עליו מאמר בניהו ב\"אסופות-כרך י).","s":"אוצר הרבנים 7599; איטליה גירונדי-י ריז; פין-כנסת ישראל"},{"i":34217,"n":"סגרי, יעקב","k":"בעל עזר יעקב","dt":"תנא - כד אד\"ב","b":"גדול בתורה ופיוט,מחכמי איטליה בצינטו","s":"אוצר הרבנים 9787; אוצר הרבנים 9786"},{"i":34218,"n":"סגרי, ישראל חיים רפאל - יר\"ח","f":"ראה גם: סגרי, חיים","dt":"תקעג - כג טבת","dp":"ירושלים","b":"מחכמי טבריה, ואינו רי\"ח סגרי בעל \"עטרת ישראל\" אלא בן משפחתו.","s":"ארזי הלבנון; פרומקין-תח\"י; תרביץ ט."},{"i":34219,"n":"סגרי, משה אליעזר","b":"מגדולי חכמי איטליה-תע\"ה","s":"אוצר הרבנים 15291"},{"i":34220,"n":"סגרי, נתנאל מציינטו-איטליה","f":"אהרן יעקב","k":"בעל אפר יצחק","bp":"קיירי - סאבוי","dt":"תנא - כא אד\"ב","dp":"ציינטו","b":"הגיע מהעיר קיירי (במלכות סאבוי), רב בציינטו-איטליה. חיבר \"עפר יעקב\" בכת\"י (אצל הגביר דוד כהן מאיטליה). תשובות ממנו ב\"פחד יצחק\".","s":"אוצר הרבנים 16487; איטליה גירונדי-נ ב; ארזי הלבנון"},{"i":34221,"n":"סגרי, רפאל ברוך מאיטליה","b":"מחכמי איטליה-תק\"פ","s":"אוצר הרבנים 17857"},{"i":34222,"n":"סגרי, רפאל מירושלים","b":"מקובל,מרבני ירושלים-ת\"ס","s":"אוצר הרבנים 17823"},{"i":34223,"n":"סדבון, יוסף","k":"בעל אהבת השם","b":"חיבר \"אהבת השם\" ליוורנו תרלא."},{"i":34224,"n":"סדובסקי, שלמה מארה\"ב","f":"ליב יעקב מרוגאצ'וב","k":"בעל פרפראות לחכמה","bt":"תרם","bp":"רוגאצ'וב","b":"רב באולבני-ניו יורק-תרסה, רוצ'סטר-תרע. חיבר גם \"דרוש עשרת הדברות\", ועוד."},{"i":34225,"n":"סדין, יצחק מניו יורק","f":"קלמן","k":"בעל תולדות יצחק","bt":"תרנז","bp":"פוניבז","b":"תלמיד ישיבת פוניבז אצל ר כתריאל, ר נפתלי הרץ קרצמער בעל \"נועם המצות\". היגר לארה\"ב-תרעד ולמד בישיבת \"רבי יצחק אלחנן\". נסמך מאת: ר שמואל צבי וין מויזון, ר אברהם אהרן יודלביץ מקאפוליה. רב קהלת אנשי קולוד בניו יורק-תרעז, קהלת \"בני אברהם\" ואוסטר-מסצוסס-תרפא, קהלת \"אוהב שלום\" בניו יורק-תרפב, קהלת \"אספת ישראל\"-תשו, ו\"בית שלום\"-תשח. חתן ר שלמה יצחק ליברברג. חבר אגודת הרבנים באמריקה, ותנועת המזרחי.","s":"אוצר הרבנים 10866; אמריקה; אנשי שם-אמריקה"},{"i":34226,"n":"סדיקראו, משה מפאס","b":"מחכמי פאס-שנות ה-ר'. מתלמידיו - ר שמואל ן דנאן.","s":"מלכי רבנן"},{"i":34227,"n":"סדרא - חכמי הסדרא מספרד ואלגיר","b":"חסידים קדמונים ממסתגאנם שהגיעו מספרד עם הריב\"ש והרשב\"ץ - לא ידועים שמותיהם ונקברו במסתגאנם ונקראים חכמי אסזרא - מקום קברם מקודש ונהגו לערוך הילולא בל\"ג בעומר על קברם.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34228,"n":"סדרסקי, דוד מפאריס","b":"פרסם מאמרים ב\"היהודי\" - נ\"י תרצו - על ר ישראל סלנטר.","s":"אוצר כתבי עת-לוין"},{"i":34229,"n":"סהל ן, אברהם מולנסיה","k":"בן סהל אבו אסחק","b":"פייטן ומשורר בולנסיה-ספרד-ה'א. חיבר שירים בערבית. (יש מסופרי הערבים שאומרים שהמיר את דתו ואחרים מכחישים, יש אומרים שטבע בים).","s":"אלופי יעקב א-רמג"},{"i":34230,"n":"סהל ן, יוסף","dt":"ד'תתפד","b":"גדול בתורה ושירה,דיין בקורדובה","s":"אוצר הרבנים 8469"},{"i":34231,"n":"סהל ן, יצחק מאלגיר","bt":"ד' תשל","dt":"ד'תת","b":"רב בתלמסאן (הראשון הידוע מרבני העיר). פגש את ר יונה ן גאנח וסיפר לו על שראה במצרים.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34232,"n":"סהלא ן, דונש","f":"תמים","b":"חיבר חיבורים ברפואה, תכונה, ודקדוק, מקובל פירסם חיבור לספר היצירה","s":"ארזי הלבנון"},{"i":34233,"n":"סהלא ן, יצחק מספרד","f":"שלמה","k":"בעל משל הקדמוני","bt":"ד (1244)","bp":"ספרד","b":"תלמיד המקובל ר משה מבורגוס. מחכמי גואדלאחרה. חברו של ר משה די ליאון. חיבר פירוש לשיר השירים, משל הקדמוני עם איורים ממנו, ועוד.","s":"ארזי הלבנון; איטליה גירונדי-י ריג; פין-כנסת ישראל"},{"i":34234,"n":"סהלא ן, מאיר מספרד","f":"שלמה","b":"תלמיד הרשב\"א. רב ומקובל באלמאגרה-ספרד. יש אומרים שחיבר פירוש סודות הרמבן על התורה. חיבר פירושים למשנה ולספר יצירה. נזכר בתשובות הרשבא. אחיו - המקובל ר יצחק ן סאלה.","s":"ארזי הלבנון"},{"i":34235,"n":"סואבי, משה זלמן מאיטליה","f":"יעקב חי","b":"מראשי קהלת דוכסות פארמה-תקיח עם ר אברהם מיכאל פונטאנילה.","s":"מתוך קטלוג"},{"i":34236,"n":"סואיא, נסים הכהן מירושלים","b":"מחכמי ירושלים-תשמא. ראש ארגון \"כסא שלמה\" להצלת ילדים משמד.","s":"מתוך קטלוג"},{"i":34237,"n":"סואירו, אפרים מהולנד וברזיל","b":"גיסו של מנשה בן ישראל מאמשטרדם, היגר לפירנאמבוקו-ברזיל, ושכנע את גיסו לבוא בעקבותיו.","s":"אמריקה"},{"i":34238,"n":"סואלם, משה מתונס","k":"בעל וישמע משה","dt":"תשטז","b":"דיין בגרדאיה-תונס. חיבר גם \"וישמע משה\" ג'רבא תשטו.","s":"ארזי הלבנון"},{"i":34239,"n":"סוארעס, יעקב","b":"רב בצ'רלסטון-ארה\"ב - תקסז עד תקעא.","s":"אמריקה"},{"i":34240,"n":"סובול, יהודה ליב מטריבישאן","b":"פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח.","s":"אוצר כתבי עת-לוין"},{"i":34241,"n":"סובול, יעקב צבי","f":"יצחק","bt":"1831","bp":"שאוולי","dt":"1913","b":"אביו היה דיין בשאוולי. תלמיד ישיבות ליטא. ר\"מ בביהמ\"ד של ר הירשל נביאזר בקובנא. רב בסלובודקה, ולאחר שנודע שהוא בקי בספרות ההשכלה נאלץ לפרוש ועבר לוילנא, זיטומיר ואודסה - ולמד שם מתמטיקה. פרסם ב\"המגיד\", \"המליץ\", ועוד. מילא את מקום פרץ סמולנסקין במערכת \"השחר\". חיבר שיר \"החוזה חזיונות בארבע עולמות\" שהתפרסם. היגר לארה\"ב-1875 והתפרנס מספרית השאלה שייסד ומהוראה. פרסם בעתונים עבריים. מחלוצי הסופרים והמשוררים האידיים בארה\"ב. חיבר פואימה-1876 אודות המהגרים החדשים בארה\"ב.","s":"ליטא"},{"i":34242,"n":"סובל, אליהו מטאוויאן","f":"חיים ירוחם","bt":"תרמב","b":"תלמיד ר צבי הירש שור מביאליסטוק בעל \"צבי וחמיד\", ותלמיד ישיבות איישישוק וכולל קובנא. חתן ר משה מישל שמואל שפירא מראגובה. רב בטאוויאן-פלך קובנא-תרסז. נסמך מאת: ר חיים נפתלי הלפרין מביאליסטוק, ר משה יהודה רבינוביץ מגרודנא, ר יצחק ארונובסקי מקובנא.","s":"אוצר הרבנים 2165; אהלי שם"},{"i":34243,"n":"סובל, חיים ירוחם מביאליסטוק","b":"רב בביאליסטוק-תרם. גיסו של ר יהושע מרגליות-נכד ר בנדט בעל \"נר תמיד\".","s":"אוצר הרבנים 6437"},{"i":34244,"n":"סובל, ישראל משה מפשמישל","f":"חיים מפשמישל","k":"בעל אות לטובה","bt":"תקץ","bp":"פשמישל","dt":"תרן","b":"מחכמי פשמישל - עסק במסחר וגם מגיד שיעור ודרשן. השאיר כמה ספרים - בכתב יד. חיבר \"אות לטובה\" פרמישלא תרל.","s":"וונדר-גליציה ח\"ג"},{"i":34245,"n":"סובל, שמואל דוד ממיר וארה\"ב","k":"בעל זכות אבות","bp":"מיר","b":"רב במיר, ארה\"ב-תרסו.","s":"אמריקה"},{"i":34246,"n":"סובלסקי, יצחק מוארשא","b":"עורך \"כנסת הגדולה\" - וארשא תרן.","s":"אוצר כתבי עת-לוין"},{"i":34247,"n":"סוגר, שמואל יצחק מאוואנטא","bt":"תרלה","bp":"פאסוואהל","b":"מצאצאי הגר\"א. חתן ר מרדכי הילמן מפאסייטין. תלמיד ר\"י רבינוביץ מפוניבז. רב באוואנטא-תרסג. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ.","s":"אוצר הרבנים 19582; אהלי שם; אוצר כתבי עת-לוין"},{"i":34248,"n":"סודיטץ, אהרן מסערדאוהל","dt":"תקפח - ד אב","b":"רב בסערדאהעלי(=סערדאוהל)-תקעו עד תקפח וראש ישיבה (בזמן החת\"ס), ור יעקב ניישלס על מקומו אחריו. מתלמידיו: ר יהודה אסאד, ר דוד צבי ארנפלד, נפטר צעיר ונספד ע\"י החת\"ס.","s":"אוצר הרבנים 1656; הונגריה"},{"i":34249,"n":"סודלניצקי, זלמן מוישטיניץ","dt":"תשג","b":"רבה האחרון של וישטיניץ על מקום ר אברהם יהודה פולטינוב. נספה בשואה.","s":"אוצר הרבנים 5646; ליטא"},{"i":34250,"n":"סודרינא, שבתי מירושלים","dt":"תקא - בערך","dp":"ירושלים","b":"מחכמי ירושלים. נספד מאת ר יעקב אלגזי בספרו \"שארית יעקב\".","s":"פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":34251,"n":"סודרסקי, מנדל","bt":"1885","bp":"וישטיניץ-ליטא","dt":"1951","dp":"ניו יורק","b":"נכד ותלמיד המשכיל הידוע ר משה ויסטינצר. למד רפואת עינים בברלין מתוך רצון לעלות לירושלים ולטפל במחלה הטרכומה שהיתה נפוצה אז. רופא צבאי ברוסיה בזמן מלחמ\"ה ה-I. התישב בקובנא-1921 ועבד כרופא עינים ובנוסף עסק בפעילות ציבו ועזרה לציבור היהודי. ממייסדי \"אורט\", \"אזע\", חברת \"חובבי השכלה\", ועוד. מפעילי היאס ומיוזמי \"ייווא\". יסד את \"פאלקסבלאט\" יחד עם ע. פינקלשטין. השתתף באנציקלופדיה האידית בפאריס. פרסם מאמרים רבים. היגר לארה\"ב-1937 וחידש את \"הפדרציה של יהודי ליטא\", והו\"ל \"דער ליווישער איד\". מעורכי ספר \"ליטא\"-1951.","s":"ליטא"},{"i":34252,"n":"סוויג', ליאון","bt":"1888","bp":"קובנא","b":"פעיל בבונד. היגר לארה\"ב, עורך \"פון די טיפענישן פון הארצען\". נשיא האגודה הציונית בברונקס. ייסד את \"אגודת יוצאי ליטא\" בניו יורק. ממיסדי התאחדות יהודי רוסיה בארה\"ב.","s":"ליטא"},{"i":34253,"n":"סוויד, משה מחלב - הזקן","f":"יוסף","k":"בעל מסוא משה","dt":"תקעד","b":"דיין בחלב בזמן ר אליהו שאמע הלוי.","s":"ארזי הלבנון"},{"i":34254,"n":"סוויד, משה מחלב - הנכד","k":"בעל אמת ומשפט","dt":"תרמט - כט אייר","b":"נכד לר משה סוויד מחלב. רב בחלב. חיבר גם \"שלום ואמת\" - בכת\"י.","s":"ארזי הלבנון"},{"i":34255,"n":"סוויד, נסים מחלב","b":"רב בחלב-תריב וחתם אז על הסכמה ל\"כנסיה לשם שמים\".","s":"ארזי הלבנון"},{"i":34256,"n":"סוויד, שושן מטריפולי","f":"שלמה","bt":"תם","dt":"תקי - בערך","b":"סופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":34257,"n":"סווינחר, יצחק מלויצק","b":"רב בלויצק-תמ\"ה","s":"אוצר הרבנים 10869"},{"i":34258,"n":"סווינחר, מרדכי","f":"ישראל סווינחר","b":"רב-שנת ת\"פ","s":"אוצר הרבנים 13957"},{"i":34259,"n":"סווינחר-יולס, ישראל מדובנא","f":"מרדכי יאליס מקראקא","dp":"לוצק","b":"רב בקראקא, דובנא-תלה על מקום ר משה בן יוסף כץ ור שמחה רפפורט וחתנו - ר שמחה בן נחמן רפפורט על מקומו אחריו, לוצק. גיסו - הפרנס ר ישכר בעריש בן ר השל מקראקא.","s":"אוצר הרבנים 12008; ברוין-אנשי מופת"},{"i":34260,"n":"סוויפט, משה יהודה מאנגליה","bt":"תרסז","bp":"ליברפול-אנגליה","dt":"תשמד","b":"תלמידי ישיבת פוניבז-ליטא, מיר. רב בלונדון, יוהנסבורג-דרום אפריקה, דיין אצל הגר\"י אברמסקי בלונדון וראב\"ד על מקומו אחריו. לזכרו \"ספר זכרון\" מכון ירושלים תשמו.","s":"מתוך קטלוג"},{"i":34261,"n":"סוויר, משה מחלב","b":"רב בארם צובה-תר\"מ","s":"אוצר הרבנים 14962"},{"i":34262,"n":"סווירן, דוד ברנרד מפילדלפיה","k":"בעל דביר דוד","bt":"1889","bp":"סמרגון-ליטא","dt":"1944","dp":"פילדלפיה","b":"תלמיד ישיבות ליטא-פולין, ישיבת ר יצחק אלחנן בניו יורק. רב בווטרבורי, וילמינגטון, פילדלפיה. פעיל באגודת הרבנים האורטודוכסים. פרסם מאמרים, שירים בכתבי עת שונים.","s":"ליטא; אמריקה"},{"i":34263,"n":"סוזין, אהרן ממגניסיאה","b":"רב בקהלת \"טולידו\" במגניסיאה-תיט.","s":"רוזניס-תורכיה-ד"},{"i":34264,"n":"סוזין, אליעזר מירושלים","dt":"תקסח - ח ניסן","dp":"ירושלים","b":"מחכמי ירושלים. אביו של ר שלמה משה סוזין ה\"ראשון לציון\"","s":"גליס; אוצר הרבנים 2561; גאון-יהודי המזרח; ח\"מ, יהב\"י"},{"i":34265,"n":"סוזין, ידידיה חי ג'יליבון מירו","f":"שלמה משה","dt":"תרלד?","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקסז בראש ישיבת \"כנסת ישראל\" שנוסדה על ידי ר חיים בן עטר, חתם על תקנות ישיבת ייאני, על הסכם השלום בעדה הספרדית בשנת תרד, על שטר \"פשר המנורה| בשנת תריד ועוד. בניו: ר יצחק, ר משה.","s":"גליס; אוצר הרבנים 6622; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; \"החבצלת\" תרלד ו טבת. רבעון ירושלים שנה א ג-ד."},{"i":34266,"n":"סוזין, יהודה מירושלים","f":"שלמה משה","dt":"תרלד - ה טבת","dp":"ירושלים","b":"מחכמי ירושלים,אביו היה הראשון לציון","s":"אוצר הרבנים 7040; גאון-יהודי המזרח; ארזי הלבנון"},{"i":34267,"n":"סוזין, יצחק מירושלים","f":"ידידיה חי","dt":"תרעז - יב חשון","dp":"ירושלים","b":"מחכמי ירושלים, בשליחות בצפון אפריקה-תרלט מטעם עדת הספרדים בירושלים.","s":"גליס; אוצר הרבנים 10868; גאון-יהודי המזרח; ארזי הלבנון"},{"i":34268,"n":"סוזין, מרדכי אליעזר מירושלים","dt":"תרכח -כא-ה אלול","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקסז חתם על איגרת תלמידי ישיבת \"כנסת ישראל\". בשנת תקע חתם על תקנות ישיבת ייאני. חתם-תרט על כתב שליחות ר מרדכי חיים מיוחס.","s":"גליס; אוצר הרבנים 14071; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י"},{"i":34269,"n":"סוזין, משה מירושלים","dt":"תר - אחרי","dp":"ירושלים","b":"גביר בפיליפולי, עלה לירושלים.","s":"גאון-יהודי המזרח"},{"i":34270,"n":"סוזין, משה שלמה מירושלים","dt":"תרנח - ז אב","dp":"ירושלים","b":"מחכמי ירושלים, נכדו של הראשון לציון ר שלמה משה סוזין. בשליחות מספר פעמים וביניהם בשנת תרמז לאסוף כסף לבנית שכונת שמעון הצדיק. חתם בשנת תקסו על אגרת ראשי הקהלה. מחדושיו בספר \"תורה מציון\" שנה א חוברת א.","s":"גליס; אוצר הרבנים 15659; גאון-יהודי המזרח"},{"i":34271,"n":"סוזין, רפאל מירושלים","f":"ידידיה חי","dt":"תרי - א-ב כסלו","dp":"ירושלים","b":"מחכמי ירושלים. נפטר צעיר.","s":"גליס; ארזי הלבנון; פרומקין-תח\"י"},{"i":34272,"n":"סוזין, שלמה משה מירושלים","f":"אליעזר","dt":"תקצו - כח כסלו","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקלח בשליחות חברון לתורכיה, בשנת תקס בשליחות ירושלים, בשנת תקסג רב עדת הפורטוגזים בתונס, בשנת תקפד כיהן כראשון לציון אחרי ר יום טוב דאנון. היה חברו של ר מנחם מנדל משקלוב. הגיע להסכם פשרה-תקפט עם האשכנזים בראשות ר ישראל משקלוב בענין חלוקת התרומות מגרמניה, איטליה ואוסטריה. חיבר קונטרס \"טהרת הקדש\" לאיסור ציורים ותמונות בביהכ\"נ. מתורתו ב\"תורה מציון\" - ירושלים תרנה-תרסה. דיינים אצלו: ר חזקיה אברהם הכהן, ר יהודה רפאל נבון, ר שמואל הלוי, ר\"מ הלוי, ר ישראל חיים רפאל סגרי, ר יונה משה נבון, ר רפאל יהודה עוזיאל, ר שלמה יצחק בנימין מיוחס.","s":"גליס; אוצר הרבנים 18877,14961; גאון-יהודי המזרח; ארזי הלבנון; אוצר כתבי עת-לוין; פרומקין-תח\"י"},{"i":34273,"n":"סוחאטוב, נפתלי הרץ","dt":"תקצח - ז ניסן","b":"ראב\"ד בלבוב. בנו ר גבריאל בעל \"מצבת קדש\".","s":"אוצר הרבנים 16230"},{"i":34274,"n":"סוחולון, יוסף מאדרינופול","b":"רב באדרינופול-רע.","s":"רוזניס-תורכיה-ב"},{"i":34275,"n":"סוטין, דב בער מסמולוביץ","b":"גביר מראשי קהלת סמולוביץ. סייע למנות את שני חתניו של הגדול ממינסק לרבנים בסמולוביץ. חתנו ר יצחק גוטמן.","s":"הגדול ממינסק"},{"i":34276,"n":"סויבל, יהודה ליב מאלשד","f":"יוסף חיים מטריבוטשן","dt":"תש..","b":"חתן ר משה עזריאל ולדמן מבורשה. דיין באלשד-ליד גרוסורדין, עבר לגרוסורדין. נספה בשואה.","s":"טרנסילבניה"},{"i":34277,"n":"סויבלמן, אשר ענזיל מזינקוביץ","b":"תלמיד ר אברהם יהושע השל מאפטא, ור ישראל מרוזין. אב\"ד בזינקוביץ, פילוואריק-קמיניץ. נכדו - ר אברהם יצחק מזינקוביץ בעל \"סיפורי צדיקים החדש\".","s":"אלפסי"},{"i":34278,"n":"סויסה, אברהם","dt":"תרפ","b":"מחכמי מראקש","s":"ארזי הלבנון"},{"i":34279,"n":"סויסה, דוד","k":"בעל מתוק מדבש","bt":"תרסא","bp":"אולאד מנסור(מרוקו)","dt":"תשנג - כח שבט","dp":"חצור הגלילית","b":"עלה לא\"י, דרשן, מרביץ תורה בחצור הגלילית, חיבר \"מתוק מדבש\"","s":"ארזי הלבנון","bk":[["מתוק מדב\"ש",""]]},{"i":34280,"n":"סויסה, יצחק מתאמנארת","k":"בעל ויזרע יצחק","bt":"תקס","bp":"תאמנארת","b":"מוצאו בכפר תאמנארת(=תאמאררת) - חבל סוס במרוקו, עלה לירושלים. הו\"ל סדר מערת שדה המכפלה לר משה ן צור, וחיבר לו הקדמה.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34281,"n":"סויסה, נפתלי ממרוקו","dt":"תשז","b":"רב בסוס-מרוקו.","s":"ארזי הלבנון"},{"i":34282,"n":"סויסה, שלמה ממרוקו","dp":"תיכיראת-מרוקו","b":"מצדיקי מרוקו.","s":"ארזי הלבנון"},{"i":34283,"n":"סוכוטשבסקי, אהרן מרדכי","f":"אפרים פישל","bt":"תרכא","b":"מצאצאי בעל \"פרי תבואה\". תלמיד הכולל בקובנא. חתן ר פנחס מדובענקא-פלך לובלין, ועבר לשם וכיהן כמו\"ץ אצל חותנו. רב בקיסלין-ווהלין-תרנז. נסמך מאת: ר יצחק אלחנן מקובנא, ר זלמן מלובלין, ר יהושע מקוטנא, ר זנויל קלפפיש מוארשא.","s":"אוצר הרבנים 1839; אהלי שם"},{"i":34284,"n":"סוכוטשבסקי, דוד מטישביץ","b":"מגדולי תלמידי ר שמחה בונם מפשיסחא, והדריך בהוראת רבו את הבאים לפשיסחא.","s":"אלפסי"},{"i":34285,"n":"סוכוטשבסקי, משה ליב מביסקוביץ","b":"חתן ר יעקב ליינר מאיזביציא. אדמור בביסקוביץ על מקום דודו - אחי חותנו - ר שמואל דב אשר ליינר מביסקוביץ, עבר לרייויץ.","s":"אלפסי"},{"i":34286,"n":"סוכוטשבסקי, שלום ברוך מלודז","b":"מו\"צ בלודז-תרץ. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג.","s":"אוצר הרבנים 18229; אוצר כתבי עת-לוין"},{"i":34287,"n":"סוכוסטוב, גבריאל מלמברג","f":"נפתלי הירץ","k":"בעל זכרון צדיקים","bt":"תקף","bp":"למברג","dt":"תרם","b":"חתן ר יצחק מסמבור - וסידר לדפוס את ספרי חותנו. מחכמי למברג. חיבר \"זכרון צדיקים\" למברג תריז, \"מצבת קודש\" תרכב. בספריו הביא את תולדותיהם של החכמים הקדומים בעירו. ועסק בתיקון ואחזקת בית העלמין הישן.","s":"וונדר-גליציה ח\"ג; היברובוקס","bk":[["מצבת קודש",""]]},{"i":34288,"n":"סוכוסטוב, נפתלי הרץ מלמברג","f":"אברהם חיים מסוכוסטוב","k":"המגיד השחור","bt":"תקל","bp":"סוכוסטוב","dt":"תקצה-ו - ז ניסן","dp":"לבוב","b":"רב ברדיויל, מ\"מ ומו\"צ בלבוב תוך העיר. נזכר ב\"ברכת יעקב\". בנו - ר גבריאל בעל מצבות קודש.","s":"וונדר-גליציה ח\"ג; בובר-לבוב; אוצר הרבנים 16167; מצבות קדש-לבוב"},{"i":34289,"n":"סוכן, אברהם מארה\"ב","b":"רב בניו יורק-תרס.","s":"אוצר הרבנים 656; מרקוביץ-ראסיין"},{"i":34290,"n":"סוכרי, יעקב מדמשק","f":"שלמה","k":"בעל ויחי יעקב","dt":"תרסה","dp":"ירושלים","b":"מחכמי דמשק, נכדו של ר יעקב ענתבי. חיבר \"ויחי יעקב\" ליוורנו תרסא, ועוד. עלה לירושלים.","s":"גליס"},{"i":34291,"n":"סוכרי, שלמה מדמשק","k":"בעל עטרת שלמה","dt":"תרמ-ד - יב סיון","dp":"טבריה","b":"מחכמי דמשק, חתן ר יעקב ענתבי רבה של דמשק בזמן עלילת דמשק. דיין לצדו של ר יצחק אבולעפיה. עלה לצפת-תרמ. בנו ר יעקב הו\"ל את ספרו \"עטרת שלמה\"","s":"גליס; אוצר הרבנים 18543; גאון-יהודי המזרח; ארזי הלבנון"},{"i":34292,"n":"סולא די, אברהם מלונדון","f":"דוד","bt":"תקפה","bp":"לונדון","dt":"תרמב - יח סיון","b":"רב בקהילת הספרדים במונטריאול-קנדה - תרז, רב קהילת הספרדים בניו יורק, בנו ר מעלדאלא על מקומו אחריו. נשיא ארה\"ב גרנט כבדו לפתוח את ישיבת הקונגרס בתפילה.","s":"אמריקה; מרקוביץ-ראסיין"},{"i":34293,"n":"סולא די, דוד אהרן מלונדון","bt":"תקנז","bp":"אמשטרדם","dt":"תרכא - יג חשון","b":"חתן ר דוד מילדולה. דרשן בלונדון-תקצא. הו\"ל ספרים בעזרת שרלוט מונטיפיורי. חיבר ספרים ומאמרים, פעל להקמת מוסדות תורה וחכמה בלונדון. דודו - הרופא ר בנימין די סולא.","s":"פין-כנסת ישראל"},{"i":34294,"n":"סולא די, יעקב מנדס","k":"בעל כל דברי התורה","b":"חיבר \"כל דברי התורה\" פילדלפיה תרכה.","s":"אמריקה"},{"i":34295,"n":"סולא די, יצחק מקורסאו","f":"שמואל מינדיס מקורסאו","b":"רב בקורסאו, בארדעאוקס-צרפת, אמשטרדם-תקל.","s":"אמריקה"},{"i":34296,"n":"סולא די, מעלדאלה","f":"אברהם מלונדון וניו","b":"רב הקהלה הספרדית בניו יורק-תרמב על מקום אביו.","s":"אמריקה"},{"i":34297,"n":"סולאם, אליהו מאלגיר (סלאם)","b":"מחכמי בוסעאדא-אלגיר, עסק במסחר. הו\"ל הגדה \"אהבת הקדמונים\" ליוורנו תרסד, ובה גם פיוטים מאביו.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34298,"n":"סולאם, יצחק מאלגיר","f":"אברהם","b":"רב בגרדאייא-אלגיר, ובנו ר משה על מקומו אחריו. חיבר קונטרס על הלכות שחיטה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34299,"n":"סולאם, משה מאלגיר","f":"יצחק","k":"בעל ידי משה","bt":"תרלו - בערך","dt":"תשטז","b":"רב בגרדאייא-אלגיר על מקום אביו כ-50 שנה. פייטן. חיבר \"ידי משה\" גרבה תשטו, \"וישמע משה\" גרבה תשטז.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34300,"n":"סולברג, מרדכי מאמשטרדם","bt":"תקצח","dt":"תרסה - כב טבת","b":"מצאצאי ה\"חכם צבי\" - (דור שישי). תלמיד ה\"דברי חיים\" מצאנז, ובעל השואל ומשיב. עבר לאמשטרדם-תריב והיה מלמד בבית משפחת לעהרן, ואח\"כ בביהמ\"ד \"עץ חיים\" באמשטרדם. מתלמידיו - רא\"ל פרינץ.","s":"מתוך קטלוג"},{"i":34301,"n":"סולוב, אלכסנדר זושא מבריסק","b":"חתן ר חיים בער גרינגרוס מקרמנצוג. תלמיד ישיבת מיר. משגיח בישיבת בריסק."},{"i":34302,"n":"סולוביצ’יק יוסף דוב הלוי 1903","s":"היברובוקס","bk":[["רשימות שיעורים",""]]},{"i":34303,"n":"סולוביצ’יק יוסף דובר בן יצחק זאב מבריסק","bt":"1820","dt":"ה'תרנב 1892","s":"היברובוקס","bk":[["בית הלוי",""],["ספר בית הלוי",""]]},{"i":34304,"n":"סולוביציק סוליאלי, מנחם מכס","f":"אברהם אבא","k":"בעל יסודות התרבות","bt":"1883","bp":"קובנא","dt":"1957","dp":"ירושלים","b":"למד היסטוריה בפטרבורג וגרמניה. חוקר מקרא. מעורכי \"יאוורייסקאיה ז'יזן\", \"ראזסווייט\" - בטאוני הציונים ברוסיה. מיניסטר לעניני יהודים בליטא, חבר בועד הפועל עציוני-1921, מעורכי אנציקלופדיה \"אשכול\". עלה לארץ-1933. חיבר \"יסודות תולדות התרבות הביבלית\" פטרבורג 1912, \"אטלס גיאוגרפי\", ועוד.","s":"ליטא"},{"i":34305,"n":"סולוביציק, אבא מקובנא","b":"גביר מחכמי קובנא. היה מעשרת היהודים הראשונים שחזרו לקובנא מגלות ויליאמפולי-תקלו. ניהל משפט ממושך על בית שהיה מחוץ לאזור היהודים בקובנא ולאחר שזכה הקים בו את הקלויז הראשון בקובנא-1810 והתקיים במשך כ-60 שנה ונקרא על שמו, בבית זה נוסד גם ביה\"ח היהודי הראשון-1807. מחותן עם הגביר ר צבי הירש זלקינד, חתנו - ר ישראל בן משלם זלמן ז\"ק-זקהיים.","s":"ליטא; ליפמן-קובנא"},{"i":34306,"n":"סולוביציק, אברהם אבא מקובנא","f":"שלום","bt":"1850","bp":"גרודנא","dt":"1922","b":"פרנס קהילת קובנא. אשתו היתה אחותו של ר איסר בר וולף - והיתה עסקנית ציבור חשובה.","s":"ליטא"},{"i":34307,"n":"סולוביציק, אברהם מבריסק","f":"יצחק בן יוסף","b":"הגיע עם אביו ואחיו - ר משה ור נתן מבריסק לקובנא-תקי, גביר מראשי קהילת קובנא, וראה החשבון שלה. תרם יחד עם אחיו ר משה סכום גדול לצורך ביטול גזירת הגירש מקובנא-תקלו. ופעל יחד עם אחיו להקמת ביהכ\"נ הגדול בויליאמפולי(סלובודקה)-תקלב.","s":"ליפמן-קובנא; ליטא"},{"i":34308,"n":"סולוביציק, אליהו צבי","f":"יוסף מקובנא","b":"נכד(-אבי אמו) ר חיים מוולוזין. חתנו - ר חיים רוקח מדובנא.","s":"ברוורמן-אנשי שם"},{"i":34309,"n":"סולוביציק, אליהו צבי מדאבייק","f":"יצחק זאב מקובנא","k":"בעל קול קורא","b":"נינו של ר חיים מוולוזין. בנו ר שמחה-עלה לירושלים.","s":"ליפמן-קובנא"},{"i":34310,"n":"סולוביציק, אליעזר נפתלי מדבייק","f":"יוסף","bt":"תריא","b":"רב בדובייק-פלך קובנא-תרלה. ועל מקומו חתנו.","s":"אוצר הרבנים 2715; ליטא; אהלי שם"},{"i":34311,"n":"סולוביציק, חיים יהודה ליב מקוב","f":"מאיר שרה בילעש מקובנ","bp":"קובנא","dt":"תרלז - יח שבט","dp":"ירושלים","b":"גביר מחכמי קובנא, ונדד בעסקיו וישב גם בסימפרפול-קרים, פטרבורג. עלה לירושלים-תרלג. הניח חדושים בכת\"י. חיבר מאמרים ב\"המגיד\". החזיק כת\"י של הרמב\"ם - משנת ה'ו ליצירה. בנו ר שמחה ראובן עדלמן, איזיק השל מוילנא.","s":"עיר וילנא ח\"ב"},{"i":34312,"n":"סולוביציק, חיים שמחה מקובנא","f":"יצחק זאב","bt":"תקץ - בערך","dt":"תרפא","b":"אחיו הצעיר של ר יוסף דב בעל בית הלוי. מחכמי קובנא, תלמיד מהרי\"ל דיסקין וחברו של ר יצחק ירוחם דיסקין, ליוה את רבו לפריס בדרכו לארץ ישראל. חתנו - ר שרגא פיבל הלוי הולצברג מפריס.","s":"מתוך קטלוג"},{"i":34313,"n":"סולוביציק, יוסף דב מארה\"ב","f":"שמחה","bt":"תרסח","bp":"בריסק","b":"נכד בעל \"בית הלוי\". תלמיד אביו, ור שלמה פוליאצוק ממייציט. חתן משפחת אידלמן מליטא. היגר לארה\"ב-תרצג וכיהן כרב קהלת \"בני ישראל\" בספירנג ואלי-ניו יורק. חבר אגודת הרבנים באמריקה, ויסד ישיבה.","s":"אנשי שם-אמריקה"},{"i":34314,"n":"סולוביציק, יוסף דב מבוסטון","f":"משה","b":"נכד ר חיים מבריסק. רב בבוסטון ור\"מ בישיבה אוניברסיטה בניו יורק. פרסם מאמרים ב\"תלפיות\" - נ\"י תשד.","s":"אוצר כתבי עת-לוין"},{"i":34315,"n":"סולוביציק, יוסף דב מקובנא","f":"משה מקובנא","k":"חתן ר חיים מוואלוזין","bp":"קובנא","b":"חתן ר חיים מוולוזין. רב בקובנא-תקע על מקום אביו. בניו - ר אליהו צבי בעל תולדות אדם, ר יצחק זאב-כיהן כרב \"מטעם\" הראשון בקובנא, ונכדו ר יוסף דב מוולוזין ובריסק. נפטר צעיר ואלמנתו נישאה לר משה הכהן מנישוועז-ר מאשקע ר ארציגס.","s":"אוצר הרבנים 8755; ליטא; ברוורמן-אנשי שם; ליפמן-קובנא"},{"i":34316,"n":"סולוביציק, יחיאל משדליץ","b":"חתן ר ברוך מרדכי ליפשיץ בעל \"ברית יעקב\". אב\"ד מילייציץ, ראב\"ד בשדליץ-תרע.","s":"אוצר הרבנים 9181; מרקוביץ-נוברדוק"},{"i":34317,"n":"סולוביציק, יצחק זאב מקובנא","b":"רב מטעם בקובנא. בנו - ר יוסף דב מבריסק. יסד בקובנא חברת \"סומך נופלים\"-תרכב יחד עם ר צבי שפיר.","s":"ליטא; ליפמן-קובנא"},{"i":34318,"n":"סולוביציק, יצחק סג\"ל מקובנא","f":"זאב","b":"מקור המשפחה בבריסק - סג\"ל(=סגן לויים) - מראשי הגבאים בקובנא. בניו ר אברהם ור משה עזרו בהקמת ביהכ\"נ הגדול בויליאמפולי (סלובודקה)-1772 ותרמו סכום גדול לביטול גזרת הגירוש מקובנא-1776.","s":"ליטא"},{"i":34319,"n":"סולוביציק, ישראל גרשון","f":"חיים מבריסק","bt":"תרלה","b":"מחכמי בריסק. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ. בנו - ר משה.","s":"אוצר כתבי עת-לוין"},{"i":34320,"n":"סולוביציק, משה מבריסק","f":"יצחק בן יוסף","dt":"תקנו - אחרי","b":"גביר עשיר ורב בקובנא, הגיע עם אביו ואחיו - ר אברהם ור נתן מבריסק לקובנא-תקי, גלו לוילמפול בזמן גירוש קובנא, יסדו את ביה\"כ הישן בוילימפול-תקלב, תמכו בקהלת קובנא לביטול גזירת הגירוש, רב בוילמפול-תקלב על מקום ר אורי זקש. בנו - ר יוסף מקובנא.","s":"ליפמן-קובנא"},{"i":34321,"n":"סולוביציק, משה מניו יורק","f":"חיים הלוי מבריסק","r":"אב\"ד קלאסנא - וויעלטשקא","bt":"תרלט","bp":"וולוזין","dt":"תשא - ג שבט","dp":"ניו יורק","b":"תלמיד ישיבת וולוזין. חתן ר אליהו פינשטין מפרוזין. רב בראסיין-תרע ור יהושע מרדכי קלצקין על מקומו אחריו, חסלוביץ-תרעג, אנטופול-פלך גרודנא ומנהל ביהמ\"ד לרבנים \"תחכמוני\" בוארשא. ר\"מ בישיבת \"ר יצחק אלחנן\" בניו יורק-תרפט על מקום ר שלמה פולאצ'יק, והיה מראשי אגודת הרבנים באמריקה. בנו ר יוסף דב מבוסטון. פרסם מאמרים ב\"המסלה\" - נ\"י תרצו, \"קובץ דרושים\" - פיעטרקוב תרפג.","s":"אוצר הרבנים 14965; ליטא; אוצר כתבי עת-לוין; הגדול ממינסק; אהלי שם; מרקוביץ-ראסיין; קשת גבורים חלק א עמודים 200 - 205","bk":[["חידושי הגר\"מ הלוי - רמב\"ם",""],["חי' הגר\"מ הלוי",""]]},{"i":34322,"n":"סולוביציק, משה מקובנא","f":"יצחק בן יוסף","b":"פרנס ורב בולימפול(=ויליאמפולי)-סלובודקה-תקלב והקים יחד עם אחיו ר אברהם את ביהכ\"נ הגדול שם, קובנא-תקמג. פעל יחד עם אחיו ר אברהם לביטול גזירת הגירוש מקובנא-תקלו - תרמו סכום גדול לצורך כך, והביא את הענין לפני בית המשפט העליון בוארשא שפסק לטובת היהודים שקבלו פיצוי בסך 15000 זהובים ורשות לגור בקובנא.","s":"אוצר הרבנים 14964; ליטא"},{"i":34323,"n":"סולוביציק, משה משוייץ","f":"ישראל גרשון","dt":"תשכה - כ אייר","b":"נכד ר חיים מבריסק. תלמיד ר ברוך בער בקמניץ, תלמיד ישיבת מונטרה בשוייץ. רב וראש ישיבה בציריך-שוייץ.","s":"מתוך קטלוג"},{"i":34324,"n":"סולוביציק, מתתיהו","f":"אברהם אבא","bt":"1878","bp":"קובנא","dt":"1936","dp":"קובנא","b":"עסקן ציבור בקובנא. פעיל ב\"אורט\" ובמפלגת \"פאלקס פארטיי\".","s":"ליטא"},{"i":34325,"n":"סולוביציק, נתן מבריסק","f":"יצחק בן יוסף","b":"הגיע עם אביו ואחיו - ר אברהם ור משה מבריסק לקובנא-תקי, גבאי מראשי קהלת בריסק-תקכח.","s":"ליפמן-קובנא"},{"i":34326,"n":"סולוביציק, עמנואל","bp":"ראסיין","dp":"פטרבורג","b":"רופא בצי הרוסי. התישב באודסה והיה פעיל בציבור היהודי. יסד יחד עם ל. פינסקר את \"ציון\" - ברוסית. חבר עירית אודסה.","s":"ליטא"},{"i":34327,"n":"סולוביציק, צבי הירש ממוהילוב","b":"מו\"צ במוהילוב-תרסו, הסכים על אור ישן."},{"i":34328,"n":"סולוביציק, רפאל מירושלים","f":"יצחק זאב מבריסק וירו","b":"ראש ישיבת בריסק בירושלים.","s":"מתוך קטלוג"},{"i":34329,"n":"סולוביציק, שמחה הלוי","f":"יוסף דב","bt":"תרלט","bp":"וארשא","dt":"תשב - כו חשון","b":"גדל אצל אחיו הגדול ר חיים מבריסק. רב במוהילוב-תרעא והקים שם ישיבה. היה גם שתדלן אצל ראשי המלוכה והשיג שחרור מהצבא לרבנים. הגיע לאמריקה-תרפד וכיהן כרב יוצאי בריסק בניו יורק. חתם עם רבני ניו יורק בענינים שונים, ובהם התנגדות למנהג שניסו להנהיג הריפורמים, שהחתן ימנה את הכלה לשליחתו לכתוב לה גט לעצמה בתנאים שיתבארו בכתובה.","s":"אוצר הרבנים 19720; אמריקה; אהלי שם"},{"i":34330,"n":"סולוויי, רפאל מרדכי מקלשצל","f":"דוד הלוי","k":"בעל יד רמ\"ה","bt":"תרלב","b":"תלמיד ישיבת וולוזין. רב בליסקובה-פלך סובאלק-תרנו, קלשצל(=קלעשצעל)-פלך גרודנא-תרסג. נסמך מאת: ר יוסף מסלונים, ר יונתן מוולקוביסק. חיבר \"יד רמ\"ה\" - בכת\"י. בנו דוד - תלמיד ישיבת נוברדוק בביעלסק.","s":"אוצר הרבנים 17900; אהלי שם"},{"i":34331,"n":"סולומונוב, מרדכי ממינסק","b":"מחכמי מינסק בזמן הגדול ממינסק, נקרא יחד עם גיסו - ר מרדכי צבי יאבילוב בשם - \"די מאטקעס\".","s":"הגדול ממינסק"},{"i":34332,"n":"סולומונוב, משה צבי ממינסק","b":"גביר מחכמי מינסק-תרן.","s":"מינסק-איזנשטט"},{"i":34333,"n":"סולומיאק, אברהם","bt":"1863","bp":"סוואנציאן","dt":"1943","dp":"ירושלים","b":"תלמיד ביהמ\"ד לרבנים בוילנא. מחובבי ציון ומאנשי \"ביל\"ו\". עלה לארץ והתישב בגדרה. עבר לירושלים-תרמט והיה מזכיר בקונסוליה הרוסית, ומנהל הדואר הרוסי בארץ. פעל לטובת הישוב בזכות קשריו. נפגש עם הרצל בזמן ביקורו בארץ. יו\"ר ועד קק\"ל בירושלים. מהלוחמים במסיון.","s":"ליטא"},{"i":34334,"n":"סולוצקי, מאיר פרץ הכהן","dt":"תשג","b":"רב בווידז","s":"אוצר הרבנים 13101"},{"i":34335,"n":"סולטנסכיי, מרדכי הקראי מגוזלב","b":"מחכמי הקראים בגוזלאוו(=אפטוריה). הו\"ל \"פתח תקוה\" - גוזלב תקסח - לקראי יוסף שלמה מקושטא.","s":"רוזניס-תורכיה-ה"},{"i":34336,"n":"סולימאן, יצחק מאיטליה ואלגיר","dt":"תפג","b":"בן למשפחה מתורכיה וליוורנו, התישב באלגיר-תל והיה נגיד היהודים באלגיר. עליו ב\"ספר הזהב\" מאת האדי בצרפתית אלגיר 1871.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34337,"n":"סולימה, עזרא משלוניקי","dt":"שב - כח ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":34338,"n":"סולימה, שלמה משלוניקי","f":"עזרא","dt":"שב - בערך","b":"רופא בשלוניקי.","s":"זכרון שלוניקי"},{"i":34339,"n":"סולימן הכהן מאזמיר","b":"רב באזמיר-ת-תך. נזכר ב\"בעי חיי\".","s":"ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":34340,"n":"סולימן מבבל","f":"דוד","b":"מצאצאי ר מעתוק נשיא קהילת אענה (=נהרדעא) שנמלט לבגדד מאימת המושל. פייטן ואסטרונום מחכמי בגדד. פיוטיו נכנסו למחזור התפלה של בני בבל והודו. נכדו ר יהודה בן יעקב ששינה את שם המשפחה ל\"יהודה\" וצאצאיהם היו מיוחסים בין יהודי בבל ורבים מהם כיהנו כרבנים.","s":"ארזי הלבנון"},{"i":34341,"n":"סוליקא ממרוקו","dp":"פאס","b":"נערה יהודיה בטנג'יר-מרוקו, נהרגה עק\"ה.","s":"טולדנו-נר המערב"},{"i":34342,"n":"סולם, יצחק מירושלים","dt":"תקעה - ח תשרי","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":34343,"n":"סולמן","k":"ראה: סילמן","b":"בקי,מגדולי רבני ראבט,עלה לירושלים-תרי\"ח","s":"אוצר הרבנים 17725"},{"i":34344,"n":"סולניצע, שמואל מניו יורק","f":"ישעיה","k":"בעל חזון שמואל","bt":"תרע","bp":"קמניץ","b":"תלמיד ישיבת ביאליסטוק, קלצק, קמניץ, ר יעקב מתמיד, ר אהרן קוטלר. נסמך מאת הרב בורשטין מקמניץ, ר ברוך בר ליבוביץ. רב בניו יורק-תשב. חבר אגודת הרבנים באמריקה.","s":"אמריקה; אנשי שם-אמריקה"},{"i":34345,"n":"סולניק בנימין אהרן בן אברהם נפ’","s":"היברובוקס","bk":[["משאת בנימין",""],["משאת בנימן",""]]},{"i":34346,"n":"סולניק, אלימלך ישראל","b":"מזקני חסידות גור, ידידו של האדמור ר שמחה בונם אלתר בעל לב שמחה, ורשם את תורתו.","s":"מתוך קטלוג"},{"i":34347,"n":"סולס די, בנימין מקורסאו","dt":"תקעח - יג חשון","dp":"קורסאו","b":"תלמיד ישיבת \"עץ חיים\" באמשטרדם, רב ורופא בקורסאו-אמריקה, על מקום ר יעקב לופיס די פונסקיא.","s":"אמריקה"},{"i":34348,"n":"סומבאט, יצחק ממרוקו","b":"ציר ממשלת מרוקו-תקנא.","s":"טולדנו-נר המערב"},{"i":34349,"n":"סומך, אברהם חיים","s":"ארזי הלבנון"},{"i":34350,"n":"סומך, יהודה","b":"מחכמי בגדד,חמיו של ה\"בן איש חי\"","s":"ארזי הלבנון"},{"i":34351,"n":"סומך, מאיר הכהן מקהיר","b":"רב בקהיר. חתם על קבלת עדות-שנח.","s":"ארזי הלבנון"},{"i":34352,"n":"סומך, עבדאללה מבגדד","f":"אברהם","k":"בעל זבחי צדק","r":"המהר\"ל מפראג","bt":"תקעג-ד","bp":"בגדד","dt":"תרמט - יח אלול","dp":"בגדד","b":"רב ראשי בבגדד. מצאצאי רב נסים גאון מחבר הוידוי ליוה\"כ. תלמיד ר יעקב בן יוסף הרופא. לבקשת אחיינו שהתגורר בבומבי-הודו שלח לא במשך השנים את מנהגי בגדד והאחיין ר יחזקאל יהושע גבאי הו\"ל בשם \"זבחי צדק\". חיבר \"עץ השדה\", \"חזון למועד\" ועוד.","s":"אוצר הרבנים 16537; גאון-יהודי המזרח; ארזי הלבנון; תחילת ספר זבחי צדק, שובה ישראל גליון 569, שבת בשבתו גליון 1488, מוריה קובץ נט עמוד לד; יומא דהילולא","bk":[["זבחי צדק - יורה דעה",""],["זבחי צדק","שו\"ת - אחרונים"],["זבחי צדק (ראש מדרש \"בית זילכה\")",""]],"e":"תקע\"ג-תרמ\"ט"},{"i":34353,"n":"סומך, צאלח מבגדד","f":"עבדאללה","bt":"תקצא","bp":"בגדד","dt":"תרנז - ב כסלו","dp":"בגדד","b":"מחכמי בגדד. מחדושיו ב\"זבחי צדק\" לאביו, וב\"רב פעלים\" לר יוסף חיים. תשובה ממנו ליהודי רנגון-בורמה - תרנה.","s":"ארזי הלבנון"},{"i":34354,"n":"סומך, שלמה הכהן ממצרים","b":"מחכמי קהיר-שעו וחתם על קבלת עדות. אולי הוא הנזכר בספר הדרשות לר חיים חבריא.","s":"ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":34355,"n":"סונבאל ן, משה מפאס","b":"מחכמי פאס-תמח ומראשי הקהלה.","s":"ארזי הלבנון"},{"i":34356,"n":"סונבאל ן, נחמן מספרד","dt":"שיא - אחרי","dp":"פאס?","b":"תלמיד ר משה חלאווה מספרד ופאס. ממגורשי ספרד והגיע לפאס, ומשם ברח מהרדיפות למכנאס-רפז, ולבסוף חזר לפאס וחתם שם על תקנות עם ר אברהם עוזיאל, חתנו ר יהושע קורקוס. נשאל מר צמח דוראן והשיב לו ב\"חוט המשולש\".","s":"אוצר הרבנים 15991; מלכי רבנן; ארזי הלבנון; טולדנו-נר המערב"},{"i":34357,"n":"סונבאל ן, שלמה מפאס","dt":"שמה - אחרי","b":"רב בפאס-שלמה.","s":"טולדנו-נר המערב"},{"i":34358,"n":"סונבאל ן, שמואל מפאס-מרוקו","b":"מחכמי פאס הקדומים. נזכר אצל ר\"פ ן צור ור יצחק שמואל ן דנאן.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34359,"n":"סונה, דוד הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'.","s":"רוזניס-תורכיה-ד"},{"i":34360,"n":"סונינו, עמנואל","dt":"תסז - כ אייר","dp":"ריגייו","b":"רב באיטליה. תלמיד ר יצחק ואלי, דרש משלו ב\"גבול בנימין\".","s":"איטליה גירונדי-ע יב"},{"i":34361,"n":"סונסינו, משה משלוניקי","b":"רב ופוסק בשלוניקי-שכה.","s":"זכרון שלוניקי"},{"i":34362,"n":"סוסאן בן אמגאר ממרוקו","k":"בן סבעוני","dp":"אופראן-מרוקו","b":"נשרף עק\"ה, ומצבתו באופראן-מרוקו","s":"ארזי הלבנון; מלכי רבנן"},{"i":34363,"n":"סוסאן, אברהם דידיע בן מרשא","f":"מסעוד","b":"מחכמי פאס-שנות ה-ת'.","s":"מלכי רבנן"},{"i":34364,"n":"סוסאן, אברהם הלוי","f":"יצחק","k":"בעל מעשה הצדיקים","bt":"תקנז","bp":"סאלי - מרוקו","dt":"תרסג","dp":"טבריה","b":"בשנת תרך עלה לטבריה-תרח, בשליחות במרוקו-תרם. חיבר ספר \"מעשה הצדיקים\" ירושלים תרמט. תרגם לערבית יהודית את הספר \"בית שלמה\" לר אלתר שלמה פרידמן ירושלים תרנט.","s":"גליס; ארזי הלבנון; מלכי רבנן; שא\"י"},{"i":34365,"n":"סוסאן, אברהם מטיטואן","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד-תצז עם ר מנחם עטייה.","s":"מלכי רבנן"},{"i":34366,"n":"סוסאן, אברהם ממרוקו","bt":"תר - בערך","bp":"דבדו-מרוקו","b":"תלמיד חכמי פאס, מו\"ץ בדבדו-מרוקו, תאזא-מרוקו עד שחרבה, עבר לפאס, אב\"ד במוגאדור-מרוקו מטעם הממשלה. חתם-תרעה עם ר יוסף הכהן סקלי.","s":"מלכי רבנן"},{"i":34367,"n":"סוסאן, אברהם מפאס-מרוקו","f":"מסעוד","b":"סופר שטרות בפאס, חתם על שטר-תקטו.","s":"מלכי רבנן"},{"i":34368,"n":"סוסאן, אליהו מירושלים","f":"שמעון","b":"מחכמי ירושלים, צפת בזמן המבי\"ט, חברו של השל\"ה, חתם אחרי שפה על כתב שליחות ר אברהם ביטון ור שמואל רימון-שץ בשליחות עדת המערבים לאחר תלאות אבן פארוך.","s":"גליס; ארזי הלבנון; פרומקין-תח\"י; HUC שנה ד"},{"i":34369,"n":"סוסאן, חיים דוד ממרוקו","b":"אב\"ד בקזבלנקה-מרוקו-תש.","s":"מתוך קטלוג"},{"i":34370,"n":"סוסאן, חיים הלוי מטבריה","dt":"תריג - טז סיון","b":"שו\"ב בטבריה-תרע, חתם עם ר יעקב ועקנין ור יעקב משה טולדנו בענין עזבון השליח ר יעקב ן סאמון.","s":"מתוך קטלוג"},{"i":34371,"n":"סוסאן, יהודה - ב","b":"מחכמי פאס?","s":"מתוך קטלוג"},{"i":34372,"n":"סוסאן, יהודה הכהן מפאס","dt":"ד'תתק-ה","b":"רב בפאס, הרמב\"ם היה לו תלמיד חבר בהיותו בפאס. נהרג עק\"ה בידי האלמוואחידין, התנגד לאנוסים והיה מחלוקת בינו ובין הרמב\"ם על כך.","s":"אוצר הרבנים 7042; ארזי הלבנון; מלכי רבנן"},{"i":34373,"n":"סוסאן, יוסף","f":"משה","b":"מחכמי ירושלים, פעמיים בשליחות, בשנת רלג התעכב בקנדיא (כרתים).","s":"גליס; פריימן \"ציון\" א."},{"i":34374,"n":"סוסאן, יוסף מפאס","b":"רב בפאס-שנות ה-ק' בערך. מתלמידיו - ר יהודה אלכרסאני בעל \"ארון העדות\".","s":"אוצר הרבנים 8470; מלכי רבנן"},{"i":34375,"n":"סוסאן, יעקב מאלגיר","b":"רב במסתגאנם, ושאל את הריב\"ש. נכדו - ר יעקב בזיז ממסתגאנם-חתן ר יהודה אנקאווה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34376,"n":"סוסאן, יצחק הלוי מסאלי","k":"בעל פחד יצחק","dt":"תרכב","b":"רב ודיין בסאלי, עלה לארץ-תרח עם בנו ר אברהם והתישבו בטבריה. חיבר \"פחד יצחק\" בכת\"י ונעלם.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34377,"n":"סוסאן, ישכר ממרוקו וירושלים","f":"מרדכי דידיע בן סוסאן","k":"בעל תקון ישכר","bt":"רע","bp":"פאס","dt":"שכד-שמג","dp":"צפת","b":"מחכמי פאס, עלה לירושלים ולמד אצל ר לוי בן חביב, ועלה אתו לירושלים-רפז. בשנת שה עבר בערי תורכיה, אחר כך הקים ישיבה גדולה בצפת. חיבר \"תקון ישכר\" קושטא שכד ואחר כך מתוקן בשם \"עבור שנים\" ונציה שלט.","s":"גליס; אוצר הרבנים 12401; מלכי רבנן; ארזי הלבנון; פין-כנסת ישראל; רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":34378,"n":"סוסאן, מכלוף מדבדו-מרוקו","b":"מחכמי דבדו-שנות ה-ת'.","s":"מלכי רבנן"},{"i":34379,"n":"סוסאן, מרדכי ממרוקו","b":"מחכמי מרוקו, עלה לצפת-רץ. בנו - ר ישכר בעל \"תקון ישכר\".","s":"מלכי רבנן"},{"i":34380,"n":"סוסאן, נתן מפאס","f":"לוי","b":"מחכמי פאס, חתם-רפו בענין הנפיחה.","s":"טולדנו-נר המערב"},{"i":34381,"n":"סוסאן, שלמה מדבדו-מרוקו","f":"יעקב","b":"מחכמי דבדו-מרוקו-תרל.","s":"מלכי רבנן"},{"i":34382,"n":"סוסאן, שלמה מתאפילאלת","b":"מחכמי תאפלילאת-מרוקו-תנא.","s":"מלכי רבנן"},{"i":34383,"n":"סוסו, משה מאזמיר","dt":"תקלד - כו אדר","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":34384,"n":"סוסי, אליה מאזמיר","b":"חכם שלם באיזמיר(תורקיה)","s":"ארזי הלבנון"},{"i":34385,"n":"סוסי, משה מירושלים","b":"חתן ר מצליח מאיר המזכירו בהקדמתו ל\"זקן שמואל\". רב בירושלים-תקכ.","s":"אוצר הרבנים 14966; ארזי הלבנון"},{"i":34386,"n":"סוסניצר, חיים יהודה מברוד","f":"ראה ליטוין-סוסניצר"},{"i":34387,"n":"סוססו די, אברהם גומז","dt":"תכז - כא אלול","dp":"אמשטרדם","b":"מגולי ספרד באמשטרדם.","s":"פין-כנסת ישראל"},{"i":34388,"n":"סוסקינו, משה חיים מפירנצה","k":"מחס\"י","b":"דיין בפירנצה - [תק..], על מקום ר דניאל טירני בעל \"עיקרי הד\"ט\" ממקורבי החיד\"א המזכירו בספריו, נזכר אצל ר מתתיהו נסים טירני ב\"מדבר יחיל\".","s":"ארזי הלבנון"},{"i":34389,"n":"סוסש, פנחס מסטניסלב","f":"דוד מסטניסלב","k":"בעל פרדס המלך","bt":"תקם","bp":"סטניסלב","dt":"תר","b":"תלמיד ר צבי הירש מנדבורנא (שהחשיבו עד שהיה קם מלפניו), מקורב לר אברהם דוד מבוצאץ. מחכמי סטניסלב. נרפא בילדותו על ידי צדיק נסתר מהל\"ו. נחשב לצדיק נסתר על ידי רבו ר צבי הירש מנדבורנה. חיבר \"פרדס המלך\" בוצאץ תרסח.","s":"וונדר-גליציה ח\"ג; אלפסי"},{"i":34390,"n":"סוערדליק, ישראל","b":"שו\"ב. מחותן עם ר מתתיהו מורגנשטרן מבלגרד.","s":"מתוך קטלוג"},{"i":34391,"n":"סופאן, יוסף מטריפולי","f":"פרג'אללה","bt":"תן","dt":"תקך - בערך","b":"סופר דווקני בטריפולי. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":34392,"n":"סופינו, אליעזר מאיטליה וירושלי","f":"יעקב","dt":"תקז - ג כסלו","dp":"ירושלים","b":"מחכמי איטליה, רב בסיינה, לייורנו, פיסא, כתב תשובה בפיסא בשנת תצב לר יהודה עיאש. כתב קונטרס בתצט בדבר אמירת \"ואברהם זקן\" בשבוע החופה. החיד\"א למד אצלו ומביא מדבריו. עלה לירושלים","s":"גליס; אוצר הרבנים 2562; פין-כנסת ישראל; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה; וינר דעת קדושים,"},{"i":34393,"n":"סופינו, אליעזר מפיזא","f":"יעקב","b":"רב בפיזא וליוורנו בזמן ר\"ח ן עטר, ור רפאל מילדולה והר\"ר ריקי. חיבר קונטרס אודות מחלוקת בענין שבת חתן - תצט. תשובה אליו ב\"דבר שמואל\". המחלוקת ב\"מים רבים\" - אך לא מוזכר שם שמו.","s":"איטליה גירונדי-א מה"},{"i":34394,"n":"סופיר די פאפי מגרבה","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"אוצר כתבי עת-לוין"},{"i":34395,"n":"סופר","k":"בעל דרושי מהרש\"ם","b":"חיבר \"דרושי מהרש\"ם נ\"י תרפא.","s":"אלפסי"},{"i":34396,"n":"סופר שלמה בן אברהם שמואל בנימין","f":"הכתב סופר","k":"בעל חוט המשולש","r":"רב בדרעטשק'ע ומשנת תרמד בברגסס","bt":"תריג","bp":"פרשבורג","dt":"תרצ - יח אדר","dp":"ברגסאס","b":"חתן ר אברהם איסר פיליפ מדערעטשקע. ,רב בדרטשקא(=דרצ'קא)-תרלח על מקום ר צבי ברמן. ברגסאס-תרמד, וחתנו ר אברהם שלמה הירש על מקומו אחריו. בניו - ר שמחה שמואל בנימין, ר משה. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא.","s":"אוצר הרבנים 18544; החת\"ס ותלמידיו; הונגריה; אוצר כתבי עת-לוין; אהלי שם; המבשר תורני גליון 271 עמוד כד; היברובוקס","bk":[["איגרות סופרים - ליקוט איגרות ממשפחת הסופרים",""],["חוט המשולש החדש הנקרא גם עץ אבות - תולדות משפחת הסופרים",""],["איגרות סופרים",""],["חוט המשולש",""]]},{"i":34397,"n":"סופר שמחה בונם בן אברהם שמואל בנימין","f":"הכתב סופר","k":"בעל שבט סופר","bt":"תרג","bp":"פרשבורג","dt":"תרסז - טו כסלו","dp":"פרשבורג","b":"חתן ר פרץ ניימן מפרשבורג - וינה. רב בפרשבורג לצד אביו, וינה-תרכח ליד חותנו. רב בפרשבורג על מקום אביו-תרלב ובנו ר עקיבא בעל דעת סופר על מקומו אחריו. בנו - ר משה סופר - נפטר בצעירותו בפרשבורג.","s":"החת\"ס ותלמידיו; אוצר הרבנים 19758; קצבורג-תמונות הגדולים; מבשר ואומר טו כסליו תשעג; ראה ערך שבט סופר; היברובוקס","bk":[["שבט סופר","שו\"ת - אחרונים"],["שבט סופר – שו\"ת ושו\"ע",""],["שערי שמחה – עה\"ת",""],["שערי שמחה",""],["אבל כבד",""],["אהל רחל",""]]},{"i":34398,"n":"סופר שמעון בן משה","r":"גאב\"ד קרקא","bt":"1820","dt":"יז אדר תרמג","s":"שער הספר; היברובוקס","bk":[["מכתב סופר – דרוש ושו\"ת וחי' ש\"ס",""],["מכתב סופר",""],["מקדש מעט",""]]},{"i":34399,"n":"סופר, אברהם חיים דוד מבוריסלב","f":"יצחק יהודה ליב","k":"אח\"ד","bt":"תרלז","bp":"דרוהוביטש","dt":"תרצז - ז ניסן","dp":"בודפשט","b":"נכד הכת\"ס, למד בפרשבורג אצל דודו ה\"שבט סופר\". חתן הנגיד ר ישעיה שרמן מקאשוי. מחכמי בוריסלב-תרצו וסירב לרבנות. נשיא א\"י בגליציה-תרסז ומנהיג מחז\"ה על מקום אביו. מקורב לאדמור מבלז. במלחמת העולם ה-1 - רב צבאי. בידידות ומוערך על גדולי דורו. הניח כתובים וביניהם \"סמיכה לחיים\" על תרגום יונתן. נתמנה לרב בפרשוב-תרצא - אולם נפטר בטרם הגיע לשם.","s":"אוצר הרבנים 1091; וונדר-גליציה ח\"ג; החת\"ס ותלמידיו"},{"i":34400,"n":"סופר, אברהם יהודה ליב מפרשבורג","f":"מרדכי אפרים פישל","bt":"תקף","dt":"תקפח - ד אייר","dp":"פרשבורג","b":"נימול ע\"י החת\"ס. נפטר בבחרותו.","s":"החת\"ס ותלמידיו"},{"i":34401,"n":"סופר, אברהם יהושע השל","b":"רב בטשמרוביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד.","s":"אוצר כתבי עת-לוין"},{"i":34402,"n":"סופר, אברהם יוסף","dt":"תשד","b":"רב בטעט","s":"אוצר הרבנים 1168"},{"i":34403,"n":"סופר, אברהם יעקב מיעמרינג","f":"ישראל מרדכי אפרים פ'","bt":"תרלח","bp":"נאדי-סנט מיקלוש","dt":"תשד - כג סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, וזקנו ר אליעזר זוסמן סופר מפאקש. חתן ר יחזקאל פרידמן מטאפלאטשן ועבר לשם. רב בפאקש ליד זקנו. רב ביעמרינג-תרסד וראש ישיבה עם ר יצחק שטיינר, טעט-תרעג. בזיוו\"ש חתן ר משה אברהם סופר מטשארנא, ובזיוו\"ש חתן ר יהודה הכהן קרויס מלקנבך. נספה בשואה. מחדושיו ב\"זכרון סופרים\" לבנו ר אליעזר ישראל מרדכי אפרים.","s":"אוצר הרבנים 1197; הונגריה; החת\"ס ותלמידיו; אהלי שם"},{"i":34404,"n":"סופר, אברהם מגוריציאה וירושלים","f":"שמעון","k":"בעל הערות על המאירי","b":"רב בגוריציאה(=נורייצא), מחבר הערות על המאירי. חיבר הערות על המאירי. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר הרבנים 657; אוצר כתבי עת-לוין"},{"i":34405,"n":"סופר, אברהם מגרבה","f":"ציון","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":34406,"n":"סופר, אברהם מנחם מניש מסיגט","b":"סופרו של האדמו\"ר בעל \"אהבת ישראל\" מויזניץ בסיגט.","s":"מתוך קטלוג"},{"i":34407,"n":"סופר, אברהם מפיומא","f":"שמעון מערלוי בן הכתס","bt":"תרנח","bp":"ערלוי","dt":"תשמב - יז ניסן","dp":"ירושלים","b":"ר\"א סופר הוציא לאור ראשונים רבים ע\"פ השוואה לכתבי יד, בתוספת הערותיו והגהותיו, מהם: בית הבחירה למאירי; חי' הראב\"ד למסכת ע\"ז; חי' הר\"ן למסכת ב\"ב; חי' הרשב\"א למסכת שבועות; ר' משה קזיס למסכת מדות, ועוד.","s":"החת\"ס ותלמידיו","bk":[["רבי אברהם סופר [מו\"ל \"בית הבחירה\"]",""]]},{"i":34408,"n":"סופר, אברהם צבי הירש","f":"מרדכי אפרים פישל","b":"תלמיד ר חיים סופר בעל מחנה חיים. אחיו של ר נפתלי בעל מטה נפתלי (כך מופיע בכתב ידו על הספר - ידוע על בן אחר של ר מרדכי אפרים בשם שמעון צבי הירש שנפטר צעיר בשנת תקצו).","s":"מתוך קטלוג"},{"i":34409,"n":"סופר, אברהם שמואל בנימין","f":"משה","k":"בעל כתב סופר","bt":"תקעה","bp":"פרשבורג","dt":"תרלב - יט טבת","dp":"פרשבורג","b":"תלמיד ר מרדכי אפרים פישל סופר. חתן ר יצחק וייס מגורליץ. רב בפרשבורג על מקום אביו. בניו: ר יעקב עקיבא, ר שמחה בונם על מקומו אחריו בפרשבורג, ר יצחק ליב, ר שמעון מערלוי, ר שלמה מברגסאס בעל \"חוט המשולש\". חתניו: ר רפאל הלוי דייטש, ובזיוו\"ש (נשאה לאחר פטירתו) ר צבי הירש וייס מלאפוש. חתם בשם \"שמואל וולף\".","s":"החת\"ס ותלמידיו; אוצר הרבנים 1421; יומא דהילולא","bk":[["כתב סופר","מפרשי ש\"ס - אחרונים"],["כתב סופר [שו\"ת",""],["עהש\"ס",""],["דרשות",""],["עה\"ת]",""],["כתב סופר על התורה",""],["כתב סופר","מפרשי שו\"ע"],["כתב סופר","שו\"ת - אחרונים"]],"e":"תקע\"ה-תרל\"ב"},{"i":34410,"n":"סופר, אברהם שמואל בנימין - ב","f":"עקיבא - הדעת סופר","k":"בעל חשב סופר","bt":"תרסב","bp":"פרשבורג","dt":"תשכב - כא תשרי","dp":"ירושלים","b":"חתן ר יוסף יצחק קאהן מקאטוביץ. ר\"מ בישיבת פרשבורג לצד אביו ועל מקומו-תרצט ורב העיר. עבר לבודפשט-תשג, ניצל מהשואה הגיע לבודפשט-תשג, עלה לירושלים-תשד והיה לצד אביו בראשות הישיבה בירושלים. רב על מקום אביו-תשך, ובנו ר שמחה בונם על מקומו אחריו. חתניו - ר אברהם יוסף שפירא מתל אביב, ור אברהם בנימין לודמיר מבני ברק. פרסם מאמרים ב\"המגיד\" - סטמר תרפח, \"המעין\" - פרשבורג תרצד.","s":"החת\"ס ותלמידיו; אוצר הרבנים 1422; הונגריה; אוצר כתבי עת-לוין"},{"i":34411,"n":"סופר, אברהם שמואל בנימין מוינה","f":"משה מיאווע נכד הכת\"ס","k":"בעל כתב זאת זכרון","b":"חתן ר ישכר דב הופבויער. רב בוינה, ניו יורק. חיבר ספר לתולדות משפחות רע\"ק וחת\"ס.","s":"החת\"ס ותלמידיו"},{"i":34412,"n":"סופר, אברהם שמואל בנימין מערלו","f":"משה מערלוי","k":"בעל דברי סופר","dp":"ערלוי","b":"נפטר בחור.","s":"החת\"ס ותלמידיו"},{"i":34413,"n":"סופר, אליהו","s":"ארזי הלבנון"},{"i":34414,"n":"סופר, אליעזר זוסמן-פאקשער גאון","f":"מרדכי אפרים פישל","k":"בעל ילקוט אליעזר","bt":"תקפח - תקצט","bp":"פרשבורג","dt":"תרסג - ט תשרי","dp":"פאקש","b":"תלמיד הכתב סופר ור משה שיק מחוסט. חתן ר יואל אונגר מפאקש ועבר לשם. רב בהאלאש(=קיש קון האלאש)-תריז וראש ישיבה שם כ-30 שנה, עזב בגלל מחלוקת וכיהן כרב בפאקש על מקום חותנו. הסכים על \"אהל יצחק\" סטמר תרסג, ו\"וילקטו יוסף\" - מונקטש תרנט. בניו ר יוסף ליב ור שמעון על מקומו אחריו. חיבר \"ילקוט אליעזר\". ר זאב קרויס על מקומו אחריו בהאלאש. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"תל תלפיות\" - וייצען תרנב-תרעד.","s":"החת\"ס ותלמידיו; אוצר הרבנים 2646; הונגריה; אוצר כתבי עת-לוין","bk":[["ילקוט אליעזר",""]]},{"i":34415,"n":"סופר, אליעזר ישראל מרדכי אפרים","f":"אברהם יעקב מטעט","k":"בעל זכרון סופרים","b":"רב במאישא.","s":"החת\"ס ותלמידיו"},{"i":34416,"n":"סופר, אליעזר מוינה","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי.","s":"אוצר כתבי עת-לוין"},{"i":34417,"n":"סופר, אליעזר מרדכי אפרים פישל","f":"יצחק צבי מטימישואר","b":"רב לצד אביו בטימישואר. עלה לירושלים וכיהן כרב ביהמ\"ד פאפא.","s":"החת\"ס ותלמידיו"},{"i":34418,"n":"סופר, אפרים פישל זוסמן מבודפשט","b":"ראב\"ד בבודפשט. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"המעין\" - פרשבורג תרצד.","s":"אוצר כתבי עת-לוין"},{"i":34419,"n":"סופר, אפרים פישל מברעזביץ","f":"יעקב שלום מטאפלטשן","b":"חתנו - ר יצחק וייס מוערבא בעל \"שיח יצחק\".","s":"החת\"ס ותלמידיו"},{"i":34420,"n":"סופר, אפרים פישל מקישקון-מייאש","f":"אברהם יעקב סופר","dt":"תשד","b":"רב בקישקון-מייאשא","s":"אוצר הרבנים 3141"},{"i":34421,"n":"סופר, אפרים פישל משארוואר","dt":"תרנד","b":"רב בשארוואר על מקום הרב ארנפלד - בתקופתו נתפלגה הקהילה.","s":"הונגריה"},{"i":34422,"n":"סופר, אשר מברדיטשוב","f":"שמעון מקראקא","bt":"תריח","dt":"תרסג","b":"חתן הנגיד ר צבי מאגאזניק. רב בברדיטשוב.","s":"וונדר-גליציה ח\"ג"},{"i":34423,"n":"סופר, בנימין אליעזר מצורטקוב","b":"מחכמי צורטקוב-תרכה.","s":"וונדר-גליציה ח\"ג"},{"i":34424,"n":"סופר, גרשון מקראקא","dt":"שפא - ז חשון","b":"דיין בקרקא","s":"אוצר הרבנים 4386"},{"i":34425,"n":"סופר, דוד מברדיטשוב","f":"יהודה","bt":"תרכב","b":"תלמיד ר יוסף אפרתי מברדיטשוב. רב ומו\"צ בברדיטשוב-תרמג.","s":"אוצר הרבנים 4934; אהלי שם"},{"i":34426,"n":"סופר, דוד מנאנאש","f":"נפתלי מקלינורדין","b":"חתנו - ר מנחם צבי רוזנברג מדברצין.","s":"החת\"ס ותלמידיו"},{"i":34427,"n":"סופר, דוד עבדאללה","dt":"תרפז - יג אד\"א","b":"מגדולי רבני בבל, חריף, בקי, התיר עגונות","s":"ארזי הלבנון"},{"i":34428,"n":"סופר, זוסמן מדברצין","f":"יעקב שלום סופר","bt":"תריג","dt":"תרסג - ט תשרי","b":"מגיד בבודפשט, רב בדברצין. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז. (באוצר הרבנים תאריך פטירתו - כט חשון)","s":"אוצר הרבנים 5710; אוצר כתבי עת-לוין; שטמפן - הרצוג"},{"i":34429,"n":"סופר, זוסמן מפרשבורג","b":"הגיע מפולין לקיצע, פרשבורג. סופר סת\"ם מומחה והחת\"ס אמר עליו כי הוא גאון בעניני סופרות.","s":"אבני בית היוצר-וייס"},{"i":34430,"n":"סופר, חיים מאראד","f":"יעקב שלום מבודפשט","bt":"תרמז","bp":"בודפשט","dt":"תשט - ב סיון","dp":"אראד - בני ברק","b":"נכד בעל \"מחנה חיים\". תלמיד השב\"ס, והדעת סופר. חתן דודו זקנו ר יהודה סופר מאראד(=באראד). רב באראד-תרעג על מקום חותנו. ניצל מהשואה וחזר לאראד - שהיתה הקהילה החרדית הגדולה בטרנסילבניה שלאחר השואה, ור אהרן בריסק על מקומו אחריו. הו\"ל ספר אביו \"ישבב סופר\".","s":"אוצר הרבנים 6092; החת\"ס ותלמידיו; טרנסילבניה"},{"i":34431,"n":"סופר, חיים מבודפשט","f":"מרדכי אפרים פישל","k":"בעל שערי חיים","r":"אב\"ד מונקטאש ובודפסט","bt":"תקפב","bp":"פרשבורג","dt":"תרמו - כה סיון","dp":"פרשבורג","b":"תלמיד החת\"ס ור מאיר א\"ש מאונגוואר. חתן ר יוסף צבי דייטש ממטרסדורף ועבר לשם. מחכמי פרשבורג-תרח, רב ביעמרינג-תריא, סנט-פעטר-תריח על מקום ר דוד יהודה רוטנברג, מונקטש-תרכ ועזב בגלל רדיפות הקיצוניים, בודפשט-תרלט (קהלה שהיתה בראשיתה) ובנו ר יעקב שלום על מקומו אחריו כדיין. מהלוחמים בתיקונים בדת של הריפורמים. חיבר \"מחנה חיים\", \"פלס חיים\", ועוד. כמה מכתביו נדפסו בתוך \"תולדות סופרים\" לונדון תשכג מאת ר יצחק יעקב סופר מלונדון. נספד מאת ר גרשון שמערין ב\"אבל כבד\" פאקש תרמו. נימול ע\"י החת\"ס.","s":"אוצר הרבנים 6091; החת\"ס ותלמידיו; הונגריה; שם הגדולים השלישי; ברוין-אנשי מופת; תפארת יצחק עמוד ס","bk":[["אשכול הסופר – אגדות התלמוד",""],["מחנה חיים – שו\"ת",""],["פלס חיים – גיטין",""],["קול סופר – משניות",""],["שערי חיים - תהלים, ענינים",""],["שערי חיים - תהלים, ענינים, פלס חיים – גיטין , אשכול הסופר – אגדות התלמוד, קול סופר – משניות , מחנה חיים - שו\"ת",""]]},{"i":34432,"n":"סופר, יהודה מאראד","f":"אליעזר זוסמן מפאקש","k":"בעל מטה יהודה","bt":"תרכח","bp":"האלאש","dt":"תרעג - כ ניסן","dp":"אראד","b":"תלמיד השב\"ס, וזקנו ר יואל אונגר מפאקש. חתן ר יחיאל הכהן קליין מוינה-צעהלים. רב בוינה-תרנג (בבימ\"ד \"לוית חן\"), סירב לרבנות סעקעיהיד-תרנו בגלל מחלוקת, רב בקאדלבורג-תרנו, יעמרינג-תרנט, נאדי-סנט מיקלוש-תרסב, רבה הראשון של אראד-תרסה ובה קומם את הקהלה החרדית וחתנו ר חיים סופר על מקומו אחריו. הו\"ל ספר אביו \"מדרש מספר\" עם הוספות ממנו בשם \"מטה יהודה\".","s":"החת\"ס ותלמידיו; אוצר הרבנים 7041; טרנסילבניה; הונגריה; אהלי שם"},{"i":34433,"n":"סופר, יואל","f":"שמעון מקראקא","bt":"תרז","dt":"תרפה","b":"חסיד גור. חתן ר יהודה ליב קוזמירק מרישעשיטץ. סירב לכהן כאדמור מגוסטינין.","s":"וונדר-גליציה ח\"ג"},{"i":34434,"n":"סופר, יוחנן מערלוי - ירושלים","f":"משה מערלוי","k":"בעל אמרי סופר","bp":"תרפג","b":"נכד הכת\"ס. רב בערלוי(=אויהל), ניצל מהשואה ואחריה ראש ישיבה בבודפשט, ואח\"כ בערלוי(=אויהל) - ופעל לשיקום ניצולי השואה. עלה לירושלים והקים בה ישיבה - וכיהן כאדמו\"ר מערלוי(=אויהל). פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!).","s":"החת\"ס ותלמידיו; הונגריה; אוצר כתבי עת-לוין"},{"i":34435,"n":"סופר, יוסף יהודה מדרצ'קא","f":"אליעזר זוסמן מפאקש","b":"רב בדרצ'קא-תרמה וראש ישיבה, ואחיו ר שמואל על מקומו אחריו.","s":"הונגריה"},{"i":34436,"n":"סופר, יוסף יוזפא משיראוויץ","f":"החתם סופר","bt":"תקפה","bp":"פרשבורג","dt":"תרמג - טז תמוז","b":"חתן מרת שרל בת ר אלחנן משיראוויץ ועבר לשם. רב בשיראוויץ. נהרג ע\"י ערל אחד.","s":"אוצר הרבנים 8018; החת\"ס ותלמידיו"},{"i":34437,"n":"סופר, יוסף מגרוסורדין","b":"רב בגרוסורדין, ליוורנו.","s":"הונגריה"},{"i":34438,"n":"סופר, יוסף מטריפולי","bt":"תקך","dt":"תקץ - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד קהלת טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":34439,"n":"סופר, יוסף צבי משאמשון","f":"חיים","k":"בעל תולדות סופרים","bt":"תרך","bp":"סנט פעטר","dt":"תרץ - כ חשון","dp":"שאמשאן","b":"תלמיד השב\"ס. חתן ר עמרם בלום מבערטי-אויפאלו ועבר לשם. רב בשאמשון-תרנד על מקום ר פנחס וייס, וחתנו ר גבריאל יהודה איליוביץ על מקומו אחריו.","s":"אוצר הרבנים 8967; החת\"ס ותלמידיו; הונגריה; אהלי שם"},{"i":34440,"n":"סופר, יעקב חיים","f":"יצחק אליהו ברוך","k":"בעל כף החיים","bt":"תרל","bp":"בגדד","dt":"תרצט","dp":"ירושלים","b":"מחכמי בגדד, עלה לירושלים בשנת תרסד, מתלמידי \"בית אל\". חיבר \"כף החיים\", ועוד.","s":"גליס; אוצר 10071א; היברובוקס; רבנו האור לציון ח\"א ע' 69, המתמיד הירושלמי עמודים 275 - 276 הערה 204; יומא דהילולא","bk":[["כף החיים [על שו\"ע]",""],["חיים עד העולם",""],["חקי חיים",""],["יגל יעקב",""],["כף החיים",""],["כף החיים יורה דעה",""],["קול יעקב",""],["חוקי חיים - דרשות",""],["חיים עד העולם - סיומים למסכתות הש\"ס",""],["יגל יעקב - על התורה",""],["ישמח ישראל - על התורה",""],["כף החיים – או\"ח ויו\"ד",""],["קול יעקב - סת\"ם",""]],"e":"תרכ\"ז-תרצ\"ט"},{"i":34441,"n":"סופר, יעקב מילוטשקוב","b":"רב ביאלוטשקוב-תר\"מ","s":"אוצר הרבנים 9790"},{"i":34442,"n":"סופר, יעקב ממאר","b":"רב במאר. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב.","s":"אוצר כתבי עת-לוין"},{"i":34443,"n":"סופר, יעקב ממונקטש","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא.","s":"אוצר כתבי עת-לוין"},{"i":34444,"n":"סופר, יעקב ממרסיי","b":"רב במרסיי. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד.","s":"אוצר כתבי עת-לוין"},{"i":34445,"n":"סופר, יעקב מפינסק","dt":"תקכה - כז אייר","b":"סופר ודיין בפינסק","s":"אוצר הרבנים 9789"},{"i":34446,"n":"סופר, יעקב עקיבא ממיאווע","f":"הכתב סופר","bt":"תקצט","bp":"פרשבורג","dt":"תרעב - ב טבת","dp":"מיאווע","b":"חתן ר שמואל וייס ממיאווע ועבר לשם. מתורתו בספר זכרן שיצא לזכרו. בניו ר משה ממיאווע, ר נתן יהודה ממיאווע, ר שלמה מוינה. חתנו - בן גיסו ר שלמהצבי שטרסר מדברצין, ור אברהם פלזנבורג מטאפלטשן.","s":"החת\"ס ותלמידיו"},{"i":34447,"n":"סופר, יעקב שלום מאלגיר וצרפת","dt":"תרפז","b":"רב וסופר בווהראן ודיין שני בעניני חליצה, עבר למרסיל-צרפת. צייר ואמן - צייר דיוקנאות אישים מהתנ\"ך. הסכים על \"צו לצו\" לר סמחון חלאה ירושלים תרסד. חיבר \"הלבנון והשיריון\" על התנך - ואבד. התכתב עם ר יוסף משאש, ועם ר יצחק מרעלי. פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה.","s":"מלכי ישורון-חכמי אלגיר; אוצר כתבי עת-לוין"},{"i":34448,"n":"סופר, יעקב שלום מבודפשט","f":"חיים","k":"בעל תורת חיים","bt":"תרטו","dt":"תרפא - כד אלול","b":"תלמיד מהר\"ם שיק ונזכר בתשובותיו. מו\"צ בבודפשט.","s":"אוצר הרבנים 10332; אהלי שם; דרכי משה החדש ע' נו","bk":[["תורת חיים (סופר) [על שו\"ע או\"ח]",""],["ישבב הסופר - סנהדרין",""],["תורת חיים – שו\"ע",""]]},{"i":34449,"n":"סופר, יעקב שלום מטאפאלטשן","f":"מרדכי אפרים פישל","bt":"תקעג","bp":"פרשבורג","dt":"תריא - כז אב","dp":"טאפלטשן","b":"תלמיד החת\"ס, ור צבי הרש הלר חריף מאויבן. חתן הגביר ר אברהם פרידמן מטאפאלטשן ועבר לשם (בהשתדלות החת\"ס), רב בטאפאלטשן. (רצה לעלות לארץ בבחרותו - אולם החת\"ס לא הרשה לו).","s":"אוצר הרבנים 10331; החת\"ס ותלמידיו"},{"i":34450,"n":"סופר, יצחק","b":"מחכמי ג'רבה?. מבני דורו של ר אהרן פרץ, ור יצחק חדאד המזכירו ב\"תולדות יצחק\".","s":"ארזי הלבנון"},{"i":34451,"n":"סופר, יצחק ברוך מדמשק","f":"אליהו","dt":"תרסה - יט שבט","dp":"דמשק","b":"מחכמי דמשק. בנו ר יעקב חיים בעל כף החיים.","s":"ארזי הלבנון"},{"i":34452,"n":"סופר, יצחק יהודה ליב מדרהוביטש","f":"הכתב סופר","k":"בעל סופר מהיר","bt":"תרח","bp":"פרשבורג","dt":"תרסז - יג תמוז","b":"חתן הגביר ר דוד לינדנבוים מדרוהוביטש וכיהן שם כרב. ממלא מקום אביו בישיבת פרשבורג, ורב בפרשבורג לצד אביו. רב בקראקא על מקום דודו ר שמעון סופר. ממנהיגי היהדות בפולין, נשיא ארץ ישראל בגליציה-תרנא. בניו - ר שמואל בנימין מבודפשט, ר אברהם חיים דוד מבוריסלב. חתניו - בן אחיו עקיבא סופר מפרשבורג בעל \"דעת סופר\", ר אברהם פריידיגר מבודפשט, ר שלמה זלמן אולמן מגרוסורדין, ר ברוך בלוי מקלויזנבורג, ר נחום מגזניק מניו יורק, ר איסר יהודה גור אריה מניו יורק. חיבר חוברת בלעז \"מענה נגד הלשנות הברון קניגסוורטר\" תרמח. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!).","s":"וונדר-גליציה ח\"ג; החת\"ס ותלמידיו; אוצר הרבנים 11400; אוצר כתבי עת-לוין; תולדות המחבר בראש הספר","bk":[["סופר מהיר - חידושי סוגיות",""],["שם משמעון - הספד על ר' שמעון סופר",""]]},{"i":34453,"n":"סופר, יצחק יהודה ליב מלוגנו","f":"הדעת סופר","b":"רב בלוגנו.","s":"החת\"ס ותלמידיו"},{"i":34454,"n":"סופר, יצחק מליכטנשטט","b":"רב בליכטנשטט-ש\"ס","s":"אוצר הרבנים 10867"},{"i":34455,"n":"סופר, יצחק צבי מטימישואר","f":"ישראל מרדכי אפרים פי","k":"בעל מספר הסופר-תשכא","bt":"תרמח","bp":"שארוואר","dt":"תשכו - כו אדר","dp":"ירושלים","b":"לאחר שנתייתם גדל אצל דודו ר יוסף ליב סופר מפאקש. תלמיד הדעת סופר, ור יצחק קרפל מפאקש. חתן ר חיים יהודה לעווי מטימישואר-פאבריק. רב הקהילה החסידית \"פאבריק שטאט\" בטימישואר על מקום חותנו-תרעב כ-30 שנה. ניצל מהשואה ואחריה עסק בהתרת עגונות עם רבני רומניה, עלה לירושלים-תשיא. חיבר \"מעט צרי\" ועוד. בנו ר אליעזר מרדכי אפרים פישל כיהן כרב לצידו. והו\"ל ספר אביו ובו תולדות חייו, ופירוט של היתר עגונות לאחר השואה.","s":"החת\"ס ותלמידיו; טרנסילבניה; אוצר הרבנים 11482; הונגריה"},{"i":34456,"n":"סופר, יצחק צבי משופרון","f":"אברהם יעקב מטעט","b":"מחכמי שופרון. חתן ר יוסף אליעזר מילר משופרון.","s":"החת\"ס ותלמידיו"},{"i":34457,"n":"סופר, ישעיה מקידריניץ","b":"אב\"ד קידריניץ","s":"וונדר-גליציה ח\"ו"},{"i":34458,"n":"סופר, ישראל אפרים מנאנאש","f":"צבי הרש משאראש","k":"בעל אפסי ארץ","bt":"תקפב-ג","dt":"תרנט - טו כסלו","dp":"נאנאש","b":"נכד ר משה נתן שפירא מאלאמשד. תלמיד החת\"ס והכת\"ס, ור יצחק פרלס מבאניהאד, הישמח משה והדברי חיים מצאנז. חתן ר מרדכי וינשטוק מנאדי-טאראניא (טרין), ובזיוו\"ש חתן ר נחמיה גוטליב. רב בשאראש-פאטאק, אויהל, נאנאש-תרכב. היה בחברות קרובה עם ר שמואל קומודור מדאראג ור הערצקא מראצפעטרא. בהלוייתו השתתפו 90 רבנים. אחיו - ר נפתלי מקלינוארדין. חתנו - ר בן ציון הלפרט על מקומו בנאנאש. (העיד כי החת\"ס כשלמה ב\"שער המלך\" היה מכסה את פירוש \"טעם המלך\" ולא היה מעיין בו - מטעם ידוע).","s":"אוצר הרבנים 12143; החת\"ס ותלמידיו; אלפסי; הונגריה; ברוין-אנשי מופת; ברוין-אנשי מופת"},{"i":34459,"n":"סופר, ישראל דוד שמחה בונם","f":"שמעון המכתב סופר","bt":"תרו","dt":"תרנט - ז אדר","b":"נכד החת\"ס. תלמיד בישיבת אביו. חתן הגביר ר זושא אולריך מוארשא. עבר לקראקא, מגדולי חכמי קרקא, היה הדורש בהילולת הרמ\"א בקראקא על מקום אביו. חיבר שירים.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 12173"},{"i":34460,"n":"סופר, ישראל מרדכי אפרים משרוור","f":"אליעזר זוסמן מפאקש","k":"בעל זכרון אפרים-תרנה","r":"אב\"ד שארווער","bt":"תרטו","bp":"פאקש","dt":"תרנג - ג כסלו","dp":"שארוואר","b":"תלמיד הכת\"ס, וזקנו ר יואל אונגר מפאקש. חתן ר יצחק צבי רוטר מנאדי סנט מיקלוש. נבחר לרב בנאדי סנט-מיקלוש על מקום חותנו אולם סירב לרבנות הכללית מכיון שהקהילה סירבה להצטרף לארגון הקהלות האורטודוכסיות וכיהן כרב הקהלה החרדית בלבד שהתפלגה מהקהלה, רב בשארוואר-תרמ.ה. אביו ר זוסמן חיבר הקדמה לספר בנו שיצא אחרי פטירתו עם תולדותיו. הניח פירוש לתנ\"ך - בכת\"י.","s":"החת\"ס ותלמידיו; אוצר הרבנים 3111; טרנסילבניה; הקדמת ספר ברכת אפרים","bk":[["זכרון אפרים - בראשית",""]]},{"i":34461,"n":"סופר, כמוס מלוב","f":"מעתוק","bt":"תרסד","dt":"תשלב","b":"רב בזאויה-לוב-תרפב, עלה לארץ-תשט עם בני עדתו והתישבו במושב עלמא-ליד מירון, והמשיך לכהן כרב גם שם.","s":"מלכי חי\"ל-מרציאנו"},{"i":34462,"n":"סופר, מאיר מבגדד","b":"רב בבגדד - המאה ה-20.","s":"ארזי הלבנון"},{"i":34463,"n":"סופר, מאיר מקראקא","dt":"תקסד - טז אדר","b":"דיין בקרקא","s":"אוצר הרבנים 12914"},{"i":34464,"n":"סופר, מהר\"מ מפריעד","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח.","s":"אוצר כתבי עת-לוין"},{"i":34465,"n":"סופר, מנחם ממאראש-ואשארהעלי","f":"ישראל מרדכי אפרים פ'","k":"בעל מנחם משיב-תשלג","bt":"תרמ","bp":"נאדי - סנט מיקלוש","dt":"תשד - ט סיון","dp":"אושוויץ","b":"נתייתם בילדותו וגדל אצל דודו ר יוסף ליב סופר מפאקש. תלמיד השב\"ס, וזקנו ר אליעזר זוסמן סופר מפאקש, והדעת סופר. חתן ר שמחה בונם ארנפלד ממטרסדורף, ועבר לשם. רב במטרסדורף, ביהאר - נאדי-באיאם-תרע, מאראש-ואשארהעלי-תרעח ובנו ר שמואל חיים על מקומו אחריו. נסמך מאת: השב\"ס, ר דוד ניימן. מקורב לאדמור מנאסוד. בודפשט-תשד. נספה בשואה. בנו ר שמואל חיים ר במאראש ואשארהעלי.","s":"אוצר הרבנים 13271; החת\"ס ותלמידיו; טרנסילבניה; הונגריה; אהלי שם"},{"i":34466,"n":"סופר, מנחם מנלי מאושפיצין","f":"יהודה גולדשטין","k":"בעל שלשה עדרי צאן","bt":"תקסג","dt":"תרלג","b":"גיסו של ר משה יעקב שרף מזטור. סופר סת\"ם ומשמש של גדולי החסידות. נחשב מאוד בעיני הצבור והרבנים למרות שלא שימש ברבנות. חיבר \"שלשה עדרי צאן\" פרזמישל תרלד.","s":"וונדר-גליציה ח\"ג"},{"i":34467,"n":"סופר, מרדכי אפרים פישל מפרשב","f":"אליעזר זוסמן","bt":"תקמו","bp":"טיסמניץ או סטניסלב","dt":"תרג - א-ב תמוז","dp":"פרשבורג","b":"תלמיד החת\"ס, ור דוד דייטש מעיר חדש. חתן ר יעקב יהודה לאשברין מפרשבורג. רב בפרשבורג ומלמד לתלמידים צעירים (ובהם בני החת\"ס). היה מרואי החת\"ס יום יום. מתורתו ב\"רבבות אפרים\" מונרו תשס. רשם בפנקסו מחדושי רבו. בנו ר חיים בעל \"מחנה חיים\", ור יעקב שלום מט\"ש, ור אליעזר זוסמן פאקשר בעל \"ילקוט אליעזר\". מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר הרבנים 14074; החת\"ס ותלמידיו; אבני בית היוצר-וייס; אוצר כתבי עת-לוין"},{"i":34468,"n":"סופר, מרדכי חי מטריפולי","bt":"תקך","dt":"תקץ - בערך","b":"רב וסופר בי\"ד טריפולי, וחתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":34469,"n":"סופר, מרדכי מטריפולי","bt":"תס","dt":"תקל - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":34470,"n":"סופר, משה אברהם מטשארנא","f":"אליעזר זוסמן מהאלאש","bt":"תרכו","bp":"האלאש","dt":"תרצח - כח כסלו","dp":"טשארנא","b":"תלמיד השב\"ס. חתן ר שמואל בודנצקי מפאפא. מחכמי פאפא, האלאש, טשארנא-תרנב. מייסד חברת ת\"ת וחברות צדקה וחסד.","s":"החת\"ס ותלמידיו"},{"i":34471,"n":"סופר, משה בנימין וולף מפרשבורג","f":"מרדכי אפרים פישל","bt":"תקעו","bp":"פרשבורג","dt":"תקצד - כג כסלו","dp":"פרשבורג","b":"תלמיד החת\"ס. נפטר בבחרותו.","s":"החת\"ס ותלמידיו"},{"i":34472,"n":"סופר, משה דוד מסאסרגן","f":"חיים","bt":"תריח","dt":"תרסו - כז אדר","b":"חתן ר הלל פולק מסאסרגן, ועבר לשם, רב בסאסרעגן-תרנג על מקום חותנו.","s":"החת\"ס ותלמידיו; אוצר הרבנים 15353; טרנסילבניה"},{"i":34473,"n":"סופר, משה מבגדד","f":"מנשה","bt":"תרסד","bp":"בגדד","b":"עלה לירושלים בילדותו, מורה בבגדד, מנהל ת\"ת בביירות, מורה בגבעת עדה, מנהל הת\"ת החרדי \"יסוד הדת\" בחיפה-תרצו. פרסם מאמרים שונים.","s":"גאון-יהודי המזרח"},{"i":34474,"n":"סופר, משה מבני ברק","f":"אברהם חיים דוד","bt":"תרע","bp":"דרוהוביטש","dt":"תשנד","b":"נשיא כולל גליציה-אוסטריה ובעל בארות נפט. עלה לארץ-תש והתיישב בבני ברק, ממיסדי חוג חתם סופר. חתן ר יוסף אברמציק.","s":"וונדר-גליציה ח\"ג"},{"i":34475,"n":"סופר, משה מוואמאש","f":"הכתב סופר","bt":"תרא","bp":"פרשבורג","dt":"תרפז - כו שבט","b":"חתן הגביר ר אלימלך רוזנפלד מסעפלאק ועבר לשם. רב בוואמאש-אודווארהעלי (הסמוכה לסעפלאק). ציר בקונגרס היהודי-תרכט, רב בזיבנבירגן ומייסד חברת מחזיקי הדת בטרנסילבניה הדרומית ועמד בראשה.","s":"החת\"ס ותלמידיו; טרנסילבניה"},{"i":34476,"n":"סופר, משה מטיסא-פירעד","f":"יעקב שלום מטאפלטשן","k":"בעל מהר\"ם סופר","bt":"תר או תרט","dt":"תרעז - ז אלול","dp":"טיסא-פירעד","b":"נכד ר פישל סופר מפרשבורג-איש אמונו של החת\"ס. נתייתם בילדותו וגדל אצל דודו ר חיים סופר מבודפשט, ודודו ר אליעזר זוסמן סופר מפאקש. תלמיד הכת\"ס. חתן ר חיים מילר מברזאוויץ, וישב אצל גיסו ר ישראל מילר בברעזאוויץ וניהל שם ישיבה-תרלה, רב בסענדרא-תרלח, וחתנו בן דודו ר שמעון סופר על מקומו אחריו, טיסא-פירעד-תרנב, וחתנו ר שמואל בנימין שטרסר על מקומו אחריו. הניח חבורים בכת\"י. מאמרים ממנו ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"המגיד\" - סטמר תרפח, \"עמק הלכה\" - באטארקס תרפא. חתנו - ר שמואל רייניץ מפטרוואלאר.","s":"אוצר הרבנים 14972; החת\"ס ותלמידיו; הונגריה; אוצר כתבי עת-לוין; אהלי שם"},{"i":34477,"n":"סופר, משה מיאווע","f":"יעקב עקיבא בן הכת\"ס","bt":"תרכב","bp":"מיאווע","dt":"תש - כא תמוז","dp":"פרשבורג","b":"נכד הכת\"ס. תלמיד השב\"ס, ודודו ר מרדכי ברודא מיאווע. חתן ר נפתלי הלפרט מסיגט, ובזיוו\"ש חתן ר עקיבא סופר מפאפא - בן המכת\"ס. דרשן מחכמי מיאווע, וינה. בנו ר אברהם שמואל בנימין מוינה בעל \"זכרון לתולדות רעק\"א\".","s":"החת\"ס ותלמידיו"},{"i":34478,"n":"סופר, משה מערלוי","f":"שמעון - בן הכת\"ס","k":"בעל יד סופר-תשט","r":"דיין בערלוי","bt":"תרמה","bp":"ערלוי","dt":"תשד - כא סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור אברהם גרינבורג מקעזמארק. חתן ר משה יוחנן שנפלד ממיהאלפלווא, ועבר לשם-תרע, רב בערלוי(=אויהל)-תרעה לצד אביו. רוב כתביו אבדו בשואה, ובנו הו\"ל מתורתו בשם \"יד סופר\". נספה בשואה. בניו - ר אברהם שמואל בנימין מערלוי(=אויהל) בעל \"דברי סופר\", ור יוחנן מערלוי(=אויהל) - ירושלים בעל \"אמרי סופר\".","s":"החת\"ס ותלמידיו; אוצר הרבנים 14973; טרנסילבניה; מוריה 23-ג-ה; המבשר תורני גליון 197 עמוד יג, תוספת להמודיע טו סיון תשעד עמודים יח - יט,","bk":[["יד סופר",""],["יד סופר [שו\"ת]",""]]},{"i":34479,"n":"סופר, משה מפורט","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא.","s":"אוצר כתבי עת-לוין"},{"i":34480,"n":"סופר, משה מפעטרוזשן","f":"שלום סופר","dt":"תרעד - כב חשון","b":"רב בפעטרוזשן","s":"אוצר הרבנים 14971"},{"i":34481,"n":"סופר, משה מפפד\"מ","f":"משה שמעון","dt":"תמח - ט כסלו","dp":"פפד\"מ","b":"מחכמי פפד\"מ. זקנו של החת\"ס.","s":"רבני פרנקפורט"},{"i":34482,"n":"סופר, משה מפרג","f":"יצחק סופר","dt":"תו - כח שבט","b":"דיין בפרג","s":"אוצר הרבנים 14967"},{"i":34483,"n":"סופר, משה מפרשבורג","f":"השבט סופר","bt":"תרכז","dt":"תרמג - כה ניסן","dp":"פרשבורג","b":"נפטר בצעירותו בזמן לימודיו.","s":"החת\"ס ותלמידיו"},{"i":34484,"n":"סופר, משה מקראקא","f":"יואל מורשא -נכד החתס","b":"נכד ר שמעון סופר מקראקא בעל מכתב סופר. מחכמי קראקא, וינה פרשבורג.","s":"החת\"ס ותלמידיו"},{"i":34485,"n":"סופר, נחום מטאכאוי-הונגריה","dt":"תקעה - ל ניסן","b":"איש מופת בטאכוי-הונגריה. אמרו שכתב בעצמו את יום פטירתו.","s":"אוצר הרבנים 15880; אלפסי"},{"i":34486,"n":"סופר, נפתלי הירצקא","f":"יעקב שלום ממונקטש","bt":"תרלח","bp":"מונקטש","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר מרדכי יהודה הרצל מפאקש. מחכמי פאקש-תרסג. נספה בשואה.","s":"החת\"ס ותלמידיו"},{"i":34487,"n":"סופר, נפתלי מפעטשי-ניידורף","f":"מרדכי אפרים פישל","k":"בעל מטה נפתלי","bt":"תקעא-ט","bp":"פרשבורג","dt":"תרנט - טו אד\"ב","dp":"פעטשי-ניידרף","b":"תלמיד החת\"ס, והכת\"ס, ור שלמה זלמן בניהאד מפרשבורג. חתן ר ליפמן פרידמן. מקורב ל\"דברי חיים\" מצאנז. רב בטאפלטשן ולימד שם בישיבה, קדלבורג-תרטז, רזוביץ, שיראקא, פעטשי-ניידרף-תרלג. חיבר \"גבול בני נפתלי\" ועוד. (החת\"ס רשם חידוש ממנו בפנקסו). (ב\"החת\"ס ותלמידיו\" תאריך פטירתו - יז אדר).","s":"אוצר הרבנים 16132; אלפסי; החת\"ס ותלמידיו"},{"i":34488,"n":"סופר, נפתלי מקלינורדין","f":"צבי הרש משאראש","k":"בעל מעטה נפתלי","bt":"תקצו או תרט","dt":"תרעג - טו ניסן","dp":"קלינורדין","b":"תלמיד ר יחזקאל בנט בנייטרא, מהר\"ם שיק. דומ\"צ בקליינוורדיין-תרלח, וחתנו ר משה צבי לנדאו על מקומו אחריו.","s":"אוצר הרבנים 16149; החת\"ס ותלמידיו; הונגריה; אהלי שם"},{"i":34489,"n":"סופר, נתן יהודה מיאווע","f":"יעקב עקיבא בן הכת\"ס","bt":"תרכו","bp":"מיאווע","dt":"תשב","dp":"אושוויץ","b":"נכד הכת\"ס. תלמיד השב\"ס. חתן ר יעקב קופל אונגר מפרוינקירכן. מחכמי מיאווע, וינה. נספה בשואה.","s":"החת\"ס ותלמידיו"},{"i":34490,"n":"סופר, עזרא מרדכי מבגדד","dt":"תרצב","b":"מחכמי בגדד, וסופר בית הדין. תלמיד ר שלמה לניאדו.","s":"ארזי הלבנון"},{"i":34491,"n":"סופר, עקיבא יחזקאל מציגאנד","f":"חיים מבודפשט","dt":"תרעב - ל תשרי","dp":"ציגאנד","b":"נכד ר מרדכי אפרים פישל. תלמיד השב\"ס, מחכמי ציגאנד.","s":"החת\"ס ותלמידיו"},{"i":34492,"n":"סופר, עקיבא מסטניסלב","b":"מחכמי סטניסלב. ממשתתפי \"אהל מועד\".","s":"וונדר-גליציה ח\"ג"},{"i":34493,"n":"סופר, עקיבא מסערט","f":"שלמה אלכסנדר מסערט","b":"נכד הכת\"ס. רב בסערט, וינה. חתן ר עקיבא סופר מפאפא.","s":"החת\"ס ותלמידיו"},{"i":34494,"n":"סופר, עקיבא מפאפא","f":"שמעון המכתב סופר","k":"בעל צוף דבש","bt":"תקצט","bp":"פרשבורג","dt":"תרסג - ב טבת","dp":"פאפא","b":"נכד החת\"ס (והיה הילד האחרון שמל החת\"ס). תלמיד הכת\"ס. חתן ר חיים וולף מפאפא ועבר לשם-תרך. סירב לרבנות קראקא על מקום אביו. עסק במסחר בפאפא אך עסק רוב זמנו בתורה והיה בעל השפעה רבה - הכין את תקנון קהילת פאפא בדרך שתמנע את הפיכת הקהילה לניאולוגית.","s":"וונדר-גליציה ח\"ג; החת\"ס ותלמידיו; הונגריה; שער הספר","bk":[["צוף דב\"ש - תנ\"ך וחידושי הלכות",""]]},{"i":34495,"n":"סופר, עקיבא מפרשבורג","f":"השבט סופר","k":"בעל דעת סופר","bt":"תרלח או תרמב","bp":"פרשבורג","dt":"תשך - ב כסלו","dp":"ירושלים","b":"חתן דודו ר יצחק יהודה ליב סופר מדאהביטש - בן הכת\"ס. ר\"מ בישיבת פרשבורג-תרנח, מנהל רוחני בישיבה על מקום אביו-תרסב - בחיי אביו, רב בפרשבורג וראש הישיבה על מקום אביו-תרסז. ניצל מהשואה והגיע לשוויץ. עלה לירושלים-תש והקים ישיבת \"שבט סופר\" ו\"שערי שמחה\" בנו ר אברהם שמואל בנימין על מקומו אחריו. בניו - שמחה בונם מלוגאנו, ר יצחק יהודה ליב מלוגאנו. חתניו - ר פנחס דוד פרידיגר מבודפשט - ירושלים, ור יצחק יהודה ליב בלוי מבני ברק. פרסם מאמרים ב\"המעין\" - פרשבורג תרצד, \"הנשר\" - טירנוי תרצג-תשד, \"עמק הלכה\" - באטארקס תרפא, \"שערי אורה\" - מיהאלביץ תרץ-תרצד.","s":"החת\"ס ותלמידיו; אוצר הרבנים 16790; אוצר כתבי עת-לוין; אהלי שם; עולם החסידות גליון 238 עמוד 12 – 17, במחיצתם של גדולי ישראל חלק ב' עמודים 198 - 213","bk":[["אהל הינדא – דרוש ופתיחות לבני הישיבה",""],["דעת סופר – שו\"ת ועה\"ת",""],["דעת סופר מפרשבורג",""],["דעת סופר",""]]},{"i":34496,"n":"סופר, צאלח מבגדד","dt":"תרף","dp":"בגדד","b":"מחכמי בגדד. גיסם של ר אפרים הכהן, ושל ר יוסף רביע.","s":"ארזי הלבנון"},{"i":34497,"n":"סופר, צבי הירש","b":"תלמיד הבעש\"ט-תק\"כ","s":"אוצר הרבנים 17387"},{"i":34498,"n":"סופר, ציון מג'רבה","k":"בעל נוה ציון","b":"תלמיד ר יוסף ברבי. חיבר חדושים על השס התנך ובקבלה ורובם אבדו. למד עם חברו ר מרדכי אמייס הכהן. התכתב עם ר דוד קטורזא לימים רבה של תונס.","s":"ארזי הלבנון"},{"i":34499,"n":"סופר, רחמים מגרבה","b":"מדפיס בגרבה עם שותפו ר דוד עידאן, הדפיס כתב עת \"מקבציאל\" תרצה.","s":"אוצר כתבי עת-לוין"},{"i":34500,"n":"סופר, רפאל","b":"משב\"ק של האדמור ר יהושע מדזיקוב.","s":"וונדר-גליציה ח\"ב"},{"i":34501,"n":"סופר, שבתי מניו יורק","b":"פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, \"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":34502,"n":"סופר, שבתי מניו יורק","f":"חיים","k":"בעל שערי דעה","b":"רב בניו יורק-תרנט.","s":"אמריקה"},{"i":34503,"n":"סופר, שבתי מפרמישלא","dt":"שפ","b":"מליץ,פייטן,מדקדק,סופר מומחה בפרעמיסלא","s":"אוצר הרבנים 18078"},{"i":34504,"n":"סופר, שלום מברזנא","f":"ישראל אפרים שרייבר","dt":"כג אדר","b":"רב בברזנא-תרע. פרסם מאמרים ב\"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב.","s":"אוצר הרבנים 18174; אוצר כתבי עת-לוין"},{"i":34505,"n":"סופר, שלמה אלכסנדר מסערט","f":"שמעון - המכתב סופר","bt":"תריז","dt":"תרפד","b":"נכד החת\"ס. חתן הגביר ר משה זקס מסערט. רב בסערט. מראשי היהדות. הוציא לאור מספרי זקנו החתם סופר. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב.","s":"החת\"ס ותלמידיו, וונדר-גליציה ח\"ג; אוצר כתבי עת-לוין; אוצר הרבנים 18688; אהלי שם"},{"i":34506,"n":"סופר, שלמה מוינה שרייבר","f":"יעקב עקיבא בן הכת\"ס","k":"בעל זכרון לדוד","bt":"תרלא","bp":"מיאווע","dt":"תשח - ט תמוז","dp":"וינה","b":"תלמיד השב\"ס. חתן ר יצחק צבי רצרסדורפר מאנטורפן. מחכמי בודפשט, רב בוינה, ניצל מהשואה וברח ללונדון ויסד את קהילת \"תורת עץ חיים\". חתנו - ר עמרם גשטטנר מנייפעסט.","s":"החת\"ס ותלמידיו"},{"i":34507,"n":"סופר, שמואל בנימין מבודפשט","f":"יצחק ליב","dt":"תרצז-תשטז","dp":"לוגנו","b":"נכד הכתב סופר ונקרא על שמו. סגן נשיא קהלת החרדים בבודפשט.","s":"וונדר-גליציה ח\"ג"},{"i":34508,"n":"סופר, שמואל בנימין מדרצ'קא","f":"אליעזר זוסמן-ילקוט א","k":"בעל דברי סופרים","r":"רב דקרעטשקע","bt":"תרלג או תרם","dt":"תשג - כא שבט","dp":"פאקש","b":"תלמיד השב\"ס. חתן ר שרגא פיבל פולק מזנטא ועבר לשם. רב בדערעטשקע(=דרצ'קא) על מקום אחיו - ר יוסף ליב. בזענטא-תרעח, פאקש-תרצג. בנו ר שמחה בונם דוד מירושלים. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז.","s":"החת\"ס ותלמידיו; אוצר הרבנים 19482; אוצר כתבי עת-לוין; אהלי שם","bk":[["דברי סופרים - שו\"ת, וכללי מבוא התלמוד",""]]},{"i":34509,"n":"סופר, שמואל חיים מזאגרב","f":"שמעון סופר","b":"רב בזאגראב-תר\"פ","s":"אוצר הרבנים 19549"},{"i":34510,"n":"סופר, שמואל חיים ממארוש ואשארה","f":"מנחם ממארוש-ואשארהי","b":"חתן ר יוסף משה מייזלש ממארוש-אויוואר, רב במארוש-ואשארהי לצד אביו ור\"מ בישיבה, ועל מקומו אחריו. סירב לרבנות בודפשט. נספה בשואה.","s":"טרנסילבניה; הונגריה"},{"i":34511,"n":"סופר, שמואל מפפד\"מ","f":"משה","dt":"תקלט - טו סיון","dp":"פפד\"מ","b":"מחכמי פפד\"מ. אביו של החת\"ס.","s":"רבני פרנקפורט"},{"i":34512,"n":"סופר, שמואל מפרשבורג וירושלים","b":"בנה את ביה\"כ לפרושים בבתי הונגרים בירושלים-תרנא.","s":"פרשבורג-וינגרטן"},{"i":34513,"n":"סופר, שמחה בונם דוד מירושלים","f":"שמואל בנימין מדרטשקע","k":"בעל מזכרת פאקש","b":"רב בפאקש, עלה לירושלים. רב ביהמ\"ד זכרון ישראל (זופניק).","s":"החת\"ס ותלמידיו; הונגריה"},{"i":34514,"n":"סופר, שמחה בונם מלוגנו","f":"הדעת סופר","b":"רב בלוגנו.","s":"החת\"ס ותלמידיו"},{"i":34515,"n":"סופר, שמחה שמואל בנימין","f":"שלמה מברגסאס","b":"נכד הכת\"ס. חתן ר ישראל טריט מסטרי.","s":"החת\"ס ותלמידיו"},{"i":34516,"n":"סופר, שמעון אהרן מנובומסטא","bt":"ה'תרי","dt":"ה'תשד","b":"ר\"ש סופר ההדיר את הספר \"תורת משה\" עה\"ת של זקנו החת\"ס, ושילב בתוכו קטעים מחידושיו וחתם אותם בראשית התיבות מש\"מ [=מספר שיר מעון]. במהדורות האחרונות רוכזו קטעים אלו בסוף הספר.","s":"אוצר הרבנים 19899; אוצר הרבנים 19946","bk":[["התעוררות תשובה [שו\"ת]",""],["שיר מעון",""]]},{"i":34517,"n":"סופר, שמעון אהרן מעיר חדש","f":"משה מקראקא","bt":"תרנו","bp":"קראקא","dt":"תשג - כה תשרי","dp":"ליברטוב","b":"תלמיד הדעת סופר. חתן ר שמחה הכהן מנירנברג (בן ר בנימין זאב קאהן מבאדן). ר\"מ בישיבה בטירנא-תרפז אצל ר שמואל דוד הלוי אונגר, רב בעיר חדש-תרצט. נספה בשואה.","s":"החת\"ס ותלמידיו"},{"i":34518,"n":"סופר, שמעון מערלוי","f":"הכתב סופר","k":"בעל התעוררות התשובה","r":"רב בערלוי","bt":"תרי או תרה","bp":"פרשבורג","dt":"תשד - כא סיון","dp":"אושוויץ","b":"חתן ר יצחק פריד מקלינורדין, ובזיוו\"ש חתן ר חיים שמואל בירנבוים מדובנא-חתנו של ר עקיבא איגר (לפי אהלי שם - חתן דודו ר זלמן שפיצר בעל \"תיקון שלמה\". רב בקראקא לצד דודו האב\"ד ר שמעון סופר. בזיוו\"ש חתן ר בנימין שלמה זלמן שפיצר מוינה. רב בערלוי(=אויהל)-תרמא למעלה מ-60 שנה. בזיוו\"ש חתן ר יונה היינריך משליינינג. נספה בשואה. פרסם מאמרים ב\"המעין\" - פרשבורג תרצד. בניו - ר עקיבא מסטניסלב, ר שמואל חיים אב\"ד אגראם, ר משה ראב\"ד ערלוי(=אויהל), ר יעקב בנימין מאויהל ר שלמה זלמן מוינה בעל חדושי מהרז סופר, ר אברהם מפיומא-ירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה., \"תל תלפיות\" - וייצען תרנב-תרעד. חתנו - ר משה דייטש מלעמש.","s":"החת\"ס ותלמידיו; אוצר הרבנים 19898; הונגריה; אוצר כתבי עת-לוין; אהלי שם; המבשר תורני גליון 197 עמוד יג, תוספת להמודיע טו סיון תשעד עמודים טז - יט, כג","bk":[["התעוררות תשובה – שו\"ת",""]]},{"i":34519,"n":"סופר, שמעון מפאקש","f":"אליעזר זוסמן מפאקש","bt":"תרכז","bp":"האלאש","dt":"תרצא - ח תשרי","dp":"פאקש","b":"תלמיד השב\"ס, ור עמרם בלום מבערטי-אויפלו. חתן בן דודו ר משה סופר מסענדרא וטיסא פירעד. רב בסענדרא-תרנה על מקום חותנו. פאקש-תרעח על מקום אחיו ר יוסף ליב וראש ישיבה קטנה - בזמן הטרור הלבן שפגע ביהודים רבים בהונגריה. ערך ספר חותנו - מהר\"ם סופר עם הוספות ממנו.","s":"אוצר הרבנים 19897; החת\"ס ותלמידיו; הונגריה; אהלי שם"},{"i":34520,"n":"סופר, שמעון מפפד\"מ","dt":"תפב - יז שבט","dp":"פפד\"מ","b":"מחכמי פפד\"מ. ממשפחת החת\"ס.","s":"רבני פרנקפורט"},{"i":34521,"n":"סופר, שמעון מקראקא","f":"משה - החתם סופר","k":"בעל מכתב סופר-תשיב","bt":"תקפא","bp":"פרשבורג","dt":"תרמז - יז אד\"ב","b":"נקרא על שם ר שמעון בעל \"ילקוט שמעוני\" מאבותיו. חתן רד\"ב שטרנברג מקרולה, ועבר לשם. רב במטרדסדורף-תרד על מקום אביו, ירמוט, ניקלשבורג-תריד, קראקא-תרכא, וחתנו ר עקיבא קורנציר על מקומו אחריו. ציר בפרלמנט בוינה. חיבר \"מכתב סופר\" ירושלים תשיב, \"מקדש מעט\" תרנה, \"שיר חדש\" וינה תרסב. חתנו ר משה אשר רוט מאונסדורף. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז.","s":"וונדר-גליציה ח\"ג; החת\"ס ותלמידיו; טרנסילבניה; אוצר הרבנים 19896; הונגריה; אוצר כתבי עת-לוין"},{"i":34522,"n":"סופר, שמעון צבי הרש מפרשבורג","f":"מרדכי אפרים פישל","bt":"תקעח","bp":"פרשבורג","dt":"תקצו - ח אלול","dp":"פרשבורג","b":"תלמיד החת\"ס. נפטר בבחרותו.","s":"החת\"ס ותלמידיו"},{"i":34523,"n":"סופר-הרכבי, אליעזר מזסלב וירוש","f":"גרונם מנוברדוק","k":"בעל באר אליעזר","b":"תלמיד ר בצלאל הכהן בוילנא, הנצי\"ב. אב\"ד זסלב-ליד מינסק, עלה לארץ-תרס. חיבר גם הגהות על הזהר \"עין רואה\" ומהם נדפסו ב\"נצוצי הזהר\" לר ראובן מרגליות, ואח\"כ בנפרד-תשלב, ובראשם תולדותיו.","s":"מתוך קטלוג"},{"i":34524,"n":"סופר-לימא, רפאל מקראקא","f":"משה","b":"חתן ר אייזיק מדוברוונה (א1945) (או ר אייזיק מואנגרוב - (1945). דיין בקראקא-תל. מגיה בדפוס ר ליב מייזלש בקראקא. הו\"ל-תל ספר אביו \"חלקת מחוקק\" על אבן העזר עם הוספות ממנו. מנכדיו - ר משה מייזליש, ר רפאל מבארחוב בעל \"תוספות שבת\".","s":"אוצר הרבנים 17771; פין-קריה נאמנה"},{"i":34525,"n":"סופרינא, זאב מפיזא","b":"רב בפיזא-תר\"ע","s":"אוצר הרבנים 5521"},{"i":34526,"n":"סוצקבר, אברהם","f":"נפתלי הרץ","k":"בעל לידער","bt":"1913","bp":"סמרגון-ליטא","b":"גדל בוילנא. פרסם שירים בעברית ואידיש. בזמן השואה ישב בגיטו וילנא וזכה שם בפרס על הפואימה \"דאס קבר-קינד\", ברח-1943 והצטרף לקבוצת הפרטיזנים \"נקמה\" ביערות נארוטש. היה עד במשפטי נירנברג. עלה לארץ-1947. עורך ה\"גאלדענע קייט\", \"א שפיגל אוף א שטיין\". חיבר גם \"די פעסטונג\" נ\"י 1945, ועוד.","s":"ליטא"},{"i":34527,"n":"סוקול, יעקב מריאמפול","b":"רב בריאמפול-תרלג. חתן ר אברהם לעבענסארט מחסידי רוזין.","s":"וונדר-גליציה ח\"ג"},{"i":34528,"n":"סוקול, משה מבוריסלב","b":"מנהל הת\"ת מבוריסלב - תשובה אליו \"אמרי דוד\"-תרצא.","s":"וונדר-גליציה ח\"ג"},{"i":34529,"n":"סוקולובסקי, דב מירושלים","bt":"תרנז","dt":"תשמח","b":"תלמיד החפץ חיים. חתן ר אברהם צבי קמאי ממיר. עלה לירושלים.","s":"מתוך קטלוג"},{"i":34530,"n":"סוקולובסקי, משה מבריסק","r":"ראש ישיבת בריסק דליטא","bt":"תרכ\"ח","dt":"תרצא - יט טבת","b":"ראש ישיבה תורת חסד בבריסק-תרסא. פרסם מאמרים ב\"אהל תורה\" - ברנוביץ תרפד, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט.","s":"אוצר הרבנים 14974; אוצר כתבי עת-לוין; המבשר תורני גליון 211 עמוד כד; יומא דהילולא","bk":[["אמרי משה – שו\"ת",""],["מלאכת יום טוב – בעניני יו\"ט",""],["אמרי משה",""],["מלאכת יום טוב",""],["אמרי משה","מערכות"]],"e":"תרכ\"ח-תרצ\"א"},{"i":34531,"n":"סוקולובסקי, נח מחרקוב","f":"פסח","k":"בעל תולדות נח-כת\"י","b":"מחכמי חרקוב. חיבר שו\"ת בעניני גיטין ובסופו קונטרס שמות גיטין בשם \"תולדות נח\" - בכת\"י.","s":"מתוך קטלוג"},{"i":34532,"n":"סוקולובר, אפרים מרעננה","f":"מרדכי חיים סוקולובר","k":"בעל פני אפרים","bt":"תרסא","dt":"תשכח - ה אייר","b":"רב ברעננה","s":"אוצר הרבנים 3054"},{"i":34533,"n":"סוקולובר, מרדכי חיים משנדובה","f":"יוסף","bt":"תרלט","b":"תלמיד ר אברהם מסוכטושב. רב בשנדובה(=שנאדאווע)-פלך לומזה-תרסז, חורזיל. נסמך מאת: ר שמעון דב משדליץ.","s":"אוצר הרבנים 14166; אהלי שם"},{"i":34534,"n":"סוקולובר-ליכטנשטין, שלמה","f":"אברהם יקותיאל ליכטנש","k":"בעל שושנת עמקים","b":"רב-שנת תקל. חיבר גם \"דברי קהלת\".","s":"אוצר הרבנים 18552; שם הגדולים השלישי"},{"i":34535,"n":"סוקלוב, רפאל זאב וולף","b":"חתן ר יואב וינגרטן בעל \"חלקת יואב\". ר\"מ בוארשא, רב בסוקלוב-תרצ.","s":"אוצר הרבנים 17862"},{"i":34536,"n":"סוקמנסקי, דב מקובארסק","dt":"תש..","b":"רבה האחרון של קובארסק. נספה בשואה.","s":"ליטא"},{"i":34537,"n":"סורא, רפאל מקושטא","b":"יסד את ישיבת דמשק אליעזר בירושלים-תחילת שנות ה-תק'.","s":"רוזניס-תורכיה-ה"},{"i":34538,"n":"סורביאל, יהודה מברושא","b":"דיין בברושא-תמב אצל ר רפאל שמואל סאגיש.","s":"רוזניס-תורכיה-ד"},{"i":34539,"n":"סורביץ, ישראל","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט.","s":"אוצר כתבי עת-לוין"},{"i":34540,"n":"סורוז'ון, אהרן מקושטא","k":"בעל בית אהרן","b":"רב בקושטא-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":34541,"n":"סורוז'ון, ציון מקושטא ואזמיר","b":"מחכמי קושטא, אזמיר ביקר ברודוס-תצז ופגש את ר משה ישראל.","s":"רוזניס-תורכיה-ה"},{"i":34542,"n":"סורוצקין, אלחנן מזאלודק","b":"רב בזאלודק-תרצ\"ח","s":"אוצר הרבנים 2013"},{"i":34543,"n":"סורוצקין, בן ציון מזאכארין","f":"יחזקאל","bt":"תרג","b":"רב בזכרינא(=זאכארין)-פלך מוהילוב-תרך.","s":"אוצר הרבנים 3926(3936); אהלי שם"},{"i":34544,"n":"סורוצקין, ברוך מקליבלנד - א","b":"ר\"מ בישיבת טלז בקליבלנד. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב.","s":"אמריקה"},{"i":34545,"n":"סורוצקין, ברוך מקליבלנד - ב","k":"בעל חדושי הגר\"ב","b":"ר\"מ בישיבת טלז בקליבלנד-תשנא.","s":"אמריקה"},{"i":34546,"n":"סורוצקין, יואל מסטויפיץ","f":"בן ציון מזאכרין","k":"בעל משכיל ליוסף","bt":"תרלא","dt":"תרצח - י תמוז","b":"תלמיד ישיבת וולוזין כ-7 שנים. רב בצאריצין-תרס, סטויפיץ(=סטופצי)-פלך מינסק-תרסד. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט. חיבר \"משכיל ליוסף\", \"מלכי צדק\" - בכת\"י.","s":"אוצר הרבנים 7849; אוצר כתבי עת-לוין; אהלי שם"},{"i":34547,"n":"סורוצקין, ישראל מפתח תקוה","f":"זלמן סורוצקין","dt":"תשכו","b":"דיין בפתח תקוה-תשכ. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח.","s":"אוצר הרבנים 12012; אוצר כתבי עת-לוין"},{"i":34548,"n":"סורי, משה משלוניקי","b":"דיין בשלוניקי-שכה.","s":"זכרון שלוניקי"},{"i":34549,"n":"סוריא, דוד","b":"מדייני פורטוגיזיס","s":"ארזי הלבנון"},{"i":34550,"n":"סוריוינה, יעקב מונציה","k":"בעל סדר הניקור","b":"רב בונציה בזמן בעל \"מדבר יהודה\". חיבר \"סדר הניקוד\". הגיה ספרים רבים והוסיף להם הגהות. תלמיד השו\"ב ר צבי בן יצחק - תלמיד הרמ\"א.","s":"איטליה גירונדי-י סט; פין-כנסת ישראל"},{"i":34551,"n":"סוריוינה, יעקב מספרד","b":"מגדולי חכמי דורו בספרד-שנת צ'","s":"אוצר הרבנים 9792"},{"i":34552,"n":"סורירו, יעקב","bt":"תקכט","dt":"תריא","b":"מגדולי חכמי פאס","s":"אוצר הרבנים 9793"},{"i":34553,"n":"סורמאני, יוסף ממצרים","b":"דיין ברשיד-שנות ה-ת' אצל ר דוד גרשון, יחד עם ר שמואל נחמיאש ור יוסף בן מנשה.","s":"רוזניס-תורכיה-ד"},{"i":34554,"n":"סורמגה, יצחק","b":"מגדולי רבני ירושלים-ת\"ס","s":"אוצר הרבנים 10871"},{"i":34555,"n":"סורנגה, אברהם שמואל מירושלים","dt":"תקפה - ה אייר","dp":"מצרים","b":"מלמד תורה בירושלים, הוזמן לכהן כרב במצרים ושם נפטר.","s":"גליס; אוצר הרבנים 1416; ארזי הלבנון; רוזניס-תורכיה-ה"},{"i":34556,"n":"סורנגה, אליהו מרדכי מירושלים","f":"חיים דוד","bt":"תרלב","bp":"ירושלים","dp":"ירושלים","b":"דיין בירושלים אצל ר יעקב שמעון מטלון, ואצל הרי\"מ תג'יר, וישב בבי\"ד משותף של ספרדים ואשכנזים בשם \"משמרת הקדש\" בזמן מלחה\"ע ה-I.","s":"אוצר הרבנים 5415,2291; גאון-יהודי המזרח; ארזי הלבנון"},{"i":34557,"n":"סורנגה, אליהו מרדכי מירושלים","dt":"תרח - כד חשון","dp":"ירושלים","b":"מחכמי ירושלים, הניח חדושים בכת\"י ואבדו. חתם על שטר ירושה-תקץ.","s":"גאון-יהודי המזרח"},{"i":34558,"n":"סורנגה, חיים אברהם מירושלים","bt":"תעא","bp":"ירושלים","b":"מרבני ירושלים, בשליחות בצפון אפריקה-תקה, נשא ונתן עם ר אליהו ישראל בעל \"קול אליהו\", ועם ר\"י עייאש מאלגיר. בספר \"פתח הדביר\" מובא מפסקיו. שו\"ת ממנו בכתב יד בספריה הלאומית, נזכר ב\"שדי חמד\". לפי רוזניס התישב במצרים וכיהן כדיין.","s":"גליס; אוצר הרבנים 1082; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ה; ירושלים שנה א ח\"ב"},{"i":34559,"n":"סורנגה, חיים דוד פריסיאדו","f":"אליהו מרדכי","k":"הו\"ל מגיני ארץ ישראל","bt":"תרב","bp":"ירושלים","dt":"תרעה - כב טבת","dp":"ירושלים","b":"מחכמי ירושלים, וראב\"ד עדת הספרדים-תרס. בשנת תרסד הדפיס \"מגיני ארץ ישראל\" לר חיים נתן דמביצר מקראקא.","s":"גליס; אוצר הרבנים 6297; גאון-יהודי המזרח; ארזי הלבנון"},{"i":34560,"n":"סורנגה, חיים מירושלים","b":"מחכמי ירושלים, נזכר בשטר חזקה-תקעח כבעל חצר וחתומים עליו: שלמה ארוך, אברהם הכהן, רפאל חיים בנימין עשהאל.","s":"גאון-יהודי המזרח"},{"i":34561,"n":"סורנגה, חיים רפאל יהודה מירושל","b":"ראש השו\"בים בירושלים, תק-תר. נזכר ב\"חקרי לב\" לר יוסף רפאל חזן.","s":"גאון-יהודי המזרח"},{"i":34562,"n":"סורנגה, יהודה משלוניקי","dt":"שטז - י כסלו","dp":"שלוניקי","b":"מיוצאי ספרד, מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":34563,"n":"סורנגה, יוסף אליהו מירושלים","dt":"תקט - ה ניסן","dp":"ירושלים","b":"מרבני ירושלים, חברו של ר בנימין יונה נבון. בנו - ר רפאל חיים מרדכי.","s":"אוצר הרבנים 8708; גאון-יהודי המזרח; פרומקין-תח\"י"},{"i":34564,"n":"סורנגה, יוסף מאיר מירושלים","f":"מאיר","dp":"ירושלים","b":"מחכמי ירושלים-תקי, אחיו של ר שמואל מאיר בעל \"פרשת הכסף\" והסכים על ספר אחיו.","s":"אוצר הרבנים 8914; גאון-יהודי המזרח"},{"i":34565,"n":"סורנגה, יצחק מירושלים","b":"מחכמי ירושלים. הגיה כתבים של ר שמואל גרמיזון.","s":"גאון-יהודי המזרח"},{"i":34566,"n":"סורנגה, מאיר מירושלים","b":"ראש ישיבת הגביר ר אברהם מיוחס בירושלים-תקיח.","s":"אוצר הרבנים 12915; ארזי הלבנון; פרומקין-תח\"י"},{"i":34567,"n":"סורנגה, מאיר משלוניקי","b":"מחכמי שלוניקי-תקמ. אחיו של ר שמואל מאיר בעל \"פרשת הכסף\".","s":"ארזי הלבנון; זכרון שלוניקי-103"},{"i":34568,"n":"סורנגה, רפאל חיים מרדכי מי-ם","k":"בעל פי שנים","dt":"תקנט - כז אדר","dp":"ירושלים","b":"רב בירושלים בזמן ר מיוחס בכר שמואל בעל \"פרי האדמה\" ור יום טוב אלגזי. חתם עם חכמי ירושלים בשנת תקנז, חתם עם ר בנימין נבון ב\"קדשי דוד\", חיבר \"פי שנים\" שלוניקי תקסו - יחד עם חברו ר יונה נבון, וחיבר \"כל תוסיף\" ונדפס בתוך \"גט מקושר\" לר יונה נבון.","s":"גליס; אוצר הרבנים 17868; גאון-יהודי המזרח; איטליה גירונדי-מ נד; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":34569,"n":"סורנגה, רפאל יעקב מירושלים","b":"מחכמי ירושלים, בשליחות במרוקו-תקיט - על כתב השליחות חתומים מהרי\"ט אלגזי, החיד\"א ועוד, בדרכו חזרה עבר בליוורנו והסכים שם על \"חמדת ימים\"-תקכד.","s":"ארזי הלבנון; גאון-יהודי המזרח"},{"i":34570,"n":"סורנגה, שם טוב משלוניקי","b":"בשליחות קהלת שלוניקי-שכז בקושטא יחד עם ר משה אלמושנינו - החליף את ר משה ברוך שנפטר בשליחותו.","s":"רוזניס-תורכיה-ב"},{"i":34571,"n":"סורנגה, שמואל מאיר - מהר\"ש","f":"מאיר","k":"בעל פרשת הכסף","dt":"תקמב - אחרי","dp":"שלוניקי","b":"מחכמי ירושלים, דיין בשלוניקי. ראש \"ישיבת אברהם מיוחס\"-תקיח. חיבר \"פרשת הכסף\" שלוניקי תקיח, ועוד בכתב יד. מגיה בדפוס רפאל יהודה קלעי בשלוניקי, הגיה את \"מרכבת המשנה\"-תקמב. אחיו ר יוסף מאיר משלוניקי.","s":"גליס; אוצר הרבנים 19594; גאון-יהודי המזרח; ארזי הלבנון; זכרון שלוניקי-104; רוזניס-תורכיה-ה"},{"i":34572,"n":"סורקין, יעקב יואל מהומל","f":"צבי","bt":"תרי","b":"ר\"מ בהומל-פלך מוהילוב, רב בקאראפ-פלך צרניגוב-תרנד.","s":"אוצר הרבנים 10090; אהלי שם"},{"i":34573,"n":"סורקין, מקסימיליאן","f":"יהושע","bt":"1878","bp":"פוניבז","b":"למד משפטים בפטרבורג. עורך \"ווסחוד\", \"נובי ווסחוד\". חיבר מאמרים בעניני אמנות.","s":"ליטא"},{"i":34574,"n":"סורקין, נחום","f":"שלמה","bt":"1878","bp":"בילסק-פלך גרודנא","b":"מהנדס ועסקן ציוני, פרסם מאמרים ב\"הצפירה\", ועוד, ממאמריו: \"לביסוס עיוני של הציונות\". עורך \"דער טעלעגראף\" בוארשא.","s":"ליטא"},{"i":34575,"n":"סורקין-ניקולאיביץ, יוסף אוסיפ","k":"אוסיפ ניקולאיביץ","bp":"וילנא","dt":"1886","dp":"וילנא","b":"סופר שהתנצר, ועם זאת פעל למען היהודים. חיבר ספר \"קרן אור באפלה\" שעוסק בעלילת דם. פנה לטורגנייב-1882 ודרש ממנו לפעול כנגד התעמולה בעד הפוגרומים בעתונות הרוסית (טורגנייב ענה לו ב\"ראזסווייט\" 1883), פנה בענין זה גם לטולסטוי שעמו היה בידידות והוא שעורר בטולסטוי את הרצון ללמוד עברית והמליץ בפניו על ש. מינור כמורה. התאבד בוילנא.","s":"ליטא"},{"i":34576,"n":"סותו, ברוך משלוניקי","b":"מחכמי שלוניקי-תקע, הגיה \"ראש משביר\" לר יוסף שמואל מודיליאנו, מדפיס מהבקיאים ביותר בש\"ס ופוסקים בדורו.","s":"זכרון שלוניקי-116; רוזניס-תורכיה-ה"},{"i":34577,"n":"סותו, יהודה משלוניקי","b":"מדפיס בדפוס המנוח בצלאל אשכנזי בשלוניקי-תקכו.","s":"רוזניס-תורכיה-ה"},{"i":34578,"n":"סחולון, יוסף מאדרינופול","b":"רב באדרינופול-רע.","s":"רוזניס-תורכיה-א"},{"i":34579,"n":"סחייק, ששון מבגדד","f":"עזרא","bp":"בגדד","dt":"תשיב - ט תשרי","dp":"ירושלים","b":"אב\"ד בבגדד, ומפקח על השחיטה בבבל. תלמיד ר שלמה לניאדו, רב בבגדד על מקום ר יחזקאל עזרא יהושה הלוי שעלה לירושלים. עלה לירושלים. הניח דרשות בכת\"י, ונדפסו בירושלים - תשנו.","s":"ארזי הלבנון"},{"i":34580,"n":"סחרוב, אברהם מטרוקי","dt":"תשא","b":"חתן ר משה לנדינסקי מראדין. רב בראדין, טראקי. נספה בשואה.","s":"אוצר הרבנים 658; אנשי שם-אמריקה"},{"i":34581,"n":"ס\"ט, יצחק מקאליש","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר.","s":"אוצר כתבי עת-לוין"},{"i":34582,"n":"סטאון, דוד אליהו","bt":"1888","bp":"מאראטש","dt":"1952","b":"היגר לארה\"ב והיה תובע כללי במסצוסטס. מיסד הסתדרות ציוני אמריקה ונשיאה. יזם החלטה של הפרלמנט במסצוסטס לתמוך בהקמת בית יהודי ליהודים בארץ ישראל, ובעקבותיו הלכו פרלמנטים נוספים בארה\"ב. נשיא המגבית היהודית המאוחדת, ופעיל בהתאחדות יהודי ליטא באמריקה. קיבל אות כבוד ממשלת ליטא-1938.","s":"ליטא"},{"i":34583,"n":"סטאון, לואי","bt":"1884","bp":"מאראטש","dt":"1954","dp":"קליפורניה","b":"היגר לארה\"ב ולמד משפטים בבוסטון. יו\"ר התאחדות יהודי ליטא באמריקה, ויו\"ר אגודת העזרה של יוצאי מאראטש בבוסטון ופעל להקמת הגמ\"ח של עולי מאראטש בארץ ישראל.","s":"ליטא"},{"i":34584,"n":"סטאשאף, יהודה ליב מרכניץ","dt":"תקכז - ו אלול","b":"רב ברכניץ על מקום ר שבתי אהרן פרוסטיץ. נחשד בשבתאות ע\"י היעב\"ץ.","s":"אוצר הרבנים 7356; גרינוולד-סלובקיה והונגריה"},{"i":34585,"n":"סטביצקי, אבא מטיקטין","dt":"תש","b":"רב בטיקטין","s":"אוצר הרבנים 49"},{"i":34586,"n":"סטברובסקי, שמואל","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס.","s":"אוצר כתבי עת-לוין"},{"i":34587,"n":"סטבשסקי, אהרן אלתר הלוי","f":"מרדכי יצחק סטבסקי","b":"רב בסקאלמירז-תר\"ע","s":"אוצר הרבנים 1761"},{"i":34588,"n":"סטבשקי, דב בריש הלוי מקמינסק","f":"מרדכי מסטאבניץ","b":"תלמיד ר ישכר בער מרדושיץ. בנו - ר משה יחיאל מזאלישיץ. רב בקמינסק","s":"אוצר הרבנים 4570; אלפסי"},{"i":34589,"n":"סטול, משה שלום מפרוינבורג","f":"שלמה איסר","k":"בעל שם עולם","dt":"תשג","b":"תלמיד איישישוק, וילנא, חתן ותלמיד ר מרדכי רבינוביץ מסקידל. דרשן מפורסם. רב ביעזנא(=יאזנא)-פלך וילנא-תרסג, פרוינבורג(=פרויענבערג)-קורלנד-תרסז, בויסק. חיבר גם \"דרש משה\".","s":"אוצר הרבנים 15653; ליטא; אהלי שם; אובצינסקי-קורלנד"},{"i":34590,"n":"סטולוב, חיים שרגא פיבוש","b":"תלמיד ר אהרן הלוי מדובראוינא, ר\"מ י\"ז סלאטקין. רב בוילקי לוקי-תרע-פלך פעסקוב. נסמך מאת: ר לוי אהרן חן מארשא. בנו - ר אלתר-חתנו של ר שלום אליהו מהראדאק.","s":"אוצר הרבנים 6606; אהלי שם"},{"i":34591,"n":"סטולמן, יצחק מאזאריץ ודטרויט","f":"אריה ליב","k":"בעל מנחת יצחק","bt":"תרנז","bp":"רובל-פלך מינסק","b":"תלמיד ר משה חיים הכטמן מדרובילע, ישיבת דאוונא, ראדין, סלובודקא, קובנא, נוברדוק. נסמך מאת: ר משה מרדכי אפשטין, ר אליעזר רבינוביץ ממינסק, ר שמעון שקופ, ר משה חיים הכטמן. רב ור\"מ במאזיד-יודביץ-תרעז, אזריטש-תרפד. היגר לארה\"ב וכיהן כרב בדטרויט-תרפד, עלה לירושלים.","s":"אוצר הרבנים 10872; אמריקה; אנשי שם-אמריקה"},{"i":34592,"n":"סטון, יצחק אלבגדדי","f":"יעקב","bp":"טבריה","dt":"תרף","dp":"מצרים","b":"שו\"ב במצרים.","s":"ארזי הלבנון"},{"i":34593,"n":"סטופאווא, יוסף יעקב מסעניץ","bp":"שטמפן (=שטאמפי)","b":"רב בסעניץ. ישב בבוררות ביערגן-תקכא כדיין מכריע יחד עם ר משה המבורגר מעיר חדש - בסכסוך שבין קהלות פרשבורג שטמפן(=שטאמפי) וסערדהאלי - יחד עם נציגי הקהלות ר שמעון דוד מסערדהאלי, ר יצחק איזיק קאליש, ר יצחק לנדא כנציג פרשבורג.","s":"פרשבורג-וינגרטן; שטמפן - הרצוג"},{"i":34594,"n":"סטורה, אברהם מאלגיר","f":"חיים","bt":"רפ","dt":"שן - בערך","b":"רב בווהראן. תשובה אליו מר אברהם ן טוואה ונזכר בשו\"ת נפך.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34595,"n":"סטורה, אברהם מאלגיר - א","bt":"רך","dp":"ש - בערך","b":"רב בבג'איה-אלגיר. התכתב עם הרשב\"ש.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34596,"n":"סטורה, אברהם מאלגיר - ג","bt":"תר","dt":"תרע - בערך","b":"רב באלגיר. הסכים על סידור \"תפלה בכל לשון\", מחזור קטן אלגיר - ליוורנו תרמו. מתורתו בקונטרס \"רוממות אל\". נזכר אצל ר יוסף אזוביב ב\"תוכחות מוסר\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":34597,"n":"סטורה, חיים מאלגיר","f":"משה","bt":"רס","dt":"של - בערך","b":"בא מתלמסאן, רב משורר וספרא רבה בווהראן. תשובות אליו מר אברהם ן טוואה. ר אברהם גבישון שבחו על שיריו. העתיק \"גנת אגוז\" בהיותו בתלמסאן.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34598,"n":"סטורה, יוסף מאלגיר - א","bt":"תץ","dt":"תקס - בערך","b":"רב באלגיר. מתורתו ב\"קרבן אהרן\" לר אהרן מועטי - ליוורנו תקלג.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34599,"n":"סטורה, יוסף מאלגיר - ב","bt":"תרז","bp":"אלגיר","dt":"תרף - בערך","b":"תלמיד בסמינר לרבנים בפאריס. רב בענאבא(=בון)-תרלט, למדייא-אלגיר-תרנא. לאחר שהביע דעתו כנגד חנוך ילדי ישראל בבתי ספר צרפתים נתבקש לעזוב את רבנותו בענאבא, ואז עבר ללמדייא. נזכר ברשימת המסייעים ל\"והוכח אברהם\" לר אברהם חלימי.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34600,"n":"סטורמן, יצחק איזיק","f":"יעקב מאיר","bt":"תריג","b":"רב בטאטארסק-פלך מוהילוב-תרמה.","s":"אוצר הרבנים 11201; אהלי שם"},{"i":34601,"n":"סטיפיאו, יעקב יוסף מסעמניץ","b":"רב בסעמניץ(=סעניץ)-תקו ור צבי הירש ברודיא על מקומו אחריו, קיצע-תקלב. ישב כדיין בדינו של ר נתן אורהולץ שנחשד ע\"י היעב\"ץ בשבתאות ויצא זכאי.","s":"גרינוולד-סלובקיה והונגריה"},{"i":34602,"n":"סטיפנסקי, אברהם הלוי","f":"ברוך מאלכסנדרי","k":"בעל דרך אמונה-כת\"י","bt":"תקנו","dp":"ירושלים","b":"רב בברזדוב-ווהלין ובנו ר חיים על מקומו אחריו, עלה לירושלים-תרמ. חיבר גם \"שמוע ומוסיף\", \"כף קמח\", \"זר זהב\" - בכת\"י.","s":"אוצר הרבנים 642; אהלי שם"},{"i":34603,"n":"סטיפנסקי, חיים הלוי מברזדוב","f":"אברהם מברזדוב","k":"בעל נתיב חיים - כת\"י","bt":"תריד","b":"רב בברזדוב(=בערעזדיב)-ווהלין-תרמ על מקום אביו. מתורתו בספר אביו \"אות לטובה\". חתניו: ר רפאל רובינשטין מווראניווצע, ר אלימלך דרברמדיקר ממיזקאיו, ר זלמן מראוונא. בנו ר שמואל ברוך.","s":"אוצר הרבנים 6094; אהלי שם"},{"i":34604,"n":"סטלביץ, מאיר מליטא וירושלים","k":"בעל מבית מאיר","bt":"תרלא","bp":"איישישוק","dt":"תשיא או תשט","dp":"ירושלים","b":"תלמיד ר אלכסנדר משה לפידות. רב בגירטיגולה על מקום ר שמואל אפשטין בעל \"אמרי שפר\", סאבז, קופצאווה-תרעג, דמיטרובקה, שביז, חסלביץ. עלה לארץ-תרצג וכיהן כרב בשכונת \"זכרון משה\" בירושלים. הוכתר כ\"ראש מורי ההוראה\" בירושלים-תשב. פרסם מאמרים ב\"יגדיל תורה\" - בוברויסק תרפח (תחת שלטון הקומוניסטים ברוסיה), \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"המאור\" - תל אביב תרצה, \"תבונה\" - ירושלים תשא-תשח, \"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"ליטא; אוצר הרבנים 12917; אוצר כתבי עת-לוין"},{"i":34605,"n":"סטלניץ, מאיר מירושלים","b":"רב בשכונת זכרון משה בירושלים-תשה.","s":"מתוך קטלוג"},{"i":34606,"n":"סטמפל, בן ציון שלום אליעזר","f":"משה מקראקא","b":"חתן ר אלתר ויינברגר מטורקא בניו יורק.","s":"וונדר-גליציה ח\"ג"},{"i":34607,"n":"סטמפל, משה מקראקא","f":"שרגא פיבל מקראקא","bt":"תרע","bp":"קראקא","dt":"תשא - ד אב","b":"חתן האדמור ר בן ציון מבובוב. נספה בשואה.","s":"וונדר-גליציה ח\"ג; אנשי שם-אמריקה"},{"i":34608,"n":"סטמפל, צבי מקראקא","f":"שרגא פיבוש מקראקא","bt":"תרסה","dt":"תשב","b":"מראשי המזרחי. נספה בשואה (היה מראשוני הנרצחים באושויץ - ומשפחתו קבלה תיבה עם אפרו).","s":"וונדר-גליציה ח\"ג"},{"i":34609,"n":"סטמפל, שמואל יהודה מלונדון","f":"משה מקראקא","b":"מראשי חסידי בובוב בלונדון. חתן ר שלמה קליינמן.","s":"וונדר-גליציה ח\"ג"},{"i":34610,"n":"סטמפל, שרגא פיבוש מקראקא","f":"יצחק מקראקא","bt":"תרם","bp":"קראקא","dt":"תשה","b":"חתן הגביר ר ליב בוכנר (בעל מכרות). מנכבדי הקהלה, חבר בסיים-תרפב, ראש הקהילה-תרץ. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":34611,"n":"סטמפלר, דב בריל מקולומיאה","b":"מחכמי קולומיאה. ממשתתפי \"ועד חכמים\".","s":"וונדר-גליציה ח\"ג"},{"i":34612,"n":"סטן, אהרן הרופא מסופיה","f":"יוסף","b":"דיין בסופיה-רצה אצל ר בנימין בן מאיר הלוי-בעל המחזור האשכנזי בשלוניקי.","s":"רוזניס-תורכיה-א,ב"},{"i":34613,"n":"סטנוב, יצחק הלוי מברלין","f":"משה","k":"בעל נבואת הילד","bt":"תצב","dt":"תקסד","b":"מדקדק ומדפיס. הו\"ל \"נבואת הילד\" ועוד. בנו ר שענעמן בעל \"מנחת בכורים\" - ובו השיב להשגות שעשה ר יהודה בן זאב לספרי אביו.","s":"איטליה גירונדי-י רכט; פין-כנסת ישראל; היברובוקס","bk":[["אגרת אדר היקר",""],["אגרת בית תפלה",""],["דברי ריבות",""],["הולך תמים",""],["משלי אסף",""],["סידור ויעתר יצחק",""],["ספר המדות",""],["שפתי רננות",""]]},{"i":34614,"n":"סטניסלבסקי, אפרים ממיאסקיבקא","f":"ברוך","k":"בעל סמא דחיי","bt":"תרטו","b":"תלמיד חותנו ר שמעון יוסף אוירבך. רב במיאסקיבקא(=מיסטקובקה)-פודוליה-תרמו. נסמך מאת: ר ראובן ור נחמן יוסף מקעשינוב, ר שלמה חריף. חיבר גם \"סמא דחיי\", \"מנחת אפרים\", וחיי אריכי\", \"סולת בלולה\", ועוד.","s":"אוצר הרבנים 3053,3087; אהלי שם"},{"i":34615,"n":"סטניסלבסקי, נתן מזבוקריץ","f":"ברוך","bt":"תרלב","b":"רב בזבוקריץ(=זאבאהקריץ)-פודוליה-תרסא.","s":"אוצר הרבנים 16342; אהלי שם"},{"i":34616,"n":"סטנפר, איזיק מלייפון","dt":"תשג","b":"רבה האחרון של לייפלנגי(=לייפון)-ליטא. נספה בשואה.","s":"אוצר הרבנים 1956; ליטא"},{"i":34617,"n":"סטנר, ראובן","f":"נחמן ממאקוב","dt":"תשיח","s":"וונדר-גליציה ח\"ו"},{"i":34618,"n":"סטראסוור, לייב","b":"מקובל,רב ברעכניץ-תק\"מ","s":"אוצר הרבנים 12602"},{"i":34619,"n":"סטרזגובסקי, אברהם דוד מקראקא","b":"מחכמי קראקא - תשובה אליו ב\"חלקת יעקב\". פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט.","s":"וונדר-גליציה ח\"ג; אוצר כתבי עת-לוין"},{"i":34620,"n":"סטריזובר, יהודה מרישא","f":"צבי","k":"בעל מנחת יהודה","b":"עלה לירושלים והתישב בבתי רנד. חיבר \"מנחת יהודה\" ירושלים תרפז.","s":"וונדר-גליציה ח\"ו"},{"i":34621,"n":"סטרל, מרדכי יהודה מארה\"ב","k":"בעל דברי מרדכי","b":"רב בארה\"ב. חיבר \"דברי מרדכי\" נ\"י תרעח.","s":"אמריקה"},{"i":34622,"n":"סטרליסקר, מרדכי מברוד","f":"דוד מברודי","k":"בעל תאנית ישרון","bt":"תקסז","bp":"ברודי","dt":"תרלו","dp":"מיהאלען","b":"חזן וסוחר מביהאלען-תרי. פרסם מאמרים בכתבי עת שונים. חיבר \"תאנית ישרון\" זולקוא תקצה, \"זכר עולם\" ובו הספד על אביו חזן קהלת פעסט.","s":"וונדר-גליציה ח\"ג"},{"i":34623,"n":"סטרליסקר, פנחס","dt":"תשג","b":"רב בדוברומיל","s":"אוצר הרבנים 16937"},{"i":34624,"n":"סטרליסקר-וולזינגר, דוד מברוד","f":"מרדכי מסטרליסק","bt":"תקמג","bp":"ברודי","dt":"תרח","b":"סוחר חזן למדן ואמן בברודי, חזן באויבן ישן-תקפג, פעסט-תקץ. היה מגדולי החזנים בהונגריה (בתפלת כל נדרי עמדו אלפי אנשים מחוץ לביהכ\"נ עד חצות הלילה - אז הסתיימה התפלה). לזכרו הו\"ל בנו - \"זכר עולם\".","s":"וונדר-גליציה ח\"ג"},{"i":34625,"n":"סטרליץ, שמעון","bt":"תרסו","dt":"תשטו","b":"בקי,מחכמי ירושלים. עורך \"בית הבחירה\".","s":"אוצר הרבנים 19900; היברובוקס","bk":[["שם משמעון",""]]},{"i":34626,"n":"סטרסטי, אליהו","dt":"תש","b":"רב בסיניווקה","s":"אוצר הרבנים 2166"},{"i":34627,"n":"סטרסטי, אליהו","dt":"תשג","b":"רב בלאכווע","s":"אוצר הרבנים 2167"},{"i":34628,"n":"סטשבסקי, אהרן","k":"בעל מטה אהרן","b":"תלמיד בעל חדושי הרי\"ם. חיבר גם \"קרבן אהרן\".","s":"אלפסי"},{"i":34629,"n":"סטשבסקי, אהרן אלתר מסקאלמירז","f":"מרדכי יצחק מדזיאלשיץ","b":"חתן ר משה יואל הגרמן מיעזוב. רב בסקאלמירז.","s":"אהלי שם"},{"i":34630,"n":"סטשבסקי, אהרן הלוי מזדונסקא","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר.","s":"אוצר כתבי עת-לוין"},{"i":34631,"n":"סטשבסקי, מרדכי יצחק","f":"משה יחיאל מקמינסק","b":"נסמך מאת: ר חיים אליעזר ואקס מקאליש בעל \"נפש חיה\". רב בקאשיץ-תרלח, סלמניק, דזיאליזיץ(=דזיאלאשיץ)-פלך קיעלץ על מקום אביו. בניו: ר דוד מנחם, ר אהרן אלתר מסקאלמירז, ר דב בריש.","s":"אוצר הרבנים 14196; אהלי שם"},{"i":34632,"n":"סטשבסקי, משה יחיאל מקמינסק","f":"דוב בער הלוי","bt":"תקעד","dt":"תרסד","b":"מחסידי פשיסחא. רב בקמינסק, עלקיש, קונצקי-תרי, דזיאלשיץ(=זאלשיץ)-פלך קיעלץ ובנו ר מרדכי יצחק על מקומו אחריו.","s":"אוצר הרבנים 15482; אהלי שם"},{"i":34633,"n":"סיאני, כמוסי יחיא מתימן","f":"יהודה","b":"רב בתימן-[תר..] ומחבר אחד הכללים הידועים בתימן (כ\"ד י\"ד זמ\"ן נק\"ט ישר\"ם קצ\"ב הרי הוא כחמור יאכל עשב - והוא רמז לכל מה שחייב יהודי לדעת).","s":"ארזי הלבנון"},{"i":34634,"n":"סיבוני, נסים ממראקש","b":"מחכמי מראקש בזמן ר מסעוד ן מוחא, חתם על כתב יוחסין של רבני מראקש לר יוסף פינטו.","s":"ארזי הלבנון"},{"i":34635,"n":"סיגל, אברהם יצחק מארה\"ב","k":"בעל ברכת אברהם יצחק","b":"רב בארה\"ב. חיבר \"ברכת אברהם יצחק\" שיקגו תרצא.","s":"אמריקה"},{"i":34636,"n":"סיגל, יהושע מארה\"ב","k":"בעל עירוב והוצאה","bt":"תרו","bp":"קוטשבורק-פלך פלוצק","dt":"תרע - יג אדר","dp":"ניו יורק","b":"נסמך מאת ר יהושע מקוטנא. אב\"ד שרפס והיה מחלוקת כנגדו מצד החסידים, היגר לניו יורק-תרמד וכיהן כרב בניו יורק (לאחר פטירת ר יעקב יוסף), ביקר בארץ-תרסח. חיבר גם \"אזני יהושע\" ושם בסוף הספר לתולדותיו. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו.","s":"אוצר כתבי עת-לוין; מתוך קטלוג"},{"i":34637,"n":"סיגר, יהודה ליב מקאמאי","bt":"תרסח","dt":"תשא - אב","b":"רבה האחרון של קאמאי.","s":"אוצר הרבנים 7357; ליטא"},{"i":34638,"n":"סיגרי, יהודה ממרוקו","b":"מו\"ץ במרוקו, מתלמידיו ר\"י בן נאים שהביא חדוש ממנו בשם ר שלמה אלגזי.","s":"מלכי רבנן"},{"i":34639,"n":"סיד ן, אברהם מדובניצה ופיליבי","f":"מנוח מדובניצה","b":"רב בדובניצה על מקום אביו, פיליפופולי(=פיליבי)-תקסח, עלה לצפת ואחיו ר יהודה על מקומו אחריו. סייע בהדפסת ספר אחיו ר יהודה - \"אות אמת\".","s":"ארזי הלבנון; רוזניס-תורכיה-ה,ו"},{"i":34640,"n":"סיד ן, וידאל משלוניקי","dt":"שצד - יח תשרי","dp":"שלוניקי","b":"מחכמי ישיבת ר אברהם מוטאל. גביר עשיר ורב בשלוניקי.","s":"זכרון שלוניקי; מלכי רבנן; רוזניס-תורכיה-ד"},{"i":34641,"n":"סיד ן, יהודה ליאון מאזמיר","f":"יעקב","k":"בעל יסד המלך","b":"רב באזמיר.","s":"ארזי הלבנון"},{"i":34642,"n":"סיד ן, יהודה מפיליבי","f":"מנוח מדובניצה","k":"בעל נר מצוה","bp":"דובניצה","dt":"תקעה","dp":"צפת","b":"אחר שנתייתם גדל אצל ר ראובן בן יעקב מסופיה, תלמיד ר ישכר אבולעפיה (כמו גם אביו). דיין מו\"צ וסופר הקהל בסופיה-תקל, מו\"צ באדרינופול-תקן וסופר סת\"ם, רב בקיוססטנדיל-תקס, פיליפופולי(=פיליבי)-תקסח על מקום אחיו - ר אברהם שעלה לארץ ור אהרן אברהם ן ארוליא על מקומו אחריו. חיבר גם \"אות אמת\" ויצא לאור בסיוע אחיו - ר אברהם - שלוניקי תקנט. בנו - ר מנוח ג'יליבון מפיליבי. חתניו - ר ישראל ברכה מסופיה, ר חיים מושקונה מבזארג'יק.","s":"ארזי הלבנון; רוזניס-תורכיה-ה,ו","bk":[["נר מצוה",""],["אות אמת",""]]},{"i":34643,"n":"סיד ן, יום טוב ממצרים","f":"יצחק ן סיד","b":"רב במצרים. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא.","s":"אוצר הרבנים 7931; רוזניס-תורכיה-ב"},{"i":34644,"n":"סיד ן, יצחק מטולדו","b":"ש\"ץ בטולדו. מגדולי חכמי התורה והתבונה בספרד-שנת ל, ולבקשת המלך אלפונסו העשירי בספרד חיבר לוחות חשבון בחכמת התכונה הנקראים \"לוחות אלפונסו\", הלוחות תורגמו לעברית בידי ר קלונימוס בן קלונימוס.","s":"אוצר הרבנים 10873; פין-כנסת ישראל"},{"i":34645,"n":"סיד ן, מנוח ג'יליבון מפיליבי","f":"יהודה","b":"מחכמי פיליבי, אבי משפחת סיד בבולגריה.","s":"רוזניס-תורכיה-ה"},{"i":34646,"n":"סיד ן, מנוח מסופיה ודובניצה","f":"יעקב","b":"תלמיד ר ישכר אבולעפיה בסופיה. רב בדובניצה ובנו ר אברהם על מקומו אחריו. נפטר צעיר. עוד מבניו - ר יהודה בעל \"נר מצוה\". אחיו - ר יהודה.","s":"רוזניס-תורכיה-ה"},{"i":34647,"n":"סיד, אברהם","f":"משה","k":"בעל תשב אנוש","b":"חיבר גם \"בחפזון פסח\" שלוניקי תרלא. חתם שמו - אס\"י (=אברהם סיד).","s":"מתוך קטלוג"},{"i":34648,"n":"סיד, יעקב מדופניצה","f":"יהודה","b":"מחכמי דופניצה-ליד סופיה-תלב.","s":"רוזניס-תורכיה-ד"},{"i":34649,"n":"סיד, יעקב מירושלים","dp":"ירושלים","b":"מחכמי ירושלים, חתן ר יצחק אלגזי בעל \"דרך עץ החיים\". נספד ב\"יסוד המלך\" ע\"י בנו, וע\"י נכדו ר נסים חיים משה מודעי.","s":"פרומקין-תח\"י"},{"i":34650,"n":"סידון, אהרן מאלגיר","bt":"תקס - בערך","bp":"תלמסאן","dt":"תרכד","b":"מצאצאי ר עלאל ן סידון. דיין בתלמסאן, מוסתאגם-תרך (ברח מתלמסאן בגלל פרעות הערבים) ובנו ר יהודה על מקומו אחריו. היה בקשר הלכתי עם ר פארוז קרסיינטי.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34651,"n":"סידון, אשר","f":"שמעון סודן","b":"רב בוורשץ-תר\"נ","s":"אוצר הרבנים 3508"},{"i":34652,"n":"סידון, יקותיאל מאלגיר","dt":"תרצב","b":"נכד ר אהרן ממסתגאנם. תלמיד ר חיים בלייח בתלמסאן. רב ברוליזאן-אלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34653,"n":"סידון, ישועה מאלגיר","bt":"תק","dt":"תקץ","b":"רב ודיין בתלמסאן-תקמח. חתם עם רבני אלגיר בהסכמה ל\"זרע יעקב\". מתורתו ב\"קרבן אהרן\" לר אהרן מועטי.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34654,"n":"סידון, מימון מאלגיר","bt":"רל - בערך","dt":"שי - בערך","b":"רב בתלמסאן-אלג'יר. חיבר שיר לכבוד ספר \"מרכבת המשנה\" לר יוסף אלשקר. (יש אומרים כי הוא נכד-מצד אביו לר ישועה בן מימון ן סעדון - וכי מקור השם \"סידון\" הוא \"סעדון\").","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34655,"n":"סידון, מרדכי מאלגיר","f":"אליעזר","bt":"תץ","dt":"תקן - בערך","b":"רב באלגיר, עלה לארץ והתישב בצפת. בשליחות צפת בעירק-לפני תקכח, ועוד.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34656,"n":"סידון, משה מאלגיר","f":"אליעזר","bt":"תץ","dt":"תקס","b":"רב באלגיר, עלה לארץ והתישב והיה מחכמי צפת, בשליחות בעירק, כורדיסטן והודו-תקכח-תקמא. אחיהם של ר ישועה ור מרדכי.","s":"גליס; שא\"י"},{"i":34657,"n":"סידון, סעדיה אל חאייך מאלגיר","bt":"תע","dt":"תקן","b":"רב בתלמסאן. חיבר רשימת רבני העיר הקדומים - הנזכרים בערב יוה\"כ, וכן פיוטים קדומים מרבני תלמסאן - (כת\"י שהיה אצל ר יצחק מורלי מאלגיר).","s":"מלכי ישורון-חכמי אלגיר"},{"i":34658,"n":"סידיס, אברהם מלאריסה","dt":"תקסא - בערך","b":"רב בלאריסה על מקום ר משה אשכנזי. נפטר צעיר.","s":"רוזניס-תורכיה-ה"},{"i":34659,"n":"סידיס, אברהם מלאריסה - א","dt":"תצא","b":"גביר בלאריסה. קרובם של הגבירים אברהם ויוסף סידיס מלאריסה. נפטר צעיר. נספד מאת ר יצחק פרנסיס.","s":"רוזניס-תורכיה-ה"},{"i":34660,"n":"סידיס, אברהם מלאריסה - ב","dt":"תקיג - לפני","b":"גביר בלאריסה, קאשטוריא. נספד מאת ר יצחק פרנסיס בספרו \"פני יצחק\"-תקיג. אחיו - ר יוסף.","s":"רוזניס-תורכיה-ה"},{"i":34661,"n":"סידיס, אברהם מקומירג'ינה","dt":"תקנח","b":"גביר בקומירג'ינה.","s":"רוזניס-תורכיה-ה"},{"i":34662,"n":"סידיס, בנימין שבתי מקומירג'ינה","f":"שבתי בכור מקומירג'ינ","b":"גביר בקומירג'ינה-תקן, סייע לרבים ובהם להוצאת ספרים.","s":"רוזניס-תורכיה-ה"},{"i":34663,"n":"סידיס, יוסף מלאריסה","b":"גביר בלאריסה-שנות ה-ת', אחיו - אברהם. חתנו - יצחק די מאיו מקשטוריה ולאריסה.","s":"רוזניס-תורכיה-ה"},{"i":34664,"n":"סידיס, קרשקש משלוניקי","b":"ראש עדת קטלוניה בשלוניקי-שנות ה-ר'-ש'. חברו של ר אליעזר השמעוני.","s":"זכרון שלוניקי; רוזניס-תורכיה-ב"},{"i":34665,"n":"סידיס, שבתי בכור מקומירג'ינה","b":"רב בקומירג'ינה-תקנג, הספיד את ר יעקב אלבוחר ונדפס ההספד ב\"בן אברהם\" לר חיים אברהם אישטרושא. בנו - הגביר בנימין שבתי.","s":"רוזניס-תורכיה-ה"},{"i":34666,"n":"סידקארו, משה הלוי מפאס","b":"רב בפאס, מתלמידיו - ר שמואל בן סעדיה דנון.","s":"טולדנו-נר המערב"},{"i":34667,"n":"סידרסקי, אהרן מקיוב","b":"חתן ר ישראל סלנטר. רב בקיוב-תר\"מ","s":"אוצר הרבנים 1658; אהלי שם"},{"i":34668,"n":"סידרר, יהודה דוב","dt":"תשג","b":"רב ביאנישק","s":"אוצר הרבנים 7125 א'"},{"i":34669,"n":"סידרר, משה מראקישוק","b":"ראש הישיבה הקטנה בראקישוק.","s":"ליטא"},{"i":34670,"n":"סיטהון, בכור","b":"רב-שנת תר\"מ","s":"אוצר הרבנים 4252"},{"i":34671,"n":"סיטון ן, מסעוד הלוי מארסילה","b":"רב בארסילה-מרוקו במאה ה-14.","s":"ארזי הלבנון"},{"i":34672,"n":"סיימאן, מסעוד מאלגיר","f":"יעקב","bt":"תקץ","dt":"תרס - בערך","b":"נגיד קהלת ענאבא-אלגיר-תרלא, עשיר ואיש חסד. התכתב עם ר אליהו חזן בעל \"תעלומות לב\", נזכר ב\"יצב גבולות\", ואצל ר חיים פלאג'י. סייע בהדפסת \"תוכחת חיים\", \"חוקות חיים\", \"עבודה והוראה\", ועוד.","s":"מלכי ישורון-חכמי אלגיר; ארזי הלבנון"},{"i":34673,"n":"סיימן, אברהם מארה\"ב","f":"דוד","bp":"נשוויל-טנסי","b":"רב בוושינגטון. חיבר ספרים באנגלית.","s":"אנשי השם בארהב-איזנשטט"},{"i":34674,"n":"סיימן, חיים יהודה מפילדלפיה","dt":"תרצז - ל ניסן","b":"רב בפילדלפיה","s":"אוצר הרבנים 6348"},{"i":34675,"n":"סייקסאס, יצחק בנימין מניו יורק","dt":"תקצט","b":"רב בניו יורק-תקפח בקהילת \"שארית ישראל\" על מקום ר משה ליוואי מאדורא פייקסוטו. אחיינו של ר גרשון מינדיס סייקסאס.","s":"אמריקה"},{"i":34676,"n":"סייקסאס, מינדיס גרשום מניו יור","bt":"[תקה]","dt":"תקעו - ז תמוז","b":"רב קהילת \"שארית ישראל\" בניו יורק במשך כחמשים שנה. השתתף בהכתרת הנשיא הראשון באמריקה וושינגטון, יסד את הח\"ק \"חסד ואמת\". אחיינו ר יצחק בנימין סייקסאס.","s":"אמריקה"},{"i":34677,"n":"סיירא, דניאל דוד מליוורנו","b":"מלמד בליוורנו. תלמידו - ר אברהם ברוך פיפרנו בעל \"קול עוגב\" ומזכירו בספרו.","s":"איטליה גירונדי-ד יג"},{"i":34678,"n":"סילבה - משפחה","b":"משפחת רבנים מאיטליה.","s":"גאון-יהודי המזרח"},{"i":34679,"n":"סילבה די, דוד מירושלים","f":"חזקיהו - בעל פרי חדש","k":"בעל פרי הים","bt":"תמד","bp":"ירושלים","dt":"תקא","dp":"ירושלים","b":"מחכמי ירושלים ובקי גם בחכמת הרפואה, בשנת תסה יצא לאיטליה להדפיס את ספר אביו \"פרי חדש\". בשנת תפה בשליחות בתורכיה איטליה הולנד ואנגליה, חזר לירושלים בשנת תקא. חיבר ספר \"פרי הדס\" בכתב יד ועוד כתבים רבים. נספד בספר \"שמע יעקב\" לר יעקב אלגזי.","s":"גליס; אוצר הרבנים 4936; גאון-יהודי המזרח; פרומקין-תח\"י; ארזי הלבנון; רוזניס-תורכיה-ה; מפתח ההספדים, שא\"י"},{"i":34680,"n":"סילבה די, חזקיה - הנכד","dt":"תקט - יב חשון","dp":"ירושלים","b":"מחכמי ירושלים, אולי נכד ר חזקה בעל \"פרי חדש\".","s":"גאון-יהודי המזרח"},{"i":34681,"n":"סילבה די, חזקיה ממצרים וירושלי","f":"דוד","k":"בעל פרי חדש","bt":"תטז-יט","bp":"ליוורנו","dt":"תנו-ח","dp":"ירושלים","b":"תלמיד ר שמואל קושטא, שליח ארץ ישראל ר יהודה שאראף. עלה לירושלים-תלו ולמד בישיבת ר משה גלנטי (המגן). ראש ישיבה בירושלים והיה מחלוקת בינו לבין ר משה גלנטי-המגן. חתן ר רפאל מרדכי מלכי, גיסיו היו ר עזרא מלכי בעל \"מלכי בקדש\" ור משה חאגיז בעל \"שתי הלחם\". לימים התמנה לראש הישיבה, וגייס תרומה מאת ר יעקב פיריא מאמשטרדם. בין תלמידיו ר יצחק הכהן בעל \"בתי כהונה\" ור ישעיה אזולאי סבו של החידא. בשנת תמח בשליחות לאירופה, ואז נשאר כרב באמשטרדם עד שנת תנב, חזר לירושלים לאחר שהדפיס את ספרו \"פרי חדש\". ספרו עורר התנגדות חריפה ביחוד במצרים בגלל שיצא נגד גדולי הפוסקים הקודמים ובעיקר ר יוסף קארו. תלמידו ר נסים שלמה אלגזי כיהן כרבה של מצרים וכל פסקיו היו על פי הוראת רבו. הדפיס גם \"מים חיים\" אמשטרדם תץ, ועוד.","s":"גליס; אוצר הרבנים 5808; גאון-יהודי המזרח; ארזי הלבנון; פין-כנסת ישראל; פרומקין-תח\"י; ירושלים א, תולדות הפוסקים"},{"i":34682,"n":"סילבה די, יהושע מלונדון","k":"בעל דרשות על העיקרים","dt":"תלט - יז אייר","dp":"לונדון","b":"דרשן, רב באמשטרדם, רב קהל הספרדים בלונדון. חיבר דורש על יג עיקרי הדת - אמשטרדם.","s":"איטליה גירונדי-י ריח; אוצר הרבנים 7601; גאון-יהודי המזרח; פין-כנסת ישראל"},{"i":34683,"n":"סילבה די, יצחק משלוניקי","dt":"תקכד - טו אב","dp":"שלוניקי","b":"רופא בשלוניקי.","s":"זכרון שלוניקי-80; גרינוולד-סלובקיה והונגריה; רוזניס-תורכיה-ה,ו"},{"i":34684,"n":"סילבה די, רפאל מונציה","b":"רב בונציה-תעא. תשובה ממנו ב\"אורח לצדיק\". חתם ב\"אגרת לצדיק\". הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה.","s":"אוצר הרבנים 17824; איטליה גירונדי-ר א, ר ט; ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":34685,"n":"סילבה די, שמואל מאמשטרדם","b":"רב ורופא באמשטרדם-ת. חיבר ספר כנגד אוריאל די אקוסטא בפורטוגזית - אמשטרדם.","s":"איטליה גירונדי-ש עא; אוצר הרבנים 19292; ארזי הלבנון"},{"i":34686,"n":"סילבר, אבא הלל מארה\"ב","f":"משה","bt":"1893","bp":"ניישטט שאקי","dt":"1964","dp":"ארה\"ב","b":"היגר לארה\"ב, תלמיד היברו יוניון קולג'. רב רפורמי בקליבלנד - הקהלה הריפורמית הגדולה בזמנו באמריקה. נשיא ההסתדרות הציונית. סייע בקבלת החלטת האו\"ם על החלוקה-1947. ארגן את החרם האנטי-נאצי בארה\"ב. על שמו כפר סילבר.","s":"ליטא; מרקוביץ-ראסיין"},{"i":34687,"n":"סילברסטון, אהרן מירושלים וארה\"","f":"גדליה","bt":"תרסא","bp":"ליברפול-אנגליה","b":"תלמיד ישיבת \"עץ חיים\" בירושלים, וישיבת \"ר יצחק אלחנן\" בניו יורק. רב בבוסלא-תרפט, וושינגטון. חיבר ספר באנגלית על מועדי ישראל.","s":"אנשי שם"},{"i":34688,"n":"סילברסטון, גדליה מבלפסט","f":"ישעיה מאיר מליברפול","k":"בעל פרחי אביב","bt":"תרלא","bp":"יאשינובקה-ליד ביאליסטוק","dt":"תשד - ב אב","b":"נכד-אבי אמו ר אליהו אברמסקי מיאשינובקה. תלמיד ישיבות ראסיין, טלז. הגיע לאנגליה עם אביו. דרשן, רב ראשי בבלפסט-תרסא, וושינגטון-תרסד, עלה לארץ-תרצו. חיבר גם \"אוצר נחמד\" ניו יורק תרסח. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד. מחותן עם ר גרשון רבינסון מאמציסלב וקליבלנד. בנו - ר אהרן.","s":"אוצר הרבנים 4344; אמריקה; דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין"},{"i":34689,"n":"סילברסטון, ישעיה מאיר מארה\"ב","k":"בעל כסף נבחר","b":"רב בסוקוט,ליברפאול-תרנא. רב בארה\"ב-תרעט.","s":"אוצר הרבנים 11779; אמריקה"},{"i":34690,"n":"סילוירה, אהרן שמואל מחלב וירוש","bt":"תרכה","bp":"חלב","dt":"תרפה - יב אדר","dp":"ירושלים","b":"גביר מחכמי חלב, עלה לירושלים-תרעט, הקדיש ביכ\"נ בירושלים. נפטר ללא ילדים.","s":"גאון-יהודי המזרח"},{"i":34691,"n":"סילוירה, דוד מחלב","f":"הלל","bt":"תרכד","bp":"חלב","b":"גביר משכיל מחכמי חלב, פעיל צבור, פרסם חוברת בצרפתית כנגד ממשלת צרפת בענין משפט דרייפוס. עלה לירושלים-תרפח.","s":"גאון-יהודי המזרח"},{"i":34692,"n":"סילוירה, יצחק","dt":"תמב - יא חשון","dp":"אזמיר","b":"תלמידו הראשון של ש\"ץ.","s":"רוזניס-תורכיה-ד,ה"},{"i":34693,"n":"סילוירה, עזרא רפאל מביירות","b":"רב בביירות-לבנון. נזכר ב\"ישא איש\".","s":"ארזי הלבנון"},{"i":34694,"n":"סילוק, ישכר מבוז'עד-מרוקו","b":"מצדיקי בוז'עד-מרוקו.","s":"ארזי הלבנון"},{"i":34695,"n":"סילמן, אברהם יצחק מחמלניק","b":"רב בחמלניק-תר\"ס","s":"אוצר הרבנים 1232"},{"i":34696,"n":"סילמן, אברהם ישראל משה מירושלי","b":"חתן ר משה לנדינסקי מראדין. רב בירושלים, מיסד וראש \"בית אולפנא ללימוד הירושלמי\". פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"אוצר כתבי עת-לוין; אנשי שם-אמריקה"},{"i":34697,"n":"סילמן, אברהם מרדכי","dt":"תשא","b":"רב בלודז","s":"אוצר הרבנים 1293"},{"i":34698,"n":"סילמן, דוד מגוסטינין","f":"אברהם יצחק מחמלניק","bt":"תרמ","b":"תלמיד ישיבת סוכטשוב, ואצל חותנו - הרב מאוסטרובצא. רב בבאלימוב-תרסב, גוסטינין-פלך וארשא. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ. חיבר פירוש לירושלמי. נסמך מאת: ר ירחמיאל ישעיה מזדונסקא ואליע.","s":"אוצר הרבנים 4937; אוצר כתבי עת-לוין; אהלי שם"},{"i":34699,"n":"סילמן, חיים אליעזר","dt":"תשג","b":"רב בחמלניק","s":"אוצר הרבנים 6238"},{"i":34700,"n":"סילמן, טוביה","dt":"תשג","b":"רב במלניק","s":"אוצר הרבנים 6753"},{"i":34701,"n":"סילמן, יוחנן","dt":"תשד","b":"רב בעיר חדש","s":"אוצר הרבנים 7907"},{"i":34702,"n":"סילמן, יוסף","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"אוצר כתבי עת-לוין"},{"i":34703,"n":"סילמן, יחזקאל אביגדור","b":"פרסם מאמרים ב\"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא.","s":"אוצר כתבי עת-לוין"},{"i":34704,"n":"סילמן, יעקב","f":"אברהם יצחק סולמן","bt":"תרנח","dt":"תשג","b":"רב בפרישניצה","s":"אוצר הרבנים 9791"},{"i":34705,"n":"סילמן, יעקב אליעזר מניו יורק","bt":"תרלח","dt":"תרצז - כב כסלו","b":"מרבני ניו יורק","s":"אוצר הרבנים 10010"},{"i":34706,"n":"סילמן, מנחם מרדכי","f":"אברהם שמעון","k":"בעל כתיבה תמה","bp":"בוטרימנאץ-ליטא","dt":"1930","dp":"ירושלים","b":"פתח בי\"ס בקובנא ובו למדו בשיטה \"עברית בעברית\". חיבר ספרי לימוד בעברית, וספרי ילדים ובהם \"ארבעים שודדים\", ועוד. פרסם ב\"הצפירה\", ועוד. ציר בקונגרסים ציוניים. בתו - בלהה - עלתה לארץ-1913 וחברה שירים ומחזות לילדים, חתנו יצחק יפה - מורה וחוקר. ?? לא באוצר ??","s":"ליטא"},{"i":34707,"n":"סילמן, משה ישראל","dt":"תשד","b":"רב באוסטרווצה-ברדיוב","s":"אוצר הרבנים 15522"},{"i":34708,"n":"סילמן, קדיש יהודה","f":"אברהם שמעון","k":"בעל סנסנים","bt":"1881","bp":"בוטרימאנץ","dt":"1938","b":"תלמיד ישיבת סלובודקה, וילנא. מורה בבי\"ס \"יהודיה\" בוילנא, וב\"חדר מתוקן\" של יש\"י אדלר בהומל. עלה לארץ-1906, והיה מורה בירושלים. פרסם שירים ומאמרים בעתונים עבריים. עורך \"ליהודים\", שבועון לילדים \"הארץ\" עם פיכמן. תרגם מחזות מאידיש. חיבר גם \"החשמונאים הקטנים\", ועוד.","s":"ליטא"},{"i":34709,"n":"סילמן, שאול יעקב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":34710,"n":"סילקינר, בנימין נחום","f":"שלמה","bt":"1882","bp":"וילקי","dt":"1934","dp":"ניו יורק","b":"התישב באודסה-1900 וכתב שם שירים. היגר לארה\"ב והיה מנהל בי\"ס עברי בניו יורק ומורה לתנ\"ך בביהמ\"ד למורים שע\"י ביהמ\"ד לרבנים של שכטר. חיבר \"מילון עברי\" עם י. קופמן, וי. אפרת. קובץ שירים - ת\"א תרפז. הכניס לשירה העברית נושאים מחיי האינדיאנים.","s":"ליטא"},{"i":34711,"n":"סים, אברהם מנריוב","b":"רב בנריוב.","s":"וונדר-גליציה ח\"ד"},{"i":34712,"n":"סים, דב בר מנריוב","dt":"תרעו","dp":"בודפסט","b":"רב בנריוב-תרע. חתנו ר צבי יהושע גרוסווקס מברזן על מקומו אחריו.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 3982; אהלי שם"},{"i":34713,"n":"סימאנדל-למדן, ישכר דב בר","f":"סיני","k":"בעל מנחת עני","bt":"תקנד","bp":"ליפטא","dt":"תרכב - כח חשון","dp":"ליפטא","b":"תלמיד זקנו ר ליב קירץ, ישיבת החת\"ס - והיה מראשוני תלמידיו בפרשבורג. חתן ר שמואל וינשטוק (וייס) מטשענגער ועבר לשם. דיין ואח\"כ רב בליפטא-סענט-מיקלוש(=מיקלאש) - תקפח ולחם בריפורמים. היה מראשי המדברים בכינוס פאקש, ועוד. חיבר \"שירי מנחה\", \"שמן כתית למנחה\", ועוד.","s":"אוצר הרבנים 12392; החת\"ס ותלמידיו"},{"i":34714,"n":"סימו מודין, שלום שם טוב מירושל","b":"מחכמי ירושלים-סוף שנות ה-תק',","s":"פרומקין-תח\"י"},{"i":34715,"n":"סימונסון, דוד יעקב מקופנהגן","bt":"תריג","bp":"קופנהגן","b":"תלמיד ביהמ\"ד לרבנים בברסלוי, בעל תואר ד\"ר. רב הכולל בקופנהגן-תרנב.","s":"אוצר הרבנים 5164; אהלי שם"},{"i":34716,"n":"סימכאוויטש, זאב וולף ממלניץ","b":"פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח.","s":"אוצר כתבי עת-לוין"},{"i":34717,"n":"סימליץ, דוד","b":"מגדולי חכמי קרקא-שנת ת'","s":"אוצר הרבנים 4938"},{"i":34718,"n":"סימן טוב עובדיה מירושלים","b":"דיין בירושלים בשנת תמט, וחתם אז על פרעון כתובה, יחד עם ר דוד יצחקי ור יוסף חזן. חתם על אגרת לר בנימין הכהן בריגיו בשנת תנה. נזכר ב\"חוט המשולש\". אחיו של ר אליהו מאדרינופול.","s":"אוצר הרבנים 16498; גליס; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ד"},{"i":34719,"n":"סימן טוב, בנימין מאפגניסטן","b":"רב ראשי באפגניסטן","s":"ארזי הלבנון"},{"i":34720,"n":"סימן טוב, יעקב מאפגניסטן","bt":"תרו","dt":"תרפח","dp":"ירושלים","b":"רבה הראשי של אפגניסטן, עלה לירושלים בתרפה.","s":"גליס; אוצר הרבנים 9794"},{"i":34721,"n":"סימן טוב, שמחה מאפגניסטן","bt":"תריט","dt":"תרצו - כח ניסן","dp":"ירושלים","b":"רב בהראט-אפגניסטן-תריט, עלה לירושלים-תרפט.","s":"ארזי הלבנון; אוצר הרבנים 19721; גליס"},{"i":34722,"n":"סימן, עוזר מאנגליה","f":"שמעון","bt":"תרט","bp":"סערהייא-פלך סובאלק","b":"היגר לאנגליה וכיהן כרב בסאות המפטון-אנגליה, מנצסטר-תרמד על מקום הרב ד\"ר גילנץ שעבר ללונדון.","s":"אוצר הרבנים 16556; אהלי שם"},{"i":34723,"n":"סינגאליה, אברהם חיים ממודנא","f":"שלמה יאודה","k":"בעל דברי הימים","b":"תלמיד אביו ובעל \"זרע אמת\". רב במודנא. הניח פסקים וחדושים בכת\"י, חיבר \"דברי הימים\" בכת\"י, פירוש למשנה - לא נשלם. בנו ר שלמה ידידיה ונכדו ר חיים סינגאליה.","s":"איטליה גירונדי-א פ, קכב; ארזי הלבנון; פין-כנסת ישראל"},{"i":34724,"n":"סינגאליה, יעקב שמשון שבתי","f":"רפאל ישכר","k":"בעל אביר יעקב","b":"רב באנקונה-תק\"ס. תלמיד ר אברהם ישראל ודיין בבית דינו באנקונא. חיבר \"שבת של מי\", \"אביר יעקב\" ועוד חלקם בכת\"י, נשא ונתן עם ר דוד זינצהיים ורבני ליוורנו.","s":"איטליה גירונדי-י מט; אוצר הרבנים 10344; פין-כנסת ישראל"},{"i":34725,"n":"סינגאליה, משה אליהו ממודנא","f":"שלמה יהודה","bp":"מודנא","dt":"תרט - א אייר","b":"רב במודנא. תלמיד אביו ומהרי\"ך בעל \"זרע אמת\". נזכר ב\"משמרת הבן\". תשובות ממנו בשו\"ת ר אלישמע מאיר פאדובאני, ועוד.","s":"איטליה גירונדי-מ יח"},{"i":34726,"n":"סינגאליה, שלמה ידידיה ממודנא","b":"דיין במודנא אצל ר ישמעאל הכהן בעל \"זרע אמת\". חיבר שירים וספר דרושים על התורה, נזכר כמשורר אצל ר חנניה הכהן - משיריו ב\"קתון חצות\" ו\"משמרת הבן\" ליוורנו. מתלמידיו - ר אלישמע מאיר פאדובאני ממודנא.","s":"איטליה גירונדי-ש מ,מו; ארזי הלבנון"},{"i":34727,"n":"סינגר, שמואל","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה.","s":"אוצר כתבי עת-לוין"},{"i":34728,"n":"סינואני, חיים","f":"יחיא","k":"בעל עטרת תפארת","r":"ראב\"ד סינואן שבתימן","bt":"תרנח","bp":"סנואן(תימן)","dt":"תשלט - כז אדר","dp":"יהוד","b":"מגדולי חכמי ומקובלי תימן בדורנו,נסמך בגיל 17 ע\"י רבו ר' שלמה טאביב,אב\"ד בסנואן-תרע\"ט,עלה לא\"י-תש\"בגר בעתלית,עבר ליהוד(יהודיה),חיבר \"עטרת תפארת\",אביו ר' יחיא ממשפחת בידה","s":"ארזי הלבנון; נחלי נצח גליון 420","bk":[["ארזי לבנון - חידושים בדרך פרד\"ס מסודרים לפי סדר א' ב'",""],["תורת חכם - נביאים וכתובים בדרך פרד\"ס",""],["מקום מקדש",""]]},{"i":34729,"n":"סינוביץ, שמעון","b":"רב-שנת ת\"ר","s":"אוצר הרבנים 19901"},{"i":34730,"n":"סינטובסקי, אליהו","f":"קלמן איזיק","bt":"1880","bp":"וילקוביסק","dt":"1943","dp":"ניו יורק","b":"חבר ב\"בונד\" וחבר בועד פועלי מברשות. נאסר על פעילות מהפכנית-1905, היגר לשוייץ והשתתף בועידת הבונד. למד משפטים בברן. וכתב דוקטורט בנושא הרעיונות המהפכניים של יהודי רוסיה. היגר לארה\"ב ופרסם מאמרים ב\"צוקונפט\", ועוד.","s":"ליטא"},{"i":34731,"n":"סיני בנימין מאונסדורף","dt":"תסו - יח חשון","b":"רב באונסדורף. (אולי נפטר בשבט)","s":"אוצר הרבנים 16499,3802"},{"i":34732,"n":"סיני מפפד\"מ","b":"דיין בפפד\"מ","s":"אוצר הרבנים 16501"},{"i":34733,"n":"סיני מפרג וניקלשבורג","f":"בצלאל מוורמייזא","dt":"שנג - ה אלול","b":"מגדולי חכמי דורו, ראש ישיבה בפרג, רב בניקלשבורג. אחיו של המהר\"ל. בנו - ר חיים מקעלין(5984).","s":"אוצר הרבנים 16502; בית העלמין בוילנא-קלויזנר; ברוין-אנשי מופת"},{"i":34734,"n":"סיני מראדום","dt":"תריא - טז שבט","b":"ראב\"ד בראדום","s":"אוצר הרבנים 16500"},{"i":34735,"n":"סיני ראובן","bt":"1850","dt":"ה'תרעח 1918","s":"היברובוקס","bk":[["אלון בכות",""],["זכרון משה",""]]},{"i":34736,"n":"סיניור ן, אלעזר שמואל","s":"ארזי הלבנון"},{"i":34737,"n":"סיניור ן, יוסף מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון.","s":"טולדנו-נר המערב"},{"i":34738,"n":"סיניור, אברהם משלוניקי","dt":"תנח","dp":"שלוניקי","b":"רופא בשלוניקי.","s":"זכרון שלוניקי-60"},{"i":34739,"n":"סיניור, יוסף מאזמיר","f":"שמואל","bt":"תקצז","bp":"אזמיר","dt":"תרעג","dp":"אזמיר","b":"תלמיד ר אברהם פלאג'י, מו\"ץ בבוקרשט, רב בביירות, ראשי באזמיר-תרס והיה מחלוקת כנגו בקהלה ור נסים דאנון מירושלים על מקומו לצדו ואחריו.","s":"אוצר הרבנים 8472; גאון-יהודי המזרח"},{"i":34740,"n":"סיניור, יעקב","b":"מחכמי ירושלים, בשנת תלח בשליחות, ובשנת תצה בשליחות חברון במצרים. נזכר בשות \"דרכי נועם\" לר מרדכי הלוי.","s":"גליס; שא\"י"},{"i":34741,"n":"סיניור, שלמה מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":34742,"n":"סיניור, שמואל מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'.","s":"רוזניס-תורכיה-ב"},{"i":34743,"n":"סינסון, נחום מאנגליה","f":"מרדכי הכהן","k":"בעל מנחת ציון","bt":"תריז","bp":"זאגר-פלך קובנא","b":"נכד ר מרדכי רייטץ, ונכד-אבי אמו ר אשר פלאטלר מפלונגיאן. תלמיד ישיבת מיר, וולוזין, ביהכ\"נ של אפאטוב בוילנא. חתן הגביר ר זאב וולף סאלץ מקרעזונקא-ליד וילנא. רב בסלצניק-תרמד, יאשין-פלך וילנא, בינקן(=ביניקאן)-פלך וילנא, לידס-אנגליה-תרע. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא, ר אליהו אליעזר מוילנא, ר שמואל לופצער מוילנא, ר רפאל שפירא מוולוזין.","s":"אוצר הרבנים 15879; אהלי שם"},{"i":34744,"n":"סיסה די, גבריאל ממונסטיר","b":"רב במונסטיר-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":34745,"n":"סיסו ן, אהרן ממרוקו","b":"רב בפאס-תרם."},{"i":34746,"n":"סיסו, אברהם","b":"מכתב תשובה ממנו-תקי לר שלמה עבאדי מדמשק.","s":"מתוך קטלוג"},{"i":34747,"n":"סיסו, יצחק ממרוקו","dt":"תרסא","b":"תלמיד ר אהרן בוטבול. סגי נהור, מחכמי פאס. חיבר שירים.","s":"מלכי רבנן"},{"i":34748,"n":"סיסי, נסים הכהן מג'רבה","k":"בעל קול רנה","bp":"ג'רבה","b":"דיין בג'רבא, אצל ר סאסי מעתוק הכהן יהונתן.","s":"ארזי הלבנון"},{"i":34749,"n":"סיסי, נסים הכהן מג'רבה וטריפול","bt":"תרי","bp":"ג'רבה","dt":"תרסד - בערך","b":"מחכמי ג'רבה, רב בטריפולי-תרם. תלמידו - ר דוד חדאד חזקיה הזכירו בספרו \"קרן לדוד\", נזכר גם ב\"ממלכת כהנים\" בתוך \"פרח שושן\" - ירושלים תשלז.","s":"מלכי חי\"ל-מרציאנו"},{"i":34750,"n":"סיקוואלו, אברהם משלוניקי","b":"רב וראש ישיבה בשלוניקי-ש-שן, חברו של המהרשד\"מ. מתלמידיו - ר אברהם די בוטון בעל \"לחם משנה\".","s":"ארזי הלבנון; אלופי יעקב א-שכח"},{"i":34751,"n":"סיקמנסקי, משה אהרן מאנגליה","bt":"תרכט","b":"נסמך מאת: ר יצחק אלחנן מקובנא ובנו ר צבי הירש רבינוביץ, ר משה דונשבסקי, ר שמשון ארנשטין מקאליש, ר שמואל זנויל קלפפיש מוארשא. רב בליוורפול-אנגליה-תרנח.","s":"אוצר הרבנים 15259; אהלי שם"},{"i":34752,"n":"סיקס, פיליפ לואי","f":"דוד","bt":"1884","bp":"ליטא","b":"היגר לארה\"ב ולמד משפטים. שופט עליון במדינת מרילנד. נשיא אגוד מוסדות החסד של בולטימור, ונשיא מועצת החינוך היהודי בבולטימור. חיבר ספרים באנגלית.","s":"ליטא"},{"i":34753,"n":"סיר ליאון, דוד משלוניקי","f":"יהודה בן יחיאל","k":"בעל מגן דוד","bt":"רלב","bp":"מנטובה","b":"מגדולי חכמי דורו, תלמיד אביו בנפולי, תלמיד מהר\"ם מפדואה. רב ורופא באיטליה, רב ומרביץ תורה באבילונה(=ואלונא)-אלבניה-רעב על מקום ר פרץ בונפיליו, רב בשלוניקי והקים ישיבה והחדיר בה את לימוד התוספות על הש\"ס. חיבר \"באור עקרי הדת\" - ויצא לאור ע\"י נכדו ר אהרן הלוי בקושטא שלז, \"עין הקורא\", \"תהלה לדוד\" - קושטא. ועוד ספרים בכת\"י.","s":"איטליה גירונדי-ד כ; אוצר הרבנים 4939; ארזי הלבנון; זכרון שלוניקי; רוזניס - א; פין-כנסת ישראל"},{"i":34754,"n":"סיר ליאון, יהודה ממנטובה","f":"יחיאל","k":"בעל נופת צופים","b":"מקור שמו - \"מסיר\" - מהמילה \"מאיסטרו\" - מוסמך לרפואה ופילוסופיה. רב ורופא בנפולי, מנטובה-ריב. היה מחלוקת בינו לבין ר\"י קולון - והדוכס גירש את שניהם ממלכתו. חיבר \"נופת צופים\", \"לבנת הספיר\", אגרות ליהודי פיררה ובולוניה, ועוד.","s":"אוצר הרבנים 6995; איטליה גירונדי-י קעט; זכרון שלוניקי; פין-כנסת ישראל"},{"i":34755,"n":"סיר ליאון, יהודה מפאריס","f":"יצחק","bt":"ד'תתקכו","dt":"ד'תתקפד","b":"מגדולי התוספות, מחכמי פאריס, ראש ישיבה.","s":"אוצר הרבנים 7113; פין-כנסת ישראל"},{"i":34756,"n":"סיר ליאון, יצחק מקושטא","f":"דוד מקושטא","b":"רב בקושטא-שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":34757,"n":"סירא, שמואל מאלגיר","b":"רב באלגיר, רב ראשי בצרפת מטעם הקונסיסטואר. הו\"ל \"עומר השכחה\" לר אברהם גבישון, וצרף לו מבוא לתולדות רבני משפחת גבישון - \"עומר השכחה\" ירושלים תשלג.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34758,"n":"סיראלוו, אברהם משלוניקי","dt":"שטו-שלג","dp":"אדרינופול","b":"תלמיד ר יוסף פאסי. רב בק\"ק איבורה בשלוניקי-רצו ור שלמה הלוי על מקומו אחריו, נפטר בדרכו לארץ. הניח שו\"ת וחבורים בכת\"י.","s":"זכרון שלוניקי; רוזניס-תורכיה-ב"},{"i":34759,"n":"סיראת ן, עוזיאל מאלגיר","b":"נזכר באגרת הרשב\"ץ לר יצחק קנשינו מווהראן.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34760,"n":"סירוטקין, אברהם ממינסק","b":"סופר במינסק.","s":"מינסק-איזנשטט"},{"i":34761,"n":"סיריליו, יוסף מירושלים","b":"רב בירושלים","s":"אוצר הרבנים 8473"},{"i":34762,"n":"סיריליו, יעקב מברושא","b":"רב בברושא(=ברוסא) - בדור שלאחר הגירוש.","s":"רוזניס-תורכיה-ב"},{"i":34763,"n":"סיריליו, שלמה מספרד וצפת","f":"יוסף","k":"בעל מאיר נתיב","bt":"רס","bp":"ספרד","dt":"שיח - בערך","dp":"ירושלים","b":". אחרי גירוש ספרד עבר עם משפחתו לאדרינופול, תלמיד ר יוסף קארו, ור משה מטרני, רב בשלוניקי, מצאצאי ר שמואל סיריליאו בעל \"כללי שמואל\". למד אצל ר לוי בן חביב בשלוניקי, בשנת רצב או רצו עלה לצפת, ואחר כך לירושלים-שו, והתמנה לרב על מקום הרלב\"ח, חיבר פירוש על הירושלמי רובו בכתב יד. חיבר \"קונרטס בענין ביעור ושמיטה\" ירושלים תרצז. (אצל גליס נרשם תאריך פטירתו - שנח).","s":"גליס; אוצר הרבנים 18546; גאון-יהודי המזרח; רוזניס-תורכיה-ב; ארזי הלבנון; פרומקין-תח\"י","bk":[["ר\"ש סירילאו (רש\"ס) [על הירושלמי]",""]]},{"i":34764,"n":"סיריליו, שמואל ממצרים - הזקן","k":"בעל כללי שמואל","bt":"רטו","bp":"טוליטולא (ספרד)","dt":"רץ או שז","dp":"צפת","b":"מחכמי ספרד, תלמיד ר יצחק די ליאון, חתן ר יצחק אבוהב. אחר הגירוש הגיע לקהיר יחד עם הרדב\"ז, ר יעקב בירב, ואחרים, היה רב הראשי בזמן המורד בשולטן סולימן - אחמד פאשה - שעשה צרות גדולות ליהודים, ונעשה על ידו נס ונהרג-רפד בכז אדר, ונקבע פורים קטן בכח אדר בקהלה וסימנך \"רד\"פ אויב\". עלה לצפת ומובא בשות המבי\"ט. חיבר \"כללי שמואל\" נדפס בתוך \"תומת ישרים\" לר בנימין מוטל ונציה שפב. חיבר גם פירוש לאבות, ועוד. יש המחליפים בטעות בינו לבין ר שלמה סיריליו מפרש הירושלמי (בגלל טעות דפוס של בעל \"קורא הדורות\" - שהחליף שמואל עם שלמה). נכדו נשא גם הוא אותו השם. על שמו בית מדרש במצרים בשם ק\"ק סיריליו.","s":"גליס; אוצר הרבנים 19291; פין-כנסת ישראל; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י"},{"i":34765,"n":"סיריליו, שמואל ממצרים - הנכד","bp":"מצרים","dt":"שצה","b":"נכד ר שמואל ן סיד הראשון. רב במצרים, חברו של ר ישראל בנימין, תלמיד ר אליעזר מנואלאנואי(=ממנלאנואי) במצרים, ישועה אזולאי. עלה לירושלים, ונזכר ב\"דברי יוסף\". מהסובלים בפרעות אבן פארוך-שפה, ונמלט ותפסו במקומו את חתנו ר עזריא זאבי. בשליחות בקושטא עם ר שמואל טרדיאולה ור חיים די שיריז, והצליחו בעזרת יהודי קושטא להדיח את אבן פארוך, וחזר לירושלים. חתנו - ר עזריה זאבי.","s":"גליס; ארזי הלבנון; רוזניס-תורכיה-ג; פרומקין-תח\"י"},{"i":34766,"n":"סיריליו, שמואל משלוניקי","b":"רב בשלוניקי-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":34767,"n":"סירינו, יצחק מאזמיר","k":"ר' ח י' מזרחי דידיע","dt":"תקסח","dp":"ירושלים","b":"גביר מחכמי אזמיר.","s":"רוזניס-תורכיה-ד"},{"i":34768,"n":"סירירו, אבא מפאס-מרוקו","f":"יהונתן","dt":"תקצה - כסלו","b":"שו\"ב, מחכמי פאס","s":"ארזי הלבנון; מלכי רבנן"},{"i":34769,"n":"סירירו, דוד בכור משלוניקי-הנכד","f":"יעקב","dt":"תרם","dp":"ירושלים","b":"דיין בשלוניקי. תשובות ממנו ב\"ירים משה\" לר משה קאשטרו. חיבר הקדמה ל\"תורת חכם\" לר חיים דלרוזה-תרח.","s":"זכרון שלוניקי-141"},{"i":34770,"n":"סירירו, חיים דוד ממרוקו - א","f":"מתתיהו","bt":"תקט-י","dt":"תקפו","b":"תלמיד ר אליהו הכהן אלכלאץ. חתן בזיוו\"ר ר אברהם מאנסאנו. מקובל, מו\"צ בפאס. חיבר שיטה לפסחים, קינה, שיר ממנו ב\"תהלה לדוד\" לר דוד ן חסין. בניו: ר יונתן, ר צמח, ר מתתיה, ר מנחם - נפטר בחיי אביו.","s":"אוצר הרבנים 6295; ארזי הלבנון; מלכי רבנן"},{"i":34771,"n":"סירירו, חיים דוד ממרוקו - ב","dt":"תשכ","b":"רב במראקש,אב\"ד ורב ראשי בפאס,למד מר' יוסף הכהן סקאלי","s":"ארזי הלבנון"},{"i":34772,"n":"סירירו, חיים דוד משלוניקי","f":"ברוך","k":"בעל סוכת דוד","bt":"תפ","dt":"תקח - ה-ח אלול","dp":"שלוניקי","b":"דיין ומקובל בשלוניקי, ורב הכולל בזמן ר יוסף ן ארדיט. חיבר גם \"משנה כסף\", \"סוכת שלום\", ועוד. על קברו נהגו לעלות יהודים רבים. בנו - ר יצחק - הו\"ל את ספרו \"סוכת דוד\"-תקלח בתמיכת הגביר ר דוד הלוי קרסו.","s":"אוצר הרבנים 5063,6301; איטליה גירונדי-ח כב; ארזי הלבנון; זכרון שלוניקי-82; פין-כנסת ישראל; רוזניס-תורכיה-ה"},{"i":34773,"n":"סירירו, יהודה בנימין מפאס","f":"מתתיה","bt":"תקצד","bp":"פאס(מרוקו)","dt":"תרף - יא סיון","b":"מו\"ץ בפאס, מלוב\"ן, פוסק, בקי בחכמת הדקדוק.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34774,"n":"סירירו, יהודה ממרוקו","f":"מתתיה","dt":"תקצה","b":"מחכמי צפון אפריקה, אב\"ד בפאס, נפטר במגיפה. חתניו: ר וידאל הצרפתי, ר מתתיה סירירו.","s":"אוצר הרבנים 7043; ארזי הלבנון; מלכי רבנן"},{"i":34775,"n":"סירירו, יהונתן מפאס","f":"חיים דוד","bt":"תקלה","dt":"תקצג","b":"נכד ר אברהם מאנסאנו. מו\"ץ בפאס. הניח חדושים בכת\"י, חיבר שיר לפורים.","s":"אוצר הרבנים 7494; מלכי רבנן"},{"i":34776,"n":"סירירו, יהושע ממרוקו","f":"מנחם","b":"גביר מחכמי מרוקו-תנז, נזכר ב\"משפט וצבי\", ו\"בעת לכל חפץ\" - שם קינה ממנו על בנו - ר שאול, מתורתו ב\"מראה עינים\" לר אלעזר בהלול. כתב כמה ספרי תורה.","s":"מלכי רבנן"},{"i":34777,"n":"סירירו, יהושע מפאס","f":"מתתיהו","dt":"תקעד-ט -כב סיון","dp":"פאס-מרוקו","b":"מו\"ץ בפאס עם אחיו-ר חיים דוד סירירו, ר שמואל אברהם ן זמרא, ר יהודה ן עטר-השני. בניו: ר יוסף, ר ראובן.","s":"אוצר הרבנים 7602(7062)"},{"i":34778,"n":"סירירו, יוסף בנימין משלוניקי","dt":"תרלט","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-141"},{"i":34779,"n":"סירירו, יוסף מפאס","f":"יהושע ציון","bt":"תרג","dt":"תרסב - תשרי","b":"מו\"ץ בפאס, ומקובל. החזיק בספריה גדולה שחלקה ירש מאביו - ונשרפה. נפטר ללא ילדים.","s":"מלכי רבנן"},{"i":34780,"n":"סירירו, יעקב מפאס","f":"מתתיה","bp":"תקכט - בערך","dp":"תריא","b":"מו\"ץ בפאס. נפטר ללא ילדים. נזכר אצל ר אבנר ישראל הצרפתי.","s":"מלכי רבנן"},{"i":34781,"n":"סירירו, יעקב משלוניקי","f":"דוד","dt":"תקכט","dp":"שלוניקי","b":"מחכמי שלוניקי-שנות התק'. מומחה בדיני חזקות ונזקי שכנים. חתן ר יצחק ן שאנג'י וחיבר הקדמה לספר חותנו \"באר יצחק\".","s":"זכרון שלוניקי-92; רוזניס-תורכיה-ה"},{"i":34782,"n":"סירירו, יעקב משלוניקי","f":"משה","dt":"תקפז","dp":"שלוניקי","b":"מצאצאי המקובל ר דוד סירירו.","s":"זכרון שלוניקי-116"},{"i":34783,"n":"סירירו, מנחם מפאס","f":"דוד","dt":"שפו","b":"מחכמי פאס-שפ. אחיו של ר שמואל. נרצח ע\"י ערבי.","s":"ארזי הלבנון"},{"i":34784,"n":"סירירו, מנחם מפאס - ב","f":"יהושע","bt":"תנג","bp":"פאס","dt":"תעט - חשבון","b":"מחכמי פאס. חתן ר יעקב ן צור=היעב\"ץ. נפטר כבן 26 ובנו ר מתתיה גדל אצל זקנו היעבץ. חיבר \"סכינא חריפא\" ולא הספיק לסיימו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34785,"n":"סירירו, מנחם מפאס - ג","f":"דוד","k":"בעל דברי מנחם","dt":"תסא - כג אדר","b":"רב בפאס-תמח ומחשובי הרבנים במרוקו בדורו. חתם על תקנות רבות עם חבריו ר יהודה עוזיאל, ר וידאל הצרפתי, ר שאול ן דנאן ור מימון אפלאלו, מהדיינים בבית דינו - ר יהודה ן עטר, ר שמואל הצרפתי. מתלמידיו - ר יהודה ן עטר ור יעקב ן צור. מתשובותיו ב\"משפט וצדקה ביעקב\" ובספרי חבריו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34786,"n":"סירירו, מנחם מפאס - ד","f":"מתתיה","b":"מחכמי פאס, נפטר צעיר בחיי הוריו כבן 36. קינה לזכרו מר דוד חסין, ומאחיו ר חיים דוד סירירו. חיבר חיבור בגיל 17.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34787,"n":"סירירו, משה משלוניקי","f":"דוד","dt":"תקטו","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-85"},{"i":34788,"n":"סירירו, מתתיה מפאס - הנכד","b":"רב בפאס-תרעה. חתם עם ר אברהם ן סוסאן, ר רפאל יעקב עטר ועוד.","s":"מתוך קטלוג"},{"i":34789,"n":"סירירו, מתתיה מפאס-מרוקו - א","f":"מנחם","dt":"תקן - לפני","b":"מחכמי פאס, התייתם בילדותו וגדל אצל זקנו-אבי אמו היעב\"ץ (ר יעקב ן צור). דיין בפאס. שבעת בניו היו מחכמי פאס ורובם כיהנו כדיינים והם - ר שאול, ר מנחם יהושע, ר חיים דוד, ר יעקב, ר יהודה ור נחמן. מתשובותיו בספרי חכמי דורו. בשנת תקן פינו השלטונות את בית העלמין ובהם את קברו. נמנה בבית הדין של חמש בפאס (ר שאול שמואל דנון, ר אפרים בן אברהם מונסונייגו, ר רפאל עובד בן יעקב ן צור, ר אליהו בן יוסף הצרפתי, ר מתתיהו בן מנחם סירירו).","s":"אוצר הרבנים 15791; מלכי רבנן; ארזי הלבנון"},{"i":34790,"n":"סירירו, מתתיה מפאס-מרוקו - ב","f":"חיים דוד","bt":"תקסו","bp":"פאס","dt":"תרנא","dp":"מרוקו","b":"רב בפאס. בניו - ר חיים, ר עמנואל, ור יהודה בנימין.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34791,"n":"סירירו, נחמן ממרוקו","f":"מתתיהו","b":"רב בפאס-תקע, אחיהם של ר יהושע, ר מתתיהו ור שאול.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34792,"n":"סירירו, עמנואל - ב","f":"יהושע","k":"בעל שפת אמת","bt":"תסה","b":"חיבר פירוש להגדה עם דיני ביעור חמץ בשם \"תורי זהב\" - \"ארוחת ירק\", חיבר שירים ופיוטים בשם \"שפת אמת\".","s":"ארזי הלבנון; מלכי רבנן"},{"i":34793,"n":"סירירו, עמנואל - ג","f":"מתתיה בן חיים דוד","bt":"תקצא","dt":"תרלח","dp":"קולירא לתפץ","b":"מחכמי מרוקו, ומלמד תורה. נפטר בחיי אביו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34794,"n":"סירירו, עמנואל ממרוקו - א","b":"מחכמי מרוקו, חתם-תסד על פס\"ד עם ר סעדיה ן דנאן, ועם ר בנימין לכרייף ממכנאס-תלד, ועוד. חיבר שיטה לבבא קמא עם חברו ר שמואל זקן בעל \"פרי מגדים\".","s":"מלכי רבנן"},{"i":34795,"n":"סירירו, צמח ממרוקו","f":"חיים דוד","b":"מחכמי פאס-תקץ ומגדולי דורו.","s":"אוצר הרבנים 17585; ארזי הלבנון"},{"i":34796,"n":"סירירו, ראובן מפאס","f":"יהושע בן מתתיהו","dt":"תרטו-ז","b":"נכד ר מתתיה סירירו מפאס. רב בפאס. חתם על פסק דין-תריב עם ר וידאל הצרפתי ור ידידה מונסונייגו.","s":"אוצר הרבנים 17718; מלכי רבנן; ארזי הלבנון; טולדנו-נר המערב"},{"i":34797,"n":"סירירו, ראובן מפאס","f":"רפאל יהושע ציון מפאס","dt":"תרלח","dp":"קולירא-מרוקו","b":"מחכמי פאס, נפטר צעיר בחיי אביו.","s":"מלכי רבנן"},{"i":34798,"n":"סירירו, רפאל יהושע ציון מפאס","f":"יוסף","bt":"תקעח","dt":"תרנז - אדר","b":"מחכמי פאס. בניו - ר ראובן-נפטר בחיי אביו, ר יוסף, ר מתתיה.","s":"מלכי רבנן"},{"i":34799,"n":"סירירו, שאול (שמואל) מפאס - א","f":"דוד","k":"בעל חנוך לנער","bt":"שכו","bp":"פאס","dt":"תטו - אלול","b":"בן למגורשים מקשטיליה שהתישבו בפאס. תלמיד ר משה בן טשטיאל, ר שלמה עוזיאל, ור יהודה עוזיאל. ראש ישיבה בפאס, דיין אצל ר וידאל הצרפתי ור שמואל ן חביב. רב ראשי-שפב על מקום ר שמואל ן דנאן. חיבר גם \"אורים ותומים\" בכת\"י, דרשות, ועוד.","s":"אוצר הרבנים 17982; מלכי רבנן; ארזי הלבנון"},{"i":34800,"n":"סירירו, שאול ממרוקו","f":"יהושע","bt":"תסו","dt":"תעח - ה שבט","b":"מחכמי מרוקו. נפטר בגיל 22, ונספד בידי ר יעקב ן צור ב\"עת לכל חפץ\", ר חנניה ן זכרי שלח אגרת נחומים לאביו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34801,"n":"סירירו, שאול ממרוקו","b":"רב בפאס-תרם."},{"i":34802,"n":"סירירו, שאול מפאס","b":"מגדולי חכמי דורו-קנ\"א","s":"אוצר הרבנים 18008"},{"i":34803,"n":"סירירו, שאול מפאס","f":"מתתיה","dt":"תקסז","b":"רב בפאס, מלומד בנסים. נספד ע\"י ר רפאל אהרן מונסונייגו - שמכנהו \"מורי\" ב\"נאות מדבר\".","s":"ארזי הלבנון; מלכי רבנן"},{"i":34804,"n":"סירירו, שמואל מימו מפאס","f":"שאול בן מתתיה","bt":"תקצא","b":"מחכמי פאס-תרמט.","s":"מלכי רבנן"},{"i":34805,"n":"סירקוס, מנחם מנדל מוארשא","b":"פרסם מאמרים ב\"עמק הלכה\" - וארשא תרפו.","s":"אוצר כתבי עת-לוין"},{"i":34806,"n":"סירקין, אריה ליב משקלוב","f":"יהושע השל משקלוב","b":"בנו - ר יוסף משקלוב.","s":"ברוורמן-אנשי שם"},{"i":34807,"n":"סירקין, יהושע השל מבריסק","k":"בעל משרת משה","dt":"תרנב - ח תשרי","b":"רב בבריסק","s":"אוצר הרבנים 7724 א'"},{"i":34808,"n":"סירקין, יהושע השל משקלוב","f":"נחמן מבריסק","dt":"תקסא - ז סיון","b":"רב בשקלוב.","s":"אוצר הרבנים 7724; ברוורמן-אנשי שם"},{"i":34809,"n":"סירקין, יהושע ממינסק ופוניבז","k":"בעל שלשה פרקים מידיע","bt":"תקצה","bp":"שקלוב","b":"עבר לפוניבז והיה חברו של יל\"ג. למד חקלאות במוסקבה, עבר לפרוסיה, חזר לרוסיה והיה פקיד באחוזת הברון גינצבורג בפודוליה, מנהל אוצרות מסילת הברזל \"ליבוי-פאמען\". פרסם מאמרים ב\"השחר\", \"אוצר החכמה\", \"המגיד\", \"כנסת ישראל\", ועוד. חיבר \"שלשה פרקים מידיעות מערכת הדומם\".","s":"דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין; מינסק-איזנשטט"},{"i":34810,"n":"סירקין, יחזקאל","k":"בעל בנין יחזקאל","b":"מחכמי יאקובשטט? פרסם קונטרס \"בנין יחזקאל\" \"יגדיל תורה\" - אודסה תרלט.","s":"אוצר כתבי עת-לוין; אובצינסקי-קורלנד"},{"i":34811,"n":"סירקין, יעקב","f":"נחמן מבריסק","b":"אחיהם של ר יהושע השל משקלוב, ר מרדכי מבריסק.","s":"ברוורמן-אנשי שם"},{"i":34812,"n":"סירקין, ישראל מפשוורסק","f":"מרדכי","b":"רב בפשעוורסק-גליציה-תקם. בנו ר יוסף קזיס מיאנוב.","s":"אוצר הרבנים 12010; אהלי שם"},{"i":34813,"n":"סירקין, מרדכי מבריסק","f":"שמואל צבי מבריסק","k":"בעל מים עמוקים","r":"רב בבריסק","dt":"תקכה - כד שבט","b":"נכד ר נחמן רפפרוט. רב בבריסק. בנו - ר ישראל מפשוורסק. חתנו ר יקותיאל מדרוהוביטש. (באבני בית היוצר מופיע - בן ר נחמן רפפורט - ובאמת היה נכדו-אבי אמו).","s":"אוצר הרבנים 13958; אבני בית היוצר-וייס; תוספת להמודיע ב' אייר תשעג עמוד לא","bk":[["מים עמוקים - פסחים",""]]},{"i":34814,"n":"סירקין, נחמן","f":"יהושע השל משקלוב","b":"חתן ר צבי הירש צייטלין משקלוב.","s":"ברוורמן-אנשי שם"},{"i":34815,"n":"סירקין, נחמן מבריסק","f":"שמואל צבי הירץ מבריס","dt":"תקיז","b":"אב\"ד בריסק על מקום אביו, ובנו ר מרדכי בעל \"מים עמוקים\" על מקומו אחריו. בניו גם - ר יעקב, ר יהושע השל משקלוב. (לפי ברוורמן - שם אביו - נפתלי הירץ בן יהודה ליב). הסכים על \"עיר דוד\"-תעח, \"ברית שלום\"-תעח. נספד מאת ר חיים הכהן. נזכר אצל ר יעקב עמדין - שלא רצה להתערב במחלוקת הידועה.","s":"אוצר הרבנים 15992; אבני בית היוצר-וייס; ברוורמן-אנשי שם; בריסק-עיר תהלה"},{"i":34816,"n":"סירקיס ישראל יוסף","bt":"1860","dt":"ה'תרפח 1928","s":"היברובוקס","bk":[["נקמת עבריה",""]]},{"i":34817,"n":"סירקיס, אליעזר מפולין","b":"ציר בסיים הפולני-תרף.","s":"מתוך קטלוג"},{"i":34818,"n":"סירקיש, אריה יהודה ליב מבריסק","f":"שמואל צבי הירץ","k":"בעל שאגת אריה","b":"נכד בעל הב\"ח (כך לפי - אהלי שם). בנו חורגו של הט\"ז. מגדולי חכמי דורו, רב בסוירז-תכג, קומרנא-תכח, סטבניץ-תלז, זאמוטש-תמב ובנו ר דוד על מקומו אחריו, טיקטין-תמט, קראקא-תנו על מקום ר אהרן תאומים (שנהרג עק\"ה) (כ-10 שנים לא היה רב בקראקא), בריסק. נשלח ע\"י הט\"ז עם ר ישעיה בן הט\"ז לבדוק אודות ש\"ץ. הסכים על \"תולדות יצחק\", \"שבתא דריגלא\" \"בית הלל\", ועוד. בניו - ר שמואל צבי, ר דוד, ר יואל מבריסק. נכדו - ר אברהם נתן נטע מייזלש בעל \"נטע שעשועים\" הו\"ל את ספרו \"שאגת אריה\".","s":"אוצר הרבנים 3368; אוסטרהא; אהלי שם; רוזניס-תורכיה-ד; צונץ-קראקא; בריסק-עיר תהלה"},{"i":34819,"n":"סירקיש, אריה יהודה ליב מקראקא","f":"יואל - בעל הב\"ח","b":"רב בקרקא-תל, חנטשין. בנו ר שמואל גרשון מירושלים.","s":"אוצר הרבנים 3367,7358; פין-כנסת ישראל"},{"i":34820,"n":"סירקיש, יואל","f":"שמואל יפה","k":"בעל הב\"ח","r":"אב\"ד בעלז","bt":"שכא","bp":"לובלין","dt":"ת-תא - כ אדר","dp":"קראקא","b":"שם משפחתו - יפה ונקרא סירקיש על שם אמו. תלמיד ר שלמה ר ליבישיס חסיד מלובלין-תלמידו של המהרש\"ל, ר הירש שור מבריסק, ר משלם פיבש מקראקא. ראש חכמי דורו, פוסק, מקובל, מרביץ תורה, רב בפרוזאני, גליל סלונים, לוקא, לומבלא, מעזיבין, בעלזא, שידלוב, בריסק, קראקא-שעט על מקום רבו - ר משלם פיבש ור יהושע בעל \"מגיני שלמה\" על מקומו אחריו. מתלמידיו בקראקא ר צבי הירש מלובלין, ר גרשון אשכנזי בעל \"עבודת הגרשוני\", ר מנחם מנדל אוירבך. בניו - ר ליב מחנטשין, ר שמואל צבי הירץ-הו\"ל מספריו.","s":"אוצר הרבנים 7848; בית העלמין בוילנא-קלויזנר; פין-כנסת ישראל; צונץ-קראקא; בריסק-עיר תהלה; היברובוקס; תוספת להמודיע ב' שבט תשעד עמוד כח, סיפורי צדיקים גליון כו שנה תשעד; יומא דהילולא","bk":[["הגהות הב\"ח","מפרשי ש\"ס - אחרונים"],["ב\"ח",""],["ב\"ח [על הטור",""],["שו\"ת]",""],["ב\"ח החדשות",""],["בית חדש",""],["בית חדש החדשות [שו\"ת]",""],["בית חדש הישנות",""],["משיב נפש",""],["ב\"ח – בית חדש",""],["הב\"ח",""],["מגילת רות - משיב נפש",""],["ב\"ח","מפרשי הטור"],["ב\"ח","שו\"ת - אחרונים"]],"e":"שכ\"א-ת'"},{"i":34821,"n":"סירקיש, שמואל גרשון מירושלים","f":"יהודה אריה ליב מקרקא","b":"נכד בעל הב\"ח. מגדולי ירושלים-תס. בנו - ר יהודה אריה ליב בעל \"לוית חן\".","s":"אוצר הרבנים 19488; פרומקין-תח\"י"},{"i":34822,"n":"סירקיש, שמואל צבי מבריסק","f":"אריה ליב-שאגת אריה","b":"חתן ר נחמן רפפורט. רב בבריסק-תעד על מקום אביו ובנו ר נחמן על מקומו אחריו ונכדו - ר מרדכי סירקין בעל \"מים עמוקים\".","s":"אוצר הרבנים 19622; אהלי שם; צונץ-קראקא; אבני בית היוצר-וייס; בריסק-עיר תהלה"},{"i":34823,"n":"סירת ן, משה מאלגיר","bt":"ש - בערך","dt":"שע - בערך","b":"מחכמי תלמסאן. נזכר במכתב ר אברהם עוזיאל לר יהודה שוראקי ור מימון כלץ - רבני תלמסאן.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":34824,"n":"סיתהון, משה עזרא","s":"מתוך קטלוג"},{"i":34825,"n":"סכנדרי, אברהם הסופר מספרד ומצר","f":"יוסף הרופא","dt":"רעח","b":"רופא מחכמי ספרד, גלה מספרד והגיע לתורכיה עם אביו, התישב במצרים עם בנו ר יוסף וכיהן כרב באלכסנדריה וקהיר ובנו ר יוסף על מקומו אחריו. (כך בספר \"דברי יוסף\" לנכדו - ידוע שבנו ר יוסף היה חברו של ר עובדיה מברטנורא שנפטר בירושלים לפני רנב - ואם כן הגיעו קודם לגירוש-רנב ואולי במאורעות קנא בספרד). למעשה השם סכנדרי החל להיקרא ע\"י בנו ר יוסף ע\"ש אלכסנדריה-מצרים).","s":"אוצר הרבנים 6560; אלופי יעקב א-קטו; פין-כנסת ישראל; רוזניס-תורכיה-ג"},{"i":34826,"n":"סכנדרי, אברהם ממצרים","f":"יוסף או אלעזר הרופא","bt":"שכה","dt":"תו-י - ט אלול","b":"רופא. תלמיד ר אברהם מונסון. רב במצרים על מקום מהריק\"ש-שנות ה-ש'. בניו - ר אלעזר, ר שמואל, ר יוסף. (אולי יוסף הוא שם זקנו).","s":"אוצר הרבנים 659,211; ארזי הלבנון; פין-כנסת ישראל; רוזניס-תורכיה-ג,ד"},{"i":34827,"n":"סכנדרי, אלעזר - אב\"א","f":"אברהם","dt":"שפ","dp":"מצרים","b":"רופא מובהק, ראש הרבנים במצרים על מקום ר בצלאל אשכנזי שעלה לארץ. ג'יליבי במצרים-שעז על מקום ר שמואל הכהן, ור יעקב טבול על מקומו אחריו. נהרג עק\"ה.","s":"אוצר הרבנים 2897; רוזניס-תורכיה-ב,ג,ד"},{"i":34828,"n":"סכנדרי, יוסף ממצרים","b":"גביר במצרים-תקטו, סייע לר שלמה מזרחי בהדפסת ספר אביו ר ישראל מאיר מזרחי.","s":"רוזניס-תורכיה-ה"},{"i":34829,"n":"סכנדרי, יוסף ממצרים - ב","k":"יוסף הזקן מבית הסופר","b":"רופא מומחה, רב במצרים-שנ.","s":"אוצר הרבנים 8474; רוזניס-תורכיה-ב"},{"i":34830,"n":"סכנדרי, יוסף ממצרים ג","f":"אברהם סכנדרי","b":"מגדולי חכמי ורבני מצרים-ת\"מ","s":"אוצר הרבנים 8475"},{"i":34831,"n":"סכנדרי, יוסף מצפת ומצרים? - א","f":"אברהם","dt":"רצה","dp":"צפת","b":"מחכמי צפת, רבו של הרדב\"ז, לדברי ר דוד קונפורטי היה חברו של ר עובדיה ברטנורה. ר יוסף קארו מביא חדושים בשמו בהלכות תפילין. ר יעקב בירב כותב על ר יעקב אליסנדרי שהיה חבר לר עובדיה ברטנורה וכנראה מתכוון אליו. כך שכנראה ישב לפני כן בירושלים. כנראה היה סופר סתם, חתום עם גדולי צפת בשנת רסד.","s":"גליס; פין-כנסת ישראל; בניהו \"ספר אסף\""},{"i":34832,"n":"סכנדרי, יעקב הלוי מקהיר וירושל","b":"מחכמי קהיר, ירושלים, מוזכר ב\"חרבות ירושלים\" כאחד מראשי הקהלה שסבלו מאבן פארוך בשנת שפה.","s":"גליס; פין-כנסת ישראל; פרומקין-תח\"י"},{"i":34833,"n":"סכנדרי, שלמה הלוי מאלכסנדריה","b":"מחכמי אלכסנדירה-שסד, וחתם על טופס קבלת עדות עם ר שמואל ן יחייא, ר יעקב לבנה, ור נסים אגוסטרי לבית ציון, ור יוסף סאגיש. תשובה בקשר אליו אצל ר חיים כפוסי - כבעל דין.","s":"ארזי הלבנון; רוזניס-תורכיה-ב,ג"},{"i":34834,"n":"סכנדרי, שלמה ממצרים","b":"מגדולי רבני מצרים-תק\"ס","s":"אוצר הרבנים 18547"},{"i":34835,"n":"סכנדרי, שמואל ממצרים","f":"אברהם הרופא ממצרים","b":"רב במצרים-שנות ה-ש'. בניו: ר אברהם, ר אלעזר אב\"א (אלעזר בן אברהם? כך לפי רוזניס), עלי, משה.","s":"רוזניס-תורכיה-ג"},{"i":34836,"n":"סכני, יצחק מבבל","f":"משה","b":"מחכמי בבל שהגיע לספרד, בזמן הרי\"ף.","s":"ארזי הלבנון"},{"i":34837,"n":"סלאדינסקי, זליג","dt":"תשג","b":"רב בסמרגן","s":"אוצר הרבנים 5764"},{"i":34838,"n":"סלאוסטש","k":"ראה: סלושץ","bt":"תריב","bp":"אודסה","b":"בגיל 14 הלך ברגל לליטא והיה תלמיד \"קלויז בלומקעס\" במינסק אצל ר חיים חייקל ברנשטין, תלמיד ישיבת וולוזין. מ\"מ באודסה, מו\"ץ מאלדאוואנקא."},{"i":34839,"n":"סלאם","k":"ראה: סולאם","b":"מגדולי חכמי ירושלים-תקי\"ד","s":"אוצר הרבנים 9488"},{"i":34840,"n":"סלאמי, שלמה ממצרים","b":"רב במצרים-תע, בזמן מהר\"י זין. מתשובותיו ב\"פרי עץ חיים\".","s":"אוצר הרבנים 18548; ארזי הלבנון"},{"i":34841,"n":"סלבוצקין, אלימלך מפפד\"מ","b":"מדפיס בפפד\"מ, הדפיס \"המסדרונה\" - תרמה.","s":"אוצר כתבי עת-לוין"},{"i":34842,"n":"סלבין, שלמה הלוי מסטולין","k":"בעל תורת חסד","dt":"תשג","b":"ר\"מ בישיבת \"בית ישראל\" בסטולין. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תלפיות\" - טרנוב תרצח.","s":"אוצר הרבנים 18549; אוצר כתבי עת-לוין"},{"i":34843,"n":"סלביצקי, יצחק","dt":"תשג","b":"מרבני פולין","s":"אוצר הרבנים 10876"},{"i":34844,"n":"סלדוכי, זבולון","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":34845,"n":"סלהוב, דוד מלוב","bt":"תרי","dt":"תרץ - בערך","b":"רב בזליתן-תרל עד תרע.","s":"מלכי חי\"ל-מרציאנו"},{"i":34846,"n":"סלודובניק, משה מארה\"ב","f":"יעקב","bt":"תרעא","bp":"פינסק","b":"תלמיד ישיבת ראדין. נסמך מאת: ר דוד רבינסקי מפינסק, ועוד. היגר לארה\"ב. חתן ר אליעזר גרליק מניו הייבן. רב קהלת \"אהבת אחים אנשי פינסק\" בניו יורק-תשב, חבר אגודת הרבנים באמריקה.","s":"אנשי שם-אמריקה"},{"i":34847,"n":"סלווירא, ישעיה מאר\"ץ","dt":"תקצז - כח סיון","dp":"טבריה","b":"רב באר\"ץ, עלה לטבריה.","s":"ארזי הלבנון"},{"i":34848,"n":"סלוונדי, יעקב אריה ליב מדירקה","f":"חיים מעיר חדש","bt":"תקצז","bp":"עיר חדש-הונגריה","dt":"תרעה - ט טבת","dp":"קרלסרוא","b":"תלמיד הכת\"ס, ור דוד שטייניץ מעיר חדש, ור שלמה קוועטש מניקלשבורג. רב בבעהרהענט(=בעהרענט)-פרוסיה-תרכד, דירקהיים-תרכו (באוצר רב בפרנקלטל). באוצר תאריך הפטירה תרמט או תרסח. הכריז על איסוף נייר משומש כדי למכרו ולשלוח את הרווחים לארץ ישראל.","s":"החת\"ס ותלמידיו; אוצר הרבנים 3365,10019; פרשבורג-וינגרטן; אהלי שם; גרינוולד-סלובקיה והונגריה"},{"i":34849,"n":"סלוטקי, אהרן אברהם מירושלים","f":"משה מקאליש","b":"מצאצאי ר ישראל הלוי הורביץ מאויהל וטבריה. ראש ישיבת המקובלים \"שער השמים\" בירושלים, מגדולי תלמידי ישיבת המקובלים \"בית אל\". בנו - המקובל ר אליהו דוד \"בעל יד אליהו\".","s":"מתוך קטלוג"},{"i":34850,"n":"סלוטקי, אליהו דוד מירושלים","f":"אהרן אברהם","k":"בעל יד אליהו","dt":"תשם - כט אייר","dp":"ירושלים","b":"מקובל בירושלים, חברו של דוד בהר\"ן. חיבר גם \"חסדי דוד\".","s":"מתוך קטלוג"},{"i":34851,"n":"סלוטקי, משה קאליש מירושלים","f":"יעקב","k":"בעל נר משה","b":"מקובל בירושלים, בנו - המקובל ר אהרן אברהם, ונכדו המקובל ר אליהו דוד.","s":"מתוך קטלוג"},{"i":34852,"n":"סלומון, אברהם ישראל משה מחרקוב","k":"בעל נזר הקדש","dt":"תשיז - ז חשון","b":"תלמיד ישיבות וולוזין וראדין. ותלמיד ר יעקב שלמה שיין מלוצקווא. חתן ר משה לנדיסקי מראדין. רב בחרקוב, ולאשנסק, עלה לירושלים-תרצו. חיבר גם \"נתיבות הקדש\".","s":"אוצר הרבנים 1266,12282; יומא דהילולא","bk":[["נתיבות הקודש",""]],"e":"תשי\"ז [פטירה]"},{"i":34853,"n":"סלומון, אברהם מנאדי-באניא","b":"רב בגליל נאדי-באניא. חתנו - ר שמחה בונם דייטש מקעלטשע.","s":"החת\"ס ותלמידיו"},{"i":34854,"n":"סלומון, אליהו לואי מארה\"ב","f":"יעקב","bt":"1879","bp":"וילנא","dt":"1956","b":"היגר בילדותו לארה\"ב. הוסמך לרבנות ע\"י הסמינר התיאולוגי בניו יורק. רב בקהילות שונות. נשיא כבוד של איחוד בתי הכנסת באמריקה. פעיל בועד למען הפאלשים. חבר הנהלת הועידה הלאומית של נוצרים ויהודים.","s":"ליטא"},{"i":34855,"n":"סלומון, ברוך שמעון מפתח תקוה","b":"רב ראשי בפתח תקוה.","s":"מתוך קטלוג"},{"i":34856,"n":"סלומון, גיאורג מסאוואנא","bt":"1873","bp":"ניו יורק","b":"תלמיד בהיברו יוניון קולג' בסינסינטי. רב ריפורמי בקהילת \"עדת חסד\" בויקסבורג, \"קהילת \"מקוה ישראל\" בסאוואנא. חיבר ספר באנגלית.","s":"דור וחכמיו-א\"ש-ו"},{"i":34857,"n":"סלומון, דוד מכפר אברהם","f":"ישראל משה סלומון","bt":"תרע","dt":"תשכח - ט אייר","b":"רב ור\"מ בכפר אברהם-תרצ\"ה","s":"אוצר הרבנים 4940"},{"i":34858,"n":"סלומון, זלמן מירושלים","f":"חיים"},{"i":34859,"n":"סלומון, טוביה מטרנוב","dt":"תרצב","b":"מחכמי טרנוב, עסקן למצוות.לפי צוואתו הטמינו בקברו 28000 מזוזות פסולות שהחליפם.","s":"וונדר-גליציה ח\"ד"},{"i":34860,"n":"סלומון, יואל משה מירושלים","f":"מרדכי","bt":"תקצח","dt":"תרעג - יב חשון","dp":"ירושלים?","b":"נכד ר שלמה זלמן צורף מירושלים. תלמיד הרבנים מקוטנא וקאליש. פעל לישוב ירושלים ופתח-תקוה. הקים דפוס בירושלים עם ר מיכל הכהן, הו\"ל \"הלבנון\", \"כבוד הלבנון\" - ירושלים תרכג. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח. עורך \"תורת ציון\" - ירושלים תרכב - המאסף התורני הראשון בירושלים.","s":"אוצר הרבנים 7877; אוצר כתבי עת-לוין; פרומקין-תח\"י"},{"i":34861,"n":"סלומון, יוחנן דוד מירושלים","bt":"תריז","bp":"ירושלים","dt":"תרעג - טז טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":34862,"n":"סלומון, יוסף מחמלניק","b":"רב ברדומישל-תקצו. חתן האדמור ר טוביה גוטמן מריגליץ.","s":"וונדר-גליציה ח\"ד; אלפסי"},{"i":34863,"n":"סלומון, יצחק מירושלים וארה\"ב","f":"מאיר ישעיה","bt":"תרע","bp":"ירושלים","b":"תלמיד ישיבת \"עץ חיים\", \"מאה שערים\" בירושלים, ישיבת רבי יצחק אלחנן בניו יורק. נסמך מאת: ר אברהם יצחק הכהן קוק, רמ\"ז מרגליות, ר דב רעוועל, ר יוסף גרשון הורביץ, ר משה סולוביציק, ר אהרן ארונוביץ. רב בלייק פלאסיד, קהלת \"אגודת אחים\" בפריהולד-ניו ג'רסי, \"אהבת ישראל\" בפילדלפיה-תשג. חבר אגודת הרבנים באמריקה, ותנועת המזרחי.","s":"אנשי שם-אמריקה"},{"i":34864,"n":"סלומון, ישכר מאנגליה","f":"שלמה","bt":"תרה","bp":"קופנהגן-דנמרק","b":"תלמיד ישיבת איזנשטט, ביהמ\"ד לרבנים בברלין, ובעל תואר ד\"ר. רב במנצסטר-תרמא בקהלת \"עדת ישורון\". פרסם מאמרים באנגלית ודנית.","s":"אוצר הרבנים 12402; אהלי שם"},{"i":34865,"n":"סלומון, ישראל משטרסבורג","f":"יוסף מחמלניק","b":"עבר מרדומישל לשטרסבורג-תרסא.","s":"וונדר-גליציה ח\"ד"},{"i":34866,"n":"סלומון, נפתלי חיים מקראקא","f":"יוסף מחמלניק","k":"אדמור מקראקא","dt":"תש..","b":"נכד ר טוביה גוטמן האדמור מריגליץ. אדמור בקראקא. נספה בשואה.","s":"וונדר-גליציה ח\"ד; אלפסי"},{"i":34867,"n":"סלומון, נתן נטע צבי הלוי","bp":"מחוז סטמר","dt":"תרמא - יז טבת","b":"תלמיד ר אשר אנשל יונגרייז בצ'נגר. רב בהידאלמש-תרכז כ-17 שנה, נספד ב\"מעגלי צדק\" ע\"י ר אשר שמואל פאנט שכיהן על מקומו אחריו בהידאלמש.","s":"טרנסילבניה; הונגריה; ברוין-אנשי מופת"},{"i":34868,"n":"סלומון, פישל מוארפלט","b":"חתן ר משה טננבוים מוארפלט. רב בוארפלט על מקום חותנו-תרעח.","s":"הונגריה"},{"i":34869,"n":"סלומונוב, מרדכי ממינסק","f":"שמואל חיים מבעליצא","bt":"תקצג","bp":"איווניץ","dt":"תרנו - כט ניסן","dp":"מינסק","b":"נכד(-אבי אמו) ר יצחק לאזדינער מאיוויניץ. לאחר שנתייתם גדל אצל דודו ר ליבל שפירא מקובנא. חתן ר צבי הירש סלומונוב ממינסק (ומכאן שמו). גביר מחכמי מינסק, ראש הגבאים של ישיבת וולוזין, התכתב עם גדולי דורו ובהם ר יצחק אלחנן מקובנא, ר יוסף דב ור חיים סולוביציק, ועוד. הניח חדושי תורה אצל בנו ר משה צבי סלומונוב.","s":"מינסק-איזנשטט; ליפמן-קובנא"},{"i":34870,"n":"סלומונס, דוד מאנגליה","bt":"1797","bp":"לונדון","dt":"1873","b":"חתן הגביר ר זליג-חותן ר משה מונטיפיורי. היהודי הראשון שנבחר לפרלמנט באנגליה","s":"פין-כנסת ישראל"},{"i":34871,"n":"סלונים, יעקב יוסף מחברון","bt":"תרמא","bp":"חברון","dt":"תרצב - יב תשרי","b":"נכד ה\"צמח צדק\". חסיד חב\"ד ונציגו של האדמור הרש\"ב ועסק ברכישת בתים עבור האדמור והחסידות, רב פעלים לחזוק הישוב היהודי והרבצת התורה, רב ראשי בחברון וראש ישיבת \"תורת אמת\" בחברון. פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ-תשז. בפרעות-תרפט נהרגו בנו, כלתו ונכדו, בנו גם - ר לוי יצחק מפרייבורג-ארה\"ב.","s":"אוצר הרבנים 10113; אוצר כתבי עת-לוין"},{"i":34872,"n":"סלונים, לוי יצחק מארה\"ב","f":"יעקב יוסף מחברון","bp":"חברון","b":"רב בפרייבורג-ארה\"ב."},{"i":34873,"n":"סלונים, מנחם מנדל מירושלים","f":"שניאור זלמן","bp":"חברון","b":"מתושבי תל אביב."},{"i":34874,"n":"סלונים, מרדכי דב בר מחברון","bt":"תר","b":"ראש כולל חב\"ד בחברון","s":"אוצר הרבנים 14100"},{"i":34875,"n":"סלונים, שניאור זלמן מחברון","f":"מרדכי דוב סלונים","bt":"תרכב","dt":"תרצו - יא תמוז","b":"רב לחסידי חב\"ד בחברון, יפו-תרנט - בהוראת ר שניאור זלמן בעל \"תורת חסד שציוה עליו לקבל את הרבנות), מרבני תל אביב.","s":"אוצר הרבנים 20166"},{"i":34876,"n":"סלונימסקי חיים זליג בן יעקב","bt":"1810","dt":"ה'תרסד 1904","s":"היברובוקס","bk":[["יסודי חכמת השעור",""],["כוכבא דשביט",""],["מוסדי חכמה",""],["מציאות הנפש",""],["תולדות השמים",""]]},{"i":34877,"n":"סלונימסקי, דוד","bt":"1849","bp":"דיסנא-ליטא","dt":"1907","dp":"וילנא","b":"אביו היה רב מטעם בגרודנא ומקורב לחיים זליג סלונימסקי. ברח מביתו בגיל 13 והגיע לוילנא והתחבב על קצנלנבוגן שהיה מפקח ביהמ\"ד לרבנים בוילנא וקיבלו ללימודים. בעת ביקור הצאר אלכסנדר השני במוסד הוצג לפניו כמצויין בתלמידים והקריא לצאר שיר שחיבר לכבודו וקיבל מהצאר מדליה של כסף. למד רפואה בברלין, ומשפטים בפטרבורג. עבר בסינט וסירב להתנצר ונאלץ לפרוש ועבר לפרקליטות. ממייסדי \"ווסחוד\" ופרסם מאמרים נגד הפוגרומים - תחת השם \"פטר שלומיאל\". תרגם ספרים לרוסית. גורש מפטרבורג ועבר לוילנא. ארגת את ההגנה על בלונדס יחד עם גרוזנברג ומירונוב.","s":"ליטא"},{"i":34878,"n":"סלונימסקי, חיים זליג","f":"יעקב","k":"בעל מוסדי חכמה","bt":"תקע","bp":"ביאליסטוק","dt":"תרם - אחרי","b":"משכיל מליטא, מקורב ותלמיד ר מיכל זבלורובסקי מביאליסטוק. ראש ביהמ\"ד לרבנים בזיטומיר על מקום ר יעקב איכנבוים, עבר לברלין והו\"ל \"הצפירה\", ועבר לוארשא עם כתב העת. חיבר ספר לימוד מתמטיקה עם הסכמת ר אברהם אבלי מוילנא, חיבר \"תולדות השמים\" אודות חישוב הלוח וכנגדו יצא ר צבי הירש פינעלעס - ופרסמו שניהם מאמרים בענין. פרסם קונטרס \"פך השמן\" על חנוכה, וכנגדו כתב ר משה רוזין ב\"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה.","s":"אוצר כתבי עת-לוין; פין-כנסת ישראל; אסף-נאחז בסבך"},{"i":34879,"n":"סלונימר, משה","dt":"תקנב - כה אייר","b":"ראב\"ד בסלונים","s":"אוצר הרבנים 14975"},{"i":34880,"n":"סלוניקי, אברהם מרוסטשוק","b":"רב הכולל ברוסטוק(=רוסטשוק)-בולגריה-תרסה.","s":"אוצר הרבנים 662; אהלי שם"},{"i":34881,"n":"סלוסטובסקי, יחיאל מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ.","s":"אוצר כתבי עת-לוין"},{"i":34882,"n":"סלוצקי, אליהו הלוי ממיר","f":"בצלאל מסלוצק","b":"רב במיר. חתנו - ר מיכאל בן אברהם איזנשטט. מצאצאיו - הנצי\"ב מוולוזין.","s":"ברוורמן-אנשי שם"},{"i":34883,"n":"סלוצקי, אליעזר","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה.","s":"אוצר כתבי עת-לוין"},{"i":34884,"n":"סלוצקי, דוד מסנאווי","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"מאסף דרושי\" - וילנא תרסט.","s":"אוצר כתבי עת-לוין"},{"i":34885,"n":"סלוצקי, חיים יעקב מוילנא","k":"בעל נטעי נאמנים","b":"רב בוילנא-תקפ. מחותן עם ר חנוך הניך איטלסון מויליאמפול.","s":"אוצר הרבנים 6401; ליפמן-קובנא"},{"i":34886,"n":"סלוצקי, מרדכי שמעון מאורלא","f":"ש\"ל","b":"דיין באורלי-פאדליאסקי. הסכים-תרפח על \"חקר שמואל\" יחד עם ר אליהו נח הלפרין (חברו לבית הדין)."},{"i":34887,"n":"סלוצקר, אריה יהודה ליב","f":"קלמן","b":"רב בפינסק-תקכ. בניו - ר שמואל, ר יוסף יאנובר, ונכדו - ר נתן שטרן. חתנו - ר יצחק אפשטין. (ראה גם אריה ליב מסלוצק)","s":"אוצר הרבנים 3364; ברוורמן-אנשי שם"},{"i":34888,"n":"סלוצקר, יהושע השל מבוליחוב","b":"רב בבוליחוב.","s":"וונדר-גליציה ח\"ד"},{"i":34889,"n":"סלוצקר, שמואל","f":"אריה יהודה סלוצקר","b":"רב באנטיפאליע,קרלין,פינסק","s":"אוצר הרבנים 19295"},{"i":34890,"n":"סלושץ, אליהו מרדכי מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"אוצר כתבי עת-לוין"},{"i":34891,"n":"סלושץ, דוד שלמה מאודסה","k":"בעל ראשית דוד","bt":"תריב","bp":"אודסה","dt":"תרסו - כ שבט","b":"בגיל 14 הלך ברגל לליטא והיה תלמיד \"קלויז בלומקעס\" במינסק אצל ר חיים חייקל ברנשטין, תלמיד ישיבת וולוזין. מ\"מ באודסה, מו\"ץ מאלדאוואנקא. חיבר גם \"כבוד ישראל\", \"צדקת משה\", ועוד. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא, \"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר הרבנים 5217; דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין; היברובוקס","bk":[["חשבון הנפש או חג היובל",""],["כבוד ישראל",""],["מנוחת שלום",""],["עלית משה",""],["קונטרס מנוחת שלום",""],["ראשית דוד",""],["שועת בת עמי",""],["תפארת יהודה",""]]},{"i":34892,"n":"סלושץ, יוסף צבי הירש ממינסק","f":"משה הכהן","dt":"תרנג - ד שבט","dp":"מינסק","b":"מחכמי מינסק.","s":"מינסק-איזנשטט"},{"i":34893,"n":"סלט, אורי זאב וולף מלמברג","f":"יחזקאל מלמברג","k":"ע. סלט","bt":"תקפח","bp":"למברג","dt":"תרנט","b":"מנכדי המדפיס ר אורי פייביש מאמשטרדם. תלמיד ר יוסף שאול נתנזון. דיין מחכמי למברג וסירב לרבנות. הקים דפוס בלמברג. השאיר חבורים בכתב יד - חלקם נדפסו בכתבי עת.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 1925; מצבות קדש-לבוב"},{"i":34894,"n":"סלט, משלם מלמברג","f":"אורי זאב וולף מלמברג","bt":"תרי","dt":"תרעח","b":"מדפיס בלמברג ודיין-תרסח על מקום אביו.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 15701"},{"i":34895,"n":"סלטרו, יהודה מפאנו","f":"משה","k":"בעל מקוה ישראל","b":"רב בפאנו-באיטליה. חיבר \"פלגי מים\" ו\"מקוה ישראל\" - בענין המקוה ברוויגו.","s":"איטליה גירונדי-י צח; אוצר הרבנים 7359; פין-כנסת ישראל"},{"i":34896,"n":"סלי (שולי) ן, יוסף הפייטן","f":"דוד","b":"פייטן בספרד-שנות ה-ק'.","s":"פין-כנסת ישראל"},{"i":34897,"n":"סליאזברג, שלום ממינסק","b":"גביר מחכמי מינסק-תרן.","s":"מינסק-איזנשטט"},{"i":34898,"n":"סלימן מנחם דניאל מחלב","b":"גביר בחלב-תרך.","s":"מתוך קטלוג"},{"i":34899,"n":"סלמה, אברהם מדמשק","b":"מראשי קהלת דמשק-שו, חתם על מעשה בי\"ד ונזכר ב\"אבקת רוכל\". חיבר פיוט \"ארץ הקדושה יקרה\".","s":"פין-כנסת ישראל"},{"i":34900,"n":"סלמה, אברהם מטיטואן-מרוקו","b":"מחכמי טיטואן, נזכר ב\"ויאמר יצחק\", חיבר \"תוכחה ארץ הקדושה\" ונדפס ב\"תכלת החדש\".","s":"מלכי רבנן"},{"i":34901,"n":"סלמה, אברהם משלוניקי","dt":"שכב - י אלול","dp":"שלוניקי","b":"גביר מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":34902,"n":"סלנט, בנימין בינוש מירושלים","f":"שמואל מירושלים","bt":"תקצח","dt":"תרס - יט תשרי","b":"מחכמי ירושלים עסק במסחר אתרוגים. הו\"ל \"חדושי הר\"ן\" ירושלים תרלא. נפטר בחיי אביו. חתנו - ר יחיאל מיכל טוקוצינסקי מירושלים.","s":"אוצר הרבנים 3790"},{"i":34903,"n":"סלנט, יהודה ליב מירושלים","b":"מחכמי ירושלים. חתם-תרלא עם מיסדי שכונת נחלת שבעה.","s":"מתוך קטלוג"},{"i":34904,"n":"סלנט, יוסף זונדל מירושלים","f":"בנימין בונם","bt":"תקמו","bp":"סלנט","dt":"תרכו","dp":"ירושלים","b":"תלמיד ישיבת וולוזין והיה תלמידו של ר חיים מוולוזין. נחשב למורהו של ר ישראל סלנט בדרך המוסר למרות שלא לימדו בצורה מסודרת. עלה לירושלים-תקצח, שימש תקופה קצרה כרבה של ירושלים עד להגעת חתנו ר שמואל סלנט. מאמר עליו ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב מאת ר יעקב ספיר.","s":"גליס; אוצר 8780 ו-5738; ליטא; אוצר כתבי עת-לוין; פרומקין-תח\"י","bk":[["רבי יוסף זונדל מסלנט",""]]},{"i":34905,"n":"סלנט, יוסף ליב משאנץ","bt":"תרכג","dt":"תרצו","b":"רב בשאנץ-תרנ\"ה","s":"אוצר הרבנים 8901"},{"i":34906,"n":"סלנט, צבי הירש מואלקוניק","f":"חיים","dt":"תקפב","b":"תלמיד ר יעקלי חריף בקריניק. אב\"ד טרוקי, וולקוניק(=ואלקיניק)-ליד ביאליסטוק, פיעסק, דרוהוצ'ין. בנו - ר שמואל מירושלים.","s":"אוצר הרבנים 17388"},{"i":34907,"n":"סלנט, צבי מירושלים","f":"בנימין ביניש","k":"ירושלים","bp":"ירושלים","dp":"תרפב - ט אב","b":"מחכמי ירושלים."},{"i":34908,"n":"סלנטר, אלחנן הכהן","bp":"סלנט","dt":"תרלט","dp":"וילנא","b":"ייצג את ר ישראל סלנטר ואת רבני רוסיה בפני השלטונות בפטרבורג.","s":"ליטא"},{"i":34909,"n":"סלניק, אברהם מטרנופול ובריסק","f":"בנימין אהרן-משאת בני","b":"תלמיד המהר\"ם מלובלין. רב בטרנופול, בריסק-שנת ת'. מחותן עם בעל \"מגיני שלמה\" הגיה את ספר אביו, ונזכר בתשובות אביו. מתורתו בשו\"ת בית חדש החדשות, שו\"ת הגאונים בתראי, ועוד. חתנו - ר יואל פייבש מרגליות.","s":"אוצר הרבנים 661; בית העלמין בוילנא-קלויזנר; שם הגדולים השלישי; בריסק-עיר תהלה"},{"i":34910,"n":"סלניק, בנימין אהרן מבריסק","f":"אברהם אשכנזי","k":"בעל משאת בנימין","bt":"ה'רצ","dt":"שפ","b":"תלמיד הרמ\"א והמהרש\"ל. מגדולי הפוסקים, רב בפודהייץ. בניו: ר יעקב בעל \"נחלת יעקב\", ר אברהם שהו\"ל את ספרו. מחותן עם ר משה בן אברהם מפרמישלא בעל \"מטה משה\", ועם ר יוסף יעקב אברהם בן יואל קצנלנפויגן מלבוב. מחותן עם ר משה בן מנחם מנדל מולאדמיר.","s":"אוצר הרבנים 3779; בית העלמין בוילנא-קלויזנר; פין-כנסת ישראל; בריסק-עיר תהלה; בובר-לבוב; פין-קריה נאמנה","bk":[["משאת בנימין [שו\"ת]",""],["מצוות נשים [ידיש]",""],["משאת בנימין","שו\"ת - אחרונים"]]},{"i":34911,"n":"סלניק, יעקב","f":"בנימין אהרן-משאת בני","k":"בעל נחלת יעקב","b":"רב-שנת ת'. חיבר \"נחלת יעקב\" על רש\"י לתורה.","s":"אוצר הרבנים 9477; בית העלמין בוילנא-קלויזנר; פין-כנסת ישראל; פין-קריה נאמנה"},{"i":34912,"n":"סלפקוביצר, משה מיאסי","b":"רב ביאסי. נספד ב\"אבל משה\" לר ישעיה ראובן קלינגר מסיוען עם הערות לר נחום אתרוג מצפת.","s":"שם הגדולים השלישי"},{"i":34913,"n":"סמאג'א, יעקב מאלגיר","dt":"תרמ..","b":"רב באלגיר, ותיקן תקנות. נזכר אצל ר אליהו גיג' ב\"זה השלחן\", ב\"מסעי ישראל\", חתם על תשובה ב\"שער שלמה\", על אגרת תמיכה בר אברהם אנקאווא-תריח במחלוקת על \"זבחים שלמים\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":34914,"n":"סמאג'א, סעדיה מאלגיר","bt":"תקל","dt":"תרי","b":"רב באלגיר. חתם עם ר ישועה סידון על שטר מכר באלגיר. ביכ\"נ על שמו באלגיר. סייע בהדפסת \"פרקי אבות\" ברלין תרח.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34915,"n":"סמאג'ה, חיים מטבריה","b":"דיין בטבריה אצל ר אשר זאב ורנר, חתם-תשו על מכתב בקשה עם הדיין ר אהרן גולדזאל.","s":"מתוך קטלוג"},{"i":34916,"n":"סמאג'ה, יעקב מאלגיר","dp":"טבריה","b":"רב במסתגאנם, עלה לארץ-תקץ והתישב בטבריה. דודו - ר חיים עליאש אסמאק.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34917,"n":"סמאג'ה, מרדכי מתונס","b":"דיין בתונס-[תרמ] בזמן ר אברהם חג'אג' בעל \"זרעו של אברהם\". הסכים על \"ספר פנים ופתגם המלך\" לר משה זקן מאזוז.","s":"ארזי הלבנון"},{"i":34918,"n":"סמאייה, אברהם מברושה","b":"רופא מחכמי ברושא בזמן ר שמעון ן חביב.","s":"רוזניס-תורכיה-א"},{"i":34919,"n":"סמאנא, אברהם ממראקש","b":"מו\"ץ במראקש-שנות ה-תר'. הסכים על \"קול מבשר\" לר משה רוזיליו-ירושלים תרסח.","s":"מלכי רבנן"},{"i":34920,"n":"סמאנא, חבאבו ממראקש","b":"מחכמי מראקש-מרוקו-שנות ה-תק'. בנו - ר חיים - עלה לירושלים.","s":"ארזי הלבנון; מלכי רבנן"},{"i":34921,"n":"סמאנא, חיים ממראקש וירושלים","f":"חבאבו","dp":"מרוקו","b":"מחכמי מראקש, עלה לירושלים. בשליחות במרוקו ונפטר בשליחותו.","s":"מלכי רבנן"},{"i":34922,"n":"סמאנו, רחמים ממצרים","b":"רב במצרים-רפ, חתם על העתק תקנת הרדב\"ז בענין השלום בין קהילת \"מסתערב\" ו\"מערבים\".","s":"אוצר הרבנים 17747; ארזי הלבנון"},{"i":34923,"n":"סמברי, יוסף ממצרים","f":"יצחק דידיע קטאייא","k":"בעל לקוטי יוסף","dt":"תסב - בערך","b":"מחכמי מצרים, היה מקורב לג'יליבי רפאל יוסף ברהין, חיבר ספר היסטוריה ובו תולדות היהודים במצרים.","s":"אוצר הרבנים 8478; רוזניס-תורכיה-ד"},{"i":34924,"n":"סמואלסון, זאב וולף מבולטימור","k":"בעל חבצלת השרון","b":"רב בבולטימור-תרסה.","s":"אמריקה"},{"i":34925,"n":"סמוט-פורמון, שמואל משלוניקי","dt":"שט - י תשרי","dp":"שלוניקי","b":"מיוצאי קאלברייה, מחכמי שלוניקי. אביו של ר יעקב סמוט-פורמון מקייאנה.","s":"עמנואל-שלוניקי"},{"i":34926,"n":"סמוט-פירמון, יעקב משלוניקי","f":"שמואל","bt":"רפ","b":"רב בקהלת קיאנא בשלוניקי-שט על מקםו ר יצחק וארון, מו\"ץ בקהלת קאלבריה - לאחר מחלוקת כנגדו מצד תקיפים בקהלה. מתורתו בספרי חכמי דורו ובהם רשד\"ם, ר יוסף קארו, ר שלמה הכהן.","s":"רוזניס-תורכיה-ב"},{"i":34927,"n":"סמוטיל, אברהם","b":"מחכמי טורקיה","s":"ארזי הלבנון"},{"i":34928,"n":"סמולנסקין, פרץ","b":"סופר. בהיותו מנהל בית דפוס בוינה סייע לר אברהם משה לונץ בהוצאת המאסף \"ירושלים\" - תרמב.","s":"אוצר כתבי עת-לוין"},{"i":34929,"n":"סמונוב, אפרים מיאקובשטט וינדאו","f":"גרשון מפילטען","k":"בעל הכהן הגדול והסגן","r":"רב ביעקוביבטש ווינדוי","bt":"תריט","bp":"פילטען","dt":"תרצב","b":"תלמיד ישיבת וולוזין. חתן ר חיים ברלין ממוסקבה. רב ביקובשטט-תרן, ווינדוי(=וינדאווי)-תרנז.","s":"אוצר הרבנים 3056; אובצינסקי-קורלנד; מוריה קובץ קא שנה יח גליונות ג - ד עמוד כ","bk":[["הכהן הגדול והסגן - קדשים (בעיקר)",""]]},{"i":34930,"n":"סמונוב, גרשון מנדל מפילטען","f":"מרדכי אוריה מילקובסק","dt":"תרעט","b":"תלמיד ר יוסף דב סולוביציק. רב בפילטען (לא רשמי). בנו - ר אפרים מוינדאווי.","s":"אובצינסקי-קורלנד"},{"i":34931,"n":"סמונוב-מילקובסקי, מרדכי אוריה","f":"אהרן","bt":"תקסט","bp":"שווקשנה-פלך קובנא","dt":"תרכד - טז סיון","dp":"וינדאווי","b":"נכד ר טוביה מזאגר, ונכד ר יוסף משועקסנא. חתן ר גרשון ברמן מקרטינגא, למד באיישישוק. רב בשוואקשנה, שאבילין(=שאבילאן, שאוולאן)-תר על מקום ר שמואל רבינוביץ, וינדאווי-תרז, מיטאוי(=מיטאו)-תרטז והיה גם רב מטעם הממשלה, חזר לוינדאווי. בניו - ר גרשון סאמונוב מפילטען, ר אליהו אהרן מגריווא. שתדלן ועסקן ציבור. ר ישראל סלנטר הציגו בפני תלמידיו כמופת במוסר. הניח כת\"י בהלכה ואגדה, ומהם נדפס בספר \"יד ושם\" לבנו - ר אליהו אהרן. חתנו - ר דוד קלוטשוב מטוקום.","s":"אוצר הרבנים 14068; אובצינסקי-קורלנד; ליטא"},{"i":34932,"n":"סמט, ישראל חיים מקלינורדין","k":"בעל שמע ישראל","dt":"תשד","b":"מיוחס לר אברהם יהושע השל מאפטא. רב בקליינורדין","s":"אוצר הרבנים 12195; אלפסי"},{"i":34933,"n":"סמיאטיצקי, י'צ' זיידל","dt":"תשיז","b":"חתן ר חיים משה שניידר ור\"מ בישיבת חותנו בלונדון.","s":"אוצר הרבנים 11484; אוצר הרבנים 5705"},{"i":34934,"n":"סמיאטיצקי, מנחם מאסטרוב וארהב","k":"בעל דברי מנחם","b":"רב באסטורב, אמריקה. חיבר \"דברי מנחם\" וארשא תרצח. ?? לא באוצר ??","s":"אמריקה"},{"i":34935,"n":"סמיוניץ, משה ממרוקו","dp":"טיטואן","b":"מחכמי טיטואן-מרוקו. שכנו של ר אליהו הצרפתי-תק. נספד ב\"נער בוכה\".","s":"ארזי הלבנון"},{"i":34936,"n":"סמיטיצקי, חיים מוארשא","b":"תלמיד ישיבת \"בית שמואל\" בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו.","s":"אוצר כתבי עת-לוין"},{"i":34937,"n":"סמייזלר, אברהם יחיאל פישל מארה","f":"יעקב יוסף","b":"גביר תומך רבנים בברונזויל-ניו יורק.","s":"אנשי השם בארהב-איזנשטט"},{"i":34938,"n":"סמילג, חיים","dt":"תשג","b":"רב בניי-רדוילישק","s":"אוצר הרבנים 6097"},{"i":34939,"n":"סמילג, יוסף","f":"פסח","k":"בעל יסוד החינוך המוס","bt":"1848","bp":"קיידאן","dt":"1900","dp":"פטרבורג","b":"תלמיד ישיבות וילנא, קובנא. למד בברלין ולייפציג והיה מורה לדת ישראל בגימנסיות בפטרבורג. פרסם מאמרים ב\"המליץ\", וחלק ממאמריו הופיעו בחוברות נפרדות - \"יסוד החינוך המוסרי\".","s":"ליטא"},{"i":34940,"n":"סמינובסקי, צבי גרשון","f":"מנחם","bt":"תקפג","b":"נכד ר אריה משטרשין ולוייב(=לאייעוו). תלמיד ר נטע מזלאבין ור שמואל מזלאבין. רב בזלאבין-תרד, פאבעלאוו-פלך מינסק-תריד בהוראת הצמח צדק, וסירב לרבנות בערים גדולות יותר. נסמך מאת ה\"צמח צדק\". בניו: ר אריה ליב, ר משה, ר אברהם. חתניו: ר אברהם משה מאיהומען, ר שמואל לוין בן מרדכי, ר יוסף בן אליעזר מאזאריץ וביחוב, ר זאב וולף מהאמעל, ר יוסף ליב מהאסטאמעץ-ליד קיוב-בנו של ר אבא קאראבלניקוב מציצערסק.","s":"אוצר הרבנים 17501; אהלי שם"},{"i":34941,"n":"סמיעלויצר, אריה ליב מהאמיל","f":"אלעזר","b":"תלמיד ר מנחם מנדל מליובאויטש, בנו ר יהודה ליב ונכדו ר שלמה זלמן מקפוסט. רב בדוינסק-תרמז, האמיל, סמילוביץ.","s":"אוצר הרבנים 3179 א'; אלפסי"},{"i":34942,"n":"סמישטרי די, אשטרוק","k":"אבו אג שטריק סמישטרי","b":"פייטן ומשורר מחכמי פרובנס-ד'תקן. . נזכר ב\"אמרי נואש\" לר שלמה בונפיד, וב\"שבט יהודה\" מביא מכתב ששלח ר אשטרוק לגירונא ומתאר בו את הויכוח אצל האפיפיור-קעג באביניון.","s":"אלופי יעקב א-תתקכג"},{"i":34943,"n":"סמליטינסקי, מאיר זאב מסמיאטש","f":"אברהם שמחה","bt":"תרכה","b":"חתן ר יצחק צבי מסעמיאטיש(=סעמייטיטש)-פלך גרודנא. מו\"צ בסמיאטיטש-תרנג.","s":"אוצר הרבנים 13054; אהלי שם"},{"i":34944,"n":"סמניץ, יהודה מאויבן","dt":"תרג - כט אייר","dp":"בודפשט","b":"ראב\"ד באויבן, אלטשאבע(=אלשטבע). נזכר ב\"אוצר החיים\", ועוד. הסכים על \"דעת זקנים\" אופן תקצד.","s":"אוצר הרבנים 7045; גרינוולד-סלובקיה והונגריה"},{"i":34945,"n":"סמניץ, ישראל הירש מאראד","dt":"תקמח - בערך","dp":"אראד","b":"רב בסעמניץ, אראד-תקמד. תשובה אליו ב\"נודע ביהודה\" לסעמניץ.","s":"טרנסילבניה"},{"i":34946,"n":"סמניץ, צבי הירש","b":"דיין בווינה-תע\"ה","s":"אוצר הרבנים 17390"},{"i":34947,"n":"סמניצר, מאיר מירושלים","b":"מכתב בעניניו ב\"קובץ דרושים\" - פיעטרקוב תרפג - המופנה לר יוסף חיים זוננפלד ובו דרישה להחרים את ר מאיר על שביזה את האדמור מגור.","s":"אוצר כתבי עת-לוין"},{"i":34948,"n":"סמסון, אברהם מהודו","b":"תושב בומבי-הודו. חיבר ספרים באנגלית.","s":"מתוך קטלוג"},{"i":34949,"n":"סמסון, חיים אלעזר מארה\"ב","f":"בנימין אהרן","bt":"תרנו","bp":"הורודשיץ","b":"תלמיד ישיבת מיר, לומזה. נסמך מאת ר יחיאל מרדכי גורדון, ר יהודה ליב גורדון מלומזה, ר יוסף אברהם צינוביץ מלומזה. חתן הגביר ר שלמה שצובנוביץ מנווגראד. בשליחות ישיבת לומזה בארה\"ב - יחד עם ר יהודה ליב גורדון, נשאר לכהן כראש ישיבת \"חפץ חיים\" מבולטימור.","s":"אנשי שם-אמריקה"},{"i":34950,"n":"סמקופלי, אברהם מירושלים","f":"משה","b":"בעל חצר בירושלים ומכר בית לר ידידיה אבולעפיה-תריט.","s":"פרומקין-תח\"י"},{"i":34951,"n":"סמרגון, יעקב מדאגדא","f":"צבי אריה","k":"בעל ביכורי יעקב","bt":"תרלז","b":"תלמיד ר ראובן קאהן מנארווא. חתן ר יקותיאל עליון מזזמיר. רב בדאגדא-פלך ויטבסק על מקום חותנו ור\"מ בקיבוץ בחורים שם. חיבר \"ביכורי יעקב על הש\"ס ועל קצות החושן.","s":"אוצר הרבנים 9797; אהלי שם"},{"i":34952,"n":"סמרגן, ישראל שאול","dt":"תשג","b":"רב בדאגדע","s":"אוצר הרבנים 12303"},{"i":34953,"n":"סמריק, בצלאל","f":"אברהם","bt":"תרטז","bp":"זטל פלך גרודנא","dt":"תרפט","dp":"חברון","b":"היה רבה של ריגה, עלה לחברון בשנת תרפד, נרצח בטבח בחברון.","s":"גליס; יזכור לקדושי חברון (ירושלים תרץ)"},{"i":34954,"n":"סמרקדיל די, ששת מספרד","b":"מחכמי ספרד, תלמיד הרמב\"ן, עלה לארץ עם רבו הרמב\"ן, והיה עמו בעכו. נזכר ב\"מאירת עינים\" לר יצחק בן שמואל מעכו, ונזכר בפירושי ר מאיר בן אבוסאלה לסודות הרמב\"ן. ותיקן סדר עבודה (ויש הסוברים בטעות כי הכוונה לר ששת אבי הריב\"ש - אך הוא רב ששת אחר). נשא ונתן עם הרשב\"א בדיני הטבת המנורה ונזכר בתשובותיו.","s":"ארזי הלבנון"},{"i":34955,"n":"סנאגיץ, יצחק מגיברלטר","b":"רב בגיבלרטר במאה ה-19.","s":"ארזי הלבנון"},{"i":34956,"n":"סנאניס (סנאנג'), יעקב","bt":"תקן","dt":"תרל - בערך","b":"רב ודיין בווהראן, אצל ר מסעוד דרמון. הסכים על \"פתח הבית\" לר אברהם בלעיש. משורר וחיבר שיר \"מי כמוכה\" לפרסום נס הצלת יהודי ווהראן מהמון ערבי - ונדפס בסידור \"בית מנוחה\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":34957,"n":"סנאניס, אברהם מטיטואן","b":"מחכמי טיטואן-שנות ה-ת' בזמן ר חסדאי אלמושנינו, ור דוד הכהן.","s":"מלכי רבנן"},{"i":34958,"n":"סנאניס, יהודה מטיטואן","b":"מחכמי טיטואן, חתם על פס\"ד-תפו עם ר מרדכי בן עזר.","s":"מלכי רבנן"},{"i":34959,"n":"סנאניס, עקיבא מטנג'יר","b":"רב בטנג'יר-תרפא, חתם-תרסב עם ר אליהו אלמליח בעל \"בקע לגולגולת\".","s":"מתוך קטלוג"},{"i":34960,"n":"סנאניס, שלום מאלגיר","bt":"תקס","dt":"תרל - בערך","b":"רב באלגיר, עלה לצפת-תקפח. בשליחות צפת-תרו.","s":"מלכי ישורון-חכמי אלגיר"},{"i":34961,"n":"סנאק, צבי הירש מפוזנא","b":"חריף,רב בפוזנא-תק\"פ","s":"אוצר הרבנים 17391"},{"i":34962,"n":"סנגוניטי, יהודה","f":"עזריה","s":"מתוך קטלוג"},{"i":34963,"n":"סנגוניטי, יצחק ברכיה","f":"יחיאל מריגיו","k":"בעל שיח יצחק","bt":"תקה","bp":"ריגיו","b":"תלמיד ר שמשון נחמני מריגיו בעל תולדות שמשון. רב בוירצילי. תלמידו - ר זכריה דוד שבתי סגרי. חיבר \"מלך ביופיו\" ועוד.","s":"ארזי הלבנון"},{"i":34964,"n":"סנגוניטי, מאיר מפירנצי","b":"רב בפירנצי-תקמד.","s":"ארזי הלבנון"},{"i":34965,"n":"סנגוניטי, עזריה חיים ממודנא","k":"בעל עולה חדשה","b":"רב במודנא-איטליה, על מקום ר מזל טוב מדינה. תלמיד ר ישמעאל הכהן, והו\"ל ספר רבו בשם \"שפת אמת\". אירח את החיד\"א ואת בנו בשהותם במודנא ונזכר ב\"מעגל טוב\". חיבר \"עולה חדשה\" ועוד. בנו - ר יהודה.","s":"איטליה גירונדי-ע ו ח; ארזי הלבנון"},{"i":34966,"n":"סנגוניטי, שבתי אלחנן מפיררה","b":"רב בפיררה-תנח. פסק ממנו ב\"פחד יצחק\". היה מחלוקת על נישואי מעוברת ואסר כנגד הרב ברוך קזיס ואחרים מרבני מנטובה.","s":"איטליה גירונדי-ש ב; אוצר הרבנים 2012"},{"i":34967,"n":"סנגוניטי, שלמה חיים ממודנא","b":"גביר במודנא, מתומכיו של ר חיים ן עטר בעל אור החיים.","s":"מתוך קטלוג"},{"i":34968,"n":"סנגוניטי, שמואל מירושלים","f":"אברהם ישמעאל","bt":"תקד - אחרי","bp":"ירושלים","b":"מחכמי ירושלים, בשנת תקמד בשליחות בליוורנו ופגש שם את החידא, בשנת תקסב בשליחות בטריפולי ובשנת תקסה בהיותו באלגיר נשדד בזמן הפרעות. הדפיס חדושי המאירי לשבת ליוורנו תקנד.","s":"גליס"},{"i":34969,"n":"סנגוניטי, שמשון אפרים חיים","b":"רב באיטליה-תרז. תלמידו - ר אליעזר מזל טוב... ן יחיא - סופר במודנא.","s":"מתוך קטלוג"},{"i":34970,"n":"סנגרי, יצחק","dt":"צופוט-קאלע","b":"לדעת ר שם טוב בעל האמונות, הוא החבר שעליו כותב ר יהודה הלוי בספר הכוזרי - שהביא את דבר היהדות לממלכת הכוזרים.","s":"פין-כנסת ישראל"},{"i":34971,"n":"סנדברג, יצחק מרדכי","b":"חתן ר אליעזר ישעיה איליביצקי מטעלחאן. נסמך מאת: ר יצבי הירש רבינוביץ מקובנא, ר משה דנישבסקי מסלובודקא. דיין אצל חותנו בטעלחאן.","s":"אהלי שם"},{"i":34972,"n":"סנדברג, יצחק מתתיהו","f":"משה מרדכי מקוברין","b":"נכד-מצד אמו ר אברהם מסלונים. חתן ר מאיר מארים שאפיט מקוברין.","s":"אלפסי"},{"i":34973,"n":"סנדהויז, זאב וולף מקולבטוב","b":"תלמיד ר זאב וולף מפשוורסק. מחכמי קולבטוב-תריב. נזכר ב\"שואל ומשיב\", ועוד. ידידו של ר שמואל אהרן רובין.","s":"וונדר-גליציה ח\"ד"},{"i":34974,"n":"סנדומירסקי, אשר","b":"רב באוני,דרגובה,עלה לא\"י-תרצ\"ב","s":"אוצר הרבנים 3509"},{"i":34975,"n":"סנדורי, חיים הלוי ממצרים","b":"רב הכולל בקהיר-מצרים-תקיג.","s":"אוצר הרבנים 6098; ארזי הלבנון"},{"i":34976,"n":"סנדיקובסקי, נח מראסאווא","f":"ישראל פאליק","b":"רב בראסובה(=ראסאווא)-פלך קיוב-תרס. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי, האדמור רש\"ב מלובאביץ. הניח חבורים בכת\"י.","s":"אוצר הרבנים 15815; אהלי שם"},{"i":34977,"n":"סנדלוביץ, נחום בן ציון מארה\"ב","f":"שמואל מאיר מויניטא","bp":"ויניטא-פלך קובנא","b":"חתן ר חיים צבי וינברג מטאוויאן בעל \"ברכת חיים\". רב בטייוואן(=טאוויאן)-פלך קובנא-תרסא, היגר לארה\"ב וכיהן כרב בדנוור-ארה\"ב-תרסז.","s":"אוצר הרבנים 15907; אהלי שם"},{"i":34978,"n":"סנדלסון, יחיאל מאיר מאנגליה","f":"אלעזר","bt":"תרכב","dt":"תרצה - ט ניסן","b":"תלמיד ישיבת סלונים, מינסק, וולוזין וכונה \"המתמיד מעיר מוש\", וילנא אצל ר אליהו אליעזר ור שמואל ליבצער. נסמך מאת: ר שלמה הכהן מוילנא, ר יצחק אלחנן מקובנא, ר יצחק מאיר מסלובודקא. רב בפרירושלא-תרמו, נאווידוואר-תרנו, ניו קסטל-אנגליה-תרנח. הניח חבור בהלכה ואגדה.","s":"אוצר הרבנים 9228; אהלי שם"},{"i":34979,"n":"סנדלר, אברהם אליהו","bt":"1857","bp":"וילקוביסק","dt":"1928","b":"תלמיד ישיבה בליטא. בגיל 16 היה עוזר למלמד. יסד חדר מתוקן בוירבאלן-ליטא - ובין המורים שם ש.ל. גורדון, ואח\"כ מורה בגימנסיה העברית בוירבאלן. חיבר ספר בדקדוק, ופרסם מאמרים בעתוני התקופה.","s":"ליטא"},{"i":34980,"n":"סנדלר, אליהו מקאניוב","f":"יוסף","bt":"תרלח","b":"רב בקאניוב-פלך קיוב-תרסט.","s":"אוצר הרבנים 2164; אהלי שם"},{"i":34981,"n":"סנדלר, אלעזר מקולומיאה","b":"רב בקולומיאה.","s":"וונדר-גליציה ח\"ד"},{"i":34982,"n":"סנדלר, שלמה מארה\"ב","k":"בעל אמרי בינה","b":"מחכמי ארה\"ב. חיבר \"אמרי בינה\" נ\"י תרעד.","s":"אמריקה"},{"i":34983,"n":"סנדמירסקי, נחמן מהאלוסק","b":"תלמיד הסבא מסלובודקא. ר\"מ בישיבת הלוסק אצל ר ברוך בר ליבוביץ, ומשגיח על מקום ר אברהם נח פלאיי - שעבר לישיבת שקלוב.","s":"מתוך קטלוג"},{"i":34984,"n":"סנדר","b":"רב בלעסלא,פרנס ומנהיג בקורוטשין","s":"אוצר הרבנים 16511"},{"i":34985,"n":"סנדר","f":"פנחס","b":"רב בחורחוב","s":"אוצר הרבנים 16513"},{"i":34986,"n":"סנדר","b":"רב ברכניץ-תק\"צ","s":"אוצר הרבנים 16515"},{"i":34987,"n":"סנדר ר\"י מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז.","s":"עיר וילנא ח\"א"},{"i":34988,"n":"סנדר, יצחק מארה\"ב","b":"ר\"מ בישיבת בית מדרש לתורה בשיקגו. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\".","s":"אוצר כתבי עת-לוין"},{"i":34989,"n":"סנדר. שר המלחמה","bp":"דעסוי","b":"נדד באמריקה, אפריקה, שר המלחמה של הקיסר טהעארד באפריקה ולחם באנגלים במאגדאלה, נפל בשבי האנגלים-1861.","s":"פין-כנסת ישראל"},{"i":34990,"n":"סנדרוביץ, אברהם אבא יעקב","f":"דוד שלמה","dt":"תרסה - טבת","dp":"ירושלים","b":"אב\"ד פריראשלא, עלה לירושלים וכיהן כדיין, גבאי ועסקן. נזכר בשו\"ת \"בני ציון\" יא בשנת תרל, והסכים בספר \"זכרון תנחום\". פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"גליס; שם הגדולים השלישי; אוצר כתבי עת-לוין"},{"i":34991,"n":"סנדרוביץ, יעקב חיים מקרמניץ","f":"ישראל","bt":"תרלה","b":"רב בקרמניץ-ווהלין-תרסז.","s":"אוצר הרבנים 10072; אהלי שם"},{"i":34992,"n":"סנדרס, צבי אריה מקליבלנד","k":"בעל מקומן של זבחים","b":"רב בקליבלנד-ארה\"ב.","s":"אמריקה"},{"i":34993,"n":"סנה ן, שמואל צרצה מספרד","k":"אבן סנה-בעל מקור חיי","b":"פילוסוף, מחכמי ולנסיה-ספרד-קי. חיבר \"מקור חיים\", \"טהרת הקדש\", \"צרור המור\", \"מכלל יופי\", ועוד.","s":"אוצר הרבנים 19353; ארזי הלבנון"},{"i":34994,"n":"סנהדראי, ישראל","f":"משה סנדרוביץ","bt":"תרע","bp":"פרוסקורוב","b":"רב ביברוב, למברג. עלה לארץ-תרצו. רב צבאי בצבא הבריטי במלחמת העולם השניה.","s":"וונדר-גליציה ח\"ד"},{"i":34995,"n":"סנחני, שלמה מתימן","b":"רב בכפר צייח - מחוז אנס - תימן. מקובל ומלוב\"ן.","s":"ארזי הלבנון"},{"i":34996,"n":"סנטא, מאיר","f":"אברהם יהודה פרייש","dt":"תקצא - כז תשרי","b":"רב בקניזשא","s":"אוצר הרבנים 12918"},{"i":34997,"n":"סנטאר, שם טוב מספרד","b":"מתרגם ומשורר מחכמי ספרד. תרגם ספרים מערבית לעברית.","s":"ארזי הלבנון"},{"i":34998,"n":"סנטר, בנימין בינם מחירוב","b":"מחכמי חירוב-תריד.","s":"וונדר-גליציה ח\"ד"},{"i":34999,"n":"סניג, שמואל אבא מליטא","bp":"ראקישוק","b":"רב צבאי בליטא, ניצל מהשואה ואחריה יו\"ר ועדת הרבנים באזור האמריקאי בגרמניה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה.","s":"ליטא; אוצר כתבי עת-לוין"},{"i":35000,"n":"סנידרס, ?? מג'יור-הונגריה","b":"רב הקהלה האורטודוכסית בג'יור, ובנו ר בן ציון על מקומו אחריו-תרסו.","s":"הונגריה"},{"i":35001,"n":"סנידרס, בן ציון מג'יור-הונגריה","b":"רב הקהלה האורטודוכסית בג'יור על מקום אביו-תרסו.","s":"הונגריה"},{"i":35002,"n":"סנידרס, בן ציון מראב","f":"יעקב מראב","bt":"תרלה","bp":"ראב","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר דוד פרידמן מצעהלים-הונגריה ועבר לשם. רב ביאקא-תרסב, ראב-תרסד על מקום אביו. מתורתו ב\"זכר זאת ליעקב\". מזקני המשתתפים בכנס בוגרי הישיבה - פרשבורג תרץ.","s":"אוצר הרבנים 3927; החת\"ס ותלמידיו; פרשבורג-וינגרטן; אהלי שם"},{"i":35003,"n":"סנידרס, יעקב מפרשבורג","b":"מג\"מ בחברה \"אוהבי תורה\" בפרשבורג על מקום ר יהודה ליב רובינשטין. ניצל מהשואה ועבר לשוייץ.","s":"פרשבורג-וינגרטן"},{"i":35004,"n":"סנידרס, יעקב מקיש-קערש","b":"רב בקיש-קערש. ניצל מהשואה, ואחריה רב בברזיל. פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה.","s":"הונגריה; אוצר כתבי עת-לוין"},{"i":35005,"n":"סנידרס, יעקב מראב","f":"מרדכי מאמשטרדם","bt":"תקצג","bp":"אמשטרדם","dt":"תרס-ד - ה אב","dp":"ראב","b":"תלמיד הכת\"ס, ור אברהם וקסלר משוואבאך ור יצחק דב במברגר מוירצבורג. רב ביערגין-תרכא, מגנדורף, ראב-תרלב ובנו ר בנציון על מקומו אחריו.","s":"אוצר הרבנים 9798; החת\"ס ותלמידיו"},{"i":35006,"n":"סניפישקי, שמואל","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":35007,"n":"סנפיר, גדליה","f":"יעקב קופשטין","dt":"תשד","b":"רב בניאמצין-תרצ\"ד","s":"אוצר הרבנים 4345"},{"i":35008,"n":"סנקביץ, יעקב חנוך מירושלים","bt":"תרנה","dt":"תשיז - ט תשרי","b":"ר\"מ בישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ. עורך \"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\".","s":"אוצר הרבנים 10078; אוצר כתבי עת-לוין"},{"i":35009,"n":"ססובר, אליעזר ליבר מקימנקא","f":"צבי אריה הכהן","bt":"תקסג","bp":"קמינקא","dt":"תרמט","b":"רב בקמינקא. רבם של בני השם שלום מבלז. עלה לירושלים-תרל. חתם על איסור השקאלעס-תרלג. בזיוו\"ש נשא את לאה מפינסק שתרגמה את תפלה זכה ללשון אשכנז ונדפסה בתרנא. נכדו - ר ברוך מרדכי כהן ססובר.","s":"וונדר-גליציה ח\"ד"},{"i":35010,"n":"ססובר, בנימין חיים מירושלים","f":"אליעזר ליבר מקמינקא","bt":"תרל","bp":"ירושלים","dt":"תשא","b":"ממונה בכולל גליציה וגבאי החברא קדישא של הכולל. עסקן והתקין תאורה בכותל-תרעז.","s":"וונדר-גליציה ח\"ד"},{"i":35011,"n":"ססובר, ברוך מרדכי הכהן","f":"בנימין חיים","bt":"תרפה","bp":"ירושלים","dt":"תשנא","b":"פרסם בכתבי עת שונים. חוקר במוסד הרב קוק. מראשוני מפעל הביבליוגרפיה העברית. מפרש המחזור המבואר.","s":"וונדר-גליציה ח\"ו"},{"i":35012,"n":"סעאדה, אברהם","b":"דיין בנאבל-תקמ\"ח","s":"ארזי הלבנון"},{"i":35013,"n":"סעדה, חי מלוב","bt":"תרס","dt":"תשל - בערך","b":"רב בבנגאזי, וכיהן כדיין-תשב - תשך.","s":"מלכי חי\"ל-מרציאנו"},{"i":35014,"n":"סעדה, יעקב מטריפולי","bt":"תקל","dt":"תר - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":35015,"n":"סעדה, מסעוד מטריפולי","bt":"תן","dt":"תקך - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד בטריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":35016,"n":"סעדוד, שלום מתימן","b":"מחכמי שרפה-תימן - בתחילת המאה ה-20.","s":"ארזי הלבנון"},{"i":35017,"n":"סעדוה מתימן","f":"מעודד בן סעדיה","b":"סופר מחכמי תימן-תרב.","s":"מתוך קטלוג"},{"i":35018,"n":"סעדון, אברהם מאלגיר","b":"נגיד בתלמסאן, מקורב למלכות והיה מעין משנה למלך. עסק בפדיון שבויים בזמן גירוש ספרד, ותמך במגורשים שהגיעו לתלמסאן, ובהם ר אברהם זכות שהגיע לתלמסאן וחיבר לבקשתו חיבור על גאולת ישראל בשם \"מאמר על הקץ\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":35019,"n":"סעדון, אהרן","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","s":"אוצר כתבי עת-לוין"},{"i":35020,"n":"סעדון, בוגיד מגרבה","b":"הו\"ל \"כתר תורה\" - גרבה תרצח - ירחון תורני מחכמי אפריקה הצפונית. פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":35021,"n":"סעדון, דוד","f":"פינחס","b":"רב בכפר טוזר(תונס)","s":"ארזי הלבנון"},{"i":35022,"n":"סעדון, דוד ממראקש","b":"מו\"ץ במראקש, חתם על אגרת ניחומים לפטרית היעב\"ץ-תקיג.","s":"ארזי הלבנון; מלכי רבנן"},{"i":35023,"n":"סעדון, חי מאלגיר","dt":"תרלד - חשון","b":"רב בתונס, עבר לאלגיר, רב ודיין בסטיף-אלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35024,"n":"סעדון, יהודה מאלגיר","b":"תלמיד ר אפרים אנקאווא. רב בתלמסאן. ציון קברו נחשב לקדוש. עליו ב\"תולדות תלמסאן\" בצרפתית מאת ר' א' מאייר - פאריס 1902.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":35025,"n":"סעדון, יהודה מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון.","s":"טולדנו-נר המערב"},{"i":35026,"n":"סעדון, יום טוב מגיברלטר","b":"מחכמי גיברלטר, חתם על פס\"ד-תצט עם ר שלמה ן עמארא.","s":"מלכי רבנן"},{"i":35027,"n":"סעדון, יום טוב ממרוקו","f":"עמור","b":"מחכמי מרוקו, חתם על פס\"ד-תקל עם ר מנחם גיגי.","s":"מלכי רבנן"},{"i":35028,"n":"סעדון, יוסף מטיטואן","b":"מחכמי טיטואן-שנות ה-תק'.","s":"מלכי רבנן"},{"i":35029,"n":"סעדון, יוסף ממראקש","f":"דוד","b":"מו\"ץ במראקש, חתם על פס\"ד-תקי עם ר דוד מאמאן, ר יעקב פינטו.","s":"מלכי רבנן"},{"i":35030,"n":"סעדון, יוסף מפאס","b":"מחכמי פאס, חתם על פס\"ד-תצז אחרי הרבנים ר שלם אדרעי, ר יעקב ן מלכא, ר שמואל אלבאז.","s":"מלכי רבנן"},{"i":35031,"n":"סעדון, יעקב ממראקש","f":"דוד","b":"מו\"ץ במראקש, עם ר דוד בנבנישתי, חתם על פס\"ד-תסט. נזכר ב\"משפט וצבי\".","s":"מלכי רבנן"},{"i":35032,"n":"סעדון, יעקב מסאלי","b":"מחכמי סאלי-מרוקו-שנות ה-ת', מראשי השבתאים, וחזר בו-תל.","s":"מלכי רבנן; רוזניס-תורכיה-ד; טולדנו-נר המערב"},{"i":35033,"n":"סעדון, יעקב מפאס","b":"מחכמי פאס-תקו, נזכר אצל היעב\"ץ.","s":"מלכי רבנן"},{"i":35034,"n":"סעדון, יעקב מפאס","b":"מראשי קהלת פאס, נאסר-תקן בידי המושל אליזיד בענין עזבון ר מרדכי אשריקי, יחד עם בנימין בן שמחון.","s":"טולדנו-נר המערב"},{"i":35035,"n":"סעדון, ישועה מאלגיר","f":"מימון בן סעדון","dt":"רס - יט תמוז","b":"רב בתלמסאן.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35036,"n":"סעדון, ישכר ממרוקו","b":"רב בפאס-תרם."},{"i":35037,"n":"סעדון, מנחם מפאס","b":"מחכמי פאס.","s":"מלכי רבנן"},{"i":35038,"n":"סעדון, מסעוד מפאס","k":"בן קציץ","dt":"תרא - אחרי","b":"מחכמי פאס, חתם-תקסא על שטר.","s":"מלכי רבנן"},{"i":35039,"n":"סעדון, מקיקץ דוד מג'רבה","k":"בעל חגי דוד","bt":"תרסא","bp":"ג'רבא","dt":"תשמט - טו סיון","dp":"ירושלים","b":"תלמיד ר רחמים חי חיותה הכהן, ומהרד\"ך מג'רבא. מחכמי ג'רבא, עלה לירושלים. פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":35040,"n":"סעדון, סעדיה מאלגיר","bt":"תרל - בערך","dt":"תש","b":"רב במוחמדיה(=פיריגו)-אלגיר. תלמיד ר חיים בלייח.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":35041,"n":"סעדון, סעדיה מפאס","b":"מחכמי פאס-תקעט.","s":"מלכי רבנן"},{"i":35042,"n":"סעדון, פנחס הזקן","k":"בעל פסקי הרא\"ש","bp":"ג'רבא","dt":"תרנו - לפני","b":"רב בתונס, ואב\"ד בכפר טוזר. חיבר גם \"שרי המאה\", ובנו ר יהודה הו\"ל את ספרו.","s":"ארזי הלבנון"},{"i":35043,"n":"סעדון, שמואל מפאס","f":"שמעון-כתונת תשב\"ץ","b":"סופר בי\"ד מחכמי פאס-תכח או תצה.","s":"מלכי רבנן"},{"i":35044,"n":"סעדון, שמעון מפאס - הזקן","f":"סעדיה","k":"בעל כתונת תשב\"ץ","b":"מחכמי פאס בשנות ה-ת'. חיבר ספר דרשות על התורה \"כתונת תשב\"ץ\" בכת\"י.","s":"ארזי הלבנון; מלכי רבנן"},{"i":35045,"n":"סעדון, שמעון מפאס - הנכד","k":"בעל כתונת תשבץ","b":"נכד ר שמעון הראשון. מחכמי פאס.","s":"מלכי רבנן"},{"i":35046,"n":"סעדי מיכאל משלוניקי","b":"דיין בשלוניקי-תרג.","s":"זכרון שלוניקי-140"},{"i":35047,"n":"סעדיה","dt":"שלו - כח אלול","b":"מקובל","s":"אוצר הרבנים 16523"},{"i":35048,"n":"סעדיה","f":"ישראל","b":"מחכמי ירושלים בתקופת הגאונים.","s":"גליס"},{"i":35049,"n":"סעדיה (מבעלי התוספות)","b":"מחכמי צרפת, עלה בשנת ד'תתקעא (1211) יחד עם ר יונתן מלוניל ו-300 בעלי התוספות. פגש את ר יהודה אלחריזי באשקלון.","s":"גליס"},{"i":35050,"n":"סעדיה גאון פיומי","k":"בעל אמונות ודעות","bt":"ד'תרנב (892)","bp":"פיום-מצרים","dt":"ד'תשב (942)","dp":"בגדד","b":"מגדולי דור הגאונים. נולד במצרים, עבר לארץ ישראל, חלב, בגדד. ראה ישיבת סורא, היה במחלוקת עם ראש הגולה דוד בן זכאי ונאלץ לפרוש מכהונתו אולם בהמשך חזר לכהונתו. חיבר פירושים ותרגומים לתנך, ועוד.","s":"ארזי הלבנון"},{"i":35051,"n":"סעדיה החברוני","f":"אברהם","b":"מחכמי חברון בתקופת הגאונים.","s":"גליס"},{"i":35052,"n":"סעדיה הלוי מקושטא","b":"שו\"ב ודיין בקושטא-תטו.","s":"רוזניס-תורכיה-ד"},{"i":35053,"n":"סעדיה מוילנא וירושלים","f":"נתן נטע","bp":"ליטא","dt":"תקעג - כה אב","dp":"ירושלים","b":"מתלמידי הגר\"א, גבאי בקלויז הגר\"א בוילנא. בשנת תקנח עלה לצפת בשיירת העולים השניה, עבר לירושלים. ר סעדיה רשם את הנהגות הגרא, ובנו ר נתן נטע שלח אותם לר ישכר בר בעל \"מעשה רב\" שהוסיפם לספרו.","s":"גליס; אוצר הרבנים 16522; עיר וילנא ח\"א; שא\"י"},{"i":35054,"n":"סעדיה מירושלים","f":"אחוילי","k":"בעל גולת הכותרת","b":"סופר מחכמי ירושלים-שנות ה-תק'. נזכר בספר \"האורב\".","s":"פרומקין-תח\"י"},{"i":35055,"n":"סעדיה מלוב","f":"משה","b":"רב בלוב. עליו ב\"גנזים\" ת\"א תשכט.","s":"מלכי חי\"ל-מרציאנו"},{"i":35056,"n":"סעדיה ממרוקו","f":"יהודה בן אביתר","b":"מחכמי מרוקו הקדומים, העתיק את סידור ר שלמה אלסגלסאסי. בנו - ר עמרם.","s":"טולדנו-נר המערב"},{"i":35057,"n":"סעדיה מסיציליה וספרד","f":"יצחק","bp":"סיציליה","b":"ברח מסגלמסה-מרוקו ועבר לאיטליה, והיה שם תלמיד ר אברהם אבולעפיה.","s":"ארזי הלבנון; טולדנו-נר המערב"},{"i":35058,"n":"סעדיה מפרס","f":"שלום אריה","b":"רב בפרס (טהרן?)-תרפח.","s":"מתוך קטלוג"},{"i":35059,"n":"סעדיה משקלוב מלובלין","f":"יהודה ליב","dt":"תקסא - יג טבת","dp":"לובלין","b":"מחכמי וחשובי קהילת לובלין. חתם על חרם ר שאול מרגליות שלא להוסיף מנינים חדשים בלובלין.","s":"לקורות היהודים בלובלין"},{"i":35060,"n":"סעדיה מתילית-מרוקו","f":"מסעוד בן דוד ויוסף","b":"מחכמי תילית-מרוקו, חתם-תרס בערך על תקנה של השד\"ר ר מסעוד אדהאן.","s":"מתוך קטלוג"},{"i":35061,"n":"סעדיה מתימן","f":"עוואץ בן אור","k":"בעל ארזי אל","bt":"תרעד","bp":"תימן","dt":"תשנז - ה אד\"א","dp":"רעננה","b":"מחכמי תימן, עלה לארץ-תשי והתישב ברעננה. חיבר גם \"מחמדי אל\", ועוד.","s":"ארזי הלבנון"},{"i":35062,"n":"סעדיה שאול","dt":"ת' - אחרי","dp":"יון","b":"מחכמי ירושלים, בשנת ת' בשליחות ביון, ונהרג בדרך בין שלוניקי לשירון, בית הדין של שלוניקי קיים דיון בנושא התרת עגינותה של אשתו.","s":"גליס; שא\"י"},{"i":35063,"n":"סעוואדין, בוגיד מג'רבה","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד.","s":"אוצר כתבי עת-לוין"},{"i":35064,"n":"סעיד ן, יעקב מתאפילאת","b":"מחכמי תאפילאלת-שנות ה-ת', תאזא-מרוקו, היה מחלוקת כנגדו מר יצחק ביבאס בענין הנפיחה.","s":"מלכי רבנן"},{"i":35065,"n":"סעיד ן, מיכאל","k":"בעל קול קורא","bt":"תריב","dt":"תרפח","b":"רב בווהראן(=אוראן)-אלגיר-תרן, ודיין-תרעז. נתבקש לבדוק כל רב או שד\"ר המגיע לווהראן לערוך מגבית - כדי לדעת את גדלותו בתורה. הו\"ל קול קורא בענין מצות ברית מילה - ווהראן תרנד. הסכים על \"קרית חנ\"א\" לר ח' ח' אזולאי, ועוד.","s":"אוצר הרבנים 13137; מלכי ישורון-חכמי אלגיר"},{"i":35066,"n":"סעיד, חסן","f":"שלום","k":"בעל חק נאמן","b":"חכם בצ'אלע(תימן),חיבר \"חק נאמן\" פירושים לתורה ע\"פ הסוד","s":"ארזי הלבנון"},{"i":35067,"n":"סעיד, יום טוב מאלגיר","f":"יוסף","bt":"קע","dt":"רמ - בערך","b":"רב במאזונה(=מג'אנה, מזאנא)-אלגיר. נזכר אצל הרשב\"ש המשבחו אך גם מבקרו.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35068,"n":"סעיד, יוסף מאלגיר","bt":"קל","dt":"ר - בערך","b":"רב בברשך-אלגיר. התכתב עם הרשב\"ץ.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35069,"n":"סעידו ן, שלמה","f":"ישועה בן שמואל","b":"נזכר בשטר כתובה-תקלו.","s":"ארזי הלבנון"},{"i":35070,"n":"סעניער, אברהם אבא מארה\"ב","f":"צבי","b":"סופר ומתרגם, מתלמידי אברהם מאפו ומהשורר י\"ל גורדון.","s":"אנשי השם בארהב-איזנשטט"},{"i":35071,"n":"סעקולא, אנשיל","b":"פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט.","s":"אוצר כתבי עת-לוין"},{"i":35072,"n":"סעקולא, ישראל ירחמיאל מסדובנא","f":"יצחק יוסף","k":"אדמור מאלכסנדר ארה\"ב","bp":"סובלוב","b":"נינו של ר שרגא פיבל מגריצא אבי שושלת אלכסנדר. תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא. ניצל מהשואה ואחריה היגר לארה\"ב וכיהן כאדמור מאלכסנדר בארה\"ב.","s":"אלפסי; אוצר כתבי עת-לוין"},{"i":35073,"n":"סער, משה","dt":"תשג","b":"דומ\"צ בסטוטשין","s":"אוצר הרבנים 14979"},{"i":35074,"n":"ספורנו, הושעיה","f":"ניסים יצחק","b":"מחכמי מנטובה-שפ\"ב","s":"ארזי הלבנון"},{"i":35075,"n":"ספורנו, חננאל","b":"אחיו של ר עובדיה ספורנו. הוזכר ב\"באר עשק\".","s":"איטליה גירונדי-ח טו"},{"i":35076,"n":"ספורנו, חננאל","f":"ישראל","b":"למד בישיבת מהרשד\"ם בשאלוניקי,עבר לקושטא,מנטובה,רבה של רומא-שע\"ז-שע\"ט","s":"ארזי הלבנון"},{"i":35077,"n":"ספורנו, יהודה","b":"מרבני מנטובה","s":"ארזי הלבנון"},{"i":35078,"n":"ספורנו, ישראל מויאדנה-איטליה","f":"יהודה","b":"רב בויאדנה-איטליה בשנות ה-ש. אחיו של ר נסים יצחק.","s":"ארזי הלבנון"},{"i":35079,"n":"ספורנו, נסים יצחק ממנטובה","f":"יהודה","b":"רב במנטובה-שמה. היה במחלוקת עם ר דוד מהטוב על דרשותיו.","s":"ארזי הלבנון"},{"i":35080,"n":"ספורנו, עובדיה מבולוניה","k":"בעל פירוש לתורה","bt":"1480","dt":"שי","b":"רב ורופא ברומא, בולוניה, ריגייו. מפרש התורה. אחיו - ר חננאל. חיבר \"אור עמים\" בלטינית ושלח ספר למלכי צרפת.","s":"איטליה גירונדי-ע יא יד; אוצר הרבנים 16547; יומא דהילולא","bk":[["ספורנו","מפרשי תורה"],["ספורנו [עה\"ת והמגילות",""],["על אבות]",""],["ביאורי הספורנו",""]],"e":"רל\"ח~-ש\"י~"},{"i":35081,"n":"ספורנו, עוזריאל מאיטליה","f":"משה","b":"מראשי קהלת דוכסות פארמה-תקיח עם ר אברהם מיכאל פונטאנילה.","s":"מתוך קטלוג"},{"i":35082,"n":"ספורנו, שלמה שמעיה מאיטליה","dt":"שעז - חשון","b":"רב בפדובה, ונציה בזמן ר אריה ממודנא המזכירו בספרו \"חיי יהודה\". תשובה ממנו בכת\"י-שנב.","s":"איטליה גירונדי-ש מז; ארזי הלבנון"},{"i":35083,"n":"ספיבק, ברוך מזנמינקא","f":"אברהם","bt":"תרמב","dt":"תשג","b":"רב בזמינקה-פלך חרסון-תרסג, דוקשט. נסמך מאת: ר שמואל פנחס מריואצק-פלך חרסון, האדמור ר דוד מזלוטופול.","s":"אוצר הרבנים 4127; אהלי שם"},{"i":35084,"n":"ספיבק, יוסף יעקב יצחק מאיזמאיל","f":"זאב הלוי","dt":"תרז - יב אב","b":"תלמיד ר משה צבי מסאווראן. רב בדוביסאר, איזמאיל-בסרביה-תקץ. נפטר ללא ילדים.","s":"אלפסי"},{"i":35085,"n":"ספיבק, משה מנחם מנדל מזיכלין","f":"אליעזר","bt":"תרמ","b":"נסמך מאת: ר יחיאל מיכל בעל \"ערוך השלחן\", ר יצחק פיגנבוים מוארשא, ר פתחיה הארנבלאס מוארשא. רב בזיכלין(=ציזשאוו)-פלך לומזה-תרסח.","s":"אוצר הרבנים 15564; אהלי שם"},{"i":35086,"n":"ספיבק, נפתלי מוישאגראד","b":"רב בוישאגראד. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג.","s":"אוצר כתבי עת-לוין"},{"i":35087,"n":"ספיבק, ר' ב'","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":35088,"n":"ספייזהנדלר, אברהם מארה\"ב","b":"עסקן ציוני בארה\"ב.","s":"אנשי השם בארהב-איזנשטט"},{"i":35089,"n":"ספינובר, יצחק משה","b":"רב בראחוב","s":"אוצר הרבנים 11449"},{"i":35090,"n":"ספיר, אהרן זלמן מלנצהוט","b":"רב בלנצהוט-תקנד.","s":"וונדר-גליציה ח\"ד"},{"i":35091,"n":"ספיר, אליהו מירושלים","bt":"תרכט","dt":"תרעא - אלול","b":"סופר, מורה ועסקן בירושלים."},{"i":35092,"n":"ספיר, אלעזר מלאסק","k":"בעל מעשה רקח","b":"חתן הצדיק ר הירש ניליס. דרשן, מ\"מ בלאסק, פלונסק. חיבר גם \"לבב חכמה\", \"אבן ספיר\". בנו - ר סיני.","s":"אוצר הרבנים 2898; עיר לאסק וחכמיה"},{"i":35093,"n":"ספיר, יהודה לייביש מהומאנא","k":"בעל שער יהודה","dt":"תרמב - יד טבת","b":"רב בהומאנא-תקפ\"ח","s":"אוצר הרבנים 7360"},{"i":35094,"n":"ספיר, יעקב הלוי מירושלים","f":"נתן","k":"בעל אבן ספיר","bt":"תקפב","bp":"וילנא","dt":"תרמ-ה - י תמוז","dp":"ירושלים","b":"עלה בילדותו-תקצג עם הוריו לצפת, נתייתם-תקצו ועבר לירושלים ולמד אצל ר ישראל משקלוב ור זונדל סלנט. בשנת תריח בשליחות להודו ואוסטרליה ואף עבר בתימן. חיבר \"אבן ספיר\" ליק תרכו. פרסם מאמרים ב\"הלבנון\", \"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"קול מחזיקי הדת\" - קלוזש תרפח, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז. חתנו - ר יחיאל בריל.","s":"גליס; אוצר הרבנים 9799; ליטא; פין-כנסת ישראל; פרומקין-תח\"י; אוצר כתבי עת-לוין; תדהר ב, גרייבסקי."},{"i":35095,"n":"ספיר, יעקב משה מסראטוב","f":"יצחק","k":"בעל תורת יעקב","bt":"תרכה","b":"רב בקענא-פלך וילנא-תרנא, סאראטוב(=סראטוב), עלה לארץ והתישב בפתח תקוה. בתו היתה בקיאה בתלמוד ובגיל 13 לימדה תלמיד בשכר, חתנו - ר אליעזר פופקא מביעלאויזש.","s":"אוצר הרבנים 10252; אהלי שם"},{"i":35096,"n":"ספיר, יצחק","b":"חסיד בלז. בעל אחוזה בשטרוויץ. השיא את שבעת בנותיו לגדולים בתורה.","s":"וונדר-גליציה ח\"ד"},{"i":35097,"n":"ספיר, יצחק איזיק (יהודה ליב)","f":"שרגא עזריה זוסיא","k":"בעל שרגא נפשי","bt":"תריח","dt":"תרצה","dp":"פתח תקוה","b":"נכד-אם אביו לאחותם של ר ישראל הלר בעל \"נחלת ישראל\", ר יחיאל בעל \"עמודי אור\", ואחיהם. חתן הגביר ר אלחנן ברקובסקי משאקי. תלמיד ישיבת טלז. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא. רב בוודלסק(=אדעלסק)-פלך גרודנא-תרמ, קוזניצא-פלך גרודנא-תרנב ואחר כך בראצקי-פלך סובאלק-תרסג, עלה לארץ ישראל וכיהן כרבה של פתח תקוה-תרפא. חיבר גם \"אלומת עלומים\", \"שרגא טובא\", ועוד. מאמר ממנו ב\"תבונה\" - ירושלים תשא-תשח - זכרונות על ר ישראל סלנטר.","s":"גליס; אוצר 11342,1969,11202; אוצר כתבי עת-לוין; אהלי שם"},{"i":35098,"n":"ספיר, ישראל אריה","dt":"תשכא","b":"ראב\"ד בפתח תקוה-תר\"פ","s":"אוצר הרבנים 12147"},{"i":35099,"n":"ספיר, מרדכי יוסף מזמוטשקיעלץ","dt":"תשג","b":"רב בזאמאטשקיעלץ. נספה בשואה.","s":"אוצר הרבנים 14188"},{"i":35100,"n":"ספיר, מרדכי יוסף מצאנז","f":"שמחה","bt":"תרל","bp":"טורנא","dt":"תרצו","b":"חתן ר חיים ישראל בארב. דיין בסטריזוב ובלימנוב, רב בצאנז. חתנו - ר בן ציון וסטרייך.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 14188"},{"i":35101,"n":"ספיר, סיני מוידאווע ובראזין","f":"אליעזר מלוסק","k":"בעל עולת חדש","dt":"תרלה - כז אב","b":"נכד ר איצק גאלדעס. תלמיד ר חננאל מלוטימורסק בלאסק. דרשן, רב בווידאווע, ברעזין. חיבר \"עולת חדש\" וארשא תרו, \"מנחת עני\" עם הקדמה מאחיו ר יצחק איצק אילנברג. היה מתנגד לחסידות אולם לעת זקנתו התקרב לאדמור בעל חדושי הרי\"ם. בנו - ר ישראל מאיר מברעזין, חתניו - ר זאב וולף הכהן מוטשין (אביו של הגביר ר ישכר שעפס מלודז), ר זאב נחמיה הלוי.","s":"אוצר הרבנים 16506(16516); עיר לאסק וחכמיה"},{"i":35102,"n":"ספיר, עקיבא מגעבע","dt":"תרצד - תשד","b":"תלמיד השב\"ס, ור שמואל דוד יונגרייז מפעהר-ירמוט. גביר מחכמי געבע וחבר הועד המרכזי של הקהלות האורטודוכסיות בהונגריה.","s":"החת\"ס ותלמידיו; ברוין-אנשי מופת"},{"i":35103,"n":"ספיר, שאול מארה\"ב","k":"בעל דער באלעבעסל","bt":"1893","bp":"וילנא","b":"היגר לארה\"ב. עורך ב\"מארגן ז'ורנאל\", \"ג'ואיש אמעריקאן\". חיבר ספורים היסטוריים באידיש ובהם \"דער קאליף פון קארדאווא, ועוד.","s":"ליטא"},{"i":35104,"n":"ספירנגר, מרדכי אשר הלוי מבני","b":"רב בבני ברק, חתם-תשכג על בקשת עזרה מטעם הת\"ת של הסטייפלר.","s":"מתוך קטלוג"},{"i":35105,"n":"ספירשטין, נפתלי הכהן מפרושניץ","b":"רב בפרושניץ. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד.","s":"אוצר כתבי עת-לוין"},{"i":35106,"n":"ספקונה, משה","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":35107,"n":"ספקטור, אברהם אלחנן מענדזאב","bt":"תרנד","bp":"וונגרוב","dt":"כב טבת תשמה \\ תשמג","b":"חתן האדמור ר נפתלי שפיגל. מחשובי חסידי ברסלב (נסע לאומן-תרעט ולא יכל לחזור במשך שנתייים - בגלל הקומוניסטים), חזר לפולין וכיהן כאב\"ד אענדזאב(=ענדזייאב), לאחר שחותנו היגר לארה\"ב ביקש למנותו לאדמור על מקומו, הוא סירב וברח לביאליסטוק ושם למד בישיבת נוברדוק (עם הסטייפלר).","s":"מתוך קטלוג; אוצרות גליון 137, וגליון 185, נחלי נצח גליון 410","bk":[["גנזי אבא – מכתבים וחידושי תורה",""]]},{"i":35108,"n":"ספקטור, אהרן יהודה מקטירבורג","f":"צבי הלוי","bt":"תרלד","b":"רב בקרטיברג(=קאטירבארג)-ווהלין-תרנז.","s":"אוצר הרבנים 1803; אהלי שם"},{"i":35109,"n":"ספקטור, גרשון מהארידוק","f":"אברהם","bt":"תרכ","b":"רב בהארידק-וואהלין-תרן.","s":"אוצר הרבנים 4428; אהלי שם"},{"i":35110,"n":"ספקטור, יעקב דוד מירושלים","f":"ישראל איסר מרוסי","dt":"תרנט","dp":"ירושלים","b":"אחיו של ר יצחק אלחנן מקובנא. עלה לירושלים. חתניו: ר חיים דב קנטור, ר אברהם ברוידא ונכדו ר שמחה זיסל ראש ישיבת חברון.","s":"מתוך קטלוג"},{"i":35111,"n":"ספקטור, יצחק אלחנן מקובנא","f":"ישראל איסר מרוסי","k":"בעל נחל יצחק","r":"רב בקובנא","bt":"תקעו","bp":"רוסי-פלך גרודנא","dt":"תרנו - כא אדר","dp":"קובנא","b":"ראש הפוסקים בדורו. תלמיד ר בנימין דיסקין מלומזה, ור אליהו שיק מלידא. ישב בוולקוביסק, רב בזאבלין-תקצו, באראזא-תקצט ונאלץ לעזוב בלילה מחמת סירובם של בני הקהלה להפרד ממנו, נאסוויז-תרו ונאלץ גם כאן לעזוב בלילה, נוברדוק-תריא על מקום ר אלכסנדר זיסקינד הרכבי ור ברוך מרדכי ליפשיץ בעל \"ברית יעקב\" על מקומו אחריו, קובנה-תרכד ויסד שם את ישיבת הפרושים, ובנו ר צבי רבינוביץ על מקומו אחריו. בשנים תקצז-צט התיר לאכול קטניות בפסח בגלל הבצורת. התיר לעבוד בארץ בשנת השמיטה ע\"י נוכרים-תרמט. בזמן המחלוקת בוולוזין-תריז היה צעיר הבוררים. היה בורר בסכסוך בישיבת מיר-תרכח והצילה מחורבן. לקח על עצמו אחריות לכלל ישראל, וכך דאג להגשת עזרה ליהודי שטרסבורג-אחרי מלחמת פרוסיה צרפת, אסר על יהודי פרס להשתמש באתרוגי קורפו, סייע ליהודי קובנא-תרמב אחרי שריפה גדולה. באמצעות תלמידו פרופ' הרכבי המקורב לשלטון שיכנע את השלטון הרוסי למנות רבנים בועדה לעניני היהודים מטעם הממשלה, לפי הצעתו הגיש ר שמשון רפאל הירש תזכיר לנסיך פאלן-ראש הועדה ובו הסביר את הקשר שבין היהודים לתלמוד. התנגד לביהמ\"ד לרבנים בקובנא. תמך ביישוב הארץ. חבר בחברת מפיצי השכלה בפטרבורג. הסתייע בשתדלנותו באחים הגבירים לבית פרידלנד בפטרבורג, ובר בינוש כצנלסון בקיוב. בזמן גזירות הגירוש סייע לביטול הגזרה ממאות קהילות. עוד מבניו: ר חיים מקובנא, ר בנימין רבינוביץ מקובנא-נרצח בתרסו. פרסם מאמרים ב\"תבונה\" - ממל-קניגסברג תרכא.","s":"אוצר הרבנים 11249; ליטא; אוצר כתבי עת-לוין; פרוייקט השו\"ת; פרוייקט השו\"ת על שו\"ת באר יצחק; יומא דהילולא","bk":[["נחל יצחק","מפרשי שו\"ע"],["באר יצחק – שו\"ת",""],["עין יצחק – שו\"ת",""],["עין יצחק",""],["באר יצחק",""],["שו\"ת באר יצחק",""],["באר יצחק","שו\"ת - אחרונים"],["עין יצחק","שו\"ת - אחרונים"]],"e":"תקע\"ז-תרנ\"ו"},{"i":35112,"n":"ספקטור, ישראל איסר מראש","b":"רב בראש-תק\"צ","s":"אוצר הרבנים 12128; ברוורמן-אנשי שם"},{"i":35113,"n":"ספקטור, מרדכי מוארשא","k":"בעל דער אידישער מוזש","bt":"תריט","bp":"אומאן","b":"סופר אידי בוארשא. למד רוסית בילדותו מאחד משרי הצבא ברוסיה. חיבר \"א ראמאן אהן ליעבע\", עורך משנה ב\"פאלקס בלאט\" בפטרבורג-1884, מו\"ל \"הויזפריינד\" ו\"הפאמיליענפריינד\" בוארשא-1887. הו\"ל כ-50 ספורים גדולים וקטנים.","s":"דור וחכמיו-א\"ש-ו"},{"i":35114,"n":"ספקטור, משה מורחיבקה","b":"רב בוורחיבקה","s":"אוצר הרבנים 14980"},{"i":35115,"n":"ספקטור-רבינוביץ, חיים אריה מקו","f":"יצחק אלחנן ספקטור","dt":"תרלד - ב סיון","dp":"קובנא","b":"חתן ר יוסף פיימר מסלוצק וישב אצלו כמה שנים. עסק במסחר ואח\"כ כיהן כמו\"צ בקובנא. אחיו - ר צבי הירש-אב\"ד קובנא.","s":"מרקוביץ-נוברדוק; תולדות יצחק-ליפשיץ"},{"i":35116,"n":"ספרגר, ויליאם מניו יורק","bt":"1860","bp":"הונגריה","b":"תלמיד ביהמ\"ד לרבנים בבודפשט, וינה. היגר לאמריקה והיה ש\"ץ ב\"טמפל עמנואל\" בניו יורק. חיבר והדפיס מנגינות.","s":"דור וחכמיו-א\"ש-ו"},{"i":35117,"n":"ספרד, אברהם מקיניוב","f":"יעקב יוסף מאוסטרהא","k":"אדמור מקיניוב","dt":"תרל","b":"מצאצאי רב ייבי. אדמור בקיניוב-ליד אוסטרהא, והיה ראשון בשושלת עצמאית. בניו ר איזיק, ר נחמן חתן ר ברוך מפודואלטשיסק.","s":"אוצר הרבנים 73; אוסטרהא קצט; אלפסי"},{"i":35118,"n":"ספרד, אברהם פנחס מקיניוב ארה\"ב","f":"יעקב יוסף מקיניוב","k":"אדמור מקיניוב בארה\"ב","dt":"תשי - יז תמוז","b":"נכד רב ייבי. חתן ר מרדכי מלויאב (טשרנוביל). חיבר \"רב ייבי סבא\" - ובו מתורתו ומתורת אבותיו.","s":"אלפסי"},{"i":35119,"n":"ספרד, אליקים גץ מאוסטרהא","f":"יעקב יוסף מאוסטרהא","k":"אדמור מאוסטרהא","dt":"תרמה - כא אדר","b":"מצאצאי רב ייבי. חתן נכדת ר דוד פורקיס, ובזיוו\"ש חתן ר יוסף דוד מאליק. אדמור באוסטרהא.","s":"אוצר הרבנים 2768; אוסטרהא קצט; אלפסי"},{"i":35120,"n":"ספרד, אלתר מרדכי מאוסטרהא","f":"אליקים געץ מאוסטרהא","k":"אדמור מאוסטרהא","bt":"תריח","dt":"תרצה - יט תשרי","b":"חתן ר יוסף מברזנא (סטפין). אדמור באוסטרהא כ-50 שנה. בניו לא נהגו אדמורות.","s":"אלפסי; אוצר הרבנים 2973"},{"i":35121,"n":"ספרד, יעקב יוסף מאוסטרהא","f":"פנחס","dt":"תרט - כג תמוז","dp":"יאמפולא","b":"נכד רב ייבי. לאחר שנתייתם גדל אצל ר ברוך ממזבוז. אדמור באוסטרהא על מקום אביו וזקנו. נאסר בגלל הלשנה יחד עם ר אברהם מטריסק. חתנו ר אברהם דב מלכוביץ-נכד ר אברהם דב מחמלניק.","s":"אוצר הרבנים 10112; אלפסי"},{"i":35122,"n":"ספרד, יעקב יוסף מקיניוב","f":"אברהם מקיניוב","k":"אדמור מקיניוב באוסטר","b":"חתן ר מרדכי מלויאב (טשרנוביל). כיהן כאדמור מקיניוב באוסטרהא. נספה בשואה. בנו ר ליב חתן ר אלתר ישראל שמעון מנובומינסק (נסכיז).","s":"אלפסי"},{"i":35123,"n":"ספרידלאוור, יוסף","f":"משה","b":"אביו ר משה מפיסטין היה רב בסוירז שבגליציה ונהרג על קידוש השם. בנו ר יוסף כמו אביו, נחשב לאיש פרוש וקדוש. בנו היחיד ר יצחק מדרוהוביטש אביו של המגיד מזלוטשוב. אחרי פטירת אשתו יענטא שהייתה צדקת עלה ר יוסף לארץ, לאחר שלא הסתייע לו לעלות יחד עם הבעשט. שלח חומש לבנו ר יצחק ובו כתוב בכתב ידו.","s":"גליס; סורסקי \"דמויות הוד\" א,"},{"i":35124,"n":"ספרין, אברהם מרדכי מבוריסלב","f":"אליעזר צבי מקומרנא","k":"אדמור מבוריסלב","bt":"תרטו-ז","dt":"תשב - א כסלו","dp":"בוריסלב","b":"חתן ר חיים יעקב דומיניץ מניישטט. רב בדלטין, זסלב, אדמור בבוריסלב. נספה בשואה.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 1294; אלפסי"},{"i":35125,"n":"ספרין, אליעזר צבי","f":"מנחם מאניש מקומרנא","k":"אדמור מקומרנא ב\"ב","bt":"ה'תקצ","dt":"ה'תרנח","b":"אדמור מקומרנא בבני ברק על מקום אביו.","s":"אלפסי; היברובוקס","bk":[["דמשק אליעזר (קומרנא)",""],["אור עינים",""],["דמשק אליעזר",""]]},{"i":35126,"n":"ספרין, אליעזר צבי מוירשוב","f":"אברהם מרדכי מבוריסלב","k":"אדמור מווירשוב פבינץ","bt":"תרס","dt":"תש..","dp":"לודז","b":"אדמור בוירשוב ופביאניץ. נספה בשואה.","s":"וונדר-גליציה ח\"ד; אלפסי"},{"i":35127,"n":"ספרין, אליעזר צבי מקומרנא","f":"יצחק איזיק יהודה יח'","k":"אדמור מקומרנא","r":"האדמו\"ר מקאמרנא","bt":"תקץ","bp":"זידיטשוב","dt":"תרנח - כד אייר","b":"חתן הגביר ר יוסף שעהנר מטורקא. אדמור מקומרנא על מקום אביו. בנו ר יעקב משה על מקומו אחריו. חיבר \"אור עינים\" פרמישלא תרמב, \"בן ביתי\", ועוד.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 2724; אלפסי; עטרת שלום גליון ריז","bk":[["אור עינים - מפתחות לחכמת הקבלה",""],["בן ביתי - תהלים",""],["דמשק אליעזר - זוהר",""],["דמשק אליעזר - זוהר, אור עינים - מפתחות לחכמת הקבלה, בן ביתי - תהלים",""]]},{"i":35128,"n":"ספרין, אלכסנדר","f":"יצחק אייזיק ספרין","bt":"תקל","dt":"תקעח - כא אב","b":"מקובל","s":"אוצר הרבנים 2797","bk":[["זכרון דברים (קומרנא)",""]]},{"i":35129,"n":"ספרין, אלכסנדר סנדר מקומרנא","f":"יצחק איזיק יהודה יח'","bt":"תקפא","dt":"תריט","b":"חתן ר חיים משה מגריידינג (שושלת סטעפין). בנו ר משה חיים מאלטשטאט.","s":"וונדר-גליציה ח\"ו; אלפסי"},{"i":35130,"n":"ספרין, אלתר יצחק אלימלך","f":"חיים יעקב מקומרנא","k":"אדמור מקומרנא","bt":"תרפד","bp":"אונגוואר","b":"תלמיד ר יוסף אלימלך כהנא מקומרנא. היגר לארה\"ב-תרצט. תלמיד ישיבת תורה ודעת וחתן סופר. ר\"מ בישיבת מהרש\"ק-תשו. אדמור מקומרנא על מקום אביו. חתן ר הרש ליב ברנדוין מסטרטין-טורקא.","s":"וונדר-גליציה ח\"ו; אלפסי"},{"i":35131,"n":"ספרין, אלתר ישכר דב מאלטשטט","f":"משה חיים מאלטשטט","k":"אדמור מאלטשטט","bt":"תרלג","dt":"תשג - סיון","b":"אדמור באלטשטט על מקום אביו. חתן ר שמואל שמלקא רובין מסערט. נהג לנסוע כחסיד לשאר אדמורי קומרנא. נספה בשואה.","s":"וונדר-גליציה ח\"ד; אלפסי"},{"i":35132,"n":"ספרין, ברוך מקומרנא","f":"שלום מקומרנא","k":"אדמור מקומרנא","bt":"תרעג","bp":"סטולין","dt":"תשג - ז סיון","dp":"סמבור","b":"חתן דודו ר אליהו בומבך מאושפיצין. אדמור מקומרנא על מקום אביו וראש ישיבת \"בנין שלם\". סירב להימלט בזמן השואה וחילק את כל רכושו לעניים. נספה בשואה.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 4123; אלפסי"},{"i":35133,"n":"ספרין, זידא מדוברומיל","f":"מנחם מוניש מפלשטין","k":"אדמור מדוברומיל","b":"חתן ר יוסף ב\"ר דוד שפירא האדמור מדינוב. אדמור בדוברומיל על מקום אביו. בנו ר חיים מאיר יחיאל אב\"ד סאהל. פרסם מאמרים ב\"אחיאסף\" - סטריזוב תרפט.","s":"וונדר-גליציה ח\"ד; אלפסי; אוצר כתבי עת-לוין"},{"i":35134,"n":"ספרין, זידא משה חיים מקשישוביץ","f":"אברהם מרדכי מזלושיץ","k":"אדמור מקשישוביץ","dt":"תשג","b":"אדמור בקשישוביץ-ליד קראקא. נספה בשואה.","s":"אלפסי"},{"i":35135,"n":"ספרין, זידא צבי מפשמישל","f":"משה חיים מאלטשטט","k":"אדמור מפשמישל","dt":"תש - א תשרי","b":"חתן ר אלתר שלום דוד צוקרברג מקומרנא. אדמור בפשמישל. נספה בשואה.","s":"וונדר-גליציה ח\"ד; אוצר הרבנים 5706; אלפסי"},{"i":35136,"n":"ספרין, זלמן מסטניסלב","b":"מחכמי סטניסלב-תרמח.","s":"וונדר-גליציה ח\"ג"},{"i":35137,"n":"ספרין, חיים יעקב מקומרנא ונ\"י","f":"אברהם מרדכי מבוריסלב","k":"אדמור מקומרנא ני וים","r":"אדמו\"ר מקאמרנא","bt":"תרנב","bp":"קומורנא-גליציה","dt":"תשכט - ה סיון","dp":"ניו יורק","b":"חתן ר יצחק פלאם מקרוטושין. אדמור מבוריסלב קומרנא באונגוואר. היגר לניו יורק-תרצח וכיהן כאדמור מקומרנא. עלה לירושלים-תשכב וכיהן כאדמור מקומרנא. חיבר \"שבת שלום\" ירושלים תשל, \"בית אבות\", ועוד. עשרות מחבוריו - בכתב יד. בנו - ר צבי אלעזר הי\"ד - נספה בשואה.","s":"וונדר-גליציה ח\"ג ח\"ד; אוצר הרבנים 6399; אלפסי; אנשי שם-אמריקה; המבשר תורני גליון 286 עמודים טו - יז","bk":[["בית אבות - שבעת הרועים",""],["בית יעקב - חיבת ירושלים",""],["בית יעקב - סמיכות הפרשיות",""],["בית יעקב עיון יעקב ואגודת יעקב - אגדות הש\"ס",""],["ברכת אבות - אבות",""],["טועמיה חיים זכו - טעמי המקרא",""],["ישועת יעקב - חנוכה ופורים",""],["כתר לראשך - על תרי\"ג מצוות",""],["מה זאת - על ג' האותות",""],["פרי חיים ובית יעקב - על התורה ומועדים ותהילים והגדה של פסח",""],["קהילות יעקב - על כ\"ב אותיות",""],["שבת שלום ומבורך - רמזים במילת שב\"ת",""]]},{"i":35138,"n":"ספרין, חיים מאיר יחיאל מסאהל","f":"זידא מדוברומיל","bt":"תרסה","dt":"תשג","b":"חתן ר נחמיה שפירא מסאסוב. רב בסטריזוב, סאהל, מראשי אגודת ישראל. נספה בשואה. הוציא לאור כתב עת \"אחיאסף\" סטריזוב (בילגורי) תרפט.","s":"וונדר-גליציה ח\"ג; אוצר כתבי עת-לוין"},{"i":35139,"n":"ספרין, יעקב מקומרנא","f":"האדמור מקומרנא","b":"חתן ר אברהם מרדכי טויב האדמור מסאסוב. רב בפמורן, קומרנא.","s":"וונדר-גליציה ח\"ג"},{"i":35140,"n":"ספרין, יעקב משה מקומרנא","f":"אליעזר צבי מקומרנא","k":"אדמור מקומרנא","bt":"תרכא","bp":"קומרנא","dt":"תרפט - טו תמוז","b":"חתן נכדת זקנו - ר אברהם מרדכי מפינטשוב, ובזיוו\"ש חתן ה\"חקל יצחק\" מספינקא. אדמור בקומרנא על מקום אביו. חיבוריו אבדו בשואה. בנו ר שלום על מקומו אחריו.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 10253; אלפסי; אהלי שם"},{"i":35141,"n":"ספרין, יצחק שלמה מירושלים","f":"מנחם מאניש מקומרנא","k":"אדמור מקומרנא י-ם","b":"חתן ר מרדכי מזוויהל. אדמור מקומרנא בירושלים על מקום אביו.","s":"אלפסי"},{"i":35142,"n":"ספרין, ישכר דב מבני ברק","k":"אדמור מספרין","b":"אדמור מספרין בבני ברק-תשן."},{"i":35143,"n":"ספרין, מנחם מוניש מפלשטין","f":"אליעזר צבי מקומרנא","k":"אדמור מפלשטין","bt":"תרי","dt":"תרעג - ו טבת","b":"רב ואדמור בפלשטין-תרס, ודוברומיל. חתן ר נפתלי הירץ לאבין חתנו של האדמור מזידיטשוב, (לפי אלפסי חתן ר ישראל יוסף האדמור מזידיטשוב). בנו ר זיידא על מקומו בדוברומיל. הו\"ל ספר אביו \"בן ביתי\".","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 13353; אלפסי; אהלי שם"},{"i":35144,"n":"ספרין, מנחם מוניש מקומורנא ב\"ב","f":"חיים יעקב מקומרנא","k":"אדמור מקומרנא ב\"ב","bt":"תרעח","bp":"אונגוואר","dt":"תשן - ט סיון","b":"עלה לארץ-תרצט וכיהן כאדמור מקומרנא בבני ברק. חתן ר שלום וגשל מזלוטשוב, ובזיוו\"ש חתן ר יהושע ארנרייך משמלויא. בניו ר יצחק שלמה-חתן ר מרדכי מזוויהל - אדמור מקומרנא בירושלים, ור אליעזר צבי מבני ברק.","s":"וונדר-גליציה ח\"ג; אלפסי"},{"i":35145,"n":"ספרין, משה חיים מאלטשטט","f":"אלכסנדר סנדר מקומרנא","k":"אדמור מאלטשטט","bt":"תר","dt":"תרנח - טבת","b":"אדמור באלטשטט. חתן ר אלכסנדר סנדר איכנשטין מזידיטשוב. בניו: ר אלטר ישכר דב על מקומו אחריו, ר זיידא צבי אדמור בפשמישל, ר אברהם מרדכי.","s":"וונדר-גליציה ח\"ג; אלפסי"},{"i":35146,"n":"ספרין, משה חיים מלימנא","f":"אלטר ישכר מאלטשטט","b":"חתן ר מנשה מרילוס מרופשיץ. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":35147,"n":"ספרין, משה מזלושיץ ונ\"י","f":"שם מזלושיץ","k":"אדמור מזלושיץ אנטורפ","b":"אדמור מזלושיץ בניו יורק, עבר לאנטורפן. חיבר \"ברכת משה\".","s":"אלפסי"},{"i":35148,"n":"ספרין, פנחס נתן מרידיק","f":"אליעזר צבי מקומרנא","k":"אדמור מרידיק ונאנאש","bt":"תרכא-ד","dt":"תרצב - כט אדר","b":"חתן ר נפתלי חיים הורביץ \"הצדיק הפלאי\", ובזיוו\"ש חתן ר יהושע הורביץ מדזיקוב. אדמור ברידיק-תרע, נאנאש. נפטר ללא ילדים.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 17023; אלפסי"},{"i":35149,"n":"ספרין, צבי","f":"אלכסנדר מסטבניק","b":"רב-שנת ת\"פ","s":"אוצר הרבנים 17393"},{"i":35150,"n":"ספרין, צבי אלעזר מקומורנא","f":"חיים יעקב מקומורנא","b":"חתן ר אלתר ספרין מעיר ישן. נספה בשואה.","s":"אנשי שם-אמריקה"},{"i":35151,"n":"ספרין, שלום מקומרנא","f":"יעקב משה מקומרנא","bt":"תרנג","dt":"תרצז - כו אדר","b":"חתן ר ישראל פרלוב האדמור מסטולין. אדמור מקומרנא-תרפט על מקום אביו. בנו ר ברוך על מקומו אחריו.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 18175; אלפסי"},{"i":35152,"n":"ספרין, שלום מקומרנא ירושלים","f":"חיים יעקב מקומרנא","k":"אדמור מקומרנא","bt":"תרעו","bp":"אונגוואר או בוריסלוב","dt":"תשנח - תשרי","b":"חתן ר בן ציון וייס מראסיוויגעף בן ר אהרן ממונקטש, ובזיוו\"ש חתן ר ישראל יצחק ריזמן. עלה לארץ וכיהן כאדמור מקומרנא בירושלים. חבר מערכת אוצר הפוסקים. בניו: האדמורים ר נתנאל, ור אברהם מרדכי בעל \"הלכה אחרונה\", ור אליעזר צבי-חתן האדמור מללוב.","s":"וונדר-גליציה ח\"ג,ח\"ו; אלפסי"},{"i":35153,"n":"ספרין, שלמה","dt":"תשג","b":"רב בקומרנא","s":"אוצר הרבנים 18550"},{"i":35154,"n":"ספרין, שם מזלושיץ קראקא","f":"אברהם מרדכי מזלושיץ","k":"אדמור מזלושיץ קראקא","bt":"תרלב","dt":"תשג - כח ניסן","dp":"מחנה פלשוב","b":"חתן ר ישראל הורביץ מויסליץ (שושלת רופשיץ). מגדולי המקובלים בדורו. מתורתו ב\"אהלי שם\". נספה בשואה.","s":"אלפסי"},{"i":35155,"n":"ספרין, שמואל שמלקא מאלטשטט","f":"אלטר ישכר מאלטשטט","dt":"תש..","b":"רב באלטשטט על מקום אביו. חתן ר אליהו בומבך מאושפיצין. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":35156,"n":"ספרן, אברהם נחום מארה\"ב","bp":"סאקאלע","b":"ר\"מ בניו יורק, מנהל הת\"ת בפאסייק-ניו ג'רזי. חיבר לוחות ללימוד הקריאה לילדים, פרסם מאמרי דרוש שונים.","s":"אנשי השם בארהב-איזנשטט"},{"i":35157,"n":"ספרן-פוקס, ישראל אלתר מדוינסק","f":"יהודה הירש","bt":"תרעא","bp":"בלשביץ","dt":"תשב - כ סיון","b":"תלמיד הרוגטשובר בדוינסק ורב בדוינסק על מקומו אחריו. עסק בעריכת והוצאת כתבי רבו \"צפנת פענח\" בדוינסק תש והצליח לשלחם לרמ\"מ כשר. נספה בשואה.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 12141; אוצר הרבנים 12017"},{"i":35158,"n":"סצינבוים, אברהם יהושע השל","b":"רב ברישא-תרכט אצל ר נחום ראובן פלסקר.","s":"וונדר-גליציה ח\"ג"},{"i":35159,"n":"סקאבויניק, נחמן מראסקין","b":"מתורתו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד.","s":"אוצר כתבי עת-לוין"},{"i":35160,"n":"סקאליטשר, נחום","f":"ישראל מטשאהן","b":"רב בסקאליטש-ת\"ר","s":"אוצר הרבנים 15878"},{"i":35161,"n":"סקאצילאס, אפרים פישל","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט.","s":"אוצר כתבי עת-לוין"},{"i":35162,"n":"סקארוטא, משה מסלובודקה","dt":"תשג","b":"חתן ר משה מרדכי אפשטיין. רב בסלובודקא-תרצח. נספה בשואה.","s":"אוצר הרבנים 14982; אנשי שם-אמריקה"},{"i":35163,"n":"סקה, הנרי","bt":"1856","bp":"ליטא","dt":"1933","dp":"וילסדן","b":"היגר לדרום אפריקה-1876 וניהל מכרות יהלומים. נקרא ע\"י ססיל רודס לברברטון-רודזיה לחקור את מחצביה.","s":"ליטא"},{"i":35164,"n":"סקוביץ, יוסף מוילנא","f":"רפאל","k":"בעל פורת יוסף","bt":"תקעה","bp":"וילנא","dt":"תרן - א תמוז","dp":"וילנא","b":"נכד ר ישראל בן שאול מוילנא. חתן ר אהרן אליהו-בן ר יעקב שטרשון. ישב בביהמ\"ד של הגר\"א ולימד לומדים מופלגים וישב כל היום עטור בתפילין. מו\"צ בוילנא-תרה. חתם נגד מסכת \"כלים החדשה\".","s":"אוצר הרבנים 8482; ליטא; עיר וילנא ח\"א; היברובוקס","bk":[["פורת יוסף [המודפס בש\"ס]","מפרשי ש\"ס - אחרונים"],["פורת יוסף [עהש\"ס, נד' בסוף הגמ']",""],["הוראת היתר",""]]},{"i":35165,"n":"סקוטש, יצחק איזיק מטרויכלינגן","f":"פנחס מגרוסהאבר","b":"אב\"ד טרויכלינגן-שנות ה-תק'.","s":"מתוך קטלוג"},{"i":35166,"n":"סקוטש, פנחס מגירסהבר","b":"דיין בגירסהבר(=גרוסהאבר)-שנות ה-תק'. בנו - ר יצחק איזיק מטרויכלינגן.","s":"מתוך קטלוג"},{"i":35167,"n":"סקול, אהרן יצחק מלברג","b":"תשובה אליו - שנות חיים לרש\"ק.","s":"וונדר-גליציה ח\"ו"},{"i":35168,"n":"סקולסקי, אליהו אליעזר מלונדון","b":"מראשי קהלת \"עדת ישראל\" בלונדון-תרצד. קרוב משפחתו של ר אליהו דסלר וסייע לו בהגיעו ללונדון.","s":"מתוך קטלוג"},{"i":35169,"n":"סקירטיש די, שלמה מספרד","b":"מחכמי ספרד, חתנו ותלמידו של הריב\"ש, שהזכירו בספרו.","s":"ארזי הלבנון"},{"i":35170,"n":"סקלי - משפחת כהנים","b":"משפחת כהנים במרוקו.","s":"טולדנו-נר המערב"},{"i":35171,"n":"סקלי, אברהם הכהן","f":"דוד","k":"בעל ברית כרותה","dt":"תרלא - כסלו","b":"רב ומו\"ץ בתאזה-מרוקו, חיבר \"ברית כרותה\"","s":"ארזי הלבנון; אוצר הרבנים 665; מלכי רבנן"},{"i":35172,"n":"סקלי, אברהם הכהן","f":"יעקב","dt":"תקצו - לפני","dp":"מרוקו","b":"רב בדברו-מרוקו. אחיו של ר חיים.","s":"מלכי רבנן"},{"i":35173,"n":"סקלי, אברהם הכהן מפאס","b":"מחכמי פאס-תרא.","s":"מלכי רבנן"},{"i":35174,"n":"סקלי, אהרן הכהן מדבדו-מרוקו","b":"מחכמי דבדו-מרוקו. זקנו של ר יוסף בן יצחק.","s":"מלכי רבנן"},{"i":35175,"n":"סקלי, אהרן הכהן מפאס","f":"משה","dt":"תקעט - י אדר","b":"מחכמי פאס, חתם על פס\"ד-תקעה (בשם - ר אהרן בן אליהו הכהן סקאלי) עם ור שלמה סירירו. נספד בידי ר דניאל ן צולטאן.","s":"ארזי הלבנון; מלכי רבנן"},{"i":35176,"n":"סקלי, אליהו הכהן מפאס","b":"מחכמי פאס-שנות ה-ת'-תק', בנו - ר אהרן.","s":"ארזי הלבנון; מלכי רבנן"},{"i":35177,"n":"סקלי, דוד הכהן מדבדו - הזקן","b":"ממיסדי הקהלה בדברו(=דבדו)-מרוקו. זקנו של ר דוד הכהן סקלי מאלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35178,"n":"סקלי, דוד הכהן מדבדו-מרוקו","f":"חיים","b":"סופר מחכמי דבדו-שנות ה-תק'.","s":"מלכי רבנן"},{"i":35179,"n":"סקלי, דוד הכהן ממרוקו ואלגיר","f":"משה","k":"בעל קרית חנה דוד","bt":"תרכא-ב","bp":"דברו-מרוקו","dt":"תשט","dp":"ווהראן","b":"מצאצאי ר דוד הכהן סקלי מדברו. ראש ישיבה בדבדו, עבר לתלמסאן-תרנו, אב\"ד וראש ישיבה בווהראן-תרנד-תרפג. חיבר גם \"לך דוד\" ירושלים תרצו, \"קרן לדוד\", חיבר גם קונטרס לתולדות חייו.","s":"אוצר הרבנים 4942; ארזי הלבנון; מלכי ישורון-חכמי אלגיר; מלכי רבנן","bk":[["קרית חנה דוד",""]]},{"i":35180,"n":"סקלי, דוד הכהן מפאס","b":"מחכמי פאס-שנות ה-ש'.","s":"מלכי רבנן"},{"i":35181,"n":"סקלי, חיים הכהן מדבדו","b":"מחכמי דבדו-מרוקו-שנות ה-ת'. בנו - ר יעקב.","s":"מלכי רבנן"},{"i":35182,"n":"סקלי, חיים הכהן מדבדו-מרוקו","b":"מחכמי דבדו-מרוקו-שנות ה-תק'. אחיו של ר אברהם, בנו - ר דוד.","s":"מלכי רבנן"},{"i":35183,"n":"סקלי, חיים ימין הכהן מפאס","f":"אהרן","bt":"תקצו","bp":"פאס או דבדו-מרוקו","dt":"תרפה - א חשון","b":"מו\"ץ בפאס-תרנב.","s":"ארזי הלבנון; מלכי רבנן"},{"i":35184,"n":"סקלי, חננאל ממצרים","b":"ראש ישיבה במצרים-תקע\"ח","s":"אוצר הרבנים 6712; ארזי הלבנון"},{"i":35185,"n":"סקלי, יהודה הכהן מממרוקו","b":"רב במרוקו.","s":"מלכי רבנן"},{"i":35186,"n":"סקלי, יהודה הכהן מפאס","dt":"תרא","b":"עשיר, רב בפאס. בנו - ר יעקב.","s":"אוצר הרבנים 7047; מלכי רבנן"},{"i":35187,"n":"סקלי, יוסף הכהן מאלגיר","f":"משה","bt":"תרי","dt":"תרף - בערך","b":"מוצאו מדברו (אולי מצאצאי ר דוד הכהן סקלי מדברו). רב בווהראן, מחכמי אלגיר, ספרא רבא. חיבר הגדה של פורים - אלגיר תרן - בערבית יהודית. נזכר עם רבני ווהראן בתחילת ספר \"פרקי אבות\" ברלין תרח?.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35188,"n":"סקלי, יוסף הכהן מדובדו-מרוקו","f":"שמעון","dt":"תפד","dp":"דבדו-מרוקו","b":"רב בדובדו(=דבדו)-מרוקו-שנות ה-ת', נזכר ב\"משפט וצדקה ביעקב\".","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":35189,"n":"סקלי, יוסף הכהן מפאס","f":"אליהו","dt":"תרפט - יא אייר","b":"תלמיד ר רפאל אהרן ן דנאן, דודו - ר חיים הכהן. מחכמי פאס, מיסד ומנהל הת\"ת \"אם הבנים\".","s":"מלכי רבנן"},{"i":35190,"n":"סקלי, ימין הכהן מדבדו-מרוקו","b":"מחכמי דבדו-מרוקו-שנות ה-ת'.","s":"מלכי רבנן"},{"i":35191,"n":"סקלי, יעקב","f":"חננאל","k":"בעל תורת המנחה","bp":"סיציליה","b":"מגדולי חכמי דורו בספרד-שנת ע\"ח, רב בדמשק,עלה לא\"י. יצא לנדודים במטרה למצוא פירושים ומדרשים על התורה לצורך ספרו, הגיע לקורדובה שם התקשר עם חכם בשם חזקיה ונדרו לעלות תוך שנתיים לירושלים ולעסוק שם בתורה, אך הוא איחר את נדרו וארבעה מחמשת ילדיו מתו, והוא שאל את הרא\"ש בענין זה. עלה לירושלים ועבר לדמשק שם ישב בשנת פד (1324). חיבר \"ילקוט תלמוד תורה\" נדפס בירושלים תרעג, ועוד. החידא קורא לספר \"תורת המנחה\". לדעת כמה חוקרים הוא גם מחבר \"קונטרס ארץ ישראל\".","s":"גליס; אוצר הרבנים 9876,9800; פין-כנסת ישראל; ש.ה. קוק \"קרית ספר\" ב', \"ארשת\" ספר א."},{"i":35192,"n":"סקלי, יעקב הכהן מדבדו-מרוקו","b":"מחכמי דבדו-שנות ה-תק'. בנו - ר אברהם.","s":"מלכי רבנן"},{"i":35193,"n":"סקלי, יעקב הכהן מטבריה","f":"אהרן ממרוקו","bt":"תקצח או תרו","bp":"טבריה","dt":"תרעט - כא חשון","dp":"טבריה","b":"מחכמי טבריה וצפת, בשנת תרלא בשליחות בצפון אפריקה. ובשנת תרמט בשליחות להודו. בשנת תרן נתמנה לדיין בטבריה ואחר כך לאב\"ד. בנה את ביהכנ\"ס ר' מאיר בעל הנס,","s":"גליס; אוצר הרבנים 9801; גאון-יהודי המזרח; אהלי שם"},{"i":35194,"n":"סקלי, יצחק הכהן מאלגיר","bt":"תקך","dt":"תקץ - בערך","b":"רב באלגיר ומלמד תורה. מתלמידיו: ר שלמה זוראפה והזכירו ב\"שער שלמה\". פסק דין ממנו בענין שעון בשבת.","s":"מלכי ישורון-חכמי אלגיר"},{"i":35195,"n":"סקלי, יצחק הכהן מפאס","b":"מחכמי פאס - שנות ה-ת'. מצאצאי ר אברהם בן משה הכהן.","s":"מלכי רבנן"},{"i":35196,"n":"סקלי, משה הכהן","b":"מחכמי חברון, בשליחות במרוקו בשנת תקלה, בנו - ר יהודה סקלי הכהן.","s":"גליס; רוזניס-תורכיה-ה; שא\"י"},{"i":35197,"n":"סקלי, משה הכהן ממרוקו","f":"יהודה","b":"רב בדבדו-מרוקו, חתם-תרכז עם ר יוסף בן אהרן בן חמו.","s":"מתוך קטלוג"},{"i":35198,"n":"סקלי, משה ממרוקו","f":"יצחק","b":"רב בדבדו?-מרוקו, חתם-תרכח עם ר משה בן יהודה הכהן סקלי.","s":"מתוך קטלוג"},{"i":35199,"n":"סקלי, נסים אפרים מחברון","b":"מחכמי חברון-תריא.","s":"גליס; ארזי הלבנון"},{"i":35200,"n":"סקלי, ראובן הכהן מדברו-מרוקו","b":"מחכמי דברו-מרוקו-שנות ה-ת'.","s":"מלכי רבנן"},{"i":35201,"n":"סקלי, שמעון הכהן ממרוקו","b":"במקור מדיבדו-מרוקו. ראש משפחת סקלי בכפר צאר בן משעאל במרוקו-שנות ה-ש' או ת', והקים שם בית כנסת. בניו - ר יהודה, ר משה, ר שלמה.","s":"טולדנו-נר המערב"},{"i":35202,"n":"סקמורובסקי, שלמה צבי מזיטומיר","f":"אהרן","b":"רב מטעם בזיטומיר-תרסא. הסכמה ממנו ל\"פרחי חמד\" מאת ר מתתיהו לוין."},{"i":35203,"n":"סקראבון, משה ממיר","k":"בעל לקץ הימין","b":"רב במיר, חיבר \"לקץ הימין\" וארשא תרצג. (באוצר נרשם המחבר ר משה ימיני בן יצחק).","s":"מתוך קטלוג"},{"i":35204,"n":"סראוול, יהודה ליב מונציה וצפת","dt":"שעז","dp":"פדובה","b":"מחכמי צפת, דיין בונציה אצל ר בן ציון צרפתי. עם רבו - ר יהודה קצנלנבוגן. חיבר פירוש למעמדות - ונציה, עם הקדמה מבנו ר נחמיה. תשובות ממנו בכת\"י ובספרי חכמי דורו-שעב, וביניהם תשובה בענין המקוה ברוויגו ב\"משבית מלחמות\". תלמידו - ר יעקב היילפרון בעל \"נחלת יעקב\".","s":"איטליה גירונדי-ל ב; אוצר הרבנים 7361; רוזניס-תורכיה-ג"},{"i":35205,"n":"סראוול, יעקב רפאל מונציה","dt":"תקמב","dp":"מנטובה","b":"רב בונציה-תקי, מנטובה, בשליחות קהלת ונציה בהולנד ואנגילטירה לגיוס עזרה לקהלה. חיבר אגרת מחקרות - מנטובה. תרגם לאיטלקית את \"ברכי נפשי\" לרבנו בחיי. הדפיס \"קינת סופרים\" על האסון שקרה במנטובה שנהרסו בתים רבים - והוא ניצל. נזכר בספרי חכמי דורו הנוצרים שעמם התכתב.","s":"איטליה גירונדי-י ה,ריו; אוצר הרבנים 9802; פין-כנסת ישראל"},{"i":35206,"n":"סראוול, ליב","b":"מגדולי חכמי איטליה","s":"אוצר הרבנים 12605"},{"i":35207,"n":"סראוול, משה מקושטא","b":"נביאו של שבתי צבי-תכו בקושטא.","s":"רוזניס-תורכיה-ד"},{"i":35208,"n":"סראוול, נחמיה מונציה","f":"ליב","b":"רב בונציה בזמן ר שמואל יהודה קצנלנבוגן. תשובה ממנו ב\"דבר שמואל\". הסכים על ספר אלים ליש\"ר מקנדיא.","s":"איטליה גירונדי-נ ד,יא"},{"i":35209,"n":"סראנו פרנקו, יוסף מאמשטרדם","k":"בעל פירוש לתורה","b":"מחכמי אמשטרדם-תרכה, ממיסדי חברת \"תמימי דרך\" ומלמד תורה שם. תרגם התורה לספרדית באמשטרדם וחיבר פירוש לתורה - אמשטרדם.","s":"איטליה גירונדי-י קסד; ארזי הלבנון"},{"i":35210,"n":"סרבניק, אריה","b":"בנו - ר נתן נטע מביאלא.","s":"אוצר הרבנים 3366; אהלי שם"},{"i":35211,"n":"סרבניק, נח מפיאסעצני","f":"נתן נטע מביאלא","bt":"תרי","b":"רב בביאלע(=ביאלא)-תרלד על מקום אביו, פיאסצנע(=פיאסעצני)-פלך וארשא-תרנג. חתניו - ר שמחה חנוך הניך נייפלד מיעזארני, ר מאיר ישראל בן צמח ברוך-נכד היהודי מפשיסחא.","s":"אוצר הרבנים 15806; אהלי שם"},{"i":35212,"n":"סרבניק, נתן נטע מביאלא","f":"אריה סרבניק","b":"רב בביאלא קטן-תר\"ל","s":"אוצר הרבנים 16445"},{"i":35213,"n":"סרברניק, יצחק איטשע מסטרזנובא","f":"אביגדור","bt":"תרלט","b":"נכד ר שמשון מנווידוואהר, ונכד ר שמואל מזליחוב. חתן ר אביגדור מזליחוב. רב בסטעגאווא(=סטשעגאווא)-פלך פלאצק. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט.","s":"אוצר הרבנים 11392; אוצר כתבי עת-לוין; אהלי שם"},{"i":35214,"n":"סרברניק, שלמה","dt":"תרנח - יא כסלו","b":"רב בווילען","s":"אוצר הרבנים 18553"},{"i":35215,"n":"סרגוסי, אברהם יוסף משלוניקי","b":"מחכמי שלוניקי-תרס.","s":"זכרון שלוניקי-191"},{"i":35216,"n":"סרגוסי, אברהם מספרד","k":"אברהם סרקוסטי","b":"מחכמי ספרד. אביו של ר יוסף.","s":"ארזי הלבנון; אלופי יעקב א-רח"},{"i":35217,"n":"סרגוסי, חיים","b":"מלומד בנסים, קידש שם שמים.","s":"אוצר הרבנים 6099; ארזי הלבנון"},{"i":35218,"n":"סרגוסי, יוסף ממצרים","f":"אברהם","bt":"רך","bp":"סיציליה","dt":"רסז - לפני","dp":"עין זיתים (צפת)","b":"מגולי סיציליה בזמן גירוש ספרד, הגיע לקהיר ושימש כרב ובין תלמידיו היה הרדב\"ז, עלה לצפת והיה שם לרב, בדרכו לצפת עבר בבירות וצידון ושם בקשו ממנו להשאר כרבם, אך לאחר תקופה לא ידועה הגיע לצפת. היה החכם הספרדי הראשון שהתיישב בעיר.","s":"גליס; אוצר הרבנים 8483; גאון-יהודי המזרח; פין-כנסת ישראל; \"ירושלים\" ו."},{"i":35219,"n":"סרגוסי, מנחם מפטרץ","b":"דיין בפטרץ החדשה(=פטראג'יק)-תק.","s":"רוזניס-תורכיה-ה"},{"i":35220,"n":"סרגוסי, משה ממצרים","b":"נכד ר יעקב קשטרו-מהריק\"ש ממצרים, רב במצרים-תן בזמן ר מנחם הכהן ור דוד די מדינה. חתם בשו\"ת מהרי פארג'י ראשון על הסכמה לפסק דין, ואחריו ר יעקב בירב - הנכד, ר ישראל רומנו, ר מנחם הכהן ור זרחיה גוטה.","s":"אוצר הרבנים 14983; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":35221,"n":"סרגוסי, משה משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'. אבי משפחת סאראגוסה.","s":"רוזניס-תורכיה-ד"},{"i":35222,"n":"סרגוסי, פרחיה מירושלים","b":"מחכמי ירושלים, בשנת תקצז בשליחות. היה ראש ישיבת \"בית אברהם\" בירושלים. בשנת תרח בשליחות בארצות ערב. יתכן שהוא השליח ר פתחיה שנפטר בכורדיסטן בעיר ארביל.","s":"גליס; אוצר הרבנים 17057; גאון-יהודי המזרח; פרומקין-תח\"י; שא\"י"},{"i":35223,"n":"סרגוסי, רפאל מקושטא","b":"רב בקושטא, יסד ישיבה בירושלים \"דמשק אליעזר\".","s":"פרומקין-תח\"י"},{"i":35224,"n":"סרדצקי, ינטה","f":"יהושע","k":"בעל געקליבענע שריפטע","bt":"1877","bp":"אלקסוט","dt":"1962","b":"חיברה סיפור \"מיכל\" ונסעה לוארשא אל י.ל. פרץ שפרסם את הסיפור ועודדה להמשיך בכתיבה. פרסמה בעתונות העברית. היגרה לארה\"ב-1907 ועסקה גם בעבודה ספרותית. ?? לא באוצר ??","s":"ליטא"},{"i":35225,"n":"סרווקא, יהושע דוד הלוי מגלזגי","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח.","s":"אוצר כתבי עת-לוין"},{"i":35226,"n":"סרוסי, חלאפו מלוב","dt":"תקעג","b":"דיין בטריפולי-תקנח עם ר חיים ואתורי ור שלום פלוס, וכן עם ר יעקב זטלאוי ור יוסף כלפון. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":35227,"n":"סרוסי, יצחק מטריפולי","dt":"תקע","b":"דיין בטריפולי-לוב. מתלמידיו ר כמוס אג'רבי.","s":"אוצר הרבנים 10480; ארזי הלבנון"},{"i":35228,"n":"סרוסי, ישראל מטריפולי","dt":"תקנט","b":"רב בטריפולי. נזכר אצל ר אברהם חלפון. הסכים על \"יסוד הקיום\" לר בנימין אספינוזא. נזכר ב\"ישרש יעקב\" - \"יסוד הקיום\" - תשסה.","s":"מלכי חי\"ל-מרציאנו"},{"i":35229,"n":"סרוסי, ישראל מליוורנו","f":"בנימין","b":"רב בליוורנו-תקמח. דיין אצל ר דוד מלאך. בפורים-תקיד התארח החיד\"א בביתו בונציה.","s":"ארזי הלבנון"},{"i":35230,"n":"סרוסי, משה מטריפולי","f":"ראובן","k":"בעל וישב משה","bt":"תקפא-ה","bp":"טריפולי-לוב","dt":"תרעט - כט טבת","b":"רב בטריפולי, דרנא-לוב, ממונה על השחיטה וכשרות בטריפולי. לא כיהן בדיין בגלל שהיה כבד שמיעה. מגדולי המשיבים בדורו בלוב. חיבר \"וישב משה\" תונס תרנז.","s":"ארזי הלבנון; אוצר הרבנים 14439; מלכי חי\"ל-מרציאנו","bk":[["וישב משה",""]]},{"i":35231,"n":"סרוסי, משה מטריפולי","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":35232,"n":"סרוק ן, זכריה מספרד","f":"יהושע","k":"בעל פירוש לאסתר","bt":"רי","dp":"ש - בערך","b":"מחכמי ספרד, רב בקהילות בארגון, בגירוש ברח לאלגיר, ולאות הוקרה על עזרת בני הקהלה חיבר לכבודם \"פירוש למגילת אחשורות\" - רנג. עבר לאיטליה והדפיס שם את ספרו. בספרו מביא מפירוש ר אברהם ן עזרא למס' קידושין (וזהו חידוש כפי שכתב החיד\"א).","s":"אוצר הרבנים 5580; ארזי הלבנון; מלכי ישורון-חכמי אלגיר; פין-כנסת ישראל"},{"i":35233,"n":"סרוק, יוסף משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא.","s":"עמנואל-שלוניקי"},{"i":35234,"n":"סרוק, ישראל מצפת","k":"בעל נעים זמירות ישרא","dt":"שסג - לפני","b":"מחכמי צפת, מגורי האר\"י ותלמיד ר חיים ויטאל. בשנת שנג יצא להפיץ חכמת הנסתר בחו\"ל, ובין תלמידיו רמ\"ה מפאנו, ר ישכר בר אב\"ד וורמס ור מאיר פאפירש, בהולנד למד עם ר ישראל איררה בעל \"שער השמים\", משם הלך לפולין וחזר לארץ ישראל. חיבר \"נעים זמירות ישראל\" ורשה תרמג, ועוד.","s":"גליס; אוצר הרבנים 12011; ארזי הלבנון; פין-כנסת ישראל; רוזניס-תורכיה-ג"},{"i":35235,"n":"סרוק, מנחם מספרד","f":"יעקב","k":"בעל המחברת","bt":"ד'תש - לפני","bp":"טורטוסה","b":"מראשוני חכמי ישראל בספרד, משורר ומדקדק, ישב אצל ר חסדאי ן שפרוט בקורדובה והיה מזכירו ומשורר החצר. חיבר מילון למקרא בשם \"מחברת\" והיה בר פלוגתא של דונש ן לברט וכתב עליו השגות. גדולי הפרשנים השתמשו בחיבורו. מתלמידיו בדקדוק - ר יהודה חיוג'.","s":"אוצר הרבנים 13272; ארזי הלבנון"},{"i":35236,"n":"סרוק, שלמה מהולנד","b":"רב בקהלת הספרדים בהאג-הולנד-תקלד.","s":"ארזי הלבנון; רוזניס-תורכיה-ה"},{"i":35237,"n":"סריבנר, צבי הירש","b":"פרסם מאמרים ב\"בית המדרש\" - קראקא תרמח.","s":"אוצר כתבי עת-לוין"},{"i":35238,"n":"סרילייא, אברהם מאנקונא","dt":"שיו - יג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":35239,"n":"סרינו, רפאל מליוורנו","b":"מחכמי ליוורנו-תל.","s":"רוזניס-תורכיה-ד"},{"i":35240,"n":"סריקי, מסעוד","f":"יוסף","b":"מחכמי מרוקו. הו\"ל \"חצות לילה אקום\" על תקון חצות כמנהג מראקיש, ורבאט - קזבלנקה תרצב.","s":"ארזי הלבנון"},{"i":35241,"n":"סרכוב, אברהם","dt":"תשא","b":"רב בטראבי(פולין)","s":"אוצר הרבנים 638"},{"i":35242,"n":"סרנא, שרגא מסלונים","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט.","s":"אוצר כתבי עת-לוין"},{"i":35243,"n":"סרנה, יחזקאל מירושלים","k":"בעל המוסר","bt":"תרמט","dt":"תשכט - י אלול","b":"מגדולי המוסר בליטא, עלה לירושלים-תרפד, ראש ישיבת \"חברון\" בירושלים. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"תבונה\" - ירושלים תשא.","s":"אוצר הרבנים 9060; אוצר כתבי עת-לוין"},{"i":35244,"n":"סרניצר, משה יהודה","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":35245,"n":"סתהון דבאח, דוד","k":"בעל יעלה הדס","bt":"תרמח","bp":"חלב","dt":"תשי - אב","dp":"בואנוס איירס","b":"רב ומו\"צ בקילז, עלה לא\"י-תרע\"ח, נסע לארגנטינה -תרפ\"ט, רב ואב\"ד בבואנוס איירס-תר\"צ, חיבר \"יעלה הדס\"","s":"ארזי הלבנון"},{"i":35246,"n":"סתהון, אברהם מחלב","f":"שלמה","k":"בעל מלל לאברהם","dt":"תקעו","b":"גדול בתורה ומדע, משורר, ראש הרבנים בארם צובה-תקסו. הסכים על \"ברך משה\" - ליוורנו תקסט. בנו - ר משה מחלב בעל \"דברי משה\".","s":"אוצר הרבנים 666; ארזי הלבנון; שם הגדולים השלישי"},{"i":35247,"n":"סתהון, אליעזר מחלב","f":"חביב","b":"מחכמי חלב-תקך. חתם עם ר יצחק דבח ור ישעיה דבח על הסכמה-תקיט ל\"בירך יצחק\" ונציה תקכג.","s":"מתוך קטלוג"},{"i":35248,"n":"סתהון, אליעזר מנצור מטבריה ומצ","f":"חביב","k":"בעל קרבן אליצור","bt":"תרך או תרכו","bp":"טבריה","dt":"תרצז - ב אב","dp":"טבריה","b":"תלמיד ר משה נאים מגיברלטר, ר בכור סתהון. מחכמי טבריה, רב בפורט סעיד-תרסה בהזמנת הגביר ר משה חנוך ואחיו. בשנת תרצד בשליחות עם בנו ר גבריאל במצרים צפון אפריקה והודו. חיבר \"קרבן אליצור\" נדפס בטבריה, \"נוצר אדם\".","s":"גליס; אוצר הרבנים 13621; ארזי הלבנון; אהלי שם"},{"i":35249,"n":"סתהון, גבריאל","dt":"תקצט","dp":"טבריה","b":"מחכמי ארם צובא-תקס, עלה לטבריה-תקף. חיבר ספרים בכתב יד.","s":"גליס; אוצר 4292; ארזי הלבנון"},{"i":35250,"n":"סתהון, דוד","f":"גבריאל סתהון","b":"יבם את אשת אחיו ר אהרן שבות - ונולד בנו ר חיים דוד.","s":"אוצר הרבנים 4943"},{"i":35251,"n":"סתהון, דוד הלל מנשה","f":"מנשה","k":"בעל ארוכה ומרפא","r":"חכם דוד מנשה","dt":"תרסט - יז אלול","dp":"ירושלים או חלב","b":"מחכמי ארם צובא, חתן הרב שלום כ'אסכי, עלה לירושלים בתרן. חיבר \"ארוכה ומרפא\" ארם צובא תרעג, ועוד. (ישנה מצבה לר דוד עזרה סתהון שנפטר ירושלים תרסד)","s":"גליס; ארזי הלבנון; אוצר 5108; ישא ברכה גליון 352","bk":[["ארוכה ומרפא - מוסר",""]]},{"i":35252,"n":"סתהון, דוד עזרא מטבריה","s":"מתוך קטלוג"},{"i":35253,"n":"סתהון, חביב","f":"גבריאל סתהון","b":"מחכמי ארם צובה","s":"אוצר הרבנים 5795"},{"i":35254,"n":"סתהון, חביב דוד אליהו חיים","f":"דוד","k":"בעל שמש ומגן","bt":"תקפז או תקצח","bp":"טבריה","dt":"תרסז - יב טבת","dp":"טבריה או חיפה","b":"חתן ר משה אלקלעי מטבריה. מגדולי רבני טבריה, אביו ייבם את אשת אחיו, אך נפטר כשאמו עוד היתה מעוברת, והוא נשא את שמו של אביו דוד ודודו חביב והוסיפו לו לסגולה את השם חיים, אמו גדלה אותו, תלמיד זקנו ר אהרן שבות הלוי ור חיים שמואל קונוורטי. בשליחות בתורכיה, מצרים ומרוקו-תרכה, ושוב במרוקו-תרלג. דרשן, אב\"ד, נדד לפקיעין ושפרעם, חיפה-תרסא, יסד ישיבת \"אליהו הנביא\" בחיפה וראש הישיבה-תרסד. חיבר \"תקפו של נס\",\"שמש ומגן\". חתם-תריז על תעודות ראשי הקהלה.","s":"גליס; אוצר הרבנים 6298; גאון-יהודי המזרח; ארזי הלבנון; יהב\"י","bk":[["תוקפו של נס",""]]},{"i":35255,"n":"סתהון, יוסף מנשה","k":"בעל ויצבור יוסף","dt":"תרמה - יד אדר","b":"מגדולי רבני ארם צובה,עלה לא\"י","s":"אוצר הרבנים 8925; אוצר הרבנים 8484"},{"i":35256,"n":"סתהון, יעקב שלמה","b":"אין פרטים","s":"מתוך קטלוג"},{"i":35257,"n":"סתהון, יצחק","f":"מנשה","s":"מתוך קטלוג"},{"i":35258,"n":"סתהון, מטלוב מחלב","dt":"תקצד - א אד\"ב","b":"רב בחלב. בנו - ר מנשה","s":"אוצר הרבנים 14126; ארזי הלבנון"},{"i":35259,"n":"סתהון, מנשה מטלוב מחלב","f":"מטלוב?","k":"בעל כנסיה לשם שמים","dt":"תרלו - כו אלול","dp":"צפת או אלכסנדריה","b":"מחכמי חלב, עלה לצפת וכיהן כרב-תרל, רב בחלב-תרלד, נתקבל לרב באלכסנדריה, אך נפטר בדרכו לשם. חיבר ספר כנגד מנהג ה\"אינדולקו\" - טקס מנחה לשדים - להצלחת הבית - שהיה נפוץ ע\"י נשים במזרח. חיבר עוד \"פרחי שושנים\" ועוד.","s":"גליס; אוצר 13635; ארזי הלבנון"},{"i":35260,"n":"סתהון, משה מחלב","k":"בעל קהלת משה","dt":"תרלח - כב תמוז","b":"רב בחלב-תר. פעל למען יהודי דמשק בזמן עלילת הדם-תר. הסכים על \"הדר עזר\" לר יצחק שרים, ועוד.","s":"אוצר הרבנים 14984; ארזי הלבנון"},{"i":35261,"n":"סתהון, נסים מדמשק","b":"רב בדמשק-תר, וחתם עם ר יצחק אבולעפיה ור חיים שמואל הכהן על קבלת עדות - תר, כנזכר ב\"שות מהר\"א אשכנזי\".","s":"ארזי הלבנון"},{"i":35262,"n":"סתהון, שאול דוד מחלב וארגנטינה","f":"דוד","k":"בעל דבר שאול","bt":"תריא","bp":"חלב","dt":"תרץ - יט סיון","b":"דיין בחלב, רב בעינטב-תרמא, ראש ישיבה בחלב-תרנא, רב בבואנוס איירס-תרעב - לשם היגרו בניו. תיקן שלא לקבל גרים בארגנטינה - והיה מחלוקת על כך.","s":"ארזי הלבנון; אוצר הרבנים 19299; גאון-יהודי המזרח"},{"i":35263,"n":"סתהון, שלום מחלב","f":"משה","dt":"תשלז - יא אב","dp":"ירושלים","b":"מחכמי חלב, עלה לירושלים והקים בית יתומים \"חפץ חיים\" וניהלו.","s":"ארזי הלבנון"},{"i":35264,"n":"סתהון, שלמה יצחק מטבריה","f":"חביב חיים דוד","dt":"תרצא - כד תשרי","dp":"טבריה","b":"מחכמי טבריה ועסק במסחר ספרים וסופר סת\"ם. חיבר ספרים בכת\"י, ב\"קרית ספר טבריה\".","s":"אוצר הרבנים 18859; ארזי הלבנון"},{"i":35265,"n":"סתהון-שומר, ישעיה מאר\"ץ","dt":"תרסב - ט טבת","b":"רב בארם צובה.","s":"אוצר הרבנים 11738; ארזי הלבנון"}];
